# SinergIA0011 - Drive guardrails (actor + write check por folder)
import uuid
from googleapiclient.errors import HttpError

def sinergia_drive_get_actor_email(drive_service) -> str:
    try:
        about = drive_service.about().get(fields="user(emailAddress)").execute()
        return (about.get("user") or {}).get("emailAddress") or ""
    except Exception:
        return ""

def sinergia_drive_can_write_folder(drive_service, folder_id: str, *, supports_all_drives: bool = True) -> tuple[bool, str]:
    """
    Verifica permisos de escritura creando y borrando un archivo marcador en el folder.
    Retorna (ok, reason).  No deja basura.
    """
    folder_id = str(folder_id or "").strip()
    if not folder_id:
        return False, "EMPTY_FOLDER_ID"

    probe_name = f"._sinergia_probe_{uuid.uuid4().hex[:8]}.txt"
    file_id = None
    try:
        meta = {"name": probe_name, "mimeType": "text/plain", "parents": [folder_id]}
        created = drive_service.files().create(
            body=meta,
            fields="id",
            supportsAllDrives=supports_all_drives
        ).execute()
        file_id = created.get("id")
        if not file_id:
            return False, "CREATE_NO_FILE_ID"

        drive_service.files().delete(
            fileId=file_id,
            supportsAllDrives=supports_all_drives
        ).execute()
        return True, "OK"

    except HttpError as e:
        # 403/404 típicamente: no permisos o folder no existe / no visible para el actor
        return False, f"HTTP_ERROR_{getattr(e, 'status_code', '')}".strip("_") or "HTTP_ERROR"
    except Exception as e:
        return False, f"ERROR_{type(e).__name__}"

# SinergIA0020 · Helper gSheet usando gspread (autenticado, tolerante a headers vacíos)

import pandas as pd

def read_gsheet(spreadsheet_id: str, sheet_name: str) -> pd.DataFrame:
    """
    Lee una hoja de Google Sheets como DataFrame usando gspread y las
    credenciales autenticadas en #SinergIA0020.

    Tolera encabezados vacíos o duplicados generando nombres únicos.
    """

    sh = gc.open_by_key(spreadsheet_id)
    ws = sh.worksheet(sheet_name)

    # Leemos TODAS las celdas
    values = ws.get_all_values()

    if not values:
        return pd.DataFrame()

    raw_header = values[0]
    rows = values[1:]

    # Normalizar encabezados: si está vacío, darle un nombre único
    header = []
    seen = {}
    for i, h in enumerate(raw_header):
        name = h.strip()
        if not name:
            name = f"col_{i+1}"
        # evitar duplicados exactos
        if name in seen:
            seen[name] += 1
            name = f"{name}_{seen[name]}"
        else:
            seen[name] = 1
        header.append(name)

    df = pd.DataFrame(rows, columns=header)
    return df

# SinergIA0030 · Drive list helpers (API v3) para poblar dropdowns

from typing import List, Tuple, Optional

def drive_list_files_in_folder(folder_id: str, max_results: int = 200) -> List[Tuple[str, str]]:
    """
    Retorna lista de (file_id, file_name) dentro de una carpeta de Drive.
    Solo archivos visibles para el usuario autenticado.
    """
    if not folder_id:
        return []

    q = f"'{folder_id}' in parents and trashed = false"
    fields = "nextPageToken, files(id, name, mimeType, modifiedTime)"

    out: List[Tuple[str, str]] = []
    page_token = None

    while True:
        resp = drive_service.files().list(
            q=q,
            spaces="drive",
            fields=fields,
            pageToken=page_token,
            pageSize=min(max_results, 1000),
            orderBy="modifiedTime desc"
        ).execute()

        files = resp.get("files", []) or []
        for f in files:
            name = f.get("name")
            fid = f.get("id")
            if name and fid:
                out.append((fid, name))

        page_token = resp.get("nextPageToken")
        if not page_token or len(out) >= max_results:
            break

    return out[:max_results]


def drive_list_names_in_folder(folder_id: str, max_results: int = 200) -> List[str]:
    return [name for (_fid, name) in drive_list_files_in_folder(folder_id, max_results=max_results)]

