# SinergIA0100 - Helpers para configuración (Config_SinergIA)
from typing import Dict
import pandas as pd

def load_config_sheets(spreadsheet_id: str) -> Dict[str, pd.DataFrame]:
    """
    Carga todas las hojas del Google Sheet de configuración y devuelve
    un dict {nombre_hoja: DataFrame}.

    Usa el cliente gspread global `gc` y el helper `read_gsheet`.
    """
    sh = gc.open_by_key(spreadsheet_id)
    cfg: Dict[str, pd.DataFrame] = {}

    for ws in sh.worksheets():
        name = ws.title
        try:
            cfg[name] = read_gsheet(spreadsheet_id, name)
        except Exception as e:
            print(f"[Config] Error leyendo hoja '{name}': {e}")

    return cfg

# SinergIA0200 - Getters folder_id desde SettingID (usa sinergia_load_settingid_df)
def sinergia_get_folder_id(kind: str, log: str = ""):
    df = sinergia_load_settingid_df(force=False)
    kind = str(kind).strip().lower()

    candidates = {
        "rutinas": ["RUTINAS", "RUTINA", "FOLDER_RUTINAS", "CARPETA_RUTINAS", "ID_CARPETA_RUTINAS"],
        "gestion": ["Gestion", "FOLDER_GESTION", "CARPETA_GESTION", "ID_CARPETA_GESTION"],
        "promesas": ["PROMESAS", "PROMESA", "FOLDER_PROMESAS", "CARPETA_PROMESAS", "ID_CARPETA_PROMESAS"],
        "pagos": ["PAGOS", "PAGO", "FOLDER_PAGOS", "CARPETA_PAGOS", "ID_CARPETA_PAGOS"],
    }.get(kind, [])

    if not candidates:
        log = _log_append(log, f"CONFIG · kind desconocido: {kind}")
        return None, log

    # Busca filas por SettingID/UNICODE
    hits = []
    for _, r in df.iterrows():
        sid = str(r.get("SettingID","")).upper()
        uni = str(r.get("UNICODE","")).upper()
        if any(c.upper() in sid or c.upper() in uni for c in candidates):
            hits.append(r)

    # Extrae ID desde Parameters/Estructuras/IndiceEstructuras
    for r in hits:
        for col in ["Parameters", "Estructuras", "IndiceEstructuras", "ArbolHeuristico"]:
            val = str(r.get(col, "")).strip()
            if val:
                fid = _extract_folder_id_from_cell(val)
                if fid:
                    log = _log_append(log, f"CONFIG · {kind} folder_id={fid} (source={col}, SettingID={r.get('SettingID','')})")
                    return fid, log

    log = _log_append(log, f"CONFIG · {kind} folder_id NO ENCONTRADO en SettingID.  Revisa Config_SinergIA.")
    return None, log


# Wrappers que tu SinergIA0735 ya está llamando
def get_rutinas_folder_id():
    fid, _ = sinergia_get_folder_id("rutinas", log="")
    return fid

