# SinergIA0500 - RunContext + audit_events + manifest (evidencia por corrida)
import os
import json
import uuid
from datetime import datetime
from typing import Any, Dict, Optional

RUNS_BASE_DIR = os.environ.get("SINERGIA_RUNS_DIR", "/content/sinergia_runs")


def _sinergia_now_iso() -> str:
    return datetime.now().isoformat(timespec="seconds")


def _sinergia_json_safe(x: Any) -> Any:
    try:
        import numpy as np
        import pandas as pd
        if isinstance(x, (np.integer,)):
            return int(x)
        if isinstance(x, (np.floating,)):
            return float(x)
        if isinstance(x, (np.bool_,)):
            return bool(x)
        if isinstance(x, (pd.Timestamp,)):
            return x.isoformat()
    except Exception:
        pass
    if isinstance(x, (datetime,)):
        return x.isoformat()
    if isinstance(x, (set,)):
        return list(x)
    return x


def _sinergia_deep_set(d: Dict[str, Any], path: str, value: Any) -> None:
    """
    path estilo: "inputs.rutina.rows" o "gates.export_gestion.status"
    """
    cur = d
    parts = [p for p in str(path).split(".") if p.strip()]
    for p in parts[:-1]:
        if p not in cur or not isinstance(cur[p], dict):
            cur[p] = {}
        cur = cur[p]
    cur[parts[-1]] = value


def sinergia_guess_file_name(file_obj: Any) -> str:
    """
    Mejor esfuerzo para mostrar en manifest.
    """
    if file_obj is None:
        return ""
    if isinstance(file_obj, (str, os.PathLike)):
        return os.path.basename(str(file_obj))
    if isinstance(file_obj, dict):
        p = file_obj.get("path") or file_obj.get("name") or ""
        return os.path.basename(str(p)) if p else ""
    name = getattr(file_obj, "name", "") or ""
    return os.path.basename(str(name)) if name else ""


SINERGIA_EVIDENCE_SCHEMA_VERSION = "2026-01-02.01"


class SinergIA_RunContext:
    def __init__(self, action: str, meta: Optional[Dict[str, Any]] = None, base_dir: str = RUNS_BASE_DIR):
        self.run_id = f"{datetime.now().strftime('%Y%m%d_%H%M%S')}_{uuid.uuid4().hex[:10]}"
        self.action = str(action)
        self.started_at = _sinergia_now_iso()
        self.base_dir = base_dir
        self.dir = os.path.join(self.base_dir, self.run_id)
        os.makedirs(self.dir, exist_ok=True)

        self.events: list[dict] = []
        self.manifest: dict = {
            # Core
            "schema_version": SINERGIA_EVIDENCE_SCHEMA_VERSION,
            "run_id": self.run_id,
            "action": self.action,
            "started_at": self.started_at,
            "ended_at": None,
            "status": None,  # OK | FAIL | BLOCKED | ABORTED

            # Contexto
            "meta": meta or {},
            "environment": {},          # ej: {"host": "...", "user": "...", "python": "..."}
            "config": {},               # ej: {"setting_id": "...", "archivo_logico": "..."}
            "modo_degradado": False,
            "degradado_reasons": [],

            # Evidencia por etapa
            "inputs": {},
            "metrics": {},
            "gates": {},
            "outputs": {},

            # Resumen final (se completa en finalize)
            "summary": {},
        }

        # Evidencia mínima de selección de corrida (sin logs, solo manifest)
        try:
            env = self.manifest.get("environment")
            if not isinstance(env, dict):
                env = {}
                self.manifest["environment"] = env
            env.setdefault("runs_base_dir", self.base_dir)
            env.setdefault("run_dir", self.dir)

            cfg = self.manifest.get("config")
            if not isinstance(cfg, dict):
                cfg = {}
                self.manifest["config"] = cfg
            cfg.setdefault("latest_run_dir_policy", "AUTO_PICK_LATEST_VALID")
        except Exception:
            pass

    def add_event(
        self,
        code: str,
        level: str = "INFO",
        message: str = "",
        data: Optional[Dict[str, Any]] = None,
        etapa: str = "RUNTIME",
        stage: Optional[str] = None,   # compat: algunos callers usan "stage"
    ) -> None:
        etapa_final = str(stage or etapa or "RUNTIME")
        ev = {
            "ts": _sinergia_now_iso(),
            "run_id": self.run_id,
            "etapa": etapa_final,       # canónico
            "stage": etapa_final,       # compat hacia atrás
            "code": str(code),
            "level": str(level).upper(),
            "message": str(message),
            "data": data or {},
        }
        self.events.append(ev)

    def set_manifest(self, path: str, value: Any) -> None:
        _sinergia_deep_set(self.manifest, path, value)

    def mark_degraded(self, reason: str, *, stage: str = "RUNTIME", data: Optional[Dict[str, Any]] = None) -> None:
        # No destructivo: activa degradación y acumula razones únicas
        self.manifest["modo_degradado"] = True
        rs = self.manifest.get("degradado_reasons") or []
        r = str(reason or "").strip()
        if r and r not in rs:
            rs.append(r)
        self.manifest["degradado_reasons"] = rs
        # Evento explícito
        self.add_event(
            code="DEGRADED_MODE",
            level="WARNING",
            message=r or "modo_degradado=True",
            data=data or {},
            etapa=str(stage or "RUNTIME"),
        )

    def write_audit_events(self) -> None:
        jsonl_path = os.path.join(self.dir, "audit_events.jsonl")
        with open(jsonl_path, "w", encoding="utf-8") as f:
            for ev in self.events:
                safe_ev = json.loads(json.dumps(ev, default=_sinergia_json_safe))
                f.write(json.dumps(safe_ev, ensure_ascii=False) + "\n")

        # CSV simple (para BI/QA rápido)
        csv_path = os.path.join(self.dir, "audit_events.csv")
        try:
            import csv
            with open(csv_path, "w", newline="", encoding="utf-8") as f:
                w = csv.writer(f)
                w.writerow(["ts", "run_id", "etapa", "code", "level", "message"])
                for ev in self.events:
                    w.writerow([
                        ev.get("ts", ""),
                        ev.get("run_id", ""),
                        ev.get("etapa", ""),
                        ev.get("code", ""),
                        ev.get("level", ""),
                        ev.get("message", ""),
                    ])
        except Exception:
            pass

    def write_manifest(self) -> None:
        manifest_path = os.path.join(self.dir, "manifest.json")
        safe_manifest = json.loads(json.dumps(self.manifest, default=_sinergia_json_safe))
        with open(manifest_path, "w", encoding="utf-8") as f:
            json.dump(safe_manifest, f, ensure_ascii=False, indent=2)

    def finalize(self, status: str) -> None:
        # Nunca debe romper.  Siempre intenta escribir evidencia.
        try:
            self.manifest["ended_at"] = _sinergia_now_iso()
            self.manifest["status"] = str(status)

            # Summary determinístico (sin logs ruidosos)
            levels: Dict[str, int] = {}
            stages: Dict[str, int] = {}
            for ev in self.events:
                lv = str(ev.get("level", "INFO")).upper()
                levels[lv] = levels.get(lv, 0) + 1
                st = str(ev.get("etapa") or ev.get("stage") or "RUNTIME")
                stages[st] = stages.get(st, 0) + 1

            gates = self.manifest.get("gates") or {}
            gates_ok = sum(1 for _, v in gates.items() if isinstance(v, dict) and v.get("ok") is True)
            gates_fail = sum(1 for _, v in gates.items() if isinstance(v, dict) and v.get("ok") is False)

            self.manifest["summary"] = {
                "events_total": int(len(self.events)),
                "events_by_level": levels,
                "events_by_stage": stages,
                "gates_ok": int(gates_ok),
                "gates_fail": int(gates_fail),
                "modo_degradado": bool(self.manifest.get("modo_degradado", False)),
                "degradado_reasons": list(self.manifest.get("degradado_reasons") or []),
            }
        except Exception:
            pass

        # Persistencia (best-effort)
        try:
            self.write_audit_events()
        except Exception:
            pass
        try:
            self.write_manifest()
        except Exception:
            pass


def sinergia_new_run_context(action: str, meta: Optional[Dict[str, Any]] = None) -> SinergIA_RunContext:
    return SinergIA_RunContext(action=action, meta=meta or {})

# SinergIA0600 - Contratos de datasets + PR_05 wiring mínimo (df_base_cobranza)
import os
import json
import hashlib
import pandas as pd
from typing import Any, Dict, Optional, Tuple


def _sinergia_pick_col(df: pd.DataFrame, candidates: list[str]) -> str:
    for c in candidates:
        if c in df.columns:
            return c
    return ""


def sinergia_contract_from_estructuras(
    df_estructuras: pd.DataFrame,
    archivo_logico: str,
    sistema: str = "SinergIA",
) -> Dict[str, Any]:
    """
    Construye contrato canónico desde Config_SinergIA/Estructuras (sin transcripción manual).
    Contrato = orden + nombres + tipos (según Estructuras).  Falla si Estructuras no tiene el archivo.
    """
    if df_estructuras is None or getattr(df_estructuras, "empty", True):
        raise ValueError("Estructuras vacío.  No se puede construir contrato.")

    c_sistema = _sinergia_pick_col(df_estructuras, ["Sistema", "sistema"])
    c_archivo = _sinergia_pick_col(df_estructuras, ["ArchivoLogico", "Archivo Lógico", "archivo_logico"])
    c_orden = _sinergia_pick_col(df_estructuras, ["ColumnaOrden", "Orden", "columna_orden"])
    c_nombre = _sinergia_pick_col(df_estructuras, ["NombreColumna", "Nombre Columna", "nombre_columna"])
    c_tipo = _sinergia_pick_col(df_estructuras, ["TipoDato", "Tipo Dato", "tipo_dato"])
    c_oblig = _sinergia_pick_col(df_estructuras, ["Obligatoria", "obligatoria"])

    required_cols = [c_sistema, c_archivo, c_orden, c_nombre, c_tipo, c_oblig]
    if any(not x for x in required_cols):
        raise ValueError(f"Estructuras no tiene columnas mínimas esperadas.  Faltan: {required_cols}")

    dff = df_estructuras.copy()
    dff[c_sistema] = dff[c_sistema].astype(str)
    dff[c_archivo] = dff[c_archivo].astype(str)

    dff = dff[(dff[c_sistema].str.upper() == str(sistema).upper()) &
              (dff[c_archivo].str.upper() == str(archivo_logico).upper())].copy()

    if dff.empty:
        raise ValueError(f"No existe contrato en Estructuras para ArchivoLogico='{archivo_logico}' (Sistema='{sistema}').")

    # Orden canónico
    dff[c_orden] = pd.to_numeric(dff[c_orden], errors="coerce")
    dff = dff.sort_values(c_orden, kind="mergesort")

    cols_ordered = dff[c_nombre].astype(str).tolist()
    tipos = dff[c_tipo].astype(str).tolist()
    oblig = dff[c_oblig].astype(str).str.upper().tolist()

    required = [c for c, o in zip(cols_ordered, oblig) if o == "SI"]

    payload = [{"i": i + 1, "col": c, "tipo": t, "req": (c in required)}
               for i, (c, t) in enumerate(zip(cols_ordered, tipos))]

    schema_bytes = json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
    schema_hash = hashlib.sha256(schema_bytes).hexdigest()[:12]
    contract_id = f"{archivo_logico}@{schema_hash}"

    return {
        "archivo_logico": archivo_logico,
        "sistema": sistema,
        "contract_id": contract_id,
        "schema_hash": schema_hash,
        "columns_ordered": cols_ordered,
        "types_ordered": tipos,
        "required_columns": required,
        "payload": payload,
    }


def sinergia_validate_df_against_contract(
    df: pd.DataFrame,
    contract: Dict[str, Any],
    *,
    strict_required: bool = True,
    sample_for_typecheck: int = 2000,
) -> Dict[str, Any]:
    """
    Validador: esquema + chequeos suaves de tipo (no muta df).
    Falla fuerte: faltan columnas requeridas.  Tipos: reporta % coerción inválida (WARN).
    """
    cols_expected = contract["columns_ordered"]
    cols_required = set(contract["required_columns"])

    present = set(df.columns.tolist())
    missing_any = [c for c in cols_expected if c not in present]
    missing_required = [c for c in cols_expected if (c in cols_required and c not in present)]
    extra = [c for c in df.columns.tolist() if c not in set(cols_expected)]

    ok_schema = (len(missing_required) == 0) if strict_required else (len(missing_any) == 0)

    # type check suave (muestra)
    df_s = df.head(int(sample_for_typecheck)).copy()
    type_stats = {"numeric_invalid_rate": {}, "date_invalid_rate": {}}

    # Mapa col -> tipo (según payload)
    tipo_map = {x["col"]: str(x["tipo"]).strip().lower() for x in contract["payload"]}

    for c in cols_expected:
        if c not in df_s.columns:
            continue
        t = tipo_map.get(c, "")
        if "numero" in t:
            s = pd.to_numeric(df_s[c], errors="coerce")
            invalid = float(s.isna().mean())
            type_stats["numeric_invalid_rate"][c] = invalid
        elif "fecha" in t:
            # dayfirst=True por patrones reales (DD/MM/YYYY) en histórico
            s = pd.to_datetime(df_s[c], errors="coerce", dayfirst=True)
            invalid = float(s.isna().mean())
            type_stats["date_invalid_rate"][c] = invalid

    return {
        "ok": bool(ok_schema),
        "missing_required": missing_required,
        "missing_any": missing_any,
        "extra_columns": extra,
        "typecheck": type_stats,
    }


def sinergia_pr05_wiring_minimo(
    df_rutina: pd.DataFrame,
    log: str = "",
    *,
    meta: Optional[Dict[str, Any]] = None,
    df_estructuras: Optional[pd.DataFrame] = None,
    archivo_logico_base: str = "IN_SISTECREDITO",
    sample_rows: int = 200,
) -> Tuple[pd.DataFrame, str, "SinergIA_RunContext"]:
    """
    PR_05: construye df_base_cobranza (vía pipeline Rutina→IN ya existente),
    valida contrato con Estructuras, y deja evidencia (manifest + audit_events + sample CSV).
    No exporta Gestion.  No altera la lógica existente.
    """
    rc = sinergia_new_run_context("PR_05_WIRING_MIN", meta=meta or {})
    rc.add_event("PR_05_START", message="Inicio PR_05 wiring mínimo.", data={"archivo_logico_base": archivo_logico_base})

    # 1) Construcción canónica del DF base (usa tu pipeline estable)
    df_base, log = run_pipeline_rutina_to_in_full(df_rutina=df_rutina, log=log)

    # 2) Cargar Estructuras (si no viene inyectado)
    if df_estructuras is None:
        try:
            df_estructuras, log = _get_cfg_estructuras(log)
        except Exception as e:
            df_estructuras = pd.DataFrame()
            log = _log_append(log, f"PR_05_WARN · No se pudo cargar Estructuras: {e}")

    if df_estructuras is None or getattr(df_estructuras, "empty", True):
        rc.add_event("PR_05_FAIL", level="ERROR", message="Estructuras vacío.  No se puede validar contrato.")
        rc.set_manifest("gates.PR_05", {"ok": False, "reason": "CONFIG_ESTRUCTURAS_MISSING"})
        rc.finalize("FAIL")
        raise ValueError("PR_05 FAIL: no se pudo cargar Estructuras (Config_SinergIA).")

    # 3) Contrato + validación
    contract = sinergia_contract_from_estructuras(df_estructuras, archivo_logico_base)
    report = sinergia_validate_df_against_contract(df_base, contract)

    # 4) Evidencia (manifest + sample)
    rc.set_manifest("inputs.rutina_rows", int(len(df_rutina)))
    rc.set_manifest("metrics.PR_05.df_base_rows", int(len(df_base)))
    rc.set_manifest("metrics.PR_05.df_base_cols", int(df_base.shape[1]))
    rc.set_manifest("metrics.PR_05.contract_id", contract["contract_id"])
    rc.set_manifest("metrics.PR_05.schema_hash", contract["schema_hash"])
    rc.set_manifest("metrics.PR_05.validation", report)

    # Sample controlado (no DF completo)
    n = int(min(sample_rows, len(df_base)))
    sample_path = os.path.join(rc.dir, f"df_base_cobranza_sample_{n}.csv")
    try:
        df_base.head(n).to_csv(sample_path, index=False, encoding="utf-8")
        rc.set_manifest("outputs.df_base_cobranza_sample", os.path.basename(sample_path))
    except Exception as e:
        rc.add_event("PR_05_WARN", level="WARN", message=f"No se pudo escribir sample CSV: {e}")

    ok = bool(report.get("ok", False))
    rc.set_manifest("gates.PR_05", {"ok": ok, "missing_required": report.get("missing_required", [])})

    if ok:
        rc.add_event("PR_05_OK", message="df_base_cobranza validado contra contrato.", data={"rows": int(len(df_base)), "contract_id": contract["contract_id"]})
        rc.finalize("OK")
        log = _log_append(log, f"PR_05_OK · run_id={rc.run_id} · rows={len(df_base)} · contract={contract['contract_id']} · run_dir={rc.dir}")
    else:
        rc.add_event("PR_05_FAIL", level="ERROR", message="Contrato no cumple (faltan requeridas).", data=report)
        rc.finalize("FAIL")
        log = _log_append(log, f"PR_05_FAIL · run_id={rc.run_id} · missing_required={len(report.get('missing_required',[]))} · run_dir={rc.dir}")

    return df_base, log, rc


