# SinergIA0610 - Contratos internos (df_scored/df_bolsas/df_elegibles/df_excluidos/df_listas_por_canal/df_export_final)
#
# Objetivo: contratos estrictos y reportes de calidad por etapa.  No muta DataFrames.
# REGLA: df_base_cobranza debe fallar si cambia el esquema (set u orden) vs contrato IN_SISTECREDITO.

from copy import deepcopy


def _sinergia_tipo_norm(t: str) -> str:
    t = str(t or "").strip().lower()
    if "texto" in t or "string" in t or t == "str":
        return "texto"
    if "numero" in t or "num" in t or "int" in t or "float" in t:
        return "numero"
    if "fecha" in t or "date" in t or "datetime" in t:
        return "fecha"
    if "bool" in t or "boolean" in t:
        return "bool"
    return t


def sinergia_contract_make(
    dataset_name: str,
    columns: list[tuple[str, str, bool]],
    *,
    sistema: str = "SinergIA_Cobros",
) -> Dict[str, Any]:
    """
    Crea un contrato interno con el mismo formato del contrato de Estructuras.
    columns: [(col, tipo, requerida_bool), ...] en orden canónico.
    """
    cols_ordered = [c for c, _, _ in columns]
    tipos = [t for _, t, _ in columns]
    required = [c for c, _, req in columns if bool(req)]

    payload = [
        {"i": i + 1, "col": c, "tipo": t, "req": (c in required)}
        for i, (c, t) in enumerate(zip(cols_ordered, tipos))
    ]

    schema_bytes = json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
    schema_hash = hashlib.sha256(schema_bytes).hexdigest()[:12]
    contract_id = f"{dataset_name}@{schema_hash}"

    return {
        "archivo_logico": dataset_name,
        "sistema": sistema,
        "contract_id": contract_id,
        "schema_hash": schema_hash,
        "columns_ordered": cols_ordered,
        "types_ordered": tipos,
        "required_columns": required,
        "payload": payload,
        "internal": True,
        "derived_from": "",
    }


def sinergia_contract_extend(
    base_contract: Dict[str, Any],
    dataset_name: str,
    add_columns: list[tuple[str, str, bool]],
    *,
    make_added_required_strict: bool = True,
) -> Dict[str, Any]:
    """
    Extiende un contrato base (layout) agregando columnas internas al final.
    add_columns: [(col, tipo, requerida_bool), ...]
    """
    c = deepcopy(base_contract)
    cols_ordered = list(c.get("columns_ordered", []))
    tipos = list(c.get("types_ordered", []))
    required = list(c.get("required_columns", []))
    payload = list(c.get("payload", []))

    for col, tipo, req in add_columns:
        col = str(col).strip()
        tipo = str(tipo).strip()
        if not col:
            continue
        if col in cols_ordered:
            continue
        cols_ordered.append(col)
        tipos.append(tipo)
        if bool(req) and make_added_required_strict:
            required.append(col)
        payload.append({"i": len(payload) + 1, "col": col, "tipo": tipo, "req": bool(req)})

    schema_bytes = json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
    schema_hash = hashlib.sha256(schema_bytes).hexdigest()[:12]
    contract_id = f"{dataset_name}@{schema_hash}"

    return {
        **c,
        "archivo_logico": dataset_name,
        "contract_id": contract_id,
        "schema_hash": schema_hash,
        "columns_ordered": cols_ordered,
        "types_ordered": tipos,
        "required_columns": required,
        "payload": payload,
        "internal": True,
        "derived_from": str(base_contract.get("contract_id", "")),
    }


def sinergia_internal_contracts_build(
    df_estructuras: pd.DataFrame,
    *,
    sistema: str = "SinergIA_Cobros",
) -> Dict[str, Any]:
    """
    Retorna contratos internos por dataset.
    Notas:
      - df_base_cobranza: estrictamente IN_SISTECREDITO (set + orden).
      - df_listas_por_canal: contratos layout DIGITAL_* por canal.
    """
    c_base = sinergia_contract_from_estructuras(df_estructuras, "IN_SISTECREDITO", sistema=sistema)
    c_teleton = sinergia_contract_from_estructuras(df_estructuras, "TELETON", sistema=sistema)
    c_sms = sinergia_contract_from_estructuras(df_estructuras, "DIGITAL_SMS", sistema=sistema)
    c_wa = sinergia_contract_from_estructuras(df_estructuras, "DIGITAL_WHATSAPP", sistema=sistema)
    c_wise = sinergia_contract_from_estructuras(df_estructuras, "DIGITAL_WISE", sistema=sistema)

    c_scored = sinergia_contract_extend(
        c_base,
        "DF_SCORED",
        add_columns=[
            ("_score_rules", "Numero", True),
        ],
    )

    c_bolsas = sinergia_contract_extend(
        c_teleton,
        "DF_BOLSAS",
        add_columns=[
            ("Bolsa", "Texto", True),
            ("MotivoBolsa", "Texto", True),
            ("PrioridadEnBolsa", "Numero", False),
        ],
    )

    c_compliance = sinergia_contract_extend(
        c_bolsas,
        "DF_COMPLIANCE",
        add_columns=[
            ("compliance_eval_ok", "Bool", True),
            ("exclusion_reason_code", "Texto", True),
            ("exclusion_reason_detail", "Texto", False),
            ("canal_afectado", "Texto", False),
        ],
    )

    def _export_final_from_layout(layout_contract: Dict[str, Any], name: str) -> Dict[str, Any]:
        return sinergia_contract_extend(
            layout_contract,
            name,
            add_columns=[
                ("run_id", "Texto", True),
                ("dt_generacion", "Fecha", True),
                ("config_version", "Texto", False),
            ],
        )

    return {
        "layout.IN_SISTECREDITO": c_base,
        "layout.TELETON": c_teleton,
        "layout.DIGITAL_SMS": c_sms,
        "layout.DIGITAL_WHATSAPP": c_wa,
        "layout.DIGITAL_WISE": c_wise,
        "df_base_cobranza": c_base,
        "df_scored": c_scored,
        "df_bolsas": c_bolsas,
        "df_compliance": c_compliance,
        "df_listas_por_canal": {
            "SMS": c_sms,
            "WHATSAPP": c_wa,
            "WISE": c_wise,
        },
        "df_export_final": {
            "SMS": _export_final_from_layout(c_sms, "DF_EXPORT_FINAL_SMS"),
            "WHATSAPP": _export_final_from_layout(c_wa, "DF_EXPORT_FINAL_WHATSAPP"),
            "WISE": _export_final_from_layout(c_wise, "DF_EXPORT_FINAL_WISE"),
        },
    }


def _sinergia_schema_strict_check(df: pd.DataFrame, contract: Dict[str, Any]) -> Dict[str, Any]:
    expected = list(contract.get("columns_ordered", []))
    got = list(df.columns.tolist())
    extra = [c for c in got if c not in expected]
    missing_any = [c for c in expected if c not in got]
    order_ok = (got == expected)
    return {
        "order_ok": bool(order_ok),
        "missing_any": missing_any,
        "extra_cols": extra,
        "expected_cols": len(expected),
        "got_cols": len(got),
    }


def sinergia_contract_quality_report(
    df: pd.DataFrame,
    contract: Dict[str, Any],
    *,
    stage: str = "",
    rc: Optional["SinergIA_RunContext"] = None,
    strict_schema: bool = False,
    strict_order: bool = False,
    strict_required: bool = True,
    sample_for_typecheck: int = 2000,
) -> Dict[str, Any]:
    """
    Reporte de contrato + calidad.  Puede fallar duro si strict_schema/strict_order.
    Retorna dict con: ok, missing_required, schema(order/missing/extra), type_stats, null_rates_required_top.
    """
    base = sinergia_validate_df_against_contract(
        df,
        contract,
        strict_required=strict_required,
        sample_for_typecheck=sample_for_typecheck,
    )

    schema = _sinergia_schema_strict_check(df, contract)

    ok = bool(base.get("ok", False))
    if strict_schema and (schema["missing_any"] or schema["extra_cols"]):
        ok = False
    if strict_order and not schema["order_ok"]:
        ok = False

    req = list(contract.get("required_columns", []))
    null_rates = {}
    if req:
        for c in req:
            if c in df.columns:
                null_rates[c] = float(pd.isna(df[c]).mean())
    null_rates_top = dict(sorted(null_rates.items(), key=lambda kv: kv[1], reverse=True)[:15])

    report = {
        **base,
        "ok": bool(ok),
        "stage": stage,
        "schema": schema,
        "null_rates_required_top": null_rates_top,
        "contract_id": contract.get("contract_id", ""),
    }

    if rc is not None:
        try:
            rc.set_manifest(f"contracts.{stage}.{contract.get('archivo_logico','')}.report", report)
            rc.add_event(
                code="CONTRACT_REPORT",
                level="INFO" if ok else "ERROR",
                message=f"Contrato {contract.get('archivo_logico','')} ok={ok}",
                data={
                    "contract_id": contract.get("contract_id", ""),
                    "missing_required": report.get("missing_required", []),
                    "schema": report.get("schema", {}),
                },
                etapa=stage,
            )
        except Exception:
            pass

    return report

# SinergIA0700 - PR_06 Teletón + Bolsas (wiring mínimo, contract-driven, degradable)
from datetime import datetime
from typing import Optional, Dict, Any, Tuple, List
import os
import unicodedata
import pandas as pd

def _sinergia_month_es(m: int) -> str:
    meses = ["Ene","Feb","Mar","Abr","May","Jun","Jul","Ago","Sep","Oct","Nov","Dic"]
    m = int(m)
    return meses[m-1] if 1 <= m <= 12 else str(m)

def _pick_col_any(df: pd.DataFrame, candidates: List[str]) -> str:
    for c in candidates:
        if c in df.columns:
            return c
    return ""

def _ensure_cols(df: pd.DataFrame, cols: List[str], fill_value=None) -> pd.DataFrame:
    out = df.copy()
    for c in cols:
        if c not in out.columns:
            out[c] = fill_value
    return out

def _norm_col(s: str) -> str:
    s = "" if s is None else str(s)
    s = unicodedata.normalize("NFKD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    s = s.strip().lower()
    s = s.replace("_", " ")
    s = " ".join(s.split())
    return s

def _find_contract_col(tele_cols: List[str], wanted: str) -> str:
    """Encuentra el nombre real de columna en tele_cols usando normalización (maneja acentos)."""
    w = _norm_col(wanted)
    for c in tele_cols:
        if _norm_col(c) == w:
            return c
    return ""  # no existe en contrato

def sinergia_pr06_build_teleton_y_bolsas_min(
    df_base_cobranza: pd.DataFrame,
    log: str = "",
    *,
    meta: Optional[Dict[str, Any]] = None,
    rc: Optional["SinergIA_RunContext"] = None,
    df_estructuras: Optional[pd.DataFrame] = None,
    sample_rows: int = 0,
) -> Tuple[pd.DataFrame, pd.DataFrame, str, "SinergIA_RunContext"]:
    """
    PR_06 mínimo:
    - Teleton_General: agrega por Documento (conteos y totales) y respeta contrato TELETON de Config.
    - Bolsas: dataset interno simple (no es export), reproducible, derivado de Teleton_General.
    Degradable: si faltan columnas, deja campos opcionales en null y registra modo_degradado.
    Nota: si rc viene desde afuera, NO finaliza el rc (para no romper PR_08 u otros).
    """
    meta = meta or {}
    own_rc = False
    if rc is None:
        rc = sinergia_new_run_context("PR_06_TELETON_BOLSAS_MIN", meta=meta)
        own_rc = True

    rc.add_event("PR_06_START", message="Inicio PR_06 (Teletón+Bolsas) wiring mínimo.", etapa="PR_06")

    # Corte (obligatorio en TELETON: Año, Mes)
    now = datetime.now()
    ano = int(meta.get("corte_ano") or now.year)
    mes = str(meta.get("corte_mes") or _sinergia_month_es(now.month))

    # Base vacía
    if df_base_cobranza is None or getattr(df_base_cobranza, "empty", True):
        rc.set_manifest("modo_degradado", True)
        rc.set_manifest("degradado_reasons", ["BASE_EMPTY"])
        rc.add_event("PR_06_FAIL", level="ERROR", message="df_base_cobranza vacío.  PR_06 no ejecutable.", etapa="PR_06")
        rc.set_manifest("gates.PR_06", {"ok": False, "reason": "BASE_EMPTY"})
        df_tele = pd.DataFrame()
        df_bolsas = pd.DataFrame()
        if own_rc:
            rc.finalize("FAIL")
        log = _log_append(log, f"PR_06_FAIL · run_id={rc.run_id} · reason=BASE_EMPTY · run_dir={rc.dir}")
        return df_tele, df_bolsas, log, rc

    # Estructuras
    if df_estructuras is None:
        try:
            df_estructuras, log = _get_cfg_estructuras(log)
        except Exception as e:
            df_estructuras = pd.DataFrame()
            log = _log_append(log, f"PR_06_WARN · No se pudo cargar Estructuras: {e}")

    if df_estructuras is None or getattr(df_estructuras, "empty", True):
        rc.set_manifest("modo_degradado", True)
        rc.set_manifest("degradado_reasons", ["CONFIG_ESTRUCTURAS_MISSING"])
        rc.add_event("PR_06_FAIL", level="ERROR", message="Estructuras vacío.  No se puede construir contrato TELETON.", etapa="PR_06")
        rc.set_manifest("gates.PR_06", {"ok": False, "reason": "CONFIG_ESTRUCTURAS_MISSING"})
        df_tele = pd.DataFrame()
        df_bolsas = pd.DataFrame()
        if own_rc:
            rc.finalize("FAIL")
        log = _log_append(log, f"PR_06_FAIL · run_id={rc.run_id} · reason=CONFIG_ESTRUCTURAS_MISSING · run_dir={rc.dir}")
        return df_tele, df_bolsas, log, rc

    teleton_contract = sinergia_contract_from_estructuras(df_estructuras, "TELETON")
    tele_cols = list(teleton_contract.get("columns_ordered") or [])

    # Mapeo a nombres reales del contrato (maneja acentos y variaciones)
    col_doc     = _find_contract_col(tele_cols, "Documento de identidad") or "Documento de identidad"
    col_ano     = _find_contract_col(tele_cols, "Año") or "Año"
    col_mes     = _find_contract_col(tele_cols, "Mes") or "Mes"
    col_cntcred = _find_contract_col(tele_cols, "# Creditos") or "# Creditos"
    col_saldo   = _find_contract_col(tele_cols, "Saldo Total") or "Saldo Total"
    col_maxdias = _find_contract_col(tele_cols, "Max Dias Mora") or "Max Dias Mora"
    col_franja  = _find_contract_col(tele_cols, "Franja") or "Franja"
    col_tel1    = _find_contract_col(tele_cols, "Telefono 1") or _find_contract_col(tele_cols, "Teléfono 1") or "Telefono 1"
    col_tel2    = _find_contract_col(tele_cols, "Telefono 2") or _find_contract_col(tele_cols, "Teléfono 2") or "Telefono 2"
    col_tel3    = _find_contract_col(tele_cols, "Telefono 3") or _find_contract_col(tele_cols, "Teléfono 3") or "Telefono 3"
    col_tel4    = _find_contract_col(tele_cols, "Telefono 4") or _find_contract_col(tele_cols, "Teléfono 4") or "Telefono 4"
    col_prio    = _find_contract_col(tele_cols, "Prioridad") or "Prioridad"
    col_cargar  = _find_contract_col(tele_cols, "Cargar")
    col_tipoc   = _find_contract_col(tele_cols, "Tipo de carga")

    # Columnas base mínimas (fuente)
    c_doc   = _pick_col_any(df_base_cobranza, ["Documento de identidad","DocumentoDeIdentidad","Identificacion","Identificación"])
    c_cred  = _pick_col_any(df_base_cobranza, ["Crédito","Credito","CreditNumber"])
    c_saldo = _pick_col_any(df_base_cobranza, ["Saldo Total","SaldoTotal"])
    c_dias  = _pick_col_any(df_base_cobranza, ["Días en Mora","Dias en Mora","DiasMora","DíasMora"])
    c_fran  = _pick_col_any(df_base_cobranza, ["Franja"])
    c_tel1s = _pick_col_any(df_base_cobranza, ["Telefono 1","Teléfono 1","Telefono1"])
    c_tel2s = _pick_col_any(df_base_cobranza, ["Telefono 2","Teléfono 2","Telefono2"])
    c_tel3s = _pick_col_any(df_base_cobranza, ["Telefono 3","Teléfono 3","Telefono3"])
    c_tel4s = _pick_col_any(df_base_cobranza, ["Telefono 4","Teléfono 4","Telefono4"])
    c_prios = _pick_col_any(df_base_cobranza, ["IN_PRIORIDAD","Prioridad"])

    missing_min = [k for k in ["DOC","CRED","SALDO","DIAS","FRANJA"] if not {
        "DOC": c_doc, "CRED": c_cred, "SALDO": c_saldo, "DIAS": c_dias, "FRANJA": c_fran
    }[k]]

    if missing_min:
        rc.set_manifest("modo_degradado", True)
        rc.set_manifest("degradado_reasons", [f"BASE_MISSING_{'_'.join(missing_min)}"])
        rc.add_event("PR_06_WARN", level="WARN", message="Base sin columnas mínimas.  Teletón se degradará.", etapa="PR_06")

    # Agregación determinística por Documento: representante = mayor Días en Mora (estable)
    dfb = df_base_cobranza.copy()
    if c_doc:
        dfb[c_doc] = dfb[c_doc].astype(str)

    if c_doc and c_dias:
        dfb["_tmp_dias"] = pd.to_numeric(dfb[c_dias], errors="coerce").fillna(-1)
        df_rep = (
            dfb.sort_values([c_doc, "_tmp_dias"], ascending=[True, False], kind="mergesort")
               .drop_duplicates(subset=[c_doc], keep="first")
        )
    else:
        df_rep = dfb.head(0).copy()

    # Métricas por Documento
    s_cnt = (dfb.groupby(c_doc, sort=False)[c_cred].nunique(dropna=True).rename(col_cntcred)
             if (c_doc and c_cred) else pd.Series(dtype="float64", name=col_cntcred))

    s_saldo = (pd.to_numeric(dfb[c_saldo], errors="coerce").groupby(dfb[c_doc], sort=False).sum(min_count=1).rename(col_saldo)
               if (c_doc and c_saldo) else pd.Series(dtype="float64", name=col_saldo))

    s_maxdias = (pd.to_numeric(dfb[c_dias], errors="coerce").groupby(dfb[c_doc], sort=False).max().rename(col_maxdias)
                 if (c_doc and c_dias) else pd.Series(dtype="float64", name=col_maxdias))

    # Construcción TELETON (con nombres reales del contrato)
    if c_doc and (not df_rep.empty):
        df_tele = pd.DataFrame({col_doc: df_rep[c_doc].astype(str)})
    else:
        df_tele = pd.DataFrame({col_doc: pd.Series(dtype="object")})

    df_tele[col_ano] = ano
    df_tele[col_mes] = mes

    if not s_cnt.empty:
        df_tele = df_tele.merge(s_cnt.reset_index().rename(columns={c_doc: col_doc}), on=col_doc, how="left")
    if not s_saldo.empty:
        df_tele = df_tele.merge(s_saldo.reset_index().rename(columns={c_doc: col_doc}), on=col_doc, how="left")
    if not s_maxdias.empty:
        df_tele = df_tele.merge(s_maxdias.reset_index().rename(columns={c_doc: col_doc}), on=col_doc, how="left")

    # Representativos (franja/telefonos/prioridad) desde df_rep
    rep_cols = []
    if c_doc:   rep_cols.append(c_doc)
    if c_fran:  rep_cols.append(c_fran)
    if c_tel1s: rep_cols.append(c_tel1s)
    if c_tel2s: rep_cols.append(c_tel2s)
    if c_tel3s: rep_cols.append(c_tel3s)
    if c_tel4s: rep_cols.append(c_tel4s)
    if c_prios: rep_cols.append(c_prios)

    if c_doc and c_fran and (not df_rep.empty) and len(rep_cols) >= 2:
        df_rep2 = df_rep[rep_cols].copy()
        ren = {c_doc: col_doc, c_fran: col_franja}
        if c_tel1s: ren[c_tel1s] = col_tel1
        if c_tel2s: ren[c_tel2s] = col_tel2
        if c_tel3s: ren[c_tel3s] = col_tel3
        if c_tel4s: ren[c_tel4s] = col_tel4
        if c_prios: ren[c_prios] = col_prio
        df_rep2 = df_rep2.rename(columns=ren)
        df_tele = df_tele.merge(df_rep2, on=col_doc, how="left")

    # Completar columnas faltantes del contrato TELETON
    if tele_cols:
        df_tele = _ensure_cols(df_tele, tele_cols, fill_value=None)

    # Defaults mínimos Infinivirt (opcionales)
    if col_cargar and col_cargar in df_tele.columns and df_tele[col_cargar].isna().all():
        df_tele[col_cargar] = 1
    if col_tipoc and col_tipoc in df_tele.columns and df_tele[col_tipoc].isna().all():
        df_tele[col_tipoc] = "AUTO"

    # Reordenar exacto
    if tele_cols:
        df_tele = df_tele[tele_cols].copy()

    # Validación contrato TELETON (requeridas)
    report = sinergia_validate_df_against_contract(df_tele, teleton_contract, strict_required=True)
    rc.set_manifest("metrics.PR_06.teleton_rows", int(len(df_tele)))
    rc.set_manifest("metrics.PR_06.teleton_cols", int(df_tele.shape[1]) if hasattr(df_tele, "shape") else 0)
    rc.set_manifest("metrics.PR_06.teleton_contract_id", teleton_contract.get("contract_id"))
    rc.set_manifest("metrics.PR_06.teleton_validation", report)

    ok = bool(report.get("ok", False))
    rc.set_manifest("gates.PR_06", {"ok": ok, "missing_required": report.get("missing_required", [])})

    # Bolsas internas mínimas (dataset interno, no export)
    # Si no hay columnas esperadas, queda vacío pero estable.
    try:
        s_doc = df_tele[col_doc].astype(str) if col_doc in df_tele.columns else pd.Series(dtype="object")
        s_fra = df_tele[col_franja].astype(str) if col_franja in df_tele.columns else pd.Series(dtype="object")
        df_bolsas = pd.DataFrame({
            col_doc: s_doc,
            "Bolsa": s_fra.replace({"nan": "SIN_FRANJA"}).map(lambda x: f"TELETON_{x}"),
            col_prio: pd.to_numeric(df_tele.get(col_prio), errors="coerce"),
            col_saldo: pd.to_numeric(df_tele.get(col_saldo), errors="coerce"),
            col_maxdias: pd.to_numeric(df_tele.get(col_maxdias), errors="coerce"),
        })
    except Exception:
        df_bolsas = pd.DataFrame()

    rc.set_manifest("metrics.PR_06.bolsas_rows", int(len(df_bolsas)) if hasattr(df_bolsas, "__len__") else 0)
    rc.set_manifest("metrics.PR_06.bolsas_unique", int(df_bolsas["Bolsa"].nunique(dropna=True)) if ("Bolsa" in df_bolsas.columns) else 0)

    # Evidencia sample (opcional).  sample_rows=0 => no crea archivos extra.
    if int(sample_rows or 0) > 0:
        n = int(min(sample_rows, len(df_tele)))
        try:
            df_tele.head(n).to_csv(os.path.join(rc.dir, f"teleton_general_sample_{n}.csv"), index=False, encoding="utf-8")
            rc.set_manifest("outputs.teleton_general_sample", f"teleton_general_sample_{n}.csv")
        except Exception as e:
            rc.add_event("PR_06_WARN", level="WARN", message=f"No se pudo escribir sample teleton: {e}", etapa="PR_06")

    if ok:
        rc.add_event("PR_06_OK", message="Teletón y Bolsas generados (mínimo) y validados.", data={"rows": int(len(df_tele))}, etapa="PR_06")
        log = _log_append(log, f"PR_06_OK · run_id={rc.run_id} · teleton_rows={len(df_tele)} · bolsas={df_bolsas['Bolsa'].nunique() if 'Bolsa' in df_bolsas.columns else 0} · run_dir={rc.dir}")
        if own_rc:
            rc.finalize("OK")
    else:
        rc.add_event("PR_06_FAIL", level="ERROR", message="Contrato TELETON no cumple (faltan requeridas).", data=report, etapa="PR_06")
        log = _log_append(log, f"PR_06_FAIL · run_id={rc.run_id} · missing_required={len(report.get('missing_required',[]))} · run_dir={rc.dir}")
        if own_rc:
            rc.finalize("FAIL")

    return df_tele, df_bolsas, log, rc

# SinergIA0900 - PR_04 BaseDataset Contract + Gate (df_base_cobranza)  Alias=IN_SISTECREDITO si no existe BASE_COBRANZA.

from typing import Optional, Dict, Any, Tuple

def sinergia_pr04_resolve_base_structure(df_estructuras: "pd.DataFrame") -> str:
    """
    Fuente de contrato para df_base_cobranza.
    Orden: BASE_COBRANZA (si existe) → IN_SISTECREDITO (fallback canónico actual).
    """
    if df_estructuras is None or getattr(df_estructuras, "empty", True):
        raise ValueError("PR_04_BASE: df_estructuras vacío.  No se puede resolver contrato.")

    candidates = ["BASE_COBRANZA", "IN_SISTECREDITO"]
    for name in candidates:
        if "ArchivoLogico" in df_estructuras.columns and (df_estructuras["ArchivoLogico"] == name).any():
            return name

    raise ValueError("PR_04_BASE: No existe estructura BASE_COBRANZA ni IN_SISTECREDITO en Config_SinergIA/Estructuras.")

def sinergia_pr04_validate_base_cobranza(
    df_base_cobranza: "pd.DataFrame",
    log: str = "",
    *,
    rc: Optional["SinergIA_RunContext"] = None,
    meta: Optional[Dict[str, Any]] = None,
    df_estructuras: Optional["pd.DataFrame"] = None,
) -> Tuple[Dict[str, Any], str, "SinergIA_RunContext"]:
    """
    Gate PR_04_BASE:
    Valida df_base_cobranza contra contrato (BASE_COBRANZA si existe, si no IN_SISTECREDITO).
    Es estricto.  Si cambia el contrato, falla y deja evidencia en manifest.
    """
    meta = meta or {}

    # Guardrails de dependencias canónicas (ya existen en el sistema por PR_06)
    required = ["_get_cfg_estructuras", "sinergia_contract_from_estructuras", "sinergia_validate_df_against_contract", "_log_append", "sinergia_new_run_context"]
    missing = [n for n in required if n not in globals() or not callable(globals().get(n))]
    if missing:
        raise RuntimeError(f"PR_04_BASE ABORT.  Faltan definiciones en memoria: {missing}")

    if rc is None:
        rc = sinergia_new_run_context("PR_04_BASE_VALIDATE", meta=meta)

    rc.add_event("PR_04_BASE_START", message="Inicio PR_04_BASE (contrato df_base_cobranza).", etapa="PR_04")

    if df_estructuras is None:
        df_estructuras, log = _get_cfg_estructuras(log)

    base_struct = sinergia_pr04_resolve_base_structure(df_estructuras)
    base_contract = sinergia_contract_from_estructuras(df_estructuras, base_struct)

    report = sinergia_validate_df_against_contract(df_base_cobranza, base_contract, strict_required=True)
    ok = bool(report.get("ok", False))

    rc.set_manifest("metrics.PR_04.base_shape", list(getattr(df_base_cobranza, "shape", (None, None))))
    rc.set_manifest("metrics.PR_04.base_struct_source", base_struct)
    rc.set_manifest("metrics.PR_04.base_contract_id", base_contract.get("contract_id"))
    rc.set_manifest("metrics.PR_04.base_validation", report)
    rc.set_manifest("gates.PR_04_BASE", {"ok": ok, "missing_required": report.get("missing_required", [])})

    if ok:
        rc.add_event("PR_04_BASE_OK", message=f"PR_04_BASE OK.  Contrato fuente={base_struct}.", etapa="PR_04")
        log = _log_append(log, f"PR_04_BASE_OK · fuente={base_struct} · shape={getattr(df_base_cobranza,'shape',None)}")
    else:
        rc.add_event("PR_04_BASE_FAIL", level="ERROR", message=f"PR_04_BASE FAIL.  Contrato fuente={base_struct}.", data=report, etapa="PR_04")
        log = _log_append(log, f"PR_04_BASE_FAIL · fuente={base_struct} · missing_required={len(report.get('missing_required',[]))}")

    return report, log, rc

# SinergIA1200 - PR_07 ComplianceGate mínimo (Ley 2300: días sin llamada + exclusiones básicas)
from typing import Optional, Dict, Any, Tuple, List
from datetime import datetime, date
import os
import pandas as pd

def _rc_safe_add_event(rc, code: str, *, message: str, etapa: str = "PR_07", level: str = "INFO", data: Optional[dict] = None):
    try:
        if rc is not None and hasattr(rc, "add_event") and callable(getattr(rc, "add_event")):
            rc.add_event(code, level=level, message=message, data=data, etapa=etapa)
    except Exception:
        pass

def _rc_safe_set_manifest(rc, key: str, value: Any):
    try:
        if rc is not None and hasattr(rc, "set_manifest") and callable(getattr(rc, "set_manifest")):
            rc.set_manifest(key, value)
        elif rc is not None and hasattr(rc, "manifest") and isinstance(getattr(rc, "manifest"), dict):
            # set dotted key en dict simple
            d = rc.manifest
            parts = str(key).split(".")
            cur = d
            for p in parts[:-1]:
                if p not in cur or not isinstance(cur[p], dict):
                    cur[p] = {}
                cur = cur[p]
            cur[parts[-1]] = value
    except Exception:
        pass

def _pick_col_any(df: pd.DataFrame, candidates: List[str]) -> str:
    for c in candidates:
        if c in df.columns:
            return c
    return ""

def _parse_dt_series(s: pd.Series) -> pd.Series:
    # robusto.  dayfirst=True para DD/MM/YYYY típico.
    out = pd.to_datetime(s, errors="coerce", dayfirst=True, utc=False)
    try:
        out = out.dt.tz_localize(None)
    except Exception:
        pass
    return out

def _cfg_get_dias_no_llamada(df_params: pd.DataFrame, default_val: int = 4) -> Tuple[int, bool]:
    """
    Lee Restriccion / Dias_NoLlamada desde Config.  Retorna (valor, usado_fallback).
    """
    try:
        if df_params is None or getattr(df_params, "empty", True):
            return int(default_val), True
        c_param = _pick_col_any(df_params, ["Parametro", "PARÁMETRO", "PARAMETRO"])
        c_name  = _pick_col_any(df_params, ["Nombre", "NOMBRE"])
        c_desde = _pick_col_any(df_params, ["Desde", "DESDE"])
        if not (c_param and c_name and c_desde):
            return int(default_val), True

        mask = (df_params[c_param].astype(str).str.strip().eq("Restriccion")) & (df_params[c_name].astype(str).str.strip().eq("Dias_NoLlamada"))
        row = df_params.loc[mask]
        if row.empty:
            return int(default_val), True

        v = row.iloc[0][c_desde]
        v = int(float(v)) if v is not None and str(v).strip() != "" else int(default_val)
        return v, False
    except Exception:
        return int(default_val), True

def _build_last_contact_index(
    df_base_cobranza: pd.DataFrame,
    *,
    df_mejorgest_log: Optional[pd.DataFrame] = None,
    df_traza: Optional[pd.DataFrame] = None,
) -> Tuple[pd.Series, Dict[str, Any]]:
    """
    Retorna una Serie indexada por documento con last_contact_dt (max).
    También retorna debug_info con fuentes usadas.
    """
    debug = {"source": None, "rows_used": 0, "doc_col": "", "dt_col": ""}

    # 1) Desde base (si ya trae fecha última gestión)
    c_doc = _pick_col_any(df_base_cobranza, ["Documento de identidad","DocumentoDeIdentidad","Identificacion","Identificación","IN_DOCUMENTO_DE_IDENTIDAD"])
    c_dt  = _pick_col_any(df_base_cobranza, ["Fecha Ult Contacto","Fecha Último Contacto","Fecha Mejor Gest","Fecha Gestion","Fecha Gestión","UltimaGestion","Última Gestión"])
    if c_doc and c_dt:
        tmp = df_base_cobranza[[c_doc, c_dt]].copy()
        tmp[c_doc] = tmp[c_doc].astype(str)
        tmp["_dt"] = _parse_dt_series(tmp[c_dt])
        s = tmp.groupby(c_doc, sort=False)["_dt"].max()
        debug.update({"source": "BASE", "rows_used": int(len(tmp)), "doc_col": c_doc, "dt_col": c_dt})
        return s, debug

    # 2) Desde MejorGest Log (si está disponible)
    if df_mejorgest_log is not None and not getattr(df_mejorgest_log, "empty", True):
        c_doc2 = _pick_col_any(df_mejorgest_log, ["IN_DOCUMENTO_DE_IDENTIDAD","Documento de identidad","Documento Clte","Documento","Identificacion","Identificación"])
        c_dt2  = _pick_col_any(df_mejorgest_log, ["Fecha Mejor Gest","Fecha Ult Contacto","Fecha Último Contacto","Fecha Contacto","Fecha Gestion","Fecha Gestión"])
        if c_doc2 and c_dt2:
            tmp = df_mejorgest_log[[c_doc2, c_dt2]].copy()
            tmp[c_doc2] = tmp[c_doc2].astype(str)
            tmp["_dt"] = _parse_dt_series(tmp[c_dt2])
            s = tmp.groupby(c_doc2, sort=False)["_dt"].max()
            debug.update({"source": "MEJORGEST_LOG", "rows_used": int(len(tmp)), "doc_col": c_doc2, "dt_col": c_dt2})
            return s, debug

    # 3) Desde TRAZA (si está disponible)
    if df_traza is not None and not getattr(df_traza, "empty", True):
        c_doc3 = _pick_col_any(df_traza, ["IN_DOCUMENTO_DE_IDENTIDAD","Documento de identidad","Documento","Identificacion","Identificación"])
        c_dt3  = _pick_col_any(df_traza, ["CAP_FECHA","Fecha","Fecha Gestion","Fecha Gestión","FechaContacto"])
        if c_doc3 and c_dt3:
            tmp = df_traza[[c_doc3, c_dt3]].copy()
            tmp[c_doc3] = tmp[c_doc3].astype(str)
            tmp["_dt"] = _parse_dt_series(tmp[c_dt3])
            s = tmp.groupby(c_doc3, sort=False)["_dt"].max()
            debug.update({"source": "TRAZA", "rows_used": int(len(tmp)), "doc_col": c_doc3, "dt_col": c_dt3})
            return s, debug

    return pd.Series(dtype="datetime64[ns]"), debug

def sinergia_pr07_compliance_gate_min(
    df_base_cobranza: pd.DataFrame,
    log: str = "",
    *,
    rc: Optional["SinergIA_RunContext"] = None,
    meta: Optional[Dict[str, Any]] = None,
    df_params: Optional[pd.DataFrame] = None,
    df_mejorgest_log: Optional[pd.DataFrame] = None,
    df_traza: Optional[pd.DataFrame] = None,
    corte_date: Optional[str] = None,  # "YYYY-MM-DD".  Si None, usa hoy.
    strict_no_history: bool = True,    # Si no hay historia, gate FAIL y excluye todo (modo real).
    dev_override_allow_pass: bool = False,  # Solo para construir listas sin datos de historia.  Queda marcado en manifest.
    sample_rows: int = 0,
) -> Tuple[pd.DataFrame, pd.DataFrame, str, "SinergIA_RunContext"]:
    """
    PR_07 mínimo (ComplianceGate):
      - Regla Ley 2300 (días sin llamada): excluye si last_contact < dias_no_llamada.
      - Exclusión opt-out si existe alguna columna booleana en base.
      - Si no hay forma de evaluar last_contact y strict_no_history=True: gate FAIL (STOP).
    Salida:
      df_elegibles, df_excluidos (con código/razón), log, rc
    """
    meta = meta or {}
    own_rc = False
    if rc is None:
        rc = sinergia_new_run_context("PR_07_COMPLIANCE_MIN", meta=meta)
        own_rc = True

    _rc_safe_add_event(rc, "PR_07_START", message="Inicio PR_07 ComplianceGate mínimo.", etapa="PR_07")

    # Params
    if df_params is None:
        try:
            df_params, log = _get_cfg_params(log)  # función canónica existente
        except Exception:
            df_params = pd.DataFrame()

    dias_no_llamada, used_fallback = _cfg_get_dias_no_llamada(df_params, default_val=4)
    _rc_safe_set_manifest(rc, "metrics.PR_07.dias_no_llamada", int(dias_no_llamada))
    _rc_safe_set_manifest(rc, "metrics.PR_07.dias_no_llamada_used_fallback", bool(used_fallback))

    # Corte date
    if corte_date:
        corte_dt = pd.to_datetime(corte_date, errors="coerce")
        if pd.isna(corte_dt):
            corte_dt = pd.Timestamp.today().normalize()
    else:
        corte_dt = pd.Timestamp.today().normalize()
    _rc_safe_set_manifest(rc, "metrics.PR_07.corte_date", str(corte_dt.date()))

    # Doc col base
    c_doc = _pick_col_any(df_base_cobranza, ["Documento de identidad","DocumentoDeIdentidad","Identificacion","Identificación","IN_DOCUMENTO_DE_IDENTIDAD"])
    if not c_doc:
        # No se puede ni indexar exclusiones.  Gate FAIL.
        _rc_safe_set_manifest(rc, "metrics.PR_07.compliance_eval_ok", 0)
        _rc_safe_set_manifest(rc, "gates.PR_07", {"ok": False, "reason": "BASE_MISSING_DOC"})
        _rc_safe_add_event(rc, "PR_07_FAIL", level="ERROR", message="Falta Documento en df_base_cobranza.", etapa="PR_07")
        if own_rc:
            try: rc.finalize("FAIL")
            except Exception: pass
        raise ValueError("PR_07 FAIL: df_base_cobranza sin columna Documento.")

    dfw = df_base_cobranza.copy()
    dfw[c_doc] = dfw[c_doc].astype(str)

    # Opt-out simple si existe
    c_opt = _pick_col_any(dfw, ["OPT_OUT","OptOut","NO_CONTACTAR","NoContactar","EXCLUSION","Exclusion","Ley2300_OptOut"])
    opt_mask = pd.Series(False, index=dfw.index)
    if c_opt:
        opt_mask = dfw[c_opt].astype(str).str.strip().str.upper().isin(["1","TRUE","VERDADERO","SI","SÍ","YES","Y"])

    # Last contact index
    s_last, dbg = _build_last_contact_index(dfw, df_mejorgest_log=df_mejorgest_log, df_traza=df_traza)
    _rc_safe_set_manifest(rc, "metrics.PR_07.last_contact_source", dbg.get("source"))
    _rc_safe_set_manifest(rc, "metrics.PR_07.last_contact_rows_used", dbg.get("rows_used"))
    _rc_safe_set_manifest(rc, "metrics.PR_07.last_contact_doc_col", dbg.get("doc_col"))
    _rc_safe_set_manifest(rc, "metrics.PR_07.last_contact_dt_col", dbg.get("dt_col"))

    # Si no hay historia
    if s_last.empty and strict_no_history and not dev_override_allow_pass:
        df_ex = dfw[[c_doc]].copy()
        df_ex["PR_07_EXCLUSION_CODE"] = "EXCL_NO_HISTORY"
        df_ex["PR_07_EXCLUSION_REASON"] = "Sin fuente de historial de contacto para evaluar Ley 2300."
        df_el = dfw.head(0).copy()

        _rc_safe_set_manifest(rc, "metrics.PR_07.eligible_rows", int(len(df_el)))
        _rc_safe_set_manifest(rc, "metrics.PR_07.excluded_rows", int(len(df_ex)))
        _rc_safe_set_manifest(rc, "metrics.PR_07.reasons_counts", {"EXCL_NO_HISTORY": int(len(df_ex))})
        _rc_safe_set_manifest(rc, "metrics.PR_07.compliance_eval_ok", 0)
        _rc_safe_set_manifest(rc, "gates.PR_07", {"ok": False, "reason": "NO_CONTACT_HISTORY"})

        _rc_safe_add_event(rc, "PR_07_FAIL", level="ERROR", message="Sin historial de contacto.  ComplianceGate bloquea export.", etapa="PR_07")
        if int(sample_rows or 0) > 0:
            n = int(min(sample_rows, len(df_ex)))
            try:
                df_ex.head(n).to_csv(os.path.join(rc.dir, f"compliance_exclusions_sample_{n}.csv"), index=False, encoding="utf-8")
                _rc_safe_set_manifest(rc, "outputs.PR_07.exclusions_sample", f"compliance_exclusions_sample_{n}.csv")
            except Exception:
                pass

        if own_rc:
            try: rc.finalize("FAIL")
            except Exception: pass
        log = _log_append(log, f"PR_07_FAIL · no_history · excluded={len(df_ex)} · run_dir={rc.dir}")
        return df_el, df_ex, log, rc

    # Join last contact to base (por documento)
    if not s_last.empty:
        map_last = s_last.to_dict()
        dfw["_last_contact_dt"] = dfw[c_doc].map(map_last)
    else:
        dfw["_last_contact_dt"] = pd.NaT

    # Días desde último contacto.  NaT => elegible (no contacto registrado).
    days_since = (corte_dt - dfw["_last_contact_dt"]).dt.days
    recent_mask = (days_since.notna()) & (days_since < int(dias_no_llamada))

    # Excluidos
    excl_mask = opt_mask | recent_mask

    df_ex = dfw.loc[excl_mask, [c_doc]].copy()
    df_el = dfw.loc[~excl_mask, :].copy()

    # Razones codificadas
    df_ex["PR_07_EXCLUSION_CODE"] = "EXCL_UNKNOWN"
    df_ex["PR_07_EXCLUSION_REASON"] = ""

    if c_opt:
        m = dfw.loc[excl_mask, c_doc].index.intersection(dfw.index[opt_mask])
        df_ex.loc[m, "PR_07_EXCLUSION_CODE"] = "EXCL_OPT_OUT"
        df_ex.loc[m, "PR_07_EXCLUSION_REASON"] = "Opt-out / No contactar."

    m2 = dfw.loc[excl_mask, c_doc].index.intersection(dfw.index[recent_mask])
    df_ex.loc[m2, "PR_07_EXCLUSION_CODE"] = "EXCL_RECENT_CONTACT"
    df_ex.loc[m2, "PR_07_EXCLUSION_REASON"] = f"Contacto reciente dentro de {int(dias_no_llamada)} días."

    # Métricas
    reasons = df_ex["PR_07_EXCLUSION_CODE"].value_counts(dropna=False).to_dict()
    _rc_safe_set_manifest(rc, "metrics.PR_07.eligible_rows", int(len(df_el)))
    _rc_safe_set_manifest(rc, "metrics.PR_07.excluded_rows", int(len(df_ex)))
    _rc_safe_set_manifest(rc, "metrics.PR_07.reasons_counts", {str(k): int(v) for k, v in reasons.items()})

    # Gate OK
    # Si llegamos aquí, pudimos evaluar (o dev_override_allow_pass=True).
    ok_gate = True
    if dev_override_allow_pass and s_last.empty:
        _rc_safe_set_manifest(rc, "modo_degradado", True)
        _rc_safe_set_manifest(rc, "degradado_reasons", ["DEV_OVERRIDE_NO_HISTORY"])
        _rc_safe_set_manifest(rc, "metrics.PR_07.dev_override_allow_pass", True)

    _rc_safe_set_manifest(rc, "metrics.PR_07.compliance_eval_ok", 1)
    _rc_safe_set_manifest(rc, "gates.PR_07", {"ok": ok_gate})

    # Evidencia sample (opcional)
    if int(sample_rows or 0) > 0 and len(df_ex) > 0:
        n = int(min(sample_rows, len(df_ex)))
        try:
            df_ex.head(n).to_csv(os.path.join(rc.dir, f"compliance_exclusions_sample_{n}.csv"), index=False, encoding="utf-8")
            _rc_safe_set_manifest(rc, "outputs.PR_07.exclusions_sample", f"compliance_exclusions_sample_{n}.csv")
        except Exception:
            pass

    _rc_safe_add_event(rc, "PR_07_OK", message="ComplianceGate mínimo aplicado.", etapa="PR_07", data={"eligible": int(len(df_el)), "excluded": int(len(df_ex))})
    if own_rc:
        try: rc.finalize("OK")
        except Exception: pass

    log = _log_append(log, f"PR_07_OK · eligible={len(df_el)} excluded={len(df_ex)} · run_dir={rc.dir}")
    return df_el, df_ex, log, rc

# SinergIA1300 - PR_03.5 Enrich Base with Contact History (Gestion_Log/MejorGest) (wiring mínimo)

from typing import Optional, Dict, Any, Tuple, List
import pandas as pd

def _sinergia_resolve_value(x) -> str:
    if isinstance(x, str) and x.strip():
        return x.strip()
    v = getattr(x, "value", None)
    if isinstance(v, str) and v.strip():
        return v.strip()
    return ""

def _sinergia_pick_col_any(df: pd.DataFrame, candidates: List[str]) -> str:
    for c in candidates:
        if c in df.columns:
            return c
    return ""

def _sinergia_parse_dt(s: pd.Series) -> pd.Series:
    out = pd.to_datetime(s, errors="coerce", dayfirst=True, utc=False)
    try:
        out = out.dt.tz_localize(None)
    except Exception:
        pass
    return out

def _rc_add(rc, code: str, message: str, *, etapa: str = "PR_03_5", level: str = "INFO", data: Optional[dict] = None):
    try:
        if rc is not None and hasattr(rc, "add_event") and callable(getattr(rc, "add_event")):
            rc.add_event(code, level=level, message=message, data=data, etapa=etapa)
    except Exception:
        pass

def _rc_set(rc, key: str, val: Any):
    try:
        if rc is not None and hasattr(rc, "set_manifest") and callable(getattr(rc, "set_manifest")):
            rc.set_manifest(key, val)
            return
        if rc is not None and hasattr(rc, "manifest") and isinstance(getattr(rc, "manifest"), dict):
            d = rc.manifest
            parts = str(key).split(".")
            cur = d
            for p in parts[:-1]:
                if p not in cur or not isinstance(cur[p], dict):
                    cur[p] = {}
                cur = cur[p]
            cur[parts[-1]] = val
    except Exception:
        pass

def sinergia_pr035_enrich_base_with_contact_history(
    df_base_cobranza: pd.DataFrame,
    log: str = "",
    *,
    rc: Optional["SinergIA_RunContext"] = None,
    dd_archivo_gestion: Optional[Any] = None,
    file_gestion_local: Any = None,
    max_rows_gestion: int = 5000,
    out_col_last_contact: str = "Fecha Ult Contacto",
) -> Tuple[pd.DataFrame, str, "SinergIA_RunContext"]:
    """
    Enriquecimiento mínimo para que PR_07 pueda evaluar Ley 2300.
    Fuente principal: DF_GESTION_CACHE (si existe).  Si no existe, intenta cargar preview Gestion_Log desde Drive.
    Resultado: agrega out_col_last_contact a df_base_cobranza (por Documento, max fecha).
    """
    if rc is None:
        rc = sinergia_new_run_context("PR_03_5_ENRICH_HISTORY", meta={"max_rows_gestion": int(max_rows_gestion)})

    _rc_add(rc, "PR_03_5_START", "Inicio enrich base con historial (Gestion_Log).")

    # Documento base
    c_doc_base = _sinergia_pick_col_any(df_base_cobranza, ["Documento de identidad","DocumentoDeIdentidad","Identificacion","Identificación","IN_DOCUMENTO_DE_IDENTIDAD"])
    if not c_doc_base:
        _rc_set(rc, "gates.PR_03_5", {"ok": False, "reason": "BASE_MISSING_DOC"})
        _rc_add(rc, "PR_03_5_FAIL", "Base sin columna Documento.  No se puede enriquecer.", level="ERROR")
        raise ValueError("PR_03_5 FAIL: df_base_cobranza sin Documento.")

    df_out = df_base_cobranza.copy()
    df_out[c_doc_base] = df_out[c_doc_base].astype(str)

    # Resolver Gestion DF
    df_gestion = globals().get("DF_GESTION_CACHE", None)
    gestion_source = "DF_GESTION_CACHE"

    if df_gestion is None or not isinstance(df_gestion, pd.DataFrame) or df_gestion.empty:
        # Intentar cargar desde GUI si existen componentes
        if dd_archivo_gestion is None:
            dd_archivo_gestion = globals().get("dd_archivo_gestion", None)
        if file_gestion_local is None:
            file_gestion_local = globals().get("file_gestion_local", None)

        gestion_name = _sinergia_resolve_value(dd_archivo_gestion)
        if gestion_name or (file_gestion_local is not None):
            try:
                df_gestion, log = _load_gestion_any_source(
                    dd_archivo_gestion=gestion_name if gestion_name else None,
                    file_gestion_local=file_gestion_local,
                    log=log,
                    max_rows=int(max_rows_gestion),
                )
                globals()["DF_GESTION_CACHE"] = df_gestion.copy() if isinstance(df_gestion, pd.DataFrame) else None
                gestion_source = "LOAD_GESTION_PREVIEW"
            except Exception as e:
                df_gestion = pd.DataFrame()
                gestion_source = "GESTION_LOAD_FAIL"
                log = _log_append(log, f"PR_03_5_WARN · no_gestion_loaded · {e}")

    # Si sigue sin Gestion, marcar y salir dejando NaT
    if df_gestion is None or not isinstance(df_gestion, pd.DataFrame) or df_gestion.empty:
        df_out[out_col_last_contact] = pd.NaT
        _rc_set(rc, "metrics.PR_03_5.gestion_source", gestion_source)
        _rc_set(rc, "metrics.PR_03_5.gestion_rows", 0)
        _rc_set(rc, "metrics.PR_03_5.gestion_unique_docs", 0)
        _rc_set(rc, "metrics.PR_03_5.matched_docs", 0)
        _rc_set(rc, "gates.PR_03_5", {"ok": False, "reason": "NO_GESTION_HISTORY"})
        _rc_add(rc, "PR_03_5_WARN", "No hay Gestion_Log disponible.  Se deja Fecha Ult Contacto en NaT.", level="WARN")
        log = _log_append(log, "PR_03_5_WARN · no_history_source · Fecha Ult Contacto=NaT")
        return df_out, log, rc

    # Columnas Gestion: documento y fecha de gestión
    c_doc_gestion = _sinergia_pick_col_any(df_gestion, ["IN_DOCUMENTO_DE_IDENTIDAD","Documento de identidad","Documento","Documento Clte","Identificacion","Identificación"])
    c_dt_gestion  = _sinergia_pick_col_any(df_gestion, ["Fecha Mejor Gest","Fecha Ult Contacto","Fecha Último Contacto","Fecha Gestion","Fecha Gestión","Fecha Contacto"])

    _rc_set(rc, "metrics.PR_03_5.gestion_source", gestion_source)
    _rc_set(rc, "metrics.PR_03_5.gestion_doc_col", c_doc_gestion)
    _rc_set(rc, "metrics.PR_03_5.gestion_dt_col", c_dt_gestion)
    _rc_set(rc, "metrics.PR_03_5.gestion_rows", int(len(df_gestion)))

    if not (c_doc_gestion and c_dt_gestion):
        df_out[out_col_last_contact] = pd.NaT
        _rc_set(rc, "gates.PR_03_5", {"ok": False, "reason": "GESTION_MISSING_COLS"})
        _rc_add(rc, "PR_03_5_WARN", "Gestion_Log no tiene columnas esperadas (doc/fecha).  Se deja NaT.", level="WARN")
        log = _log_append(log, "PR_03_5_WARN · gestion_missing_cols · Fecha Ult Contacto=NaT")
        return df_out, log, rc

    # Agregación determinística: max fecha por documento
    tmp = df_gestion[[c_doc_gestion, c_dt_gestion]].copy()
    tmp[c_doc_gestion] = tmp[c_doc_gestion].astype(str)
    tmp["_dt"] = _sinergia_parse_dt(tmp[c_dt_gestion])
    s_last = tmp.groupby(c_doc_gestion, sort=False)["_dt"].max()

    gestion_unique = int(s_last.index.nunique())
    _rc_set(rc, "metrics.PR_03_5.gestion_unique_docs", gestion_unique)

    # Join hacia base
    df_out[out_col_last_contact] = df_out[c_doc_base].map(s_last.to_dict())

    matched = int(df_out[out_col_last_contact].notna().sum())
    _rc_set(rc, "metrics.PR_03_5.base_rows", int(len(df_out)))
    _rc_set(rc, "metrics.PR_03_5.base_unique_docs", int(df_out[c_doc_base].nunique(dropna=True)))
    _rc_set(rc, "metrics.PR_03_5.matched_docs", matched)
    _rc_set(rc, "metrics.PR_03_5.matched_ratio", float(matched / max(1, len(df_out))))

    _rc_set(rc, "gates.PR_03_5", {"ok": True})
    _rc_add(rc, "PR_03_5_OK", "Historial integrado a base (Fecha Ult Contacto).", data={"matched": matched, "gestion_unique_docs": gestion_unique})

    log = _log_append(log, f"PR_03_5_OK · history_source={gestion_source} · matched_docs={matched}/{len(df_out)}")
    return df_out, log, rc

# SinergIA1400 - HOTFIX PR_07: "all-NaT" cuenta como NO_HISTORY (evita false-positive)
import pandas as pd

def _build_last_contact_index(
    df_base_cobranza: pd.DataFrame,
    *,
    df_mejorgest_log: pd.DataFrame | None = None,
    df_traza: pd.DataFrame | None = None,
):
    """
    Retorna Serie indexada por documento con last_contact_dt (max).
    Hotfix: si la serie es all-NaT => se considera NO_HISTORY y se intenta la siguiente fuente.
    """
    debug = {"source": None, "rows_used": 0, "doc_col": "", "dt_col": ""}

    # Usa helpers existentes si están.  Si no, fallback mínimo.
    _pick = globals().get("_pick_col_any", None)
    _parse = globals().get("_parse_dt_series", None)

    def _pick_col(df, candidates):
        if callable(_pick):
            return _pick(df, candidates)
        for c in candidates:
            if c in df.columns:
                return c
        return ""

    def _parse_dt(s):
        if callable(_parse):
            return _parse(s)
        out = pd.to_datetime(s, errors="coerce", dayfirst=True, utc=False)
        try:
            out = out.dt.tz_localize(None)
        except Exception:
            pass
        return out

    def _series_or_empty(tmp, c_doc, c_dt, source_name):
        tmp = tmp[[c_doc, c_dt]].copy()
        tmp[c_doc] = tmp[c_doc].astype(str)
        tmp["_dt"] = _parse_dt(tmp[c_dt])
        s = tmp.groupby(c_doc, sort=False)["_dt"].max()

        # Hotfix clave: si no hay ni un valor válido, no sirve como historial.
        if s.dropna().empty:
            return pd.Series(dtype="datetime64[ns]"), {"source": f"{source_name}_ALL_NAT", "rows_used": int(len(tmp)), "doc_col": c_doc, "dt_col": c_dt}
        return s, {"source": source_name, "rows_used": int(len(tmp)), "doc_col": c_doc, "dt_col": c_dt}

    # 1) Base
    c_doc = _pick_col(df_base_cobranza, ["Documento de identidad","DocumentoDeIdentidad","Identificacion","Identificación","IN_DOCUMENTO_DE_IDENTIDAD"])
    c_dt  = _pick_col(df_base_cobranza, ["Fecha Ult Contacto","Fecha Último Contacto","Fecha Mejor Gest","Fecha Gestion","Fecha Gestión","UltimaGestion","Última Gestión"])
    if c_doc and c_dt:
        s, dbg = _series_or_empty(df_base_cobranza, c_doc, c_dt, "BASE")
        if not s.empty:
            return s, dbg
        debug = dbg  # deja rastro, pero continúa a siguiente fuente.

    # 2) MejorGest_Log
    if df_mejorgest_log is not None and not getattr(df_mejorgest_log, "empty", True):
        c_doc2 = _pick_col(df_mejorgest_log, ["IN_DOCUMENTO_DE_IDENTIDAD","Documento de identidad","Documento Clte","Documento","Identificacion","Identificación"])
        c_dt2  = _pick_col(df_mejorgest_log, ["Fecha Mejor Gest","Fecha Ult Contacto","Fecha Último Contacto","Fecha Contacto","Fecha Gestion","Fecha Gestión"])
        if c_doc2 and c_dt2:
            s, dbg = _series_or_empty(df_mejorgest_log, c_doc2, c_dt2, "MEJORGEST_LOG")
            if not s.empty:
                return s, dbg
            debug = dbg

    # 3) TRAZA
    if df_traza is not None and not getattr(df_traza, "empty", True):
        c_doc3 = _pick_col(df_traza, ["IN_DOCUMENTO_DE_IDENTIDAD","Documento de identidad","Documento","Identificacion","Identificación"])
        c_dt3  = _pick_col(df_traza, ["CAP_FECHA","Fecha","Fecha Gestion","Fecha Gestión","FechaContacto"])
        if c_doc3 and c_dt3:
            s, dbg = _series_or_empty(df_traza, c_doc3, c_dt3, "TRAZA")
            if not s.empty:
                return s, dbg
            debug = dbg

    # Ninguna fuente usable.
    return pd.Series(dtype="datetime64[ns]"), debug

# SinergIA1410
# =========================================================
# PR_03.6 · Builder MejorGest desde TRAZA AWS (mínimo, determinístico)
# Inserta ESTE BLOQUE completo entre:
#   - arriba: fin de SinergIA1400
#   - abajo: inicio de SinergIA1500
# =========================================================

from typing import Optional, Dict, Any, Tuple
from datetime import date
import pandas as pd
import numpy as np

MEJORGEST_LOG_COLS = [
    "IN_DOCUMENTO_DE_IDENTIDAD",
    "Mejor Prioridad",
    "Tipo Contacto",
    "Tipificacion",
    "Nombre BD",
    "Fecha Mejor Gest",
    "Asesor Mejor Gest",
    "Fecha Promesa",
    "Valor Promesa",
    "Canal Mejor Gest",
    "Marcaciones",
    "Rotacion",
    "Fecha 1er Gestion",
    "Tipo Contacto 1er Gest",
    "Tipificacion 1er Gest",
    "Fecha Ult Gestion",
    "Tipo Contacto Ult Gest",
    "Tipificacion Ult Gest",
    "Asesor Ult Gest",
    "Fecha Ult Contacto",
    "Tipo Contacto Ult Contacto",
    "Tipificacion Ult Contacto",
    "Asesor Ult Contacto",
    "Cant Interacciones WS",
    "Dias desde el ult CD",
    "Fecha",
    "Fecha Hoy",
]

MEJORGEST_CONSOL_COLS = [
    "Documento de identidad",
    "Fecha Mes",
    "Mín. de Prioridad",
    "Tipo Contacto",
    "Tipificacion",
    "BD",
]


def _mg__pick_col(df: pd.DataFrame, candidates: list[str]) -> Optional[str]:
    if not isinstance(df, pd.DataFrame) or df.empty:
        return None
    low = {str(c).strip().lower(): c for c in df.columns}
    for c in candidates:
        if c in df.columns:
            return c
        k = str(c).strip().lower()
        if k in low:
            return low[k]
    return None


def _mg__get_arbol_df(cfg_sheets: Optional[Dict[str, Any]] = None) -> pd.DataFrame:
    """
    Intenta obtener ArbolHeuristico desde:
      1) cfg_sheets (si lo pasan)
      2) CFG_SHEETS_COMPONENTS (global)
      3) arbol_load_df() (si existe)
    """
    try:
        if isinstance(cfg_sheets, dict) and "_get_sheet_df_from_components" in globals():
            df = _get_sheet_df_from_components(cfg_sheets, "ArbolHeuristico")
            if isinstance(df, pd.DataFrame) and not df.empty:
                return df
    except Exception:
        pass

    try:
        comp = globals().get("CFG_SHEETS_COMPONENTS")
        if isinstance(comp, dict) and "_get_sheet_df_from_components" in globals():
            df = _get_sheet_df_from_components(comp, "ArbolHeuristico")
            if isinstance(df, pd.DataFrame) and not df.empty:
                return df
    except Exception:
        pass

    try:
        if "arbol_load_df" in globals() and callable(globals().get("arbol_load_df")):
            df = arbol_load_df()
            if isinstance(df, pd.DataFrame) and not df.empty:
                return df
    except Exception:
        pass

    return pd.DataFrame()


def sinergia_build_mejorgest_from_traza_min(
    df_traza: pd.DataFrame,
    *,
    df_base: Optional[pd.DataFrame] = None,
    cfg_sheets: Optional[Dict[str, Any]] = None,
    rc: Optional["SinergIA_RunContext"] = None,
    max_rows: int = 5000,
    today: Optional[date] = None,
) -> Tuple[pd.DataFrame, pd.DataFrame, Dict[str, Any]]:
    """
    Construye:
      - df_mejorgest_log (27 cols canónicas)
      - df_consolidado_totalfuentes (6 cols canónicas)
    Regla determinística:
      - “Mejor” = menor Prioridad (ArbolHeuristico).  Empate: fecha más reciente.
    """
    today = today or date.today()

    def _rc_set(k, v):
        try:
            if hasattr(rc, "set_manifest") and callable(getattr(rc, "set_manifest")):
                rc.set_manifest(k, v)
        except Exception:
            pass

    def _rc_event(code, msg, level="INFO", etapa="PR_03_6", data=None):
        try:
            if hasattr(rc, "add_event") and callable(getattr(rc, "add_event")):
                rc.add_event(code, level=level, message=msg, etapa=etapa, data=data or {})
        except Exception:
            pass

    if not isinstance(df_traza, pd.DataFrame) or df_traza.empty:
        _rc_set("metrics.PR_03_6.rows_in", 0)
        _rc_event("PR_03_6_SKIP", "TRAZA vacía - no se construye MejorGest.")
        return (
            pd.DataFrame(columns=MEJORGEST_LOG_COLS),
            pd.DataFrame(columns=MEJORGEST_CONSOL_COLS),
            {"ok": False, "reason": "TRAZA_EMPTY"},
        )

    work = df_traza.copy()

    c_doc = _mg__pick_col(work, ["IN_DOCUMENTO_DE_IDENTIDAD", "Documento", "Identificacion", "Identificación"])
    c_tipi = _mg__pick_col(work, ["CAP_TIPIFICACION", "COD Tipi", "COD_TIPI"])
    c_dt = _mg__pick_col(work, ["ULTIMA_ACTUALIZACION_FECHA", "CAP_FECHA", "Fecha"])
    c_user = _mg__pick_col(work, ["ULTIMA_ACTUALIZACION_USUARIO", "Asesor", "Usuario"])
    c_mes = _mg__pick_col(work, ["CAP_MES", "Mes"])
    c_ano = _mg__pick_col(work, ["CAP_ANO", "Año", "Ano"])
    c_tel = _mg__pick_col(work, ["CAP_TELEFONO_CONTACTO", "Telefono", "Teléfono"])
    c_fprom = _mg__pick_col(work, ["CAP_FECHA_PROMESA", "Fecha Promesa"])
    c_vprom = _mg__pick_col(work, ["CAP_TOTAL_PAGO", "Valor Promesa", "Valor"])
    c_canal = _mg__pick_col(work, ["CAP_CANAL", "Canal"])

    if not c_doc or not c_tipi or not c_dt:
        _rc_set("metrics.PR_03_6.rows_in", int(len(work)))
        _rc_event(
            "PR_03_6_FAIL",
            "TRAZA sin columnas mínimas (doc/tipificación/fecha).",
            level="ERROR",
            data={"c_doc": c_doc, "c_tipi": c_tipi, "c_dt": c_dt},
        )
        return (
            pd.DataFrame(columns=MEJORGEST_LOG_COLS),
            pd.DataFrame(columns=MEJORGEST_CONSOL_COLS),
            {"ok": False, "reason": "MISSING_COLS"},
        )

    # Recorte determinístico: ordenar por fecha desc y tomar max_rows
    work["_dt"] = pd.to_datetime(work[c_dt], errors="coerce")
    work = work.sort_values("_dt", ascending=False, na_position="last").head(int(max_rows)).copy()

    # Normalizaciones
    work["_doc"] = work[c_doc].astype(str).str.strip()
    work["_cod"] = pd.to_numeric(work[c_tipi], errors="coerce")

    if c_ano and c_mes and (c_ano in work.columns) and (c_mes in work.columns):
        y = pd.to_numeric(work[c_ano], errors="coerce")
        m = pd.to_numeric(work[c_mes], errors="coerce")
        work["_mes"] = pd.to_datetime({"year": y, "month": m, "day": 1}, errors="coerce")
    else:
        work["_mes"] = work["_dt"].dt.to_period("M").dt.to_timestamp()

    # ArbolHeuristico
    ar = _mg__get_arbol_df(cfg_sheets)
    col_cod = _mg__pick_col(ar, ["COD Tipi", "COD_TIPI", "cod tipi"])
    col_tipo = _mg__pick_col(ar, ["Tipo Contacto", "tipo contacto"])
    col_tipif = _mg__pick_col(ar, ["Tipificacion", "tipificacion"])
    col_pri = _mg__pick_col(ar, ["Prioridad", "prioridad"])

    if ar.empty or (not col_cod) or (not col_pri):
        _rc_event("PR_03_6_FAIL", "ArbolHeuristico no disponible - no se puede mapear Prioridad.", level="ERROR")
        return (
            pd.DataFrame(columns=MEJORGEST_LOG_COLS),
            pd.DataFrame(columns=MEJORGEST_CONSOL_COLS),
            {"ok": False, "reason": "ARBOL_MISSING"},
        )

    a = ar[[col_cod, col_pri] + ([col_tipo] if col_tipo else []) + ([col_tipif] if col_tipif else [])].copy()
    a.rename(
        columns={
            col_cod: "_cod",
            col_pri: "_pri",
            (col_tipo or "_x"): "_tipo",
            (col_tipif or "_y"): "_tipi",
        },
        inplace=True,
    )
    a["_cod"] = pd.to_numeric(a["_cod"], errors="coerce")
    a["_pri"] = pd.to_numeric(a["_pri"], errors="coerce")

    mrg = work.merge(a, how="left", on="_cod")

    # BD: EnBD/FueraBD según existencia en df_base
    docs_in_base = set()
    if isinstance(df_base, pd.DataFrame) and not df_base.empty:
        c_doc_base = _mg__pick_col(df_base, ["Documento de identidad", "Documento", "Identificacion", "Identificación", "IN_DOCUMENTO_DE_IDENTIDAD"])
        if c_doc_base:
            docs_in_base = set(df_base[c_doc_base].astype(str).str.strip().tolist())

    mrg["_bd"] = np.where(mrg["_doc"].isin(docs_in_base), "EnBD", "FueraBD")

    # Mejor por (doc, mes): prioridad asc, fecha desc
    mrg_sort = mrg.sort_values(by=["_doc", "_mes", "_pri", "_dt"], ascending=[True, True, True, False], na_position="last")
    best_month = mrg_sort.groupby(["_doc", "_mes"], as_index=False).first()

    df_consol = best_month[["_doc", "_mes", "_pri", "_tipo", "_tipi", "_bd"]].copy()
    df_consol.columns = MEJORGEST_CONSOL_COLS

    # Mejor global por doc
    best = mrg.sort_values(by=["_doc", "_pri", "_dt"], ascending=[True, True, False], na_position="last").groupby("_doc", as_index=False).first()
    first = mrg.sort_values(by=["_doc", "_dt"], ascending=[True, True], na_position="last").groupby("_doc", as_index=False).first()
    last = mrg.sort_values(by=["_doc", "_dt"], ascending=[True, False], na_position="last").groupby("_doc", as_index=False).first()

    # Último contacto: cualquier fila cuyo Tipo Contacto NO contenga “No Contacto”
    m_contact = mrg[~mrg["_tipo"].astype(str).str.lower().str.contains("no contacto", na=False)].copy()
    last_contact = (
        m_contact.sort_values(by=["_doc", "_dt"], ascending=[True, False], na_position="last")
        .groupby("_doc", as_index=False)
        .first()
        if not m_contact.empty
        else pd.DataFrame(columns=["_doc", "_dt", "_tipo", "_tipi"])
    )

    # Conteos
    cnt = mrg.groupby("_doc").size().rename("Marcaciones").reset_index().rename(columns={"_doc": "IN_DOCUMENTO_DE_IDENTIDAD"})
    if c_tel and (c_tel in mrg.columns):
        rot = (
            mrg.groupby("_doc")[c_tel]
            .nunique(dropna=True)
            .rename("Rotacion")
            .reset_index()
            .rename(columns={"_doc": "IN_DOCUMENTO_DE_IDENTIDAD"})
        )
    else:
        rot = pd.DataFrame({"IN_DOCUMENTO_DE_IDENTIDAD": best["_doc"], "Rotacion": np.nan})

    out = pd.DataFrame({"IN_DOCUMENTO_DE_IDENTIDAD": best["_doc"]})
    out["Mejor Prioridad"] = best["_pri"]
    out["Tipo Contacto"] = best["_tipo"]
    out["Tipificacion"] = best["_tipi"]
    out["Nombre BD"] = np.where(out["IN_DOCUMENTO_DE_IDENTIDAD"].astype(str).str.strip().isin(docs_in_base), "EnBD", "FueraBD")

    out["Fecha Mejor Gest"] = pd.to_datetime(best["_dt"], errors="coerce")
    out["Asesor Mejor Gest"] = best[c_user] if (c_user and c_user in best.columns) else np.nan
    out["Fecha Promesa"] = pd.to_datetime(best[c_fprom], errors="coerce") if (c_fprom and c_fprom in best.columns) else pd.NaT
    out["Valor Promesa"] = pd.to_numeric(best[c_vprom], errors="coerce") if (c_vprom and c_vprom in best.columns) else np.nan
    out["Canal Mejor Gest"] = best[c_canal] if (c_canal and c_canal in best.columns) else np.nan

    out = out.merge(cnt, on="IN_DOCUMENTO_DE_IDENTIDAD", how="left")
    out = out.merge(rot, on="IN_DOCUMENTO_DE_IDENTIDAD", how="left")

    out["Fecha 1er Gestion"] = pd.to_datetime(first["_dt"], errors="coerce")
    out["Tipo Contacto 1er Gest"] = first["_tipo"].values
    out["Tipificacion 1er Gest"] = first["_tipi"].values

    out["Fecha Ult Gestion"] = pd.to_datetime(last["_dt"], errors="coerce")
    out["Tipo Contacto Ult Gest"] = last["_tipo"].values
    out["Tipificacion Ult Gest"] = last["_tipi"].values
    out["Asesor Ult Gest"] = last[c_user].values if (c_user and c_user in last.columns) else np.nan

    if not last_contact.empty:
        lc = last_contact[["_doc", "_dt", "_tipo", "_tipi"]].rename(
            columns={
                "_doc": "IN_DOCUMENTO_DE_IDENTIDAD",
                "_dt": "Fecha Ult Contacto",
                "_tipo": "Tipo Contacto Ult Contacto",
                "_tipi": "Tipificacion Ult Contacto",
            }
        )
        out = out.merge(lc, on="IN_DOCUMENTO_DE_IDENTIDAD", how="left")
    else:
        out["Fecha Ult Contacto"] = pd.NaT
        out["Tipo Contacto Ult Contacto"] = np.nan
        out["Tipificacion Ult Contacto"] = np.nan

    out["Asesor Ult Contacto"] = np.nan
    out["Cant Interacciones WS"] = np.nan

    dt_lc = pd.to_datetime(out["Fecha Ult Contacto"], errors="coerce")
    out["Dias desde el ult CD"] = (pd.Timestamp(today) - dt_lc).dt.days
    out.loc[dt_lc.isna(), "Dias desde el ult CD"] = np.nan

    out["Fecha"] = out["Fecha Ult Gestion"]
    out["Fecha Hoy"] = pd.Timestamp(today)

    # Normaliza fechas a date()
    for c in ["Fecha Mejor Gest", "Fecha Promesa", "Fecha 1er Gestion", "Fecha Ult Gestion", "Fecha Ult Contacto", "Fecha", "Fecha Hoy"]:
        out[c] = pd.to_datetime(out[c], errors="coerce").dt.date

    # Asegura columnas canónicas
    for c in MEJORGEST_LOG_COLS:
        if c not in out.columns:
            out[c] = np.nan
    out = out[MEJORGEST_LOG_COLS]

    mapped_ratio = float(pd.to_numeric(mrg["_pri"], errors="coerce").notna().mean()) if len(mrg) else 0.0

    _rc_set("metrics.PR_03_6.rows_in", int(len(df_traza)))
    _rc_set("metrics.PR_03_6.rows_used", int(len(mrg)))
    _rc_set("metrics.PR_03_6.docs", int(len(out)))
    _rc_set("metrics.PR_03_6.consol_rows", int(len(df_consol)))
    _rc_set("metrics.PR_03_6.mapped_ratio", mapped_ratio)
    _rc_event("PR_03_6_OK", "MejorGest construido desde TRAZA (mínimo).", data={"docs": int(len(out)), "mapped_ratio": mapped_ratio})

    return out, df_consol, {"ok": True, "docs": int(len(out)), "mapped_ratio": mapped_ratio}

# SinergIA1500 - HOTFIX PR_03.5 Enrich: normaliza Documento + mejor selección de fecha de gestión (evita matched_docs=0)
from typing import Optional, Dict, Any, Tuple, List
import pandas as pd
import re

def _sinergia_norm_docid(x) -> str:
    """
    Normaliza ID documento para joins:
    - Soporta scientific (1.23E+09), floats con .0, strings con separadores.
    - Devuelve solo dígitos.  Si no hay dígitos, ''.
    """
    if x is None:
        return ""
    s = str(x).strip()
    if not s or s.lower() in ("nan", "none"):
        return ""

    # scientific
    sci = re.match(r"^\s*(\d+(?:\.\d+)?)\s*[eE]\s*([+-]?\d+)\s*$", s)
    if sci:
        try:
            base = float(sci.group(1))
            exp = int(sci.group(2))
            val = int(round(base * (10 ** exp)))
            s = str(val)
        except Exception:
            pass

    # remove trailing .0
    if re.match(r"^\d+\.0$", s):
        s = s[:-2]

    # keep digits only
    digits = re.sub(r"\D+", "", s)
    return digits

def sinergia_pr035_enrich_base_with_contact_history(
    df_base_cobranza: pd.DataFrame,
    log: str = "",
    *,
    rc: Optional["SinergIA_RunContext"] = None,
    dd_archivo_gestion: Optional[Any] = None,
    file_gestion_local: Any = None,
    max_rows_gestion: int = 5000,
    out_col_last_contact: str = "Fecha Ult Contacto",
) -> Tuple[pd.DataFrame, str, "SinergIA_RunContext"]:
    """
    Enriquecimiento mínimo para que PR_07 pueda evaluar Ley 2300.
    Hotfix:
      - Normaliza Documento (base y Gestion) para map robusto.
      - Mejor selección de columna fecha en Gestion (prefiere ult gestión > mejor gest > fecha genérica).
    """
    if rc is None:
        rc = sinergia_new_run_context("PR_03_5_ENRICH_HISTORY", meta={"max_rows_gestion": int(max_rows_gestion)})

    # Helpers del notebook (si existen)
    _pick = globals().get("_sinergia_pick_col_any", None) or globals().get("_pick_col_any", None)
    def _pick_col(df, cands):
        if callable(_pick):
            return _pick(df, cands)
        for c in cands:
            if c in df.columns:
                return c
        return ""

    def _rc_set(key, val):
        try:
            if hasattr(rc, "set_manifest") and callable(getattr(rc, "set_manifest")):
                rc.set_manifest(key, val)
                return
            if hasattr(rc, "manifest") and isinstance(getattr(rc, "manifest"), dict):
                d = rc.manifest
                parts = str(key).split(".")
                cur = d
                for p in parts[:-1]:
                    if p not in cur or not isinstance(cur[p], dict):
                        cur[p] = {}
                    cur = cur[p]
                cur[parts[-1]] = val
        except Exception:
            pass

    def _rc_event(code, msg, level="INFO", etapa="PR_03_5", data=None):
        try:
            if hasattr(rc, "add_event") and callable(getattr(rc, "add_event")):
                rc.add_event(code, level=level, message=msg, etapa=etapa, data=data)
        except Exception:
            pass

    _rc_event("PR_03_5_START", "Inicio enrich base con historial (Gestion_Log).")

    # Documento base
    c_doc_base = _pick_col(df_base_cobranza, ["Documento de identidad","DocumentoDeIdentidad","Identificacion","Identificación","IN_DOCUMENTO_DE_IDENTIDAD"])
    if not c_doc_base:
        _rc_set("gates.PR_03_5", {"ok": False, "reason": "BASE_MISSING_DOC"})
        _rc_event("PR_03_5_FAIL", "Base sin columna Documento.", level="ERROR")
        raise ValueError("PR_03_5 FAIL: df_base_cobranza sin Documento.")

    df_out = df_base_cobranza.copy()
    df_out[c_doc_base] = df_out[c_doc_base].astype(str)
    df_out["_DOC_NORM"] = df_out[c_doc_base].map(_sinergia_norm_docid)

    # Resolver Gestion DF
    df_gestion = globals().get("DF_GESTION_CACHE", None)
    gestion_source = "DF_GESTION_CACHE"

    # Resolver dropdown/file de GUI si no hay cache
    if df_gestion is None or not isinstance(df_gestion, pd.DataFrame) or df_gestion.empty:
        if dd_archivo_gestion is None:
            dd_archivo_gestion = globals().get("dd_archivo_gestion", None)
        if file_gestion_local is None:
            file_gestion_local = globals().get("file_gestion_local", None)

        # dd puede ser widget - usa .value si existe
        gestion_name = ""
        try:
            gestion_name = (dd_archivo_gestion.value if hasattr(dd_archivo_gestion, "value") else dd_archivo_gestion) or ""
        except Exception:
            gestion_name = dd_archivo_gestion or ""
        gestion_name = str(gestion_name).strip()

        if gestion_name or (file_gestion_local is not None):
            try:
                df_gestion, log = _load_gestion_any_source(
                    dd_archivo_gestion=gestion_name if gestion_name else None,
                    file_gestion_local=file_gestion_local,
                    log=log,
                    max_rows=int(max_rows_gestion),
                )
                if isinstance(df_gestion, pd.DataFrame) and not df_gestion.empty:
                    globals()["DF_GESTION_CACHE"] = df_gestion.copy()
                    gestion_source = "LOAD_GESTION_PREVIEW"
                else:
                    gestion_source = "GESTION_EMPTY"
            except Exception as e:
                df_gestion = pd.DataFrame()
                gestion_source = "GESTION_LOAD_FAIL"
                log = _log_append(log, f"PR_03_5_WARN · no_gestion_loaded · {e}")
        else:
            gestion_source = "GESTION_NOT_SELECTED"

    _rc_set("metrics.PR_03_5.gestion_source", gestion_source)

    # Si sigue sin Gestion, dejar NaT
    if df_gestion is None or not isinstance(df_gestion, pd.DataFrame) or df_gestion.empty:
        df_out[out_col_last_contact] = pd.NaT
        _rc_set("metrics.PR_03_5.gestion_rows", 0)
        _rc_set("metrics.PR_03_5.matched_docs", 0)
        _rc_set("gates.PR_03_5", {"ok": False, "reason": "NO_GESTION_HISTORY"})
        _rc_event("PR_03_5_WARN", f"No hay Gestion_Log disponible ({gestion_source}).  Se deja NaT.", level="WARN")
        df_out.drop(columns=["_DOC_NORM"], inplace=True, errors="ignore")
        return df_out, log, rc

    # Columnas Gestion: documento y fecha (preferencias)
    c_doc_gestion = _pick_col(df_gestion, ["IN_DOCUMENTO_DE_IDENTIDAD","Documento de identidad","Documento","Documento Clte","Identificacion","Identificación"])
    c_dt_gestion  = _pick_col(df_gestion, [
        "Fecha Ult Gestion", "Fecha Últ Gestión", "Fecha Mejor Gest", "Fecha Ult Contacto", "Fecha Último Contacto",
        "Fecha Gestion", "Fecha Gestión", "Fecha Contacto", "Fecha"
    ])

    _rc_set("metrics.PR_03_5.gestion_rows", int(len(df_gestion)))
    _rc_set("metrics.PR_03_5.gestion_doc_col", c_doc_gestion)
    _rc_set("metrics.PR_03_5.gestion_dt_col", c_dt_gestion)

    if not (c_doc_gestion and c_dt_gestion):
        df_out[out_col_last_contact] = pd.NaT
        _rc_set("metrics.PR_03_5.matched_docs", 0)
        _rc_set("gates.PR_03_5", {"ok": False, "reason": "GESTION_MISSING_COLS"})
        _rc_event("PR_03_5_WARN", "Gestion_Log sin columnas doc/fecha esperadas.  Se deja NaT.", level="WARN")
        df_out.drop(columns=["_DOC_NORM"], inplace=True, errors="ignore")
        return df_out, log, rc

    # Normaliza doc en Gestion + parse dt
    tmp = df_gestion[[c_doc_gestion, c_dt_gestion]].copy()
    tmp[c_doc_gestion] = tmp[c_doc_gestion].astype(str)
    tmp["_DOC_NORM"] = tmp[c_doc_gestion].map(_sinergia_norm_docid)
    tmp["_DT"] = pd.to_datetime(tmp[c_dt_gestion], errors="coerce", dayfirst=True, utc=False)
    try:
        tmp["_DT"] = tmp["_DT"].dt.tz_localize(None)
    except Exception:
        pass

    # Agregación determinística: max fecha por DOC_NORM
    s_last = tmp.groupby("_DOC_NORM", sort=False)["_DT"].max()

    gestion_unique_norm = int(s_last.index.nunique(dropna=True))
    _rc_set("metrics.PR_03_5.gestion_unique_docs_norm", gestion_unique_norm)

    # Join hacia base por DOC_NORM
    df_out[out_col_last_contact] = df_out["_DOC_NORM"].map(s_last.to_dict())
    matched = int(df_out[out_col_last_contact].notna().sum())

    _rc_set("metrics.PR_03_5.base_rows", int(len(df_out)))
    _rc_set("metrics.PR_03_5.base_unique_docs_norm", int(df_out["_DOC_NORM"].nunique(dropna=True)))
    _rc_set("metrics.PR_03_5.matched_docs", matched)
    _rc_set("metrics.PR_03_5.matched_ratio", float(matched / max(1, len(df_out))))

    if matched > 0:
        _rc_set("gates.PR_03_5", {"ok": True})
        _rc_event("PR_03_5_OK", "Historial integrado a base (Fecha Ult Contacto).", data={"matched": matched, "gestion_unique_norm": gestion_unique_norm})
        log = _log_append(log, f"PR_03_5_OK · history_source={gestion_source} · matched_docs={matched}/{len(df_out)}")
    else:
        _rc_set("gates.PR_03_5", {"ok": False, "reason": "NO_MATCH_DOC"})
        _rc_event("PR_03_5_WARN", "Gestion_Log cargó pero no hubo match por Documento.  Revisa normalización/fuente.", level="WARN", data={"gestion_unique_norm": gestion_unique_norm})
        log = _log_append(log, f"PR_03_5_WARN · gestion_loaded_but_no_match · gestion_unique_norm={gestion_unique_norm}")

    df_out.drop(columns=["_DOC_NORM"], inplace=True, errors="ignore")
    return df_out, log, rc

# SinergIA1700 - PR_08 ListBuilder + ExportGate (contract-driven desde Estructuras, sin GUI)
from datetime import datetime, date
import os
import pandas as pd

def _sinergia_month_es(m: int) -> str:
    meses = ["Ene","Feb","Mar","Abr","May","Jun","Jul","Ago","Sep","Oct","Nov","Dic"]
    try:
        m = int(m)
        return meses[m-1] if 1 <= m <= 12 else str(m)
    except Exception:
        return str(m)

def _pick_col_any(df: pd.DataFrame, candidates: list[str]) -> str:
    for c in candidates:
        if c in df.columns:
            return c
    return ""

def _safe_manifest_get(rc, key: str, default=None):
    d = getattr(rc, "manifest", None)
    if not isinstance(d, dict):
        return default
    cur = d
    for p in str(key).split("."):
        if not isinstance(cur, dict) or p not in cur:
            return default
        cur = cur[p]
    return cur

def _safe_manifest_set(rc, key: str, val):
    try:
        if hasattr(rc, "set_manifest") and callable(getattr(rc, "set_manifest")):
            rc.set_manifest(key, val)
            return
    except Exception:
        pass
    d = getattr(rc, "manifest", None)
    if not isinstance(d, dict):
        return
    cur = d
    parts = str(key).split(".")
    for p in parts[:-1]:
        if p not in cur or not isinstance(cur[p], dict):
            cur[p] = {}
        cur = cur[p]
    cur[parts[-1]] = val

# SinergIA1710 - PR_08 Publish Listas (.xlsx) a Drive (folder desde SettingID, sin hardcode, sin duplicados)

import io
import os
import re
from datetime import datetime
from googleapiclient.discovery import build
from googleapiclient.http import MediaIoBaseUpload
from google.auth import default as google_default

_XLSX_MIME = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
_DRIVE_ID_RE = re.compile(r"[A-Za-z0-9_-]{25,}")

# Cache simple (evita re-scan SettingID en la misma sesión)
_SINERGIA_FOLDER_CACHE: dict[str, str] = {}

def _pr08_filename_from_alias(alias_upper: str, now: datetime) -> str:
    ts = now.strftime("%Y_%m_%d_%H%M")
    if alias_upper == "DIGITAL_WHATSAPP":
        return f"BD_Envios_WhatsApp_{ts}.xlsx"
    if alias_upper == "DIGITAL_WISE":
        return f"BD_Envios_Validador_Wise_{ts}.xlsx"
    if alias_upper == "DIGITAL_SMS":
        return f"BD_Envios_SMS_{ts}.xlsx"
    return f"{alias_upper}_{ts}.xlsx"

def _df_to_xlsx_bytes(df, sheet_name: str = "DATA") -> bytes:
    # Requiere pd ya cargado en notebook (canon).  Evita prints o dumps.
    bio = io.BytesIO()
    with pd.ExcelWriter(bio, engine="openpyxl") as w:
        df.to_excel(w, index=False, sheet_name=sheet_name)
    return bio.getvalue()

def _drive_find_id_by_name(svc, folder_id: str, name: str):
    q = f"'{folder_id}' in parents and name = '{name}' and trashed = false"
    resp = svc.files().list(
        q=q,
        fields="files(id,name)",
        pageSize=1,
        supportsAllDrives=True,
        includeItemsFromAllDrives=True,
    ).execute()
    files = resp.get("files", []) or []
    return (files[0]["id"] if files else None)

def drive_upsert_bytes(
    folder_id: str,
    filename: str,
    data: bytes,
    mime_type: str = _XLSX_MIME,
    overwrite: bool = True,
):
    creds, _ = google_default()
    svc = build("drive", "v3", credentials=creds, cache_discovery=False)
    media = MediaIoBaseUpload(io.BytesIO(data), mimetype=mime_type, resumable=False)

    existing_id = _drive_find_id_by_name(svc, folder_id, filename)
    if existing_id and overwrite:
        svc.files().update(
            fileId=existing_id,
            media_body=media,
            supportsAllDrives=True,
        ).execute()
        return existing_id

    body = {"name": filename, "parents": [folder_id], "mimeType": mime_type}
    created = svc.files().create(
        body=body,
        media_body=media,
        fields="id",
        supportsAllDrives=True,
    ).execute()
    return created.get("id")

def _sinergia_get_folder_id_by_reference(ref_name: str, log: str = ""):
    """
    Resuelve folder_id desde SettingID por referencia.  (Nombre_referencia_carpeta / ID_Carpeta) es el camino canónico.
    Restricción de logs: máximo 1 línea por acción.  Este helper solo agrega UNA línea al log por invocación.
    Cachea por ref_name en _SINERGIA_FOLDER_CACHE.
    """
    # log append 1-line only
    def _append1(base: str, msg: str) -> str:
        if "_log_append" in globals() and callable(globals().get("_log_append")):
            return _log_append(base, msg)
        base = "" if base is None else str(base)
        return (f"{base}\n{msg}" if base else msg)

    ref = str(ref_name or "").strip().upper()
    if not ref:
        return None, _append1(log, "CONFIG · ref_name vacío.")

    if ref in _SINERGIA_FOLDER_CACHE and str(_SINERGIA_FOLDER_CACHE[ref]).strip():
        fid = str(_SINERGIA_FOLDER_CACHE[ref]).strip()
        return fid, _append1(log, f"CONFIG · {ref} folder_id={fid} (cache)")

    try:
        df = sinergia_load_settingid_df(force=False)
    except Exception as e:
        return None, _append1(log, f"CONFIG · SettingID no disponible: {e}")

    if df is None or getattr(df, "empty", True):
        return None, _append1(log, "CONFIG · SettingID vacío.")

    cols = list(df.columns)

    def _find_col(pred):
        for c in cols:
            k = str(c).strip().lower()
            if pred(k):
                return c
        return None

    col_name = _find_col(lambda k: ("nombre" in k and "carpeta" in k) or ("referencia" in k and "carpeta" in k))
    col_id = _find_col(lambda k: ("id" in k and "carpeta" in k) or (k == "id_carpeta"))

    fid = None
    via = None

    # 1) Ruta canónica por columnas
    if col_name and col_id:
        # exact
        try:
            m = df[col_name].astype(str).str.strip().str.upper() == ref
            if bool(m.any()):
                fid = str(df.loc[m, col_id].iloc[0]).strip()
                via = "cols exact"
        except Exception:
            fid = None

        # contains
        if not fid:
            try:
                m = df[col_name].astype(str).str.strip().str.upper().str.contains(ref, na=False, regex=False)
                if bool(m.any()):
                    fid = str(df.loc[m, col_id].iloc[0]).strip()
                    via = "cols contains"
            except Exception:
                fid = None

    # 2) Fallback: escaneo textual (solo si no se pudo por columnas)
    if not fid:
        try:
            for _, r in df.iterrows():
                row_text = " ".join([str(v) for v in list(r.values) if str(v).strip()])
                if ref in row_text.upper():
                    if "_extract_folder_ids_from_row_text" in globals() and callable(globals().get("_extract_folder_ids_from_row_text")):
                        fids = _extract_folder_ids_from_row_text(row_text)
                        if fids:
                            fid = str(fids[0]).strip()
                            via = "fallback extractor"
                            break
                    ids = list(dict.fromkeys(_DRIVE_ID_RE.findall(row_text or "")))
                    if ids:
                        fid = str(ids[0]).strip()
                        via = "fallback regex"
                        break
        except Exception:
            fid = None

    if fid:
        _SINERGIA_FOLDER_CACHE[ref] = fid
        return fid, _append1(log, f"CONFIG · {ref} folder_id={fid} ({via})")

    return None, _append1(log, f"CONFIG · {ref} folder_id NO ENCONTRADO en SettingID.")

def sinergia_pr08_build_and_export_list(
    df_eligible: "pd.DataFrame",
    log: str = "",
    *,
    rc: "SinergIA_RunContext",
    archivo_logico: str,
    sistema: str = "SinergIA",
    fmt: str = "XLSX",
    meta: dict | None = None,
    require_pr07_ok: bool = True,
) -> tuple["pd.DataFrame", str, str]:
    """
    PR_08 (Listas):
    - Builder inline (DIGITAL_WHATSAPP / DIGITAL_WISE / DIGITAL_SMS).
    - Fuerza layout exacto por Estructuras.
    - Writer: XLSX a rc.dir con nombre canónico.
    - Publica a Drive solo si PR_07 OK (si require_pr07_ok=True).  Evidencia local siempre.

    Idempotencia local por fingerprint:
    - out_name se deriva de (alias, fecha_corte, fingerprint_short) para evitar nombres distintos en reruns.
    - Si fingerprint no existe, cae a nombre por timestamp (legacy).
    """
    import os
    import re
    from datetime import datetime
    import pandas as pd

    meta = meta or {}
    now = datetime.now()
    al = str(archivo_logico).strip().upper()

    if rc is None:
        raise ValueError("PR_08 FAIL: rc requerido.")
    if df_eligible is None or not isinstance(df_eligible, pd.DataFrame) or df_eligible.empty:
        raise ValueError("PR_08 FAIL: df_eligible vacío/ inválido.")

    # --- Gate PR_07 (controla SOLO publicación) ---
    pr07_ok = True
    if require_pr07_ok:
        g07 = _safe_manifest_get(rc, "gates.PR_07", {}) or {}
        pr07_ok = bool((g07 or {}).get("ok", False))

    # --- Fingerprint (para idempotencia local) ---
    fp = meta.get("fingerprint")
    if not fp:
        fp = _safe_manifest_get(rc, "metrics.PR_08_MULTI.fingerprint", None)
    fp = str(fp).strip() if fp is not None else ""
    fp_short = ""
    if fp:
        # deja solo hex y corta
        fp_short = re.sub(r"[^0-9a-fA-F]+", "", fp)[:6].lower()

    # --- Fecha corte para naming (prioridad: meta -> metrics.PR_07 -> hoy) ---
    corte_date = meta.get("corte_date") or _safe_manifest_get(rc, "metrics.PR_07.corte_date", None) or now.date()
    try:
        # si llega Timestamp/date/datetime, normaliza
        if hasattr(corte_date, "date") and not isinstance(corte_date, (str,)):
            corte_date = corte_date.date() if hasattr(corte_date, "date") else corte_date
    except Exception:
        pass
    corte_s = str(corte_date)
    corte_tag = corte_s.replace("-", "_").replace("/", "_")

    # --- Estructuras (canon) ---
    df_estructuras, log = _get_cfg_estructuras(log)
    if df_estructuras is None or getattr(df_estructuras, "empty", True):
        _safe_manifest_set(rc, "gates.PR_08", {"ok": False, "reason": "CONFIG_ESTRUCTURAS_EMPTY", "alias": al})
        raise ValueError("PR_08 FAIL: Estructuras vacío.")

    # --- Picks base (robustos) ---
    def _col_or_none(candidates: list[str]) -> str | None:
        try:
            return _pick_col_any(df_eligible, candidates)
        except Exception:
            return None

    c_doc = _col_or_none(["Documento de identidad", "Documento", "Identificacion", "Identificación", "IN_DOCUMENTO_DE_IDENTIDAD"])
    c_nom = _col_or_none(["Nombre Completo", "NombreCompleto", "Upper", "Nombre"])
    c_sts = _col_or_none(["Status", "EstadoCentrales", "Estado Centrales", "Estado"])
    c_tel1 = _col_or_none(["Telefono 1", "Teléfono 1", "Telefono1", "Celular", "Celular1", "Telefono"])
    c_tel2 = _col_or_none(["Telefono 2", "Teléfono 2", "Telefono2", "Celular2"])
    c_tel3 = _col_or_none(["Telefono 3", "Teléfono 3", "Telefono3", "Fijo"])
    c_tel4 = _col_or_none(["Telefono 4", "Teléfono 4", "Telefono4", "Fijo2"])

    tel = c_tel1 or c_tel2 or c_tel3 or c_tel4

    n = int(len(df_eligible))

    def _series_or_blank(col: str | None) -> "pd.Series":
        if col and col in df_eligible.columns:
            return df_eligible[col].astype(str)
        return pd.Series([""] * n)

    s_doc = _series_or_blank(c_doc)
    s_nom = _series_or_blank(c_nom)
    s_sts = _series_or_blank(c_sts)
    s_tel = _series_or_blank(tel)

    # Defaults de negocio
    f_envio = meta.get("fecha_envio") or now.date()
    mes = meta.get("mes") or _sinergia_month_es(now.month)

    # --- Builder por alias ---
    if al in ("DIGITAL_SMS", "DIGITAL_WHATSAPP"):
        df_list = pd.DataFrame({
            "DocumentoDeIdentidad": s_doc,
            "NombreCompleto": s_nom,
            "Telefono": s_tel,
            "Status": s_sts,
            "FechaEnvio": f_envio,
            "Mes": mes,
        })
        if al == "DIGITAL_WHATSAPP":
            df_list["TipoMensaje"] = str(meta.get("wa_tipo") or "COBRANZA")

    elif al == "DIGITAL_WISE":
        df_list = pd.DataFrame({
            "Campana": str(meta.get("wise_campana") or "SINERGIA"),
            "Fecha": meta.get("wise_fecha") or now.date(),
            "DocumentoDeIdentidad": s_doc,
            "Telefono": s_tel,
            "EstadoLlamada": str(meta.get("wise_estado") or ""),
            "Intentos": pd.to_numeric(meta.get("wise_intentos"), errors="coerce") if meta.get("wise_intentos") is not None else "",
            "TiempoLlamada": pd.to_numeric(meta.get("wise_tiempo"), errors="coerce") if meta.get("wise_tiempo") is not None else "",
        })

    elif al == "CONTACTO_VOZ":
        # CONTACTO_VOZ se espera derivado desde TRAZA ya filtrada a "CD" en SinergIA1750.
        c_fecha = _col_or_none(["CAP_FECHA", "Fecha", "FECHA", "ULTIMA_ACTUALIZACION_FECHA", "EVENT_TIME", "START_TIME"])
        c_canal = _col_or_none(["CAP_CANAL", "Canal", "CANAL", "CHANNEL"])
        c_tip   = _col_or_none(["CAP_TIPIFICACION", "Tipificacion", "TIPIFICACION", "Outcome", "OUTCOME", "Resultado", "RESULTADO"])
        c_sub   = _col_or_none(["CAP_SUBTIPIFICACION", "Subtipificacion", "SUBTIPIFICACION"])
        c_telc  = _col_or_none(["CAP_TELEFONO_CONTACTO", "TelefonoContacto", "Telefono Contacto", "TELEFONO_CONTACTO"])
        c_itx   = _col_or_none(["IN_INTERACTIONID", "IN_INTERACTIONIDCREDIT", "InteractionId", "INTERACTIONID", "INTERACTION_ID"])

        s_fecha = _series_or_blank(c_fecha)
        s_canal = _series_or_blank(c_canal)
        s_tip   = _series_or_blank(c_tip)
        s_sub   = _series_or_blank(c_sub)
        s_telc  = _series_or_blank(c_telc)
        s_itx   = _series_or_blank(c_itx)

        df_list = pd.DataFrame({
            "DocumentoDeIdentidad": s_doc,
            "FechaContacto": s_fecha,
            "Canal": s_canal,
            "Tipificacion": s_tip,
            "Subtipificacion": s_sub,
            "TelefonoContacto": s_telc,
            "InteractionId": s_itx,
        })

    else:
        raise ValueError(f"PR_08 FAIL: ArchivoLogico no soportado: {al}")

    # --- Enforce layout exacto ---
    # CONTACTO_VOZ no existe aún en Config_SinergIA.xlsx/Estructuras (canon).  Se permite fallback sin romper.
    try:
        df_e_sub = df_estructuras[
            (df_estructuras["Sistema"].astype(str).str.upper() == str(sistema).upper()) &
            (df_estructuras["ArchivoLogico"].astype(str).str.upper() == str(al).upper())
        ]
    except Exception:
        df_e_sub = None

    if al == "CONTACTO_VOZ" and (df_e_sub is None or getattr(df_e_sub, "empty", True)):
        df_layout = df_list.copy()
        _safe_manifest_set(rc, "metrics.PR_08.CONTACTO_VOZ.layout_fallback", True)
        if "_log_append" in globals() and callable(globals().get("_log_append")):
            log = _log_append(log, "PR_08 · CONTACTO_VOZ sin estructura en Config.  Se usa layout fallback.")
    else:
        df_layout, log = sinergia_enforce_headers_from_estructuras(
            df_list,
            df_estructuras,
            log,
            sistema=sistema,
            archivo_logico=al,
        )


    # --- Idempotencia mínima por canal en rc: si ya marcado published en gates.PR_08_{ALIAS} ---
    g_key = f"gates.PR_08_{al}"
    prev_g = _safe_manifest_get(rc, g_key, {}) or {}
    already_published = bool(prev_g.get("published") is True)
    prev_drive_file_id = prev_g.get("drive_file_id")
    prev_drive_folder_id = prev_g.get("drive_folder_id")

    # --- Naming local: idempotente por fingerprint (si existe) ---
    def _prefix(alias_upper: str) -> str:
        if alias_upper == "DIGITAL_WHATSAPP":
            return "BD_Envios_WhatsApp_"
        if alias_upper == "DIGITAL_WISE":
            return "BD_Envios_Validador_Wise_"
        if alias_upper == "DIGITAL_SMS":
            return "BD_Envios_SMS_"
        return f"BD_Envios_{alias_upper}_"

    # Si ya existe outputs.PR_08.{ALIAS} (de esta misma corrida), reusa
    prev_out_name = _safe_manifest_get(rc, f"outputs.PR_08.{al}", None)
    if prev_out_name:
        out_name = str(prev_out_name)
    else:
        if fp_short:
            out_name = f"{_prefix(al)}{corte_tag}_{fp_short}.xlsx"
        else:
            # fallback legacy
            out_name = _pr08_filename_from_alias(al, now)

    local_path = os.path.join(getattr(rc, "dir", ""), out_name)

    # --- Writer local (siempre) ---
    xlsx_bytes = _df_to_xlsx_bytes(df_layout, sheet_name="DATA")
    os.makedirs(getattr(rc, "dir", ""), exist_ok=True)
    with open(local_path, "wb") as f:
        f.write(xlsx_bytes)

    _safe_manifest_set(rc, f"metrics.PR_08.{al}.rows", int(len(df_layout)))
    _safe_manifest_set(rc, f"metrics.PR_08.{al}.cols", int(df_layout.shape[1]))
    if fp_short:
        _safe_manifest_set(rc, f"metrics.PR_08.{al}.fingerprint", fp_short)
    _safe_manifest_set(rc, f"outputs.PR_08.{al}", os.path.basename(local_path))

    # --- Publish a Drive (solo si PR_07 OK) ---
    published = False
    drive_file_id = None
    drive_folder_id = None
    reason = None

    if pr07_ok and already_published:
        published = True
        drive_file_id = prev_drive_file_id
        drive_folder_id = prev_drive_folder_id
        reason = "ALREADY_PUBLISHED"

    elif pr07_ok:
        # Folder por referencia (permitimos override por meta.drive_folder_ref).  Default: FOLDER_LISTAS.
        folder_ref = str(meta.get("drive_folder_ref") or "FOLDER_LISTAS").strip().upper()
        folder_id, log = _sinergia_get_folder_id_by_reference(folder_ref, log)
        if (not folder_id) and folder_ref != "LISTAS_TRABAJO_GENESYS":
            folder_id, log = _sinergia_get_folder_id_by_reference("LISTAS_TRABAJO_GENESYS", log)

        if folder_id:
            drive_folder_id = folder_id
            try:
                drive_file_id = drive_upsert_bytes(folder_id, out_name, xlsx_bytes, _XLSX_MIME, overwrite=True)
                published = True
                reason = "OK"
            except Exception as e:
                reason = f"DRIVE_UPSERT_FAIL:{e}"
        else:
            reason = "FOLDER_ID_NOT_FOUND"
    else:
        reason = "PR_07_NOT_OK"

    g08 = {
        "ok": True,
        "published": bool(published),
        "reason": reason,
        "drive_file_id": drive_file_id,
        "drive_folder_id": drive_folder_id,
        "alias": al,
    }
    # Compat: se mantiene gates.PR_08 + gates.PR_08_{ALIAS}
    _safe_manifest_set(rc, "gates.PR_08", g08)
    _safe_manifest_set(rc, g_key, g08)

    # outputs auxiliares para trazabilidad
    if drive_folder_id:
        _safe_manifest_set(rc, f"outputs.PR_08.{al}.drive_folder_id", drive_folder_id)

    if hasattr(rc, "add_event"):
        rc.add_event(
            "PR_08_OK",
            level="INFO",
            message="PR_08 listo.  Publicado a Drive." if published else "PR_08 listo.  Sin publicación (evidencia local OK).",
            data={
                "archivo_logico": al,
                "file": out_name,
                "published": bool(published),
                "drive_file_id": drive_file_id,
                "drive_folder_id": drive_folder_id,
                "reason": reason,
                "fingerprint": fp_short or None,
            },
            etapa="PR_08",
        )

    print("PR_08 ·", al, "published=", bool(published), "file=", out_name)
    return df_layout, local_path, log

# SinergIA1720 - Fix FolderID resolver: Listas_Trabajo_Genesys desde SettingID (Nombre_referencia_carpeta / ID_Carpeta)

def _sinergia_get_listas_trabajo_genesys_folder_id(log: str = "", force: bool = False):
    """
    Resuelve folder_id de Listas_Trabajo_Genesys desde Config_SinergIA / hoja SettingID.
    Esperado (canónico): columnas tipo Nombre_referencia_carpeta, ID_Carpeta.
    Fallback: escaneo de texto + regex + _is_drive_folder si existe.
    Cachea el resultado en memoria (kernel) para no re-leer SettingID en cada click.
    """

    import re
    from datetime import datetime

    # Cache (memoria del kernel)
    global _LISTAS_TRABAJO_GENESYS_FOLDER_ID_CACHE
    if "_LISTAS_TRABAJO_GENESYS_FOLDER_ID_CACHE" not in globals():
        _LISTAS_TRABAJO_GENESYS_FOLDER_ID_CACHE = None

    def _append(_log: str, msg: str) -> str:
        # usa helper canónico si existe
        if ("_log_append" in globals()) and callable(globals().get("_log_append")):
            return _log_append(_log, msg)
        ts = datetime.now().strftime("%H:%M:%S")
        return (f"{_log}\n" if _log else "") + f"[{ts}] {msg}"

    def _norm(x: str) -> str:
        s = str(x or "").strip().upper()
        # normaliza separadores para match robusto
        for ch in [" ", "-", ".", "·", ":", ";", "/", "\\"]:
            s = s.replace(ch, "_")
        while "__" in s:
            s = s.replace("__", "_")
        return s

    # 0) Cache
    if (not force) and isinstance(_LISTAS_TRABAJO_GENESYS_FOLDER_ID_CACHE, str) and _LISTAS_TRABAJO_GENESYS_FOLDER_ID_CACHE.strip():
        fid = _LISTAS_TRABAJO_GENESYS_FOLDER_ID_CACHE.strip()
        return fid, _append(log, f"CONFIG · Listas_Trabajo_Genesys folder_id={fid} (cache)")

    # 1) Leer SettingID
    try:
        df = sinergia_load_settingid_df(force=bool(force))
    except Exception as e:
        return None, _append(log, f"CONFIG · SettingID no disponible: {e}")

    if df is None or getattr(df, "empty", True):
        return None, _append(log, "CONFIG · SettingID vacío.")

    # Evita “truth value of Index is ambiguous”
    cols = list(getattr(df, "columns", []))

    # helper para ubicar columnas por heurística de header
    def _find_col(pred):
        for c in cols:
            k = str(c).strip().lower()
            if pred(k):
                return c
        return None

    # 2) Ruta canónica por columnas
    col_name = _find_col(lambda k: ("nombre" in k and "carpeta" in k) or ("referencia" in k and "carpeta" in k))
    col_id   = _find_col(lambda k: ("id" in k and "carpeta" in k) or (k == "id_carpeta"))

    # regex genérico de IDs Drive (por si viene URL o texto sucio)
    _id_re = globals().get("_ID_RE", None)
    if _id_re is None:
        _id_re = re.compile(r"[A-Za-z0-9_-]{20,}")

    def _extract_first_id(text: str) -> str:
        tx = str(text or "")
        hits = list(dict.fromkeys(_id_re.findall(tx)))
        return hits[0] if hits else ""

    def _is_folder(fid: str) -> bool:
        if ("_is_drive_folder" in globals()) and callable(globals().get("_is_drive_folder")):
            try:
                return bool(_is_drive_folder(fid))
            except Exception:
                return False
        # sin validador, asumimos OK si parece ID
        return bool(fid and len(fid) >= 20)

    target_exact = "LISTAS_TRABAJO_GENESYS"

    if col_name and col_id:
        # 2.1 Match exacto
        try:
            recs = df.to_dict(orient="records")
            for r in recs:
                name = _norm(r.get(col_name, ""))
                if name == target_exact:
                    fid_raw = r.get(col_id, "")
                    fid = str(fid_raw).strip()
                    if not fid:
                        fid = _extract_first_id(fid_raw)
                    if fid and _is_folder(fid):
                        _LISTAS_TRABAJO_GENESYS_FOLDER_ID_CACHE = fid
                        return fid, _append(log, f"CONFIG · Listas_Trabajo_Genesys folder_id={fid} (via cols exact)")
        except Exception:
            pass

        # 2.2 Match contains
        try:
            recs = df.to_dict(orient="records")
            for r in recs:
                name_u = _norm(r.get(col_name, ""))
                if ("LISTAS" in name_u) and ("TRABAJO" in name_u) and ("GENESYS" in name_u):
                    fid_raw = r.get(col_id, "")
                    fid = str(fid_raw).strip()
                    if not fid:
                        fid = _extract_first_id(fid_raw)
                    if fid and _is_folder(fid):
                        _LISTAS_TRABAJO_GENESYS_FOLDER_ID_CACHE = fid
                        return fid, _append(log, f"CONFIG · Listas_Trabajo_Genesys folder_id={fid} (via cols contains)")
        except Exception:
            pass

    # 3) Fallback: escaneo por texto (headers cambiados / fila mixta)
    try:
        recs = df.to_dict(orient="records")
        for r in recs:
            row_text = " ".join([str(v) for v in r.values() if str(v).strip()])
            row_u = row_text.upper()
            if ("LISTAS" in row_u) and ("TRABAJO" in row_u) and ("GENESYS" in row_u):

                # extractor existente (si está)
                if ("_extract_folder_ids_from_row_text" in globals()) and callable(globals().get("_extract_folder_ids_from_row_text")):
                    fids = _extract_folder_ids_from_row_text(row_text)
                    if fids:
                        fid = str(fids[0]).strip()
                        if fid and _is_folder(fid):
                            _LISTAS_TRABAJO_GENESYS_FOLDER_ID_CACHE = fid
                            return fid, _append(log, f"CONFIG · Listas_Trabajo_Genesys folder_id={fid} (fallback extractor)")

                # regex crudo
                ids = list(dict.fromkeys(_id_re.findall(row_text or "")))
                for fid in ids:
                    fid = str(fid).strip()
                    if fid and _is_folder(fid):
                        _LISTAS_TRABAJO_GENESYS_FOLDER_ID_CACHE = fid
                        return fid, _append(log, f"CONFIG · Listas_Trabajo_Genesys folder_id={fid} (fallback regex)")
    except Exception:
        pass

    return None, _append(log, "CONFIG · Listas_Trabajo_Genesys folder_id NO ENCONTRADO en SettingID.")

print(_sinergia_get_listas_trabajo_genesys_folder_id()[0])

fid1, lg1 = _sinergia_get_listas_trabajo_genesys_folder_id(log="")
print("fid1:", fid1)
print(lg1)

fid2, lg2 = _sinergia_get_listas_trabajo_genesys_folder_id(log="")
print("fid2:", fid2)
print(lg2)

# SinergIA1730 - PR_08 MULTI runner (WhatsApp + Wise + SMS) reutilizable
# Idempotencia automática por fingerprint (cross-runs) + registry local + sync opcional a Drive/Modelos

from datetime import datetime
import os
import json
import hashlib

def sinergia_pr08_publish_multi(
    *,
    df_eligible: "pd.DataFrame",
    rc: "SinergIA_RunContext",
    log: str = "",
    sistema: str = "SinergIA",
    aliases: list[str] | None = None,
    require_pr07_ok: bool = True,
) -> tuple[dict, str]:
    """
    Ejecuta PR_08 para múltiples canales en una sola corrida.

    Claves:
    - Calcula fingerprint del DF (o reutiliza metrics.PR_08_MULTI.fingerprint si ya existe).
    - Idempotencia cross-runs por (alias, fingerprint) usando registry:
      * Si ya fue publicado, pre-siembra gates.PR_08_{ALIAS} y outputs.PR_08.{ALIAS} para que
        sinergia_pr08_build_and_export_list NO vuelva a upsert.
      * Igual deja evidencia local (xlsx) dentro del run_dir actual.
    - Registry:
      * Local: /content/sinergia_runs/_publish_registry.json (si existe runs_base_dir).
      * Drive opcional: carpeta Modelos (referencia: FOLDER_MODELOS o MODELOS) si está en config.
    """
    import pandas as pd  # local import para notebook

    aliases = aliases or ["DIGITAL_WHATSAPP", "DIGITAL_WISE", "DIGITAL_SMS"]

    if df_eligible is None or not isinstance(df_eligible, pd.DataFrame) or df_eligible.empty:
        raise ValueError("PR_08_MULTI FAIL: df_eligible vacío/ inválido.")
    if rc is None:
        raise ValueError("PR_08_MULTI FAIL: rc requerido.")
    if "sinergia_pr08_build_and_export_list" not in globals() or not callable(globals().get("sinergia_pr08_build_and_export_list")):
        raise RuntimeError("PR_08_MULTI FAIL: sinergia_pr08_build_and_export_list no está definido/ejecutado.")

    # ------------------------------
    # Helpers (manifest safe)
    # ------------------------------
    def _mget(path: str, default=None):
        if "_safe_manifest_get" in globals() and callable(globals().get("_safe_manifest_get")):
            return _safe_manifest_get(rc, path, default)
        # fallback mínimo
        cur = getattr(rc, "manifest", {}) or {}
        try:
            for k in str(path).split("."):
                cur = cur.get(k, {})
            return cur if cur != {} else default
        except Exception:
            return default

    def _mset(path: str, value):
        if hasattr(rc, "set_manifest") and callable(getattr(rc, "set_manifest")):
            rc.set_manifest(path, value)
            return
        if "_safe_manifest_set" in globals() and callable(globals().get("_safe_manifest_set")):
            _safe_manifest_set(rc, path, value)

    # ------------------------------
    # Fingerprint (estable y barato)
    # ------------------------------
    def _pick_cols_for_fp(df: pd.DataFrame) -> list[str]:
        # preferimos identificadores + teléfono; si no, primeras columnas
        candidates = [
            "IN_DOCUMENTO_DE_IDENTIDAD", "DocumentoDeIdentidad", "Identificacion", "Identificación",
            "Telefono", "Teléfono", "Telefono 1", "Teléfono 1", "Telefono1", "Celular", "Celular1",
        ]
        cols = [c for c in candidates if c in df.columns]
        if cols:
            return cols[:6]
        return list(df.columns)[:8]

    def _fingerprint_df(df: pd.DataFrame) -> str:
        cols = _pick_cols_for_fp(df)
        d = df[cols].copy()
        # normaliza a string para estabilidad
        for c in d.columns:
            d[c] = d[c].astype(str).fillna("")
        # hash_pandas_object es estable para contenido; lo convertimos a sha1
        try:
            arr = pd.util.hash_pandas_object(d, index=False).values.tobytes()
        except Exception:
            arr = repr(d.head(200).to_dict("records")).encode("utf-8")
        return hashlib.sha1(arr).hexdigest()[:20]

    fp = _mget("metrics.PR_08_MULTI.fingerprint", None)
    if not isinstance(fp, str) or not fp.strip():
        fp = _fingerprint_df(df_eligible)
        _mset("metrics.PR_08_MULTI.fingerprint", fp)

    fp6 = str(fp)[:6]

    # ------------------------------
    # Registry (local + Drive opcional)
    # ------------------------------
    def _runs_base_dir() -> str:
        # si rc expone runs_base_dir úsalo; si no, default canónico del proyecto
        env = _mget("environment.runs_base_dir", None)
        if isinstance(env, str) and env.strip():
            return env
        rb = getattr(rc, "runs_base_dir", None)
        if isinstance(rb, str) and rb.strip():
            return rb
        return "/content/sinergia_runs"

    REG_NAME = "_publish_registry.json"
    base_dir = _runs_base_dir()
    try:
        os.makedirs(base_dir, exist_ok=True)
    except Exception:
        pass
    reg_local_path = os.path.join(base_dir, REG_NAME)

    def _get_modelos_folder_id() -> str | None:
        # Preferimos carpeta Modelos para trazabilidad/registry
        fid = None
        if "_sinergia_get_folder_id_by_reference" in globals() and callable(globals().get("_sinergia_get_folder_id_by_reference")):
            fid, _ = _sinergia_get_folder_id_by_reference("FOLDER_MODELOS", "")
            if not fid:
                fid, _ = _sinergia_get_folder_id_by_reference("MODELOS", "")
        return fid

    reg_drive_folder_id = _get_modelos_folder_id()

    def _reg_load() -> dict:
        # 1) local
        try:
            if os.path.isfile(reg_local_path):
                with open(reg_local_path, "r", encoding="utf-8") as f:
                    d = json.load(f)
                return d if isinstance(d, dict) else {}
        except Exception:
            pass

        # 2) drive (si hay folder id y helpers)
        if reg_drive_folder_id and ("drive_find_by_name" in globals()) and ("drive_download_file" in globals()):
            try:
                file_id, _ = drive_find_by_name(reg_drive_folder_id, REG_NAME)
                if file_id:
                    drive_download_file(file_id, reg_local_path)
                    if os.path.isfile(reg_local_path):
                        with open(reg_local_path, "r", encoding="utf-8") as f:
                            d = json.load(f)
                        return d if isinstance(d, dict) else {}
            except Exception:
                pass

        return {}

    def _reg_save(reg: dict) -> tuple[str | None, str | None]:
        # retorna (drive_folder_id, drive_file_id) si logra upsert
        try:
            with open(reg_local_path, "w", encoding="utf-8") as f:
                json.dump(reg or {}, f, ensure_ascii=False, indent=2)
        except Exception:
            pass

        drive_file_id = None
        if reg_drive_folder_id and ("drive_upsert_bytes" in globals()) and callable(globals().get("drive_upsert_bytes")):
            try:
                payload = json.dumps(reg or {}, ensure_ascii=False, indent=2).encode("utf-8")
                drive_file_id = drive_upsert_bytes(
                    reg_drive_folder_id,
                    REG_NAME,
                    payload,
                    "application/json",
                    overwrite=True,
                )
            except Exception:
                drive_file_id = None

        return (reg_drive_folder_id, drive_file_id)

    reg = _reg_load()
    if not isinstance(reg, dict):
        reg = {}

    reg.setdefault("schema", "SINERGIA_PUBLISH_REGISTRY_V1")
    reg.setdefault("by_alias_fingerprint", {})  # key: ALIAS|FP -> payload

    def _reg_key(alias_upper: str, fp_str: str) -> str:
        return f"{alias_upper}|{fp_str}"

    # ------------------------------
    # Filename estable por día + fingerprint (evita HHMM infinito)
    # ------------------------------
    now = datetime.now()
    date_s = now.strftime("%Y_%m_%d")

    def _fname(alias_upper: str) -> str:
        a = str(alias_upper).upper()
        if a == "DIGITAL_WHATSAPP":
            return f"BD_Envios_WhatsApp_{date_s}_{fp6}.xlsx"
        if a == "DIGITAL_WISE":
            return f"BD_Envios_Validador_Wise_{date_s}_{fp6}.xlsx"
        if a == "DIGITAL_SMS":
            return f"BD_Envios_SMS_{date_s}_{fp6}.xlsx"
        return f"BD_Envios_{a}_{date_s}_{fp6}.xlsx"

    # ------------------------------
    # Ejecución por canal (con pre-siembra si ya publicado)
    # ------------------------------
    results: dict = {}

    for al in aliases:
        alias_upper = str(al).strip().upper()
        out_name = _fname(alias_upper)

        # fuerza nombre local estable en este run
        _mset(f"outputs.PR_08.{alias_upper}", out_name)

        # idempotencia por registry (cross-runs)
        k = _reg_key(alias_upper, fp)
        hit = reg.get("by_alias_fingerprint", {}).get(k, {}) if isinstance(reg.get("by_alias_fingerprint", {}), dict) else {}
        hit_published = bool(hit.get("published") is True and isinstance(hit.get("drive_file_id"), str) and hit.get("drive_file_id").strip())

        if hit_published:
            # pre-siembra gate para que PR_08 (build_and_export_list) NO vuelva a upsert
            _mset(
                f"gates.PR_08_{alias_upper}",
                {
                    "ok": True,
                    "published": True,
                    "reason": "ALREADY_PUBLISHED_FP",
                    "drive_file_id": hit.get("drive_file_id"),
                    "drive_folder_id": hit.get("drive_folder_id"),
                    "alias": alias_upper,
                },
            )

        # ejecuta builder+writer (siempre evidencia local); publish se decide adentro por gate pre-sembrado
        df_list, local_path, log = sinergia_pr08_build_and_export_list(
            df_eligible=df_eligible,
            rc=rc,
            archivo_logico=alias_upper,
            sistema=sistema,
            fmt="XLSX",
            meta={"run_id": getattr(rc, "run_id", None), "fingerprint": fp},
            require_pr07_ok=bool(require_pr07_ok),
        )

        # lee gate resultante
        g08 = _mget(f"gates.PR_08_{alias_upper}", {}) or {}
        published = bool(g08.get("published") is True)
        drive_file_id = g08.get("drive_file_id") if isinstance(g08, dict) else None
        drive_folder_id = g08.get("drive_folder_id") if isinstance(g08, dict) else None

        duplicate_skipped = bool(hit_published)

        results[alias_upper] = {
            "published": bool(published),
            "drive_file_id": drive_file_id,
            "file": os.path.basename(local_path) if local_path else out_name,
            "rows": int(len(df_list)) if hasattr(df_list, "__len__") else None,
            "duplicate_skipped": duplicate_skipped,
        }

        # si publicó (o ya estaba publicado) -> registra
        if published and isinstance(drive_file_id, str) and drive_file_id.strip():
            reg["by_alias_fingerprint"][k] = {
                "alias": alias_upper,
                "fingerprint": fp,
                "published": True,
                "drive_file_id": drive_file_id,
                "drive_folder_id": drive_folder_id,
                "file": os.path.basename(local_path) if local_path else out_name,
                "rows": int(len(df_list)) if hasattr(df_list, "__len__") else None,
                "updated_at": datetime.now().isoformat(timespec="seconds"),
            }

    # ------------------------------
    # Metrics + persist registry
    # ------------------------------
    _mset("metrics.PR_08_MULTI", {"fingerprint": fp, "results": results})

    drive_folder_id, drive_file_id = _reg_save(reg)

    _mset("outputs.PR_08_MULTI.publish_registry_local", os.path.basename(reg_local_path))
    if drive_folder_id:
        _mset("outputs.PR_08_MULTI.publish_registry_drive_folder_id", drive_folder_id)
    if drive_file_id:
        _mset("outputs.PR_08_MULTI.publish_registry_drive_file_id", drive_file_id)

    # Logs limpios (máx 3 líneas)
    print("PR_08_MULTI · run_id =", getattr(rc, "run_id", None))
    print("PR_08_MULTI · fingerprint =", fp)
    print("PR_08_MULTI · published =", {k: v.get("published") for k, v in results.items()})

    return results, log

# SinergIA1758
# CONTACTO_VOZ: match ArbolHeuristico + extracción Contacto Directo (voz) + salida con estructura tipo DIGITAL_SMS.

import re
import numpy as np
import pandas as pd


def _ah_score_col(df_ah: pd.DataFrame) -> str | None:
    for c in df_ah.columns:
        if str(c).strip().lower() in ("score", "socre"):
            return c
    return None


def _norm_tipif(s: pd.Series) -> pd.Series:
    x = s.astype(str).fillna("")
    x = x.str.strip().str.upper()
    x = x.str.replace(r"[\s\-]+", "_", regex=True)
    x = x.str.replace(r"[^A-Z0-9_]", "", regex=True)
    return x


def _pick_col(df: pd.DataFrame, candidates: list[str]) -> str | None:
    for c in candidates:
        if c in df.columns:
            return c
    return None


def _export_genesys_latest_call_dt_and_result(df: pd.DataFrame) -> tuple[pd.Series | None, pd.Series | None]:
    dt_cols = sorted([c for c in df.columns if re.match(r"(?i)^CallRecordLastAttempt.*Telefono", str(c))])
    rs_cols = sorted([c for c in df.columns if re.match(r"(?i)^CallRecordLastResult.*Telefono", str(c))])
    if not dt_cols or not rs_cols:
        return None, None

    dt_df = df[dt_cols].apply(pd.to_datetime, errors="coerce")
    dt_max = dt_df.max(axis=1)

    # Selección liviana del resultado: primer no nulo, y si podemos alinearlo por idxmax (datasets moderados), mejor.
    if len(df) > 2_000_000:
        rs_first = df[rs_cols].bfill(axis=1).iloc[:, 0]
        return dt_max, rs_first

    dt_vals = dt_df.to_numpy(dtype="datetime64[ns]").astype("float64")
    idx = np.nanargmax(dt_vals, axis=1)
    rs_vals = df[rs_cols].to_numpy(dtype=object)
    rs_pick = pd.Series(rs_vals[np.arange(len(df)), idx], index=df.index)
    return dt_max, rs_pick


def sinergia_apply_arbol(df_hist: pd.DataFrame, kind: str, df_ah: pd.DataFrame) -> pd.DataFrame:
    if df_hist is None or len(df_hist) == 0 or df_ah is None or len(df_ah) == 0:
        return df_hist

    df = df_hist.copy()
    kind_u = str(kind or "").upper().strip()
    ah = df_ah.copy()
    score_col = _ah_score_col(ah)

    # Normalizar campos canónicos mínimos
    doc_col = _pick_col(df, [
        "Documento de identidad", "DocumentoIdentidad", "Identificacion", "Identificación",
        "IN_DOCUMENTO_DE_IDENTIDAD", "DocumentoDelContacto", "Rut", "RUT"
    ])
    if doc_col and "CAP_DOC" not in df.columns:
        df["CAP_DOC"] = df[doc_col]

    if kind_u == "EXPORT_GENESYS":
        dt_call, rs_call = _export_genesys_latest_call_dt_and_result(df)
        if dt_call is not None and "CAP_FECHA" not in df.columns:
            df["CAP_FECHA"] = dt_call
        if rs_call is not None and "CAP_TIPIFICACION" not in df.columns:
            df["CAP_TIPIFICACION"] = rs_call

    if "CAP_FECHA" not in df.columns:
        date_col = _pick_col(df, ["Fecha Gest", "FechaGest", "Fecha", "FechaGestion", "Fecha de Envio"])
        if date_col:
            df["CAP_FECHA"] = pd.to_datetime(df[date_col], errors="coerce")

    if "CAP_TIPIFICACION" not in df.columns:
        tipif_col = _pick_col(df, ["Tipificacion", "Tipificacion Export", "Resultado", "Estado Llamada"])
        if tipif_col:
            df["CAP_TIPIFICACION"] = df[tipif_col]

    # Join ArbolHeuristico
    if kind_u == "TRAZA":
        # TRAZA empata por COD Tipi (numérico)
        if "CAP_TIPIFICACION" not in df.columns:
            return df
        left = pd.to_numeric(df["CAP_TIPIFICACION"], errors="coerce")
        right = pd.to_numeric(ah.get("COD Tipi"), errors="coerce")
        m = pd.DataFrame({"_k": left})
        ah2 = ah.assign(_k=right)
        out = m.merge(ah2.dropna(subset=["_k"]), on="_k", how="left")
    else:
        # EXPORT_GENESYS / MEJORGEST empata por Tipificacion (string ININ-OUTBOUND-...)
        if "CAP_TIPIFICACION" not in df.columns or "Tipificacion" not in ah.columns:
            return df
        m = pd.DataFrame({"_k": _norm_tipif(df["CAP_TIPIFICACION"])})
        ah2 = ah.assign(_k=_norm_tipif(ah["Tipificacion"]))
        out = m.merge(ah2.drop_duplicates("_k"), on="_k", how="left")

    df["AH_RESUMEN_CONTACTO"] = out.get("Resumen Contacto")
    df["AH_TIPO_CONTACTO"] = out.get("Tipo Contacto")
    df["AH_CANAL"] = out.get("Canal")
    df["AH_PRIORIDAD"] = out.get("Prioridad")
    df["AH_TIPIFICACION_GENERAL"] = out.get("Tipificacion General")
    df["AH_SCORE"] = out.get(score_col) if score_col else np.nan

    return df


def _pick_best_phone(df_base: pd.DataFrame) -> pd.Series:
    """
    Selección determinística: Telefono 1..4 (o variantes) primer no nulo.
    """
    phone_cols = [c for c in df_base.columns if re.match(r"(?i)^Telefono\s*[1-4]$", str(c))]
    if not phone_cols:
        # variantes comunes
        for k in range(1, 5):
            for c in (f"Telefono {k}", f"Telefono{k}", f"TEL{k}", f"Telefono_{k}"):
                if c in df_base.columns:
                    phone_cols.append(c)
    phone_cols = [c for c in phone_cols if c in df_base.columns]
    if not phone_cols:
        # último fallback
        c = _pick_col(df_base, ["Telefono", "Teléfono", "Phone"])
        return df_base[c] if c else pd.Series([None] * len(df_base), index=df_base.index)

    return df_base[phone_cols].bfill(axis=1).iloc[:, 0]


def build_contacto_voz_list(
    df_base_in: pd.DataFrame,
    df_history: pd.DataFrame,
    history_kind: str,
    df_arbol: pd.DataFrame,
) -> pd.DataFrame:
    """
    Produce DF con estructura idéntica a DIGITAL_SMS, pero para CONTACTO_VOZ.
    Columnas: Identificación, Nombre, Telefono, Status, Fecha de Envio, Mes.
    """
    if df_base_in is None or len(df_base_in) == 0:
        return pd.DataFrame(columns=["Identificación", "Nombre", "Telefono", "Status", "Fecha de Envio", "Mes"])

    # Base: doc + nombre + teléfono
    base = df_base_in.copy()
    doc_col = _pick_col(base, ["Identificacion", "Identificación", "DocumentoIdentidad", "Documento de identidad", "IN_DOCUMENTO_DE_IDENTIDAD"])
    name_col = _pick_col(base, ["Nombre", "NombreCompleto", "NOMBRE", "Nombres", "Cliente", "Nombre Cliente"])
    if doc_col is None:
        return pd.DataFrame(columns=["Identificación", "Nombre", "Telefono", "Status", "Fecha de Envio", "Mes"])

    base["_DOC"] = base[doc_col].astype(str)
    base["_NOMBRE"] = base[name_col] if name_col else ""
    base["_TEL"] = _pick_best_phone(base)

    # History enriquecido + filtro Contacto Directo por voz
    if df_history is None or len(df_history) == 0:
        # Sin history, devolvemos plantilla vacía o lista base sin status/fecha
        out = pd.DataFrame({
            "Identificación": base["_DOC"],
            "Nombre": base["_NOMBRE"],
            "Telefono": base["_TEL"],
            "Status": None,
            "Fecha de Envio": None,
            "Mes": None,
        })
        return out

    h = sinergia_apply_arbol(df_history, history_kind, df_arbol)
    if h is None or len(h) == 0 or "CAP_DOC" not in h.columns:
        return pd.DataFrame(columns=["Identificación", "Nombre", "Telefono", "Status", "Fecha de Envio", "Mes"])

    canal = h.get("AH_CANAL", pd.Series([""] * len(h))).astype(str).str.upper().fillna("")
    is_voice = canal.str.contains(r"GENESYS|VOZ|IVR|PRESENCE|PRECENSE", regex=True)

    resumen = h.get("AH_RESUMEN_CONTACTO", pd.Series([""] * len(h))).astype(str).str.upper().fillna("")
    tipo = h.get("AH_TIPO_CONTACTO", pd.Series([""] * len(h))).astype(str).str.upper().fillna("")
    is_cd = (resumen == "CONTACTO") & tipo.str.contains("DIRECTO", regex=True)

    v = h.loc[is_voice & is_cd].copy()
    if len(v) == 0:
        return pd.DataFrame(columns=["Identificación", "Nombre", "Telefono", "Status", "Fecha de Envio", "Mes"])

    v["_DOC"] = v["CAP_DOC"].astype(str)
    v["_FECHA"] = pd.to_datetime(v.get("CAP_FECHA"), errors="coerce")
    v["_STATUS"] = v.get("AH_TIPIFICACION_GENERAL")
    if "_STATUS" not in v.columns or v["_STATUS"].isna().all():
        v["_STATUS"] = v.get("CAP_TIPIFICACION")

    # 1 registro por documento: último evento por fecha
    v = v.sort_values(["_DOC", "_FECHA"]).drop_duplicates(subset=["_DOC"], keep="last")

    # Join con base para nombre y teléfono
    m = base[["_DOC", "_NOMBRE", "_TEL"]].drop_duplicates("_DOC")
    v = v.merge(m, on="_DOC", how="left")

    out = pd.DataFrame({
        "Identificación": v["_DOC"],
        "Nombre": v["_NOMBRE"],
        "Telefono": v["_TEL"],
        "Status": v["_STATUS"],
        "Fecha de Envio": v["_FECHA"],
        "Mes": v["_FECHA"].dt.strftime("%b"),
    })

    return out

# SinergIA1760 · Helpers: listar meta en Drive + autoload TRAZA (último día) sin previsualizar
def drive_list_files_in_folder_meta(folder_id: str, max_results: int = 200):
    """
    Retorna lista de dicts con meta: id, name, mimeType, modifiedTime (orden desc por modifiedTime).
    """
    if not folder_id:
        return []

    q = f"'{folder_id}' in parents and trashed = false"
    fields = "nextPageToken, files(id, name, mimeType, modifiedTime)"

    out = []
    page_token = None
    while True:
        resp = drive_service.files().list(
            q=q,
            spaces="drive",
            fields=fields,
            pageToken=page_token,
            pageSize=min(max_results, 1000),
            orderBy="modifiedTime desc",
            supportsAllDrives=True,
            includeItemsFromAllDrives=True,
        ).execute()

        files = resp.get("files", []) or []
        for f in files:
            out.append({
                "id": f.get("id"),
                "name": f.get("name"),
                "mimeType": f.get("mimeType"),
                "modifiedTime": f.get("modifiedTime"),
            })
            if len(out) >= max_results:
                return out[:max_results]

        page_token = resp.get("nextPageToken")
        if not page_token:
            break

    return out[:max_results]


def sinergia_autoload_traza_latest_day(
    folder_id: str,
    max_results: int = 200,
    max_files_same_day: int = 10,
    nrows_per_file: int = 5000,
):
    """
    Selecciona archivos TRAZA del último día disponible según nombre (YYYY-MM-DD) si existe,
    o por modifiedTime si no hay fecha en nombre.  Devuelve (df_traza_concat, files_used_meta).
    Nota: lectura limitada por nrows_per_file por archivo (peso controlado).
    """
    import re
    import pandas as pd

    files = drive_list_files_in_folder_meta(folder_id, max_results=max_results)

    # Filtrar candidatos por nombre (TRAZA)
    cand = []
    for f in files:
        name = str(f.get("name") or "")
        if "traza" in name.lower():
            cand.append(f)

    if not cand:
        return pd.DataFrame(), []

    # Determinar "día" objetivo (por fecha en nombre si existe)
    def _date_from_name(n: str):
        m = re.search(r"(\d{4}-\d{2}-\d{2})", n)
        return m.group(1) if m else None

    dates = [(_date_from_name(str(f.get("name") or "")), f) for f in cand]
    dated = [x for x in dates if x[0] is not None]

    if dated:
        target_day = dated[0][0]  # cand viene en modifiedTime desc, primer match es el más reciente
        chosen = [f for (d, f) in dated if d == target_day][:max_files_same_day]
    else:
        target_day = None
        chosen = cand[:1]  # sin fecha, tomar solo el más reciente para evitar autopick agresivo

    # Descargar y concatenar
    dfs = []
    used = []
    for f in chosen:
        fid = f.get("id")
        name = f.get("name")
        if not fid or not name:
            continue

        try:
            _name, data = drive_download_file(fid)
            df_part = _read_any_bytes_to_df(str(name), data, nrows=int(nrows_per_file))
            if isinstance(df_part, pd.DataFrame) and not df_part.empty:
                dfs.append(df_part)
            used.append({
                "source": "TRAZA",
                "file": str(name),
                "file_id": str(fid),
                "modifiedTime": str(f.get("modifiedTime") or ""),
                "picked_day": str(target_day or ""),
                "rows_read": int(len(df_part)) if hasattr(df_part, "__len__") else 0,
            })
        except Exception:
            used.append({
                "source": "TRAZA",
                "file": str(name),
                "file_id": str(fid),
                "modifiedTime": str(f.get("modifiedTime") or ""),
                "picked_day": str(target_day or ""),
                "rows_read": 0,
            })

    df_out = pd.concat(dfs, ignore_index=True) if dfs else pd.DataFrame()
    return df_out, used

# SinergIA1750 - GUI handler: Derivar Listas (PR_06 + PR_07 + PR_08_MULTI)
# Salidas: df_listas_show, df_listas_sources, previews + files por canal, run_id, log


def _sinergia_btn_listas_preview(
    preview_rows_listas,
    df_prev_wa,
    df_prev_wise,
    df_prev_sms,
    df_prev_voz,
    txt_log,
):
    import pandas as pd

    # No recalcula.  Solo recorta lo ya cargado para render estable.
    try:
        n = int(preview_rows_listas or 3000)
    except Exception:
        n = 3000
    n = max(1000, min(10000, n))

    def _to_df(v):
        if v is None or v == "":
            return pd.DataFrame()
        if isinstance(v, pd.DataFrame):
            return v
        try:
            return pd.DataFrame(v)
        except Exception:
            return pd.DataFrame()

    return (
        _to_df(df_prev_wa).head(n),
        _to_df(df_prev_wise).head(n),
        _to_df(df_prev_sms).head(n),
        _to_df(df_prev_voz).head(n),
        txt_log,
    )


def _sinergia_traza_contactados_cd_min(df_traza, rc=None):
    """
    DF mínimo para CONTACTO_VOZ: solo contactados con tipificación CD.  Deduplicado por documento.
    Contrato operativo: contactado = CD.  Intentos sin contacto no cuentan.
    """
    import pandas as pd
    import re

    if df_traza is None or getattr(df_traza, "empty", True):
        if rc is not None:
            try:
                rc.set_manifest("metrics.CONTACTO_VOZ", {"ok": False, "reason": "TRAZA_EMPTY"})
            except Exception:
                pass
        return pd.DataFrame()

    def _norm(s):
        return re.sub(r"[^A-Z0-9]+", "_", str(s).upper()).strip("_")

    cols = list(df_traza.columns)

    def _pick(cands):
        want = {_norm(c): c for c in (cands or [])}
        for c in cols:
            if _norm(c) in want:
                return c
        return None

    c_doc = _pick([
        "IN_DOCUMENTO_DE_IDENTIDAD",
        "DOCUMENTO_DE_IDENTIDAD",
        "Documento de identidad",
        "DocumentoDeIdentidad",
        "Identificacion",
        "Identificación",
    ])
    c_tip = _pick([
        "CAP_TIPIFICACION",
        "TIPIFICACION",
        "Tipificacion",
        "Outcome",
        "OUTCOME",
        "Resultado",
        "RESULTADO",
        "Disposition",
        "DISPOSITION",
    ])
    c_sub = _pick(["CAP_SUBTIPIFICACION", "SUBTIPIFICACION", "Subtipificacion"])
    c_canal = _pick(["CAP_CANAL", "CANAL", "Canal", "CHANNEL", "Channel"])
    c_fecha = _pick([
        "CAP_FECHA",
        "FECHA",
        "Fecha",
        "EVENT_TIME",
        "EventTime",
        "START_TIME",
        "StartTime",
        "ULTIMA_ACTUALIZACION_FECHA",
    ])
    c_telc = _pick(["CAP_TELEFONO_CONTACTO", "TELEFONO_CONTACTO", "TelefonoContacto", "Telefono Contacto"])
    c_itx = _pick(["IN_INTERACTIONID", "InteractionId", "INTERACTIONID", "INTERACTION_ID"])

    if not c_doc or not c_tip:
        if rc is not None:
            try:
                rc.set_manifest("metrics.CONTACTO_VOZ", {"ok": False, "reason": "MISSING_DOC_OR_TIPIFICACION"})
            except Exception:
                pass
        return pd.DataFrame()

    tip = df_traza[c_tip].fillna("").astype(str).str.strip().str.upper()
    tip_norm = tip.str.replace(r"[^A-Z0-9]+", "", regex=True)
    mask = tip_norm.eq("CD")

    canal_mode = "NONE"
    if c_canal and c_canal in df_traza.columns:
        canal = df_traza[c_canal].fillna("").astype(str).str.upper()
        if canal.str.contains("ACD", na=False).any():
            mask = mask & canal.str.contains("ACD", na=False)
            canal_mode = "ACD"
        elif canal.str.contains(r"VOZ|LLAM|CALL", na=False).any():
            mask = mask & canal.str.contains(r"VOZ|LLAM|CALL", na=False)
            canal_mode = "VOICE_FALLBACK"

    keep_cols = [c_doc] + [c for c in [c_fecha, c_canal, c_tip, c_sub, c_telc, c_itx] if c and c in df_traza.columns]
    df_cd = df_traza.loc[mask, keep_cols].copy()

    ren = {c_doc: "IN_DOCUMENTO_DE_IDENTIDAD", c_tip: "CAP_TIPIFICACION"}
    if c_fecha:
        ren[c_fecha] = "CAP_FECHA"
    if c_canal:
        ren[c_canal] = "CAP_CANAL"
    if c_sub:
        ren[c_sub] = "CAP_SUBTIPIFICACION"
    if c_telc:
        ren[c_telc] = "CAP_TELEFONO_CONTACTO"
    if c_itx:
        ren[c_itx] = "IN_INTERACTIONID"
    df_cd = df_cd.rename(columns=ren)

    # Dedupe por documento.  Si hay fecha, prioriza la más reciente.
    if "CAP_FECHA" in df_cd.columns:
        dt = pd.to_datetime(df_cd["CAP_FECHA"], errors="coerce")
        df_cd["_dt"] = dt
        if dt.notna().any():
            df_cd = df_cd.sort_values("_dt", ascending=False, kind="stable")
        df_cd = df_cd.drop_duplicates(subset=["IN_DOCUMENTO_DE_IDENTIDAD"], keep="first").drop(columns=["_dt"])
    else:
        df_cd = df_cd.drop_duplicates(subset=["IN_DOCUMENTO_DE_IDENTIDAD"], keep="first")

    if rc is not None:
        try:
            rc.set_manifest(
                "metrics.CONTACTO_VOZ",
                {
                    "ok": True,
                    "canal_mode": canal_mode,
                    "cd_rows_raw": int(mask.sum()),
                    "docs_unique": int(len(df_cd)),
                },
            )
        except Exception:
            pass

    return df_cd


def _sinergia_btn_listas_derivar(
    df_prev_in_local,         # df_prev_in (GUI)
    dd_archivo_gestion,       # selector history (Drive)
    file_gestion_local,       # upload history (local)
    prefer_traza,             # chk_use_traza_for_listas (GUI)
    txt_log,                  # txt_log (GUI)
    preview_rows_listas,      # sl_visualizar_listas (GUI)
):
    import pandas as pd
    import inspect
    import os

    # Blindaje: evitar NameError si el notebook arranca "frío" o cambian órdenes de ejecución.
    globals().setdefault("DF_IN_PREVIEW_CACHE", None)
    globals().setdefault("DF_GESTION_CACHE", None)
    globals().setdefault("DF_TELETON_CACHE", None)
    globals().setdefault("DF_BOLSAS_CACHE", None)
    globals().setdefault("DF_LISTAS_SHOW_CACHE", None)
    globals().setdefault("CFG_SHEETS_COMPONENTS", {})
    globals().setdefault("DF_TRAZA_CACHE", None)
    globals().setdefault("DF_EXPORT_GENESYS_CACHE", None)
    globals().setdefault("DF_MEJORGEST_LOG_CACHE", None)

    def _df_empty(cols=None):
        return pd.DataFrame(columns=(cols or []))

    def _safe_get(d, path: str, default=None):
        try:
            cur = d
            for k in (path or "").split("."):
                if k == "":
                    continue
                if not isinstance(cur, dict):
                    return default
                cur = cur.get(k)
            return default if cur is None else cur
        except Exception:
            return default

    def _safe_call(func, **kwargs):
        try:
            sig = inspect.signature(func)
            filt = {k: v for k, v in kwargs.items() if k in sig.parameters}
            return func(**filt)
        except Exception:
            return func(**kwargs)

    def _extract_local_filename_from_gui(file_obj):
        try:
            if file_obj is None:
                return ""
            if isinstance(file_obj, dict):
                return str(file_obj.get("name", "") or "")
            if hasattr(file_obj, "name"):
                return str(getattr(file_obj, "name", "") or "")
            return str(file_obj)
        except Exception:
            return ""

    def _extract_local_path_from_gui(file_obj):
        try:
            if file_obj is None:
                return ""
            if isinstance(file_obj, dict):
                p = str(file_obj.get("path", "") or "")
                if p:
                    return p
                n = str(file_obj.get("name", "") or "")
                return n
            if hasattr(file_obj, "name"):
                return str(getattr(file_obj, "name", "") or "")
            if isinstance(file_obj, str):
                return file_obj
            return ""
        except Exception:
            return ""

    def _preview_from_info(info: dict, max_rows: int = 200):
        try:
            if not isinstance(info, dict):
                return _df_empty()
            for k in ["df_preview", "df", "dataframe"]:
                v = info.get(k)
                if isinstance(v, pd.DataFrame) and not v.empty:
                    return v.head(max_rows).copy()
            f = info.get("file")
            if isinstance(f, str) and f and os.path.exists(f):
                ext = os.path.splitext(f.lower())[1]
                if ext in [".csv", ".txt"]:
                    return pd.read_csv(f, nrows=max_rows).copy()
                if ext in [".xlsx", ".xls"]:
                    return pd.read_excel(f, nrows=max_rows).copy()
                if ext in [".parquet"]:
                    df0 = pd.read_parquet(f)
                    return df0.head(max_rows).copy()
        except Exception:
            pass
        return _df_empty()

    def _pack_fail(rc, msg: str):
        df_show = pd.DataFrame(
            [
                {
                    "alias": "",
                    "published": None,
                    "drive_file_id": None,
                    "file": None,
                    "rows": 0,
                    "duplicate_skipped": None,
                }
            ],
            columns=["alias", "published", "drive_file_id", "file", "rows", "duplicate_skipped"],
        )

        df_sources = (
            pd.DataFrame(
                [
                    {
                        "kind": "history",
                        "preference": "",
                        "used": "",
                        "fallback_used": False,
                        "traza_rows": 0,
                        "gestion_rows": 0,
                        "file": "",
                        "drive_file_id": "",
                        "note": msg,
                    }
                ],
                columns=[
                    "kind",
                    "preference",
                    "used",
                    "fallback_used",
                    "traza_rows",
                    "gestion_rows",
                    "file",
                    "drive_file_id",
                    "note",
                ],
            )
            if rc is not None
            else pd.DataFrame(
                columns=[
                    "kind",
                    "preference",
                    "used",
                    "fallback_used",
                    "traza_rows",
                    "gestion_rows",
                    "file",
                    "drive_file_id",
                    "note",
                ]
            )
        )

        return (
            df_show,
            df_sources,
            _df_empty(),
            None,
            _df_empty(),
            None,
            _df_empty(),
            None,
            _df_empty(),
            None,
            getattr(rc, "run_id", "") if rc is not None else "",
            msg,
        )

    rc = None

    try:
        # Guardrails mínimos: si falta RunContext, no dejamos caer Gradio.
        if "sinergia_new_run_context" not in globals() or not callable(globals().get("sinergia_new_run_context")):
            return _pack_fail(None, "PR_08_MULTI FAIL.  sinergia_new_run_context no está definido.")

        # RunContext
        rc = sinergia_new_run_context(
            "PR_08_MULTI",
            meta={
                "ui_action": "btn_listas",
                "source": "DF_IN_PREVIEW_CACHE|df_prev_in",
                "history": "TRAZA|EXPORT_GENESYS (según checkbox)",
            },
        )

        # Preview rows (manifest)
        try:
            _n_prev = int(preview_rows_listas or 3000)
        except Exception:
            _n_prev = 3000
        _n_prev = max(1000, min(10000, _n_prev))
        try:
            rc.set_manifest("ui.preview_rows_listas", int(_n_prev))
        except Exception:
            pass

        # Preferencia historia (checkbox) => decisión: TRAZA vs EXPORT_GENESYS
        prefer_traza = True if prefer_traza is None else bool(prefer_traza)
        desired_kind = "TRAZA" if prefer_traza else "EXPORT_GENESYS"
        try:
            rc.set_manifest("inputs.history.preference", desired_kind)
            rc.set_manifest("inputs.history.desired_kind", desired_kind)
        except Exception:
            pass

        # 1) Base IN (cache primero, luego GUI)
        df_base_cache = globals().get("DF_IN_PREVIEW_CACHE", None)
        df_base = df_base_cache if isinstance(df_base_cache, pd.DataFrame) and not df_base_cache.empty else None
        if df_base is None and isinstance(df_prev_in_local, pd.DataFrame) and not df_prev_in_local.empty:
            df_base = df_prev_in_local.copy()

        if df_base is None or not isinstance(df_base, pd.DataFrame) or df_base.empty:
            try:
                rc.set_manifest("inputs.base.rows", 0)
                rc.add_event(
                    code="PR08_MULTI_FAIL_NO_BASE",
                    level="ERROR",
                    message="No hay base IN disponible.  Ejecuta primero 'Limpiar rutina' y verifica que IN_SISTECREDITO (limpia) tenga filas.",
                    data={},
                    etapa="PR_08",
                )
                rc.finalize("FAIL")
            except Exception:
                pass
            return _pack_fail(rc, "PR_08_MULTI FAIL.  No hay base IN (cache ni GUI).")

        df_base = df_base.copy()
        try:
            rc.set_manifest("inputs.base.rows", int(len(df_base)))
        except Exception:
            pass

        # 2) Config (si existe en componentes)
        cfg_sheets = globals().get("CFG_SHEETS_COMPONENTS", {})
        cfg_sheets = cfg_sheets if isinstance(cfg_sheets, dict) else {}
        df_params = (
            _get_parameters_df_from_components(cfg_sheets)
            if cfg_sheets and ("_get_parameters_df_from_components" in globals())
            else None
        )
        df_estructuras = (
            _get_estructuras_df_from_components(cfg_sheets)
            if cfg_sheets and ("_get_estructuras_df_from_components" in globals())
            else None
        )

        # 3) Continuación (tail) para mantener etiqueta separada sin romper Python.
        if "_sinergia_btn_listas_derivar_tail_1755" not in globals() or not callable(
            globals().get("_sinergia_btn_listas_derivar_tail_1755")
        ):
            return _pack_fail(rc, "PR_08_MULTI FAIL.  _sinergia_btn_listas_derivar_tail_1755 no está definido.")

        return _sinergia_btn_listas_derivar_tail_1755(
            df_prev_in_local=df_prev_in_local,
            dd_archivo_gestion=dd_archivo_gestion,
            file_gestion_local=file_gestion_local,
            prefer_traza=prefer_traza,
            txt_log=txt_log,
            preview_rows_listas=preview_rows_listas,
            rc=rc,
            df_base=df_base,
            df_params=df_params,
            df_estructuras=df_estructuras,
            n_prev=int(_n_prev),
            _safe_call=_safe_call,
            _pack_fail=_pack_fail,
            _preview_from_info=_preview_from_info,
            _extract_local_filename_from_gui=_extract_local_filename_from_gui,
            _extract_local_path_from_gui=_extract_local_path_from_gui,
            _safe_get=_safe_get,
            _df_empty=_df_empty,
            _traza_cd_min=_sinergia_traza_contactados_cd_min,
        )

    except Exception as e_outer:
        msg = f"PR_08_MULTI FAIL.  {type(e_outer).__name__}: {e_outer}"
        try:
            if rc is not None and hasattr(rc, "add_event"):
                rc.add_event(code="PR08_MULTI_FATAL", level="ERROR", message=msg, data={}, etapa="PR_08")
            if rc is not None and hasattr(rc, "finalize"):
                rc.finalize("FAIL")
        except Exception:
            pass
        return _pack_fail(rc, msg)

# SinergIA1755 - GUI handler: Derivar Listas (tail)
# Continuación de _sinergia_btn_listas_derivar sin partir un `def` en dos.
# v1755.3 HOTFIX:
# - Enfocado en desbloquear 504 del Launcher:  cero dependencias nuevas, sin ArbolHeuristico aún.
# - CAP_FECHA para EXPORT_GENESYS derivada desde CallRecordLastAttempt-Telefono X y SmsLastAttempt-Telefono X.
# - Mantiene comportamiento previo para PR_06/PR_07/PR_08.


def _sinergia_btn_listas_derivar_tail_1755(
    *,
    df_prev_in_local,
    dd_archivo_gestion,
    file_gestion_local,
    prefer_traza,
    txt_log,
    preview_rows_listas,
    rc,
    df_base,
    df_params,
    df_estructuras,
    n_prev,
    _safe_call,
    _pack_fail,
    _preview_from_info,
    _extract_local_filename_from_gui,
    _extract_local_path_from_gui,
    _safe_get,
    _df_empty,
    _traza_cd_min,
):
    import pandas as pd
    import os
    import re

    # Blindaje adicional: caches esperados.
    globals().setdefault("DF_TRAZA_CACHE", None)
    globals().setdefault("DF_EXPORT_GENESYS_CACHE", None)
    globals().setdefault("DF_MEJORGEST_LOG_CACHE", None)
    globals().setdefault("DF_TELETON_CACHE", None)
    globals().setdefault("DF_BOLSAS_CACHE", None)
    globals().setdefault("DF_LISTAS_SHOW_CACHE", None)

    def _norm_col(s):
        return re.sub(r"[^A-Z0-9]+", "_", str(s).upper()).strip("_")

    def _detect_kind_from_filename(fn: str):
        f = str(fn or "").upper()
        if "TRAZA" in f:
            return "TRAZA"
        if "MEJORGEST_LOG" in f or ("MEJORGEST" in f and "LOG" in f):
            return "MEJORGEST_LOG"
        if "MEJORGEST_EXPORT" in f or ("MEJORGEST" in f and "EXPORT" in f):
            return "EXPORT_GENESYS"
        if "EXPORT_GENESYS" in f or "GENESYS" in f or "OUTBOUND" in f:
            return "EXPORT_GENESYS"
        return ""

    def _detect_history_kind(df: pd.DataFrame, filename: str = ""):
        if df is None or getattr(df, "empty", True):
            return ""

        by_name = _detect_kind_from_filename(filename)
        cols = [_norm_col(c) for c in list(df.columns)]
        s = set(cols)

        # TRAZA: columnas CAP_*, tipificación, canal.
        if any(c.startswith("CAP_") for c in s) or ("CAP_TIPIFICACION" in s) or ("CAP_FECHA" in s):
            return "TRAZA" if not by_name else by_name

        # EXPORT_GENESYS: identificadores y/o last attempt por teléfono.
        if ("ININ_OUTBOUND_ID" in s) or any("CALLRECORDLASTATTEMPT" in c for c in s) or any(
            "SMSLASTATTEMPT" in c for c in s
        ):
            return "EXPORT_GENESYS"

        if by_name:
            return by_name

        return ""

    def _adapt_export_genesys_for_pr07(df: pd.DataFrame, rc=None):
        """PR_07 necesita documento + CAP_FECHA.

        EXPORT_GENESYS suele traer last attempts por teléfono.
        Deriva CAP_FECHA como el máximo por fila entre:
        - CallRecordLastAttempt-Telefono X
        - SmsLastAttempt-Telefono X

        Nota: esta función NO intenta inferir scoring ni ArbolHeuristico (se implementa después, por etapas).
        """
        if df is None or getattr(df, "empty", True):
            return df

        df2 = df.copy()

        # Normalizar doc a IN_DOCUMENTO_DE_IDENTIDAD (si existe una columna equivalente)
        cols_norm = {_norm_col(c): c for c in list(df2.columns)}
        doc_src = None
        for cand in [
            "IN_DOCUMENTO_DE_IDENTIDAD",
            "DOCUMENTO_DE_IDENTIDAD",
            "DOCUMENTOIDENTIDAD",
            "DOCUMENTODEIDENTIDAD",
            "IDENTIFICACION",
            "IDENTIFICACIÓN",
            "NUMERODOCUMENTO",
            "NUMERO_DOCUMENTO",
        ]:
            if cand in cols_norm:
                doc_src = cols_norm[cand]
                break
        if doc_src and doc_src != "IN_DOCUMENTO_DE_IDENTIDAD":
            try:
                df2 = df2.rename(columns={doc_src: "IN_DOCUMENTO_DE_IDENTIDAD"})
            except Exception:
                pass

        # Encontrar columnas *LastAttempt* por teléfono (CALL/SMS)
        attempt_cols = []
        for c in list(df2.columns):
            cn = _norm_col(c)
            # Se soporta tanto "-Telefono 1" como "_Telefono_1" gracias a _norm_col
            if cn.startswith("CALLRECORDLASTATTEMPT_TELEFONO_") or cn.startswith("SMSLASTATTEMPT_TELEFONO_"):
                attempt_cols.append(c)

        if not attempt_cols:
            if rc is not None:
                try:
                    rc.add_event(
                        code="PR07_WARN_EXPORT_NO_LASTATTEMPT",
                        level="WARN",
                        message="EXPORT_GENESYS cargado pero no se encontraron columnas CallRecordLastAttempt/SmsLastAttempt por teléfono.  PR_07 puede fallar por history vacío.",
                        data={},
                        etapa="PR_07",
                    )
                except Exception:
                    pass
            return df2

        # Parsear timestamps y tomar máximo real por fila
        try:
            dts = []
            for c in attempt_cols:
                s = pd.to_datetime(df2[c], errors="coerce", utc=True)
                try:
                    s = s.dt.tz_convert(None)
                except Exception:
                    try:
                        s = s.dt.tz_localize(None)
                    except Exception:
                        pass
                dts.append(s)

            if not dts:
                return df2

            df_tmp = pd.concat(dts, axis=1)
            df2["CAP_FECHA"] = df_tmp.max(axis=1)

            if rc is not None:
                try:
                    ratio = float(pd.to_datetime(df2["CAP_FECHA"], errors="coerce").notna().mean()) if len(df2) else 0.0
                    rc.set_manifest("inputs.export_genesys.cap_fecha_parse_ratio", ratio)
                except Exception:
                    pass

            return df2
        except Exception:
            return df2

    # 0) Preferencia historia (checkbox)
    prefer_traza = True if prefer_traza is None else bool(prefer_traza)
    desired_kind = "TRAZA" if prefer_traza else "EXPORT_GENESYS"

    # 1) Carga robusta de history (TRAZA vs EXPORT_GENESYS).  Evita confundir caches.
    traza_rows = 0
    export_rows = 0
    mejorgest_rows = 0
    traza_file_name = ""
    export_file_name = ""
    mejorgest_file_name = ""

    # Auto-migración: si DF_TRAZA_CACHE trae EXPORT_GENESYS por error previo, lo movemos.
    try:
        df_traza_cache = globals().get("DF_TRAZA_CACHE", None)
        if isinstance(df_traza_cache, pd.DataFrame) and not df_traza_cache.empty:
            k0 = _detect_history_kind(df_traza_cache, filename="")
            if k0 == "EXPORT_GENESYS":
                globals()["DF_EXPORT_GENESYS_CACHE"] = df_traza_cache.copy()
                globals()["DF_TRAZA_CACHE"] = None
                try:
                    rc.add_event(
                        code="PR07_FIX_TRAZA_CACHE_WAS_EXPORT",
                        level="WARN",
                        message="DF_TRAZA_CACHE contenía EXPORT_GENESYS (alfanuméricos).  Se migró a DF_EXPORT_GENESYS_CACHE para evitar confusión.",
                        data={},
                        etapa="PR_07",
                    )
                except Exception:
                    pass
    except Exception:
        pass

    # Resolver input file (selector o upload)
    hist_name = str(dd_archivo_gestion or "").strip()
    hist_name = hist_name if hist_name else _extract_local_filename_from_gui(file_gestion_local)
    hist_path = _extract_local_path_from_gui(file_gestion_local)

    effective_kind = ""
    df_history = None

    # 1.1) Obtener desde cache si aplica
    try:
        if desired_kind == "TRAZA":
            df0 = globals().get("DF_TRAZA_CACHE", None)
            if isinstance(df0, pd.DataFrame) and not df0.empty:
                df_history = df0.copy()
                effective_kind = "TRAZA"
                traza_rows = int(len(df_history))
        else:
            df0 = globals().get("DF_EXPORT_GENESYS_CACHE", None)
            if isinstance(df0, pd.DataFrame) and not df0.empty:
                df_history = df0.copy()
                effective_kind = "EXPORT_GENESYS"
                export_rows = int(len(df_history))
    except Exception:
        pass

    # 1.2) Si no hay cache, cargar del selector/upload usando loader existente o lectura local.
    if df_history is None:
        try:
            if ("_load_gestion_any_source" in globals()) and callable(globals().get("_load_gestion_any_source")):
                if hist_name or (file_gestion_local is not None):
                    df_hist_raw, _ = _load_gestion_any_source(
                        dd_archivo_gestion=dd_archivo_gestion,
                        file_gestion_local=file_gestion_local,
                        log="",
                    )
                    if isinstance(df_hist_raw, pd.DataFrame) and not df_hist_raw.empty:
                        detected = _detect_history_kind(df_hist_raw, filename=hist_name)
                        effective_kind = detected or desired_kind
                        df_history = df_hist_raw.copy()
            else:
                if hist_path and os.path.exists(hist_path):
                    ext = os.path.splitext(hist_path.lower())[1]
                    if ext in [".csv", ".txt", ".tsv"]:
                        try:
                            df_hist_raw = pd.read_csv(hist_path, sep=None, engine="python")
                        except Exception:
                            df_hist_raw = pd.read_csv(hist_path)
                    else:
                        df_hist_raw = pd.read_excel(hist_path)
                    if isinstance(df_hist_raw, pd.DataFrame) and not df_hist_raw.empty:
                        detected = _detect_history_kind(df_hist_raw, filename=hist_name)
                        effective_kind = detected or desired_kind
                        df_history = df_hist_raw.copy()
        except Exception:
            pass

    detected_kind = _detect_history_kind(df_history, filename=hist_name) if isinstance(df_history, pd.DataFrame) else ""
    if not effective_kind:
        effective_kind = detected_kind or ""

    # Si el archivo cargado no coincide con el checkbox, marcamos fallback por mismatch.
    fallback_kind_mismatch = bool(effective_kind and desired_kind and (effective_kind != desired_kind))

    try:
        rc.set_manifest("inputs.history.preference", desired_kind)
        rc.set_manifest("inputs.history.desired_kind", desired_kind)
        rc.set_manifest("inputs.history.detected_kind", detected_kind)
        rc.set_manifest("inputs.history.used_kind", effective_kind or "")
        rc.set_manifest("inputs.history.fallback_kind_mismatch", fallback_kind_mismatch)
    except Exception:
        pass

    if fallback_kind_mismatch:
        try:
            rc.add_event(
                code="PR07_WARN_HISTORY_KIND_MISMATCH",
                level="WARN",
                message=f"Checkbox pedía {desired_kind} pero el archivo cargado parece {effective_kind}.  Se usa {effective_kind} para no romper la corrida.",
                data={"desired": desired_kind, "effective": effective_kind, "file": hist_name},
                etapa="PR_07",
            )
        except Exception:
            pass

    # Persistir en caches correctos + contadores + archivos
    try:
        if effective_kind == "TRAZA":
            globals()["DF_TRAZA_CACHE"] = df_history.copy() if isinstance(df_history, pd.DataFrame) else None
            traza_rows = int(len(df_history)) if isinstance(df_history, pd.DataFrame) else 0
            traza_file_name = hist_name
        elif effective_kind == "EXPORT_GENESYS":
            globals()["DF_EXPORT_GENESYS_CACHE"] = df_history.copy() if isinstance(df_history, pd.DataFrame) else None
            export_rows = int(len(df_history)) if isinstance(df_history, pd.DataFrame) else 0
            export_file_name = hist_name
        elif effective_kind == "MEJORGEST_LOG":
            globals()["DF_MEJORGEST_LOG_CACHE"] = df_history.copy() if isinstance(df_history, pd.DataFrame) else None
            mejorgest_rows = int(len(df_history)) if isinstance(df_history, pd.DataFrame) else 0
            mejorgest_file_name = hist_name
    except Exception:
        pass

    # Adaptación para PR_07
    df_traza_for_pr07 = None
    df_mejorgest_for_pr07 = None
    if effective_kind == "EXPORT_GENESYS":
        df_traza_for_pr07 = _adapt_export_genesys_for_pr07(df_history, rc=rc)
    elif effective_kind == "TRAZA":
        df_traza_for_pr07 = df_history
    elif effective_kind == "MEJORGEST_LOG":
        df_mejorgest_for_pr07 = df_history

    # Manifest inputs de filas + archivos
    try:
        rc.set_manifest("inputs.traza.rows", int(traza_rows))
        if traza_file_name:
            rc.set_manifest("inputs.traza.file", traza_file_name)
    except Exception:
        pass
    try:
        rc.set_manifest("inputs.export_genesys.rows", int(export_rows))
        if export_file_name:
            rc.set_manifest("inputs.export_genesys.file", export_file_name)
    except Exception:
        pass
    try:
        rc.set_manifest("inputs.mejorgest_log.rows", int(mejorgest_rows))
        if mejorgest_file_name:
            rc.set_manifest("inputs.mejorgest_log.file", mejorgest_file_name)
    except Exception:
        pass

    # 2) Guardrails de funciones
    for fn_name, etapa, msg in [
        ("sinergia_pr06_build_teleton_y_bolsas_min", "PR_06", "sinergia_pr06_build_teleton_y_bolsas_min no está definido."),
        ("sinergia_pr07_compliance_gate_min", "PR_07", "sinergia_pr07_compliance_gate_min no está definido."),
        ("sinergia_pr08_publish_multi", "PR_08", "sinergia_pr08_publish_multi no está definido."),
    ]:
        if fn_name not in globals() or not callable(globals().get(fn_name)):
            try:
                rc.add_event(code=f"{etapa}_MISSING", level="ERROR", message=msg, data={}, etapa=etapa)
                rc.finalize("FAIL")
            except Exception:
                pass
            return _pack_fail(rc, f"{etapa} FAIL.  Función no definida.")
    # 2.5) Base efectiva: FULL si existe (exporta FULL, preview solo muestra N filas)
    df_base_effective = df_base
    base_used = "IN_SISTECREDITO_PREVIEW"
    try:
        df_full = globals().get("DF_IN_FULL_CACHE", None)
        if isinstance(df_full, pd.DataFrame) and (not df_full.empty):
            df_base_effective = df_full
            base_used = "IN_SISTECREDITO_FULL"
    except Exception:
        pass

    try:
        rc.set_manifest("inputs.base_in.used", base_used)
        rc.set_manifest(
            "inputs.base_in.rows",
            int(len(df_base_effective)) if isinstance(df_base_effective, pd.DataFrame) else 0,
        )
    except Exception:
        pass

    # 3) PR_06
    try:
        df_tele, df_bolsas, _, rc = _safe_call(
            sinergia_pr06_build_teleton_y_bolsas_min,
            df_base_cobranza=df_base_effective,
            log="",
            rc=rc,
            df_estructuras=df_estructuras,
            sample_rows=0,
        )
        globals()["DF_TELETON_CACHE"] = df_tele.copy() if isinstance(df_tele, pd.DataFrame) else None
        globals()["DF_BOLSAS_CACHE"] = df_bolsas.copy() if isinstance(df_bolsas, pd.DataFrame) else None
        try:
            rc.set_manifest("metrics.PR_06.teleton_rows", int(len(df_tele)) if isinstance(df_tele, pd.DataFrame) else 0)
            rc.set_manifest("metrics.PR_06.bolsas_rows", int(len(df_bolsas)) if isinstance(df_bolsas, pd.DataFrame) else 0)
        except Exception:
            pass
    except Exception as e:
        try:
            rc.add_event(code="PR_06_FAIL", level="ERROR", message=str(e), data={}, etapa="PR_06")
            rc.finalize("FAIL")
        except Exception:
            pass
        return _pack_fail(rc, f"PR_06 FAIL.  {e}")

    # 4) PR_07
    try:
        df_el, df_ex, _, rc = _safe_call(
            sinergia_pr07_compliance_gate_min,
            df_base_cobranza=df_base_effective,
            df_mejorgest_log=df_mejorgest_for_pr07,
            df_traza=df_traza_for_pr07,
            log="",
            rc=rc,
            df_params=df_params,
            strict_no_history=True,
            dev_override_allow_pass=False,
            sample_rows=0,
        )

        elig = int(len(df_el)) if isinstance(df_el, pd.DataFrame) else 0
        excl = int(len(df_ex)) if isinstance(df_ex, pd.DataFrame) else 0
        try:
            rc.set_manifest("metrics.PR_07.eligible_rows", elig)
            rc.set_manifest("metrics.PR_07.excluded_rows", excl)
        except Exception:
            pass

    except Exception as e:
        try:
            rc.add_event(code="PR_07_FAIL", level="ERROR", message=str(e), data={}, etapa="PR_07")
            rc.finalize("FAIL")
        except Exception:
            pass
        return _pack_fail(rc, f"PR_07 FAIL.  {e}")

    # 5) PR_08_MULTI (listas) - digitales + CONTACTO_VOZ
    pr08_results = {}

    def _voz_legacy_export_and_publish(df_cd):
        """Fallback legacy: genera XLSX local y (best-effort) publica a Drive."""
        from datetime import datetime
        import io

        info = {
            "published": False,
            "file": None,
            "drive_file_id": None,
            "rows": int(len(df_cd)) if isinstance(df_cd, pd.DataFrame) else 0,
            "duplicate_skipped": None,
        }
        if df_cd is None or getattr(df_cd, "empty", True):
            return {**info, "reason": "NO_CD_ROWS"}

        now = datetime.now()
        ts = now.strftime("%Y_%m_%d_%H%M")
        out_name = f"BD_Contactados_Voz_{ts}.xlsx"

        # local
        try:
            os.makedirs(getattr(rc, "dir", "") or "", exist_ok=True)
            local_path = os.path.join(getattr(rc, "dir", "") or "", out_name)
            bio = io.BytesIO()
            with pd.ExcelWriter(bio, engine="openpyxl") as w:
                df_cd.to_excel(w, index=False, sheet_name="DATA")
            xlsx_bytes = bio.getvalue()
            with open(local_path, "wb") as f:
                f.write(xlsx_bytes)
            info["file"] = local_path
        except Exception as e:
            return {**info, "reason": f"LEGACY_LOCAL_WRITE_FAIL:{e}"}

        # drive (best effort)
        try:
            folder_id = None
            if "_sinergia_get_folder_id_by_reference" in globals() and callable(globals().get("_sinergia_get_folder_id_by_reference")):
                folder_id, _ = _sinergia_get_folder_id_by_reference("FOLDER_LISTAS", "")
                if not folder_id:
                    folder_id, _ = _sinergia_get_folder_id_by_reference("LISTAS_TRABAJO_GENESYS", "")
            if folder_id and ("drive_upsert_bytes" in globals()) and callable(globals().get("drive_upsert_bytes")):
                fid = drive_upsert_bytes(folder_id, out_name, xlsx_bytes, overwrite=True)
                info["drive_file_id"] = fid
                info["published"] = True
                return {**info, "reason": "OK_LEGACY"}
            return {**info, "reason": "LEGACY_DRIVE_SKIPPED_NO_FOLDER_OR_FUNC"}
        except Exception as e:
            return {**info, "reason": f"LEGACY_DRIVE_FAIL:{e}"}

    try:
        df_for_lists = df_el if (isinstance(df_el, pd.DataFrame) and not df_el.empty) else df_base_effective

        pr08_dig, _ = sinergia_pr08_publish_multi(
            df_eligible=df_for_lists,
            rc=rc,
            log="",
            sistema="SinergIA",
            aliases=["DIGITAL_WHATSAPP", "DIGITAL_WISE", "DIGITAL_SMS"],
            require_pr07_ok=True,
        )
        pr08_results.update(pr08_dig or {})

        # CONTACTO_VOZ: solo si el history efectivo es TRAZA (tipificación CD vive en TRAZA).
        info_voz = {
            "published": False,
            "file": None,
            "drive_file_id": None,
            "rows": 0,
            "duplicate_skipped": None,
            "reason": "SKIPPED",
        }

        use_traza_effective = (effective_kind == "TRAZA") and isinstance(df_history, pd.DataFrame) and (not df_history.empty)

        if use_traza_effective:
            df_cd = _traza_cd_min(df_history, rc=rc)
            if isinstance(df_cd, pd.DataFrame) and not df_cd.empty:
                try:
                    voz_res, _ = sinergia_pr08_publish_multi(
                        df_eligible=df_cd,
                        rc=rc,
                        log="",
                        sistema="SinergIA",
                        aliases=["CONTACTO_VOZ"],
                        require_pr07_ok=True,
                    )
                    info_voz = (voz_res or {}).get("CONTACTO_VOZ") or info_voz
                except Exception as e_pr08_voz:
                    info_voz = _voz_legacy_export_and_publish(df_cd)
                    try:
                        rc.add_event(
                            code="PR08_WARN_CONTACTO_VOZ_LEGACY",
                            level="WARN",
                            message=f"CONTACTO_VOZ no soportado por PR_08 (fallback legacy aplicado).  Detalle: {e_pr08_voz}",
                            data={},
                            etapa="PR_08",
                        )
                    except Exception:
                        pass
            else:
                info_voz = {**info_voz, "reason": "NO_CD_ROWS"}
        else:
            info_voz = {**info_voz, "reason": "HISTORY_KIND_NOT_TRAZA_OR_EMPTY"}

        pr08_results["CONTACTO_VOZ"] = info_voz

        try:
            rc.set_manifest("outputs.PR_08_MULTI.results", pr08_results or {})
        except Exception:
            pass

    except Exception as e:
        try:
            rc.add_event(code="PR_08_MULTI_FAIL", level="ERROR", message=str(e), data={}, etapa="PR_08")
            rc.finalize("FAIL")
        except Exception:
            pass
        return _pack_fail(rc, f"PR_08_MULTI FAIL.  {e}")

    # 6) df_listas_show
    rows_show = []
    for alias, info in (pr08_results or {}).items():
        rows_show.append(
            {
                "alias": str(alias),
                "published": (info or {}).get("published"),
                "drive_file_id": (info or {}).get("drive_file_id"),
                "file": (info or {}).get("file"),
                "rows": (info or {}).get("rows"),
                "duplicate_skipped": (info or {}).get("duplicate_skipped"),
            }
        )

    df_show = pd.DataFrame(
        rows_show if rows_show else [],
        columns=["alias", "published", "drive_file_id", "file", "rows", "duplicate_skipped"],
    )
    globals()["DF_LISTAS_SHOW_CACHE"] = df_show.copy()

    # 7) df_listas_sources (schema estable para UI)
    m = getattr(rc, "manifest", {}) or {}
    src_rows = []
    src_rows.append(
        {
            "kind": "base_in",
            "preference": "",
            "used": base_used,
            "fallback_used": False,
            "traza_rows": "",
            "gestion_rows": "",
            "file": "",
            "drive_file_id": "",
            "note": f"rows={int(len(df_base_effective))}",
        }
    )

    hist_used = str(_safe_get(m, "inputs.history.used_kind", "") or "")
    hist_pref = str(_safe_get(m, "inputs.history.preference", "") or "")
    hist_fb = bool(_safe_get(m, "inputs.history.fallback_kind_mismatch", False))
    tr_rows = int(_safe_get(m, "inputs.traza.rows", 0) or 0)
    ex_rows = int(_safe_get(m, "inputs.export_genesys.rows", 0) or 0)
    mg_rows = int(_safe_get(m, "inputs.mejorgest_log.rows", 0) or 0)

    hist_file = ""
    if hist_used == "TRAZA":
        hist_file = str(_safe_get(m, "inputs.traza.file", "") or "")
    elif hist_used == "EXPORT_GENESYS":
        hist_file = str(_safe_get(m, "inputs.export_genesys.file", "") or "")
    elif hist_used == "MEJORGEST_LOG":
        hist_file = str(_safe_get(m, "inputs.mejorgest_log.file", "") or "")

    src_rows.append(
        {
            "kind": "history",
            "preference": hist_pref,
            "used": hist_used,
            "fallback_used": hist_fb,
            "traza_rows": tr_rows,
            "gestion_rows": (ex_rows if hist_used == "EXPORT_GENESYS" else mg_rows if hist_used == "MEJORGEST_LOG" else 0),
            "file": hist_file,
            "drive_file_id": "",
            "note": "history_kind=" + hist_used,
        }
    )

    for alias, info in (pr08_results or {}).items():
        src_rows.append(
            {
                "kind": "output_list",
                "preference": "",
                "used": str(alias),
                "fallback_used": False,
                "traza_rows": "",
                "gestion_rows": "",
                "file": (info or {}).get("file"),
                "drive_file_id": (info or {}).get("drive_file_id"),
                "note": f"published={(info or {}).get('published')} reason={(info or {}).get('reason','')}",
            }
        )

    df_sources = pd.DataFrame(
        src_rows,
        columns=[
            "kind",
            "preference",
            "used",
            "fallback_used",
            "traza_rows",
            "gestion_rows",
            "file",
            "drive_file_id",
            "note",
        ],
    )

    # 8) Previews + files por canal
    info_wa = (pr08_results or {}).get("DIGITAL_WHATSAPP", {}) or {}
    info_wise = (pr08_results or {}).get("DIGITAL_WISE", {}) or {}
    info_sms = (pr08_results or {}).get("DIGITAL_SMS", {}) or {}
    info_voz = (pr08_results or {}).get("CONTACTO_VOZ", {}) or {}

    def _resolve_local_path_from_info(info: dict):
        """PR_08 a veces retorna `file` como basename.  Intentamos resolver a path real."""
        p = (info or {}).get("file")
        if not isinstance(p, str) or not p.strip():
            return None
        p = p.strip()
        # 1) path tal cual
        try:
            if os.path.exists(p):
                return p
        except Exception:
            pass
        # 2) basename dentro del run_dir
        try:
            run_dir = getattr(rc, "dir", None)
            if isinstance(run_dir, str) and run_dir:
                cand = os.path.join(run_dir, os.path.basename(p))
                if os.path.exists(cand):
                    return cand
        except Exception:
            pass
        return None

    def _drive_get_bytes_best_effort(file_id: str):
        """Compatibilidad: intenta varios nombres de función drive_* si existen en el código base."""
        if not isinstance(file_id, str) or not file_id:
            return None
        for fn_name in [
            "drive_download_bytes",
            "drive_get_file_bytes",
            "drive_download_file_bytes",
            "drive_read_bytes",
            "drive_download_file_as_bytes",
        ]:
            fn = globals().get(fn_name)
            if callable(fn):
                try:
                    return fn(file_id)
                except Exception:
                    continue
        return None

    def _preview_from_info_robust(info: dict, *, max_rows: int):
        """1) usa preview nativo si existe.  2) intenta leer XLSX local.  3) intenta bajar de Drive."""
        # a) preview nativo
        try:
            dfp = _preview_from_info(info, max_rows=int(max_rows))
            if isinstance(dfp, pd.DataFrame) and not dfp.empty:
                return dfp
        except Exception:
            pass

        # b) leer local
        local_path = _resolve_local_path_from_info(info)
        if local_path:
            try:
                dfx = pd.read_excel(local_path)
                if isinstance(dfx, pd.DataFrame) and not dfx.empty:
                    return dfx.head(int(max_rows))
            except Exception:
                pass

        # c) bajar de Drive (best-effort) y leer
        fid = (info or {}).get("drive_file_id")
        bio = _drive_get_bytes_best_effort(str(fid) if fid else "")
        if bio:
            try:
                run_dir = getattr(rc, "dir", None) or ""
                os.makedirs(run_dir, exist_ok=True)
                tmp_path = os.path.join(run_dir, f"_preview_{str(fid)}.xlsx")
                with open(tmp_path, "wb") as f:
                    f.write(bio)
                dfx = pd.read_excel(tmp_path)
                if isinstance(dfx, pd.DataFrame) and not dfx.empty:
                    return dfx.head(int(max_rows))
            except Exception:
                pass

        return _df_empty()

    # previews
    df_prev_wa = _preview_from_info_robust(info_wa, max_rows=int(n_prev or 3000))
    df_prev_wise = _preview_from_info_robust(info_wise, max_rows=int(n_prev or 3000))
    df_prev_sms = _preview_from_info_robust(info_sms, max_rows=int(n_prev or 3000))
    df_prev_voz = _preview_from_info_robust(info_voz, max_rows=int(n_prev or 3000))

    # file handles (descarga local) - solo si existe en disco
    out_lista_wa = _resolve_local_path_from_info(info_wa)
    out_lista_wise = _resolve_local_path_from_info(info_wise)
    out_lista_sms = _resolve_local_path_from_info(info_sms)
    out_lista_voz = _resolve_local_path_from_info(info_voz)

    try:
        rc.set_manifest("outputs.files.DIGITAL_WHATSAPP.local_exists", out_lista_wa is not None)
        rc.set_manifest("outputs.files.DIGITAL_WISE.local_exists", out_lista_wise is not None)
        rc.set_manifest("outputs.files.DIGITAL_SMS.local_exists", out_lista_sms is not None)
        rc.set_manifest("outputs.files.CONTACTO_VOZ.local_exists", out_lista_voz is not None)
    except Exception:
        pass


    # 9) Log compacto (máx 3 líneas)
    elig = int(_safe_get(getattr(rc, "manifest", {}) or {}, "metrics.PR_07.eligible_rows", 0) or 0)
    excl = int(_safe_get(getattr(rc, "manifest", {}) or {}, "metrics.PR_07.excluded_rows", 0) or 0)
    used_kind = str(_safe_get(getattr(rc, "manifest", {}) or {}, "inputs.history.used_kind", "")) or ""
    desired_kind2 = str(_safe_get(getattr(rc, "manifest", {}) or {}, "inputs.history.desired_kind", "")) or ""
    fb_kind2 = bool(_safe_get(getattr(rc, "manifest", {}) or {}, "inputs.history.fallback_kind_mismatch", False))
    traza_rows2 = int(_safe_get(getattr(rc, "manifest", {}) or {}, "inputs.traza.rows", 0) or 0)
    export_rows2 = int(_safe_get(getattr(rc, "manifest", {}) or {}, "inputs.export_genesys.rows", 0) or 0)
    mejorgest_rows2 = int(_safe_get(getattr(rc, "manifest", {}) or {}, "inputs.mejorgest_log.rows", 0) or 0)
    voz_docs = int(_safe_get(getattr(rc, "manifest", {}) or {}, "metrics.CONTACTO_VOZ.docs_unique", 0) or 0)

    log_out = "\n".join(
        [
            f"PR_08_MULTI · run_id={str(getattr(rc, 'run_id', '') or '')}",
            f"PR_07 · eligible/excluded={elig}/{excl} · history_desired={desired_kind2} · history_used_kind={used_kind} · kind_mismatch_fallback={fb_kind2} · traza_rows={traza_rows2} · export_rows={export_rows2} · mejorgest_rows={mejorgest_rows2} · voz_cd_docs={voz_docs}",
            "PR_08_MULTI · published=" + str({k: (v or {}).get('published') for k, v in (pr08_results or {}).items()}),
        ]
    )

    return (
        df_show,
        df_sources,
        df_prev_wa,
        out_lista_wa,
        df_prev_wise,
        out_lista_wise,
        df_prev_sms,
        out_lista_sms,
        df_prev_voz,
        out_lista_voz,
        str(getattr(rc, "run_id", "") or ""),
        log_out,
    )

# SinergIA1800 - get_recent_files_from_setting (CANÓNICA) · SettingID -> Drive list
from gspread.exceptions import APIError as GspreadAPIError

def _sid(x):
    return x[0] if isinstance(x, tuple) else x

def _resolve_folder_id(nombre_carpeta: str):
    k = str(nombre_carpeta or "").strip().lower()
    if k in ["rutina", "rutinas"]:
        return _sid(get_rutinas_folder_id())
    if k in ["gestion", "gestion_log", "gestionlog"]:
        return _sid(get_gestion_folder_id())
    if k in ["promesa", "promesas"]:
        return _sid(get_promesas_folder_id())
    if k in ["pago", "pagos"]:
        return _sid(get_pagos_folder_id())
    return None

def get_recent_files_from_setting(nombre_carpeta: str, limit: int = 5):
    """
    CANÓNICA: Resuelve folder_id desde Config_SinergIA/SettingID (vía getters canónicos)
    y lista nombres directos en Drive.  Nunca tumba la GUI: ante error retorna [].
    """
    try:
        fid = _resolve_folder_id(nombre_carpeta)
        if not fid:
            return []
        if "drive_list_names_in_folder" in globals():
            return drive_list_names_in_folder(fid, max_results=limit) or []
        if "drive_list_files_in_folder" in globals():
            items = drive_list_files_in_folder(fid, max_results=limit) or []
            return [name for (_id, name) in items if name]
        if "drive_service" in globals():
            res = drive_service.files().list(
                q=f"'{fid}' in parents and trashed=false",
                fields="files(name)",
                pageSize=limit
            ).execute().get("files", [])
            return [f.get("name") for f in res if f.get("name")]
        return []
    except GspreadAPIError:
        return []
    except Exception:
        return []

# SinergIA1900 - Helper genérico: lee bytes de CSV/XLSX a DataFrame
import io, os
import pandas as pd

def _read_any_bytes_to_df(name: str, data: bytes, nrows: int) -> pd.DataFrame:
    """
    Lee un archivo en memoria (bytes) como DataFrame, soportando CSV y XLSX.
    Limita a nrows filas.
    """
    ext = os.path.splitext(name)[1].lower()

    if ext in (".xlsx", ".xls"):
        return pd.read_excel(io.BytesIO(data), nrows=nrows)

    if ext == ".csv":
        return pd.read_csv(io.BytesIO(data), nrows=nrows)

    # Fallback: intentar primero Excel y luego CSV
    try:
        return pd.read_excel(io.BytesIO(data), nrows=nrows)
    except Exception:
        return pd.read_csv(io.BytesIO(data), nrows=nrows)

# SinergIA2000 - Compatibilidad robusta para gr.File (str, dict, file-like)
import os
import io
from typing import Tuple, Optional, Any

def _local_file_to_name_and_bytes(file_input: Any) -> Tuple[str, bytes]:
    """
    Soporta:
    - str/pathlike: ruta a archivo temporal.
    - dict: variantes comunes de Gradio (path/name/data).
    - file-like: objetos con .read() y opcional .name.
    Retorna (nombre, bytes).
    """
    if file_input is None:
        raise ValueError("file_input es None")

    # 1) filepath (Gradio type='filepath')
    if isinstance(file_input, (str, os.PathLike)):
        p = str(file_input)
        name = os.path.basename(p) or "archivo_local"
        with open(p, "rb") as f:
            data = f.read()
        return name, data

    # 2) dict (algunas versiones devuelven metadata)
    if isinstance(file_input, dict):
        p = file_input.get("path") or file_input.get("name")
        data = file_input.get("data")
        if data is not None:
            name = os.path.basename(p) if p else "archivo_local"
            return name, data
        if p and os.path.exists(p):
            name = os.path.basename(p) or "archivo_local"
            with open(p, "rb") as f:
                data = f.read()
            return name, data
        raise ValueError(f"dict de archivo no soportado: keys={list(file_input.keys())}")

    # 3) file-like (Gradio type='file' antiguo)
    name = os.path.basename(getattr(file_input, "name", "")) or "archivo_local"
    try:
        if hasattr(file_input, "seek"):
            file_input.seek(0)
    except Exception:
        pass
    data = file_input.read()
    return name, data


def _read_any_bytes_to_df_full(name: str, data: bytes) -> "pd.DataFrame":
    """
    FULL (sin nrows).  CSV/XLSX desde bytes.
    """
    import pandas as pd
    ext = os.path.splitext(name)[1].lower()
    bio = io.BytesIO(data)

    if ext in (".xlsx", ".xls"):
        return pd.read_excel(bio, engine="openpyxl")

    # CSV o fallback autodetect
    return pd.read_csv(bio, sep=None, engine="python")

# SinergIA2100 - Carga de TER_UNISONO desde Drive o archivo local
import pandas as pd
from typing import Tuple, Optional

PREVIEW_ROWS_RUTINA = 3000  # filas para preview

def _load_rutina_any_source(
    dd_archivo_rutina: Optional[str],
    file_rutina_local,
    log: str,
    max_rows: int,
) -> Tuple[pd.DataFrame, str]:
    """
    Lógica de carga para Rutina:
    - Si hay archivo local, se usa ese (bytes → DataFrame).
    - Si no, se usa el archivo seleccionado en Drive (usa _leer_df_desde_drive).
    Devuelve (df_preview, log_actualizado).
    """
    log = _log_append(log, "Inicio carga de Rutina (TER_UNISONO)...")

    # 1) Archivo local (prioridad)
    if file_rutina_local is not None:
        try:
            name, data = _local_file_to_name_and_bytes(file_rutina_local)
            log = _log_append(log, f"Usando archivo local de Rutina: {name}")
            df = _read_any_bytes_to_df(name, data, nrows=max_rows)
            log = _log_append(
                log,
                f"Archivo local de Rutina leído. Shape preview={df.shape}, columnas={list(df.columns)[:8]}...",
            )
            return df, log
        except Exception as e:
            log = _log_append(log, f"Error leyendo archivo local de Rutina: {e}")
            return pd.DataFrame(), log

    # 2) Archivo en Drive
    if not dd_archivo_rutina:
        log = _log_append(log, "No se seleccionó archivo de Rutina en Drive ni archivo local.")
        return pd.DataFrame(), log

    folder_id = get_rutinas_folder_id()
    if not folder_id:
        log = _log_append(log, "No se encontró ID de carpeta 'Rutinas' en SettingID.")
        return pd.DataFrame(), log

    try:
        log = _log_append(log, f"Buscando archivo de Rutina en Drive: {dd_archivo_rutina}")
        df_drive, log = _leer_df_desde_drive(
            tipo="Rutina",
            folder_id=folder_id,
            archivo=dd_archivo_rutina,
            log=log,
            nrows=max_rows,
        )
        if df_drive is None:
            return pd.DataFrame(), log

        log = _log_append(
            log,
            f"Rutina desde Drive leída. Shape preview={df_drive.shape}, columnas={list(df_drive.columns)[:8]}...",
        )
        return df_drive, log
    except Exception as e:
        log = _log_append(log, f"Error leyendo Rutina desde Drive: {e}")
        return pd.DataFrame(), log

