# SinergIA2500 - Normalización de Rutina (TER_UNISONO) a IN_SISTECREDITO usando Config_SinergIA
import pandas as pd

_ESTRUCTURAS_DF: pd.DataFrame | None = None

def _load_estructuras_df() -> pd.DataFrame:
    """
    Carga y cachea la hoja 'Estructuras' desde Config_SinergIA.
    Usa el mismo CONFIG_SPREADSHEET_ID y read_gsheet ya definidos.
    """
    global _ESTRUCTURAS_DF
    if _ESTRUCTURAS_DF is not None:
        return _ESTRUCTURAS_DF

    df = read_gsheet(CONFIG_SPREADSHEET_ID, "Estructuras")
    _ESTRUCTURAS_DF = df
    return df


def normalize_rutina_to_in(
    df_raw: pd.DataFrame,
    config_struct: dict | None,   # se mantiene por compatibilidad, NO se usa
    log: str,
) -> tuple[pd.DataFrame, str]:
    """
    Normaliza Rutina (TER_UNISONO) → IN_SISTECREDITO:

    - Usa Config_SinergIA.Estructuras como fuente de verdad de estructura.
    - Usa ArchivoLogico + AliasCanonico para mapear columnas TER → IN.
    - Aplica tipos (Fecha / Numero) según TipoDato (IN_SISTECREDITO).
    - Limpia teléfonos dejando solo dígitos y vaciando los muy cortos.
    """

    log = _log_append(log, "Inicio normalización Rutina → IN_SISTECREDITO (via Estructuras)...")

    if df_raw is None or df_raw.empty:
        log = _log_append(log, "AVISO: df_raw vacío → no se puede normalizar.")
        return pd.DataFrame(), log

    df = df_raw.copy()
    df.columns = [str(c).strip() for c in df.columns]

    estr = _load_estructuras_df()

    # --- Bloques de Estructuras ---
    estr_ter = estr[estr["ArchivoLogico"].astype(str).str.upper() == "TER_UNISONO"].copy()
    estr_in  = estr[estr["ArchivoLogico"].astype(str).str.upper() == "IN_SISTECREDITO"].copy()

    if estr_in.empty:
        log = _log_append(log, "AVISO: no hay definición IN_SISTECREDITO en Estructuras.")
        return df, log

    # Orden final según ColumnaOrden
    estr_in = estr_in.sort_values("ColumnaOrden")

    # --- Mapeo de AliasCanonico TER → NombreColumna (origen) ---
    alias_to_ter: dict[str, str] = {}
    for _, row in estr_ter.iterrows():
        alias = str(row["AliasCanonico"]).strip()
        col   = str(row["NombreColumna"]).strip()
        if alias:
            alias_to_ter[alias] = col

    log = _log_append(
        log,
        f"Aliases TER_UNISONO cargados desde Estructuras: {len(alias_to_ter)} mapeos."
    )

    # --- Construir IN_SISTECREDITO a partir de TER ---
    df_in = pd.DataFrame(index=df.index)

    for _, row in estr_in.iterrows():
        dest_col = str(row["NombreColumna"]).strip()
        alias    = str(row["AliasCanonico"]).strip()

        source_col = None

        # 1) Intentar por AliasCanonico (TER_UNISONO)
        if alias and alias in alias_to_ter:
            src_candidate = alias_to_ter[alias]
            for cand in {
                src_candidate,
                src_candidate.strip(),
                src_candidate.replace(" ", ""),
                src_candidate.upper(),
                src_candidate.lower(),
            }:
                if cand in df.columns:
                    source_col = cand
                    break

        # 2) Fallback: si el mismo NombreColumna existe en df_raw
        if source_col is None:
            for cand in {
                dest_col,
                dest_col.strip(),
                dest_col.replace(" ", ""),
                dest_col.upper(),
                dest_col.lower(),
            }:
                if cand in df.columns:
                    source_col = cand
                    break

        # 3) Asignar o dejar vacío
        if source_col is not None:
            df_in[dest_col] = df[source_col]
        else:
            df_in[dest_col] = pd.NA
            log = _log_append(
                log,
                f"Columna origen no encontrada para '{dest_col}' (alias '{alias}'). Se llena vacío."
            )

    log = _log_append(
        log,
        f"Estructura IN_SISTECREDITO construida. Columnas={len(df_in.columns)}."
    )

    # --- Casting por TipoDato (usando definición IN_SISTECREDITO) ---
    estr_in["TipoDato"] = estr_in["TipoDato"].astype(str)

    fecha_cols = (
        estr_in.loc[estr_in["TipoDato"].str.upper() == "FECHA", "NombreColumna"]
        .astype(str).str.strip().tolist()
    )
    num_cols = (
        estr_in.loc[estr_in["TipoDato"].str.upper() == "NUMERO", "NombreColumna"]
        .astype(str).str.strip().tolist()
    )

    for col in fecha_cols:
        if col in df_in.columns:
            try:
                df_in[col] = pd.to_datetime(df_in[col], errors="coerce", dayfirst=True)
            except Exception:
                pass

    for col in num_cols:
        if col in df_in.columns:
            try:
                df_in[col] = pd.to_numeric(df_in[col], errors="coerce")
            except Exception:
                pass

    log = _log_append(
        log,
        f"Casteo de tipos aplicado. Fechas={len(fecha_cols)}, Números={len(num_cols)}."
    )

    # --- Limpieza de teléfonos (según AliasCanonico contiene 'Telefono') ---
    tel_cols = (
        estr_in.loc[
            estr_in["AliasCanonico"].astype(str).str.contains("Telefono", case=False, na=False),
            "NombreColumna",
        ]
        .astype(str).str.strip().tolist()
    )

    for col in tel_cols:
        if col in df_in.columns:
            s = df_in[col].astype(str).str.strip()
            s = s.str.replace(r"\D+", "", regex=True)   # dejar solo dígitos
            s = s.where(s.str.len() >= 7, "")           # vaciar muy cortos
            df_in[col] = s

    if tel_cols:
        log = _log_append(
            log,
            f"Limpieza de teléfonos aplicada sobre columnas: {tel_cols}."
        )

    # --- Normalización básica de texto (no fecha/num) ---
    for col in df_in.columns:
        if col in fecha_cols or col in num_cols:
            continue
        # respetamos NaN pero limpiamos strings
        df_in[col] = (
            df_in[col]
            .astype(str)
            .str.strip()
            .str.upper()
            .replace({"<NA>": ""})
        )

    # --- Reordenar columnas según Estructuras (IN_SISTECREDITO) ---
    ordered_cols = estr_in["NombreColumna"].astype(str).str.strip().tolist()
    df_in = df_in.reindex(columns=ordered_cols)

    log = _log_append(
        log,
        f"Normalización completa IN_SISTECREDITO. Shape final={df_in.shape}."
    )

    return df_in, log

# SinergIA2600 - Enforce SOLO celulares en columnas de salida (Telefono 1..4 + Teléfono Almacén)
# - Solo acepta móviles CO: 10 dígitos, empiezan por 3 (opcional: soporta prefijo 57)
# - Ignora fijos SIEMPRE (si no es móvil, se vacía)
# - Compacta y deduplica Telefono 1..4 (si se vacía alguno, corre los siguientes a la izquierda)

import pandas as pd

def _only_digits(x):
    s = "" if x is None else str(x)
    return "".join(ch for ch in s if ch.isdigit())

def _mobile_co_10(x):
    d = _only_digits(x)
    if not d:
        return ""
    if d.startswith("57") and len(d) == 12:
        d = d[2:]
    if len(d) == 10 and d.startswith("3"):
        return d
    return ""

def enforce_only_mobile_phones_on_output(df: pd.DataFrame, use_all_phones: bool, log: str = "") -> tuple[pd.DataFrame, str]:
    phone_cols = [c for c in ["Telefono 1", "Telefono 2", "Telefono 3", "Telefono 4"] if c in df.columns]

    if not phone_cols:
        log += "WARN · SOLO_MOBILE_OUTPUT: no existen columnas Telefono 1..4 en df_out.\n"
        return df, log

    # 1) Normaliza a móviles válidos
    for c in phone_cols:
        df[c] = df[c].map(_mobile_co_10)

    if "Teléfono Almacén" in df.columns:
        df["Teléfono Almacén"] = df["Teléfono Almacén"].map(_mobile_co_10)

    # 2) Compacta (left-shift) + dedup por fila
    n = len(df)
    k = 4 if use_all_phones else 2

    t1 = [""] * n
    t2 = [""] * n
    t3 = [""] * n
    t4 = [""] * n

    non_mobile_found = 0

    for i in range(n):
        seen = set()
        vals = []
        for c in phone_cols:
            v = df[c].iat[i]
            v = "" if v is None else str(v)
            if v == "":
                continue
            # a esta altura ya es móvil o vacío; si no empieza por 3, cuenta como no móvil (defensa)
            if not v.startswith("3"):
                non_mobile_found += 1
                continue
            if v in seen:
                continue
            seen.add(v)
            vals.append(v)

        # asigna compactado
        if len(vals) >= 1: t1[i] = vals[0]
        if len(vals) >= 2: t2[i] = vals[1]
        if use_all_phones:
            if len(vals) >= 3: t3[i] = vals[2]
            if len(vals) >= 4: t4[i] = vals[3]

    df["Telefono 1"] = t1
    df["Telefono 2"] = t2
    df["Telefono 3"] = t3 if use_all_phones else ""
    df["Telefono 4"] = t4 if use_all_phones else ""

    log += f"POSTFIX · SOLO_MOBILE_OUTPUT applied · use_all={use_all_phones} · non_mobile_found={non_mobile_found}\n"
    return df, log

# SinergIA2700 - Pipelines y Callbacks de SinergIA Cobros
from typing import Tuple, Dict, Any
import pandas as pd


# Cache básicos (se irán refinando)
DF_TER_CACHE: pd.DataFrame | None = None  # Rutina (preview)
DF_TER_FULL_CACHE: pd.DataFrame | None = None  # Rutina (FULL) - opcional
DF_GESTION_CACHE: pd.DataFrame | None = None
DF_PROM_CACHE: pd.DataFrame | None = None
DF_PAGOS_CACHE: pd.DataFrame | None = None

DF_IN_PREVIEW_CACHE: pd.DataFrame | None = None  # IN_SISTECREDITO (preview)
DF_IN_FULL_CACHE: pd.DataFrame | None = None     # IN_SISTECREDITO (FULL)
DF_IN_CACHE: pd.DataFrame | None = None          # compat legacy (alias preview)

# Nuevos caches operativos
DF_TELETON_CACHE: pd.DataFrame | None = None
DF_BOLSAS_CACHE: pd.DataFrame | None = None
DF_LISTAS_SHOW_CACHE: pd.DataFrame | None = None

CFG_SHEETS_COMPONENTS: Dict[str, Any] | None = None  # cache de cfg_sheets


# =========================================================
# Helpers comunes para leer hojas de Config (Gradio o DF)
# =========================================================

def _get_sheet_df_from_components(
    cfg_sheets: Dict[str, Any],
    sheet_name: str,
) -> pd.DataFrame | None:
    """
    Devuelve una hoja de Config como DataFrame real a partir
    de cfg_sheets[sheet_name], que puede venir como:
      - gr.Dataframe (.value = dict con data/headers)
      - DataFrame ya listo
      - dict en formato {"data":[...], "headers":[...]}
    """
    if not isinstance(cfg_sheets, dict):
        return None

    comp = cfg_sheets.get(sheet_name)
    if comp is None:
        return None

    # Si el componente tiene atributo .value lo usamos;
    # de lo contrario usamos comp tal cual.
    obj = getattr(comp, "value", comp)

    # Caso 1: ya es DataFrame
    if isinstance(obj, pd.DataFrame):
        return obj

    # Caso 2: dict tipo gr.DataFrame.value
    if isinstance(obj, dict):
        data = obj.get("data")
        headers = obj.get("headers")

        if data is not None:
            try:
                if headers is not None and len(headers) == len(data[0]):
                    return pd.DataFrame(data, columns=headers)
                else:
                    return pd.DataFrame(data)
            except Exception:
                return None

        # Otros formatos tipo {"value": ...}
        alt = obj.get("value")
        if alt is not None:
            try:
                return pd.DataFrame(alt)
            except Exception:
                return None

        return None

    # Caso 3: intentamos convertir lo que venga a DataFrame
    try:
        return pd.DataFrame(obj)
    except Exception:
        return None


def _get_estructuras_df_from_components(cfg_sheets: Dict[str, Any]) -> pd.DataFrame | None:
    """Helper específico para la hoja 'Estructuras'."""
    return _get_sheet_df_from_components(cfg_sheets, "Estructuras")


def _get_parameters_df_from_components(cfg_sheets: Dict[str, Any]) -> pd.DataFrame | None:
    """Helper específico para la hoja 'Parameters'."""
    return _get_sheet_df_from_components(cfg_sheets, "Parameters")


def _pick_first_existing(candidates: list[str], df: pd.DataFrame) -> str | None:
    """
    Devuelve el primer nombre de columna de candidates que exista en df,
    o None si no hay coincidencias.
    """
    for name in candidates:
        if name in df.columns:
            return name
    return None


# =========================================================
# Helper de normalización IN_SISTECREDITO desde Config
# =========================================================

def _normalize_rutina_to_in_from_cfg(
    df_in: pd.DataFrame,
    df_estructuras: pd.DataFrame,
    log: str,
    use_ints: bool = True,
    use_all_phones: bool = False,  # hook REGLA 6
    use_upper: bool = True,
    order_keys: list[str] | None = None,
    df_params: pd.DataFrame | None = None,
) -> Tuple[pd.DataFrame, str]:
    """
    Normaliza un DataFrame ya cercano a IN_SISTECREDITO usando
    Config_SinergIA.Estructuras y reglas de negocio adicionales.
    """

    def _norm(s: str) -> str:
        return (
            str(s)
            .strip()
            .lower()
            .replace("á", "a")
            .replace("é", "e")
            .replace("í", "i")
            .replace("ó", "o")
            .replace("ú", "u")
        )

    # 0. Validaciones básicas
    if df_in is None or df_in.empty:
        return pd.DataFrame(), _log_append(log, "DF de Rutina vacío, no se puede normalizar.")

    if df_estructuras is None or df_estructuras.empty:
        return pd.DataFrame(), _log_append(log, "Hoja 'Estructuras' vacía o inválida.")

    # 1. Filtrar meta para IN_SISTECREDITO y ordenar por ColumnaOrden
    df_meta_in = df_estructuras.copy()
    cols_lower = {c: str(c).strip().lower() for c in df_meta_in.columns}
    df_meta_in.rename(columns=cols_lower, inplace=True)

    if "archivologico" not in df_meta_in.columns or "nombrecolumna" not in df_meta_in.columns:
        return pd.DataFrame(), _log_append(
            log,
            "Hoja 'Estructuras' no tiene columnas requeridas 'ArchivoLogico'/'NombreColumna'.",
        )

    df_meta_in = df_meta_in.loc[
        df_meta_in["archivologico"].astype(str).str.strip().str.upper() == "IN_SISTECREDITO"
    ].copy()

    if df_meta_in.empty:
        return pd.DataFrame(), _log_append(
            log,
            "No se encontraron filas para ArchivoLogico='IN_SISTECREDITO' en 'Estructuras'.",
        )

    if "columnaorden" in df_meta_in.columns:
        df_meta_in["columnaorden"] = pd.to_numeric(df_meta_in["columnaorden"], errors="coerce")
        df_meta_in.sort_values("columnaorden", inplace=True)

    nombres_cols = df_meta_in["nombrecolumna"].astype(str).str.strip().tolist()

    # 2. Mapear columnas desde df_in a df_out respetando orden
    df_out = pd.DataFrame(index=df_in.index)
    for col in nombres_cols:
        if col in df_in.columns:
            df_out[col] = df_in[col]
        else:
            df_out[col] = pd.NA

    log = _log_append(
        log,
        f"REGLA 1 aplicada: estructura IN_SISTECREDITO con {len(nombres_cols)} columnas.",
    )

    # 2.b Reglas de mapeo especiales / defaults de negocio

    # 2.b.1 Dirección Del Cliente: vacío o null -> "SIN DIRECCION"
    dir_candidates_norm = {
        _norm(x) for x in ["direccion del cliente", "direccion_cliente", "direccion"]
    }
    dir_col = None
    for c in df_out.columns:
        if _norm(c) in dir_candidates_norm:
            dir_col = c
            break
    if dir_col is not None:
        s = df_out[dir_col].astype("string")
        mask_empty = s.isna() | (s.str.strip() == "") | (s.str.lower() == "null")
        s = s.where(~mask_empty, "SIN DIRECCION")
        df_out[dir_col] = s

    # 2.b.2 InServicioId = 1 (si la columna existe)
    for col_name in ["InServicioId", "In_Serviceid", "InServicioid"]:
        if col_name in df_out.columns:
            df_out[col_name] = 1
            df_out[col_name] = pd.to_numeric(df_out[col_name], errors="coerce").astype("Int64")
            break

    # 2.b.3 Almacén <- candidatos tipo "Almacen", "Nombre Almacen", etc.
    if "Almacén" in df_out.columns:
        src_almacen = _pick_first_existing(
            [
                "Almacén",
                "ALMACEN",
                "Almacen",
                "Nombre Almacen",
                "Nombre_Almacen",
                "NombreAlmacen",
            ],
            df_in,
        )
        if src_almacen is not None:
            df_out["Almacén"] = df_in[src_almacen]

    # 2.b.4 Municipio Almacén <- candidatos varios
    muni_targets = ["Municipio Almacén", "Municipio Almacen"]
    muni_src_candidates = [
        "Municipio Almacén",
        "Municipio Almacen",
        "Nombre Municipio",
        "Nombre",
        "Nombre.1",
    ]
    for target_name in muni_targets:
        if target_name in df_out.columns:
            src_mun = _pick_first_existing(muni_src_candidates, df_in)
            if src_mun is not None:
                df_out[target_name] = df_in[src_mun]

    # 2.b.5 Teléfonos 1..4 desde columnas que contengan "telefono"/"celular"
    def _first_col_with(patterns: list[str]) -> str | None:
        for col in df_in.columns:
            n = _norm(col)
            if all(p in n for p in patterns):
                return col
        return None

    tel_targets = ["Telefono 1", "Telefono 2", "Telefono 3", "Telefono 4"]
    tel_patterns = [
        [["telefono", "1"], ["celular", "1"], ["celular"]],
        [["telefono", "2"], ["celular", "2"]],
        [["telefono", "3"], ["celular", "3"]],
        [["telefono", "4"], ["celular", "4"]],
    ]

    for idx, target in enumerate(tel_targets):
        if target not in df_out.columns:
            continue
        if df_out[target].notna().sum() > 0:
            continue

        src = None
        for pat in tel_patterns[idx]:
            src = _first_col_with(pat)
            if src is not None:
                break

        if src is not None:
            df_out[target] = df_in[src]

    # 3. REGLA 2: Formato de fechas a 'YYYY-MM-DD'
    fecha_cols = (
        df_meta_in.loc[
            df_meta_in.get("tipodato", "").astype(str).str.upper() == "FECHA",
            "nombrecolumna",
        ]
        .astype(str)
        .str.strip()
        .tolist()
    )

    for col in fecha_cols:
        if col not in df_out.columns:
            continue

        serie = df_out[col]

        if pd.api.types.is_datetime64_any_dtype(serie):
            serie_dt = pd.to_datetime(serie, errors="coerce")
        else:
            s_str = serie.astype("string").str.strip()
            s_str = s_str.replace({"null": pd.NA, "None": pd.NA, "NONE": pd.NA})

            dt_a = pd.to_datetime(s_str, errors="coerce", dayfirst=True)
            dt_b = pd.to_datetime(s_str, errors="coerce", dayfirst=False)

            if dt_b.notna().sum() > dt_a.notna().sum():
                serie_dt = dt_b
            else:
                serie_dt = dt_a

            mask_num = s_str.str.fullmatch(r"\d+(\.0+)?")
            if mask_num.any():
                try:
                    num_vals = pd.to_numeric(s_str[mask_num], errors="coerce")
                    dt_num = pd.to_datetime(
                        num_vals,
                        unit="D",
                        origin="1899-12-30",
                        errors="coerce",
                    )
                    serie_dt.loc[mask_num] = dt_num
                except Exception:
                    pass

        serie_date = serie_dt.dt.date
        df_out[col] = serie_date.astype("string")

    log = _log_append(
        log,
        f"REGLA 2 aplicada (fechas a 'YYYY-MM-DD') en columnas: {fecha_cols}.",
    )

    # 4. REGLA 3: Forzar numéricos a enteros (si aplica)
    if use_ints:
        num_cols = (
            df_meta_in.loc[
                df_meta_in.get("tipodato", "").astype(str).str.upper() == "NUMERO",
                "nombrecolumna",
            ]
            .astype(str)
            .str.strip()
            .tolist()
        )

        for col in num_cols:
            if col not in df_out.columns:
                continue
            s = pd.to_numeric(df_out[col], errors="coerce")
            df_out[col] = s.round(0).astype("Int64")

        log = _log_append(
            log,
            f"REGLA 3 aplicada: numéricos forzados a enteros en columnas: {num_cols}.",
        )

    # 5. REGLA 4: Texto en MAYÚSCULAS (si aplica)
    if use_upper:
        text_cols = (
            df_meta_in.loc[
                df_meta_in.get("tipodato", "").astype(str).str.upper() == "TEXTO",
                "nombrecolumna",
            ]
            .astype(str)
            .str.strip()
            .tolist()
        )
        if not text_cols:
            text_cols = [
                c
                for c in df_out.columns
                if str(df_out[c].dtype) in ("object", "string")
            ]

        for col in text_cols:
            if col not in df_out.columns:
                continue
            s = df_out[col].astype("string")
            s = s.fillna("").str.strip().str.upper()
            s = s.where(s != "", pd.NA)
            df_out[col] = s

        log = _log_append(
            log,
            f"REGLA 4 aplicada: texto en MAYÚSCULAS en columnas: {text_cols}.",
        )

    # 6. REGLA 6: hook celulares
    if use_all_phones:
        log = _log_append(
            log,
            "REGLA 6 pendiente: usar todos los celulares disponibles (hook activo, sin implementación).",
        )

    # 7. REGLA 7: Defaults y reglas de negocio específicas

    # 7.1 IN_PRIORIDAD = ranking ascendente de (Valor + Valor Mora + Cargos Jurídico)
    cols_score = {
        "Valor": None,
        "Valor Mora": None,
        "Cargos Jurídico": None,
    }

    for col in df_out.columns:
        n = _norm(col)
        if n in ["valor", "valorcapital"]:
            cols_score["Valor"] = col
        elif n in ["valor mora", "valormora"]:
            cols_score["Valor Mora"] = col
        elif "cargos" in n and "jurid" in n:
            cols_score["Cargos Jurídico"] = col

    active_score_cols = [c for c in cols_score.values() if c is not None]
    if active_score_cols:
        score = pd.Series(0.0, index=df_out.index)
        for col in active_score_cols:
            s = pd.to_numeric(df_out[col], errors="coerce").fillna(0)
            score = score + s
        df_out["IN_PRIORIDAD"] = score.rank(method="dense", ascending=True).astype("Int64")

    # 7.2 Servicio = "GENERAL" si la columna existe
    if "Servicio" in df_out.columns:
        df_out["Servicio"] = "GENERAL"

    # 7.3 Franja desde Parameters (parametro='FranjaMora') usando Dias en Mora
    if df_params is not None and not df_params.empty:
        df_p = df_params.copy()
        cols_p = {c: str(c).strip().lower() for c in df_p.columns}
        df_p.rename(columns=cols_p, inplace=True)

        if "parametro" in df_p.columns and "desde" in df_p.columns and "hasta" in df_p.columns:
            df_franja = df_p.loc[df_p["parametro"].astype(str).str.upper() == "FRANJAMORA"].copy()
            if not df_franja.empty and "etiqueta" in df_franja.columns:
                df_franja["desde"] = pd.to_numeric(df_franja["desde"], errors="coerce")
                df_franja["hasta"] = pd.to_numeric(df_franja["hasta"], errors="coerce")

                dias_col = None
                for c in df_out.columns:
                    if _norm(c) in ["dias en mora", "diasmora"]:
                        dias_col = c
                        break

                if dias_col is not None:
                    dias = pd.to_numeric(df_out[dias_col], errors="coerce")
                    franja_series = pd.Series(pd.NA, index=df_out.index, dtype="string")

                    for _, row in df_franja.iterrows():
                        d = row["desde"]
                        h = row["hasta"]
                        etiqueta = str(row["etiqueta"]).strip()
                        if pd.isna(d) or pd.isna(h):
                            continue
                        mask = (dias >= d) & (dias <= h)
                        franja_series = franja_series.mask(mask, etiqueta)

                    df_out["Franja"] = franja_series

    return df_out, log


