def on_preview_rutina(
    dd_archivo_rutina,
    file_rutina_local,
    sl_visualizar_rutina,
    df_prev_rut,
    txt_log,
) -> Tuple[pd.DataFrame, str]:
    if (not dd_archivo_rutina) and (file_rutina_local is None):
        return df_prev_rut, txt_log

    max_rows = int(sl_visualizar_rutina or 3000)

    df_raw, log = _load_rutina_any_source(
        dd_archivo_rutina=dd_archivo_rutina,
        file_rutina_local=file_rutina_local,
        log=txt_log,
        max_rows=max_rows,
    )

    global DF_TER_CACHE
    DF_TER_CACHE = df_raw.copy() if isinstance(df_raw, pd.DataFrame) else None

    if isinstance(df_raw, pd.DataFrame) and not df_raw.empty:
        df_view = df_raw.head(max_rows)
    else:
        df_view = pd.DataFrame()

    return df_view, log


