def __pick_from_tokens_local(df: pd.DataFrame, spec: str) -> pd.Series:
    """
    Interpreta specs de ModeloRelacion como 'Upper;NombreCompleto' o 'lower;Nombre'.
    Preferencia: primero columnas literales; si no, aplica transformación a la primera columna válida.
    """
    tokens = [t.strip() for t in str(spec).split(';') if str(t).strip()]
    if not tokens:
        return pd.Series([pd.NA] * len(df))

    # 1) Preferir columnas literales (incluye 'Upper' si existe como columna)
    for t in tokens:
        if t in df.columns:
            return df[t]

    # 2) Buscar transform + columna base
    tr, base = None, None
    for t in tokens:
        tl = t.lower()
        if tl in ('upper', 'lower', 'title', 'strip'):
            tr = tl
            continue
        if t in df.columns:
            base = df[t].astype("string")
            break

    if base is None:
        return pd.Series([pd.NA] * len(df))

    if tr == 'upper': base = base.str.upper()
    elif tr == 'lower': base = base.str.lower()
    elif tr == 'title': base = base.str.title()
    elif tr == 'strip': base = base.str.strip()

    return base


# =========================================================
# Callback de limpieza de Rutina → IN_SISTECREDITO (PREVIEW)
# =========================================================
def on_clean_rutina(
    df_prev_rut_local,
    txt_log_local,
    chk_valores_enteros,
    chk_todos_cel_local,
    chk_mayus_local,
    chk_order_local,
    chk_order_desc_local,  # Z-A / Mayor a menor
):
    """
    Construye IN_SISTECREDITO (PREVIEW) usando como canon la hoja **ModeloRelacion**
    del Config_SinergIA (CONFIG_SPREADSHEET_ID hardcodeado).

    Retorna SIEMPRE 3 valores: (df_in_preview, run_id, log).
    """
    global DF_TER_CACHE, DF_IN_PREVIEW_CACHE, DF_IN_FULL_CACHE, DF_IN_CACHE

    log_local = txt_log_local or ""

    # Alias defensivo (wiring real del checkbox)
    force_int = bool(chk_valores_enteros)
    use_all_phones = bool(chk_todos_cel_local)
    use_upper = bool(chk_mayus_local)
    order_keys = list(chk_order_local or [])
    order_desc = bool(chk_order_desc_local)

    ctx = sinergia_new_run_context(
        action="PR_03_clean_rutina_to_in",
        meta={
            "ui_action": "btn_clean",
            "use_ints": force_int,
            "use_all_phones": use_all_phones,
            "use_upper": use_upper,
            "order_keys": order_keys,
            "order_desc": order_desc,
        },
    )
    ctx.add_event("PR_03_START", message="Inicio limpieza Rutina→IN (preview).")

    # 0) Guardrail: Rutina cargada
    if DF_TER_CACHE is None or (isinstance(DF_TER_CACHE, pd.DataFrame) and DF_TER_CACHE.empty):
        ctx.add_event("PR_03_FAIL", level="ERROR", message="No hay Rutina cargada para limpiar.")
        ctx.set_manifest("inputs.rutina.rows", 0)
        ctx.finalize("FAIL")
        log_local = _log_append(log_local, "No hay Rutina cargada para limpiar.")
        return pd.DataFrame(), ctx.run_id, log_local

    df_src = DF_TER_CACHE.copy()
    ctx.set_manifest("inputs.rutina.rows", int(len(df_src)))

    try:
        # 1) ModeloRelacion (canon)
        df_modelo_raw = _load_modelorelacion_df()
        df_modelo, log_local = sinergia_filter_modelorelacion_for_in(
            df_modelo_raw,
            log_local,
            sistema="SinergIA",
            archivo_destino="IN_SISTECREDITO",
        )

        ok_modelo, log_local = sinergia_validate_modelorelacion_min(df_modelo, log_local)
        if not ok_modelo:
            df_empty = sinergia_make_empty_in(df_modelo)
            ctx.add_event("PR_03_FAIL", level="ERROR", message="ModeloRelacion inválido/vacío para IN.")
            ctx.finalize("FAIL")
            return df_empty, ctx.run_id, log_local

        # 2) Construcción IN (DIRECTO/DEFAULT)
        df_in_base, log_local = sinergia_build_in_direct_default(
            df_src=df_src,
            df_modelo=df_modelo,
            log=log_local,
            use_ints=force_int,
            use_upper=use_upper,
            use_all_phones=use_all_phones,
        )

        # 2b) Regla teléfonos (REGLA_TELEFONOS)
        df_in_base, log_local = sinergia_apply_regla_telefonos(
            df_out=df_in_base,
            df_src=df_src,
            df_modelo=df_modelo,
            log=log_local,
            use_all_phones=use_all_phones,
        )

        # 2b.1) Regla franjas (si existe)
        try:
            if "sinergia_apply_regla_franjas" in globals():
                df_in_base, log_local = sinergia_apply_regla_franjas(
                    df_in=df_in_base,
                    log=log_local,
                    enabled=True,
                    parametro="FRANJAMORA",
                )
            else:
                log_local = _log_append(
                    log_local,
                    "WARN · REGLA_FRANJAS no aplicada: sinergia_apply_regla_franjas no existe.",
                )
        except Exception as e:
            log_local = _log_append(
                log_local,
                f"WARN · REGLA_FRANJAS falló: {e}. Se continúa sin franjas.",
            )

        # 2c) Normalización numérica a enteros (si existe helper)
        if force_int and "_sinergia_force_numeric_integers" in globals():
            estructuras_df = None
            if "_load_estructuras_df" in globals():
                try:
                    estructuras_df = _load_estructuras_df()
                except Exception as e:
                    log_local = _log_append(log_local, f"Advertencia: no se pudo cargar Estructuras: {e}")

            try:
                df_in_base, log_local = _sinergia_force_numeric_integers(
                    df_in=df_in_base,
                    estructuras_df=estructuras_df,
                    archivo_logico="IN_SISTECREDITO",
                    log=log_local,
                    enabled=True,
                    min_int_digits=5,
                )
            except Exception as e:
                log_local = _log_append(log_local, f"Advertencia: normalización enteros falló: {e}")

        # 3) Ordenamiento dinámico (preview)
        df_final_sorted, log_local = _apply_dynamic_sorting(
            df_in_base,
            log_local,
            order_keys=order_keys,
            order_desc_flag=order_desc,
        )

        # 4) Cache + QualityGate mínimo
        DF_IN_PREVIEW_CACHE = df_final_sorted.copy()
        DF_IN_CACHE = DF_IN_PREVIEW_CACHE  # compat
        ctx.set_manifest("outputs.in_preview.rows", int(len(df_final_sorted)))

        ok_gate, log_local = sinergia_quality_gate_in(df_final_sorted, log_local, ctx=ctx)
        if not ok_gate:
            ctx.add_event("PR_03_FAIL", level="ERROR", message="QualityGate IN falló.")
            ctx.finalize("FAIL")
            return df_final_sorted, ctx.run_id, log_local

        ctx.add_event("PR_03_OK", message="Limpieza Rutina→IN (preview) OK.")
        ctx.finalize("OK")
        return df_final_sorted, ctx.run_id, log_local

    except Exception as e:
        log_local = _log_append(log_local, f"ERROR en Limpiar rutina: {e}")
        try:
            ctx.add_event("PR_03_FAIL", level="ERROR", message=str(e))
            ctx.finalize("FAIL")
        except Exception:
            pass

        df_fallback = None
        try:
            df_fallback = sinergia_make_empty_in(_load_modelorelacion_df())
        except Exception:
            df_fallback = pd.DataFrame()

        return df_fallback, getattr(ctx, "run_id", "RUN-ERROR"), log_local

# SinergIA2750 - Callbacks (Register)
from typing import Dict, Any

def register_callbacks(components: Dict[str, Any]) -> None:
    """
    Refrescar listas + previews de las 4 bases + limpieza de Rutina + Export AWS + Derivar Listas.
    Derivar Listas usa el handler canónico: _sinergia_btn_listas_derivar.
    """

    # Normalización (acordeón)
    chk_valores_enteros = components["chk_valores_enteros"]
    chk_todos_cel = components["chk_todos_cel"]
    chk_mayus = components["chk_mayus"]
    chk_order = components["chk_order"]
    chk_order_desc = components["chk_order_desc"]

    # Botones Actualizar
    btn_refresh_rutina = components["btn_refresh_rutina"]
    btn_refresh_gestion = components["btn_refresh_gestion"]
    btn_refresh_prom = components["btn_refresh_prom"]
    btn_refresh_pag = components["btn_refresh_pag"]

    # Dropdowns
    dd_archivo_rutina = components["dd_archivo_rutina"]
    dd_archivo_gestion = components["dd_archivo_gestion"]
    dd_archivo_prom = components["dd_archivo_prom"]
    dd_archivo_pag = components["dd_archivo_pag"]

    # Rutina
    btn_prev_rutina = components["btn_prev_rutina"]
    file_rutina_local = components["file_rutina_local"]
    sl_visualizar_rutina = components["sl_visualizar_rutina"]
    df_prev_rut = components["df_prev_rut"]

    # Gestion
    btn_prev_gestion = components["btn_prev_gestion"]
    file_gestion_local = components["file_gestion_local"]
    df_gestion_essential = components["df_gestion_essential"]

    # Promesas
    btn_prev_prom = components["btn_prev_prom"]
    file_prom_local = components["file_prom_local"]
    df_prom_essential = components["df_prom_essential"]

    # Pagos
    btn_prev_pag = components["btn_prev_pag"]
    file_pag_local = components["file_pag_local"]
    df_pagos_essential = components["df_pagos_essential"]

    # Limpieza Rutina → IN_SISTECREDITO
    btn_clean = components["btn_clean"]
    df_prev_in = components["df_prev_in"]

    # Exportación Gestion
    btn_export_gestion = components["btn_export_gestion"]
    export_fmt = components["export_fmt"]
    out_export = components["out_export"]

    # Derivar Listas (Bases operativas)
    btn_listas = components["btn_listas"]
    df_listas_show = components["df_listas_show"]
    chk_use_traza_for_listas = components["chk_use_traza_for_listas"]
    sl_visualizar_listas = components["sl_visualizar_listas"]
    btn_prev_listas = components["btn_prev_listas"]


    # NUEVOS: fuentes usadas + previews por canal
    df_listas_sources = components["df_listas_sources"]

    df_prev_wa = components["df_prev_wa"]
    out_lista_wa = components["out_lista_wa"]

    df_prev_wise = components["df_prev_wise"]
    out_lista_wise = components["out_lista_wise"]

    df_prev_sms = components["df_prev_sms"]
    out_lista_sms = components["out_lista_sms"]

    df_prev_voz = components["df_prev_voz"]
    out_lista_voz = components["out_lista_voz"]

    # Config sheets
    cfg_sheets = components.get("cfg_sheets", {})

    global CFG_SHEETS_COMPONENTS
    CFG_SHEETS_COMPONENTS = cfg_sheets

    # Textos
    txt_log = components["txt_log"]
    txt_run_id = components.get("txt_run_id")  # puede ser None si no existe en UI

    # Wiring: Actualizar listas
    btn_refresh_rutina.click(_refresh_rutina_choices, [], [dd_archivo_rutina])
    btn_refresh_gestion.click(_refresh_gestion_choices, [], [dd_archivo_gestion])
    btn_refresh_prom.click(_refresh_promesas_choices, [], [dd_archivo_prom])
    btn_refresh_pag.click(_refresh_pagos_choices, [], [dd_archivo_pag])

    # Wiring: Previews
    btn_prev_rutina.click(
        fn=on_preview_rutina,
        inputs=[dd_archivo_rutina, file_rutina_local, sl_visualizar_rutina, df_prev_rut, txt_log],
        outputs=[df_prev_rut, txt_log],
    )

    btn_prev_gestion.click(
        fn=on_preview_gestion,
        inputs=[dd_archivo_gestion, file_gestion_local, df_gestion_essential, txt_log],
        outputs=[df_gestion_essential, txt_log],
    )

    btn_prev_prom.click(
        fn=on_preview_prom,
        inputs=[dd_archivo_prom, file_prom_local, df_prom_essential, txt_log],
        outputs=[df_prom_essential, txt_log],
    )

    btn_prev_pag.click(
        fn=on_preview_pagos,
        inputs=[dd_archivo_pag, file_pag_local, df_pagos_essential, txt_log],
        outputs=[df_pagos_essential, txt_log],
    )

    # Wiring: Limpiar Rutina → IN_SISTECREDITO (preview)
    btn_clean.click(
        fn=on_clean_rutina,
        inputs=[
            df_prev_rut,
            txt_log,
            chk_valores_enteros,
            chk_todos_cel,
            chk_mayus,
            chk_order,
            chk_order_desc,
        ],
        outputs=[df_prev_in, txt_run_id, txt_log],
        queue=True,
    )

    # Wiring: Exportación Gestion FULL
    btn_export_gestion.click(
        fn=_export_gestion_full,
        inputs=[
            export_fmt,
            dd_archivo_rutina,
            file_rutina_local,
            chk_valores_enteros,
            chk_todos_cel,
            chk_mayus,
            chk_order,
            chk_order_desc,
            txt_log,
        ],
        outputs=[out_export, txt_run_id, txt_log],
        queue=True,
    )

    # Wiring: Derivar Listas
    btn_listas.click(
        fn=_sinergia_btn_listas_derivar,
        inputs=[
            df_prev_in,
            dd_archivo_gestion,
            file_gestion_local,
            chk_use_traza_for_listas,
            txt_log,
            sl_visualizar_listas,  # <--- NUEVO (al final)
        ],
        outputs=[
            df_listas_show,
            df_listas_sources,
            df_prev_wa, out_lista_wa,
            df_prev_wise, out_lista_wise,
            df_prev_sms, out_lista_sms,
            df_prev_voz, out_lista_voz,
            txt_run_id,
            txt_log,
        ],
        queue=True,
    )

    # Wiring: recortar previews ya cargados (no recalcula listas)
    btn_prev_listas.click(
        fn=_sinergia_btn_listas_preview,
        inputs=[sl_visualizar_listas, df_prev_wa, df_prev_wise, df_prev_sms, df_prev_voz, txt_log],
        outputs=[df_prev_wa, df_prev_wise, df_prev_sms, df_prev_voz, txt_log],
        queue=True,
    )

# SinergIA2800 - Helpers post-fix SisteCredito
def _norm_name(name: str) -> str:
    return (
        str(name)
        .strip()
        .lower()
        .replace("á", "a")
        .replace("é", "e")
        .replace("í", "i")
        .replace("ó", "o")
        .replace("ú", "u")
        .replace("ñ", "n")
        .replace("  ", " ")
    )

def _clean_phone_value(val) -> str | None:
    """
    Limpia y valida números telefónicos para columnas Telefono 1..4.

    Reglas:
    - Elimina espacios y sufijo '.0'.
    - Mantiene solo dígitos.
    - Acepta solo números con longitud entre 10 y 11 dígitos.
    - Si no cumple, devuelve None.
    """
    if pd.isna(val):
        return None

    s = str(val).strip()
    if not s:
        return None

    # eliminar sufijo .0 típico de float
    if s.endswith(".0"):
        s = s[:-2]

    # dejar solo dígitos
    s = "".join(ch for ch in s if ch.isdigit())
    if not s:
        return None

    # longitud estricta: >9 y <12 → 10 a 11 dígitos
    if not (10 <= len(s) <= 11):
        return None

    return s

def _strip_string_columns(df: pd.DataFrame) -> pd.DataFrame:
    import unicodedata

    def _clean_text(val):
        if pd.isna(val):
            return pd.NA
        s = str(val).strip()
        if not s:
            return s
        # quitar tildes
        s = "".join(
            c for c in unicodedata.normalize("NFKD", s)
            if not unicodedata.combining(c)
        )
        # reemplazar guiones por espacio (solo para textos NO fecha)
        # Temporalmente sin procesarse esta regla
        s = s.replace("-", "-")
        return s

    df_out = df.copy()
    for col in df_out.columns:
        if pd.api.types.is_string_dtype(df_out[col]) or df_out[col].dtype == "object":
            col_norm = _norm_name(col)  # usamos helper ya definido
            serie = df_out[col].astype("string")

            if "fecha" in col_norm:
                # columnas de fecha: solo strip, no tocar símbolos
                df_out[col] = serie.str.strip()
            else:
                # resto de textos: limpieza completa
                df_out[col] = serie.map(_clean_text)

    return df_out

# SinergIA2900 - Lógica de fechas;  posible DEPRECATED; REVISAR
def _apply_sistecredito_ter_overrides(df_in, df_ter_raw, log):
    if df_ter_raw is None: return df_in, log
    df_out = df_in.copy()

    # Solo lógica de fechas para asegurar formato YYYY-MM-DD
    def _override_date_direct(src, dst, desc, l):
        if src in df_ter_raw.columns and dst in df_out.columns:
            s = df_ter_raw[src].astype("string").str.strip().str.slice(0, 10)
            df_out[dst] = s
            return _log_append(l, f"Date Fix: {dst} <- {src}")
        return l

    log = _override_date_direct("FechaMasVencida", "Fecha de vencimiento", "", log)
    log = _override_date_direct("FechaNacimiento", "Fecha Nacimiento", "", log)
    log = _override_date_direct("FechaExpedicion", "Fecha Expedición", "", log)

    # ¡NADA MÁS! Ni Almacén, ni Nombre, ni Municipio.
    # Eso lo hace build_in_from_modelorelacion.

    return df_out, log

