# SinergIA3100 - REGLA_TELEFONOS (sin hardcode; params-driven)
import re
import unicodedata
import pandas as pd

_TEL_EXT_PATTERN = re.compile(r"^\s*(\d{7,9})\s*[-\s]\s*(\d{1,3})\s*$")

def _tel__norm_key(s: str) -> str:
    if s is None:
        return ""
    s = str(s).strip().lower()
    s = "".join(c for c in unicodedata.normalize("NFKD", s) if not unicodedata.combining(c))
    s = re.sub(r"\s+", " ", s)
    return s

def _tel__find_col(df: pd.DataFrame, wanted: str):
    if wanted in df.columns:
        return wanted
    w = _tel__norm_key(wanted)
    for c in df.columns:
        if _tel__norm_key(c) == w:
            return c
    return None

def _tel__parse_kv_params(raw: str) -> dict:
    """
    Esperado (canónico): key=val;key2=val2
    IMPORTANTE: NO partir por coma, porque cols trae comas dentro del valor.
    """
    out = {}
    if raw is None or (isinstance(raw, float) and pd.isna(raw)):
        return out
    s = str(raw).strip()
    if not s:
        return out
    parts = [p.strip() for p in s.split(";") if p.strip()]
    for p in parts:
        if "=" in p:
            k, v = p.split("=", 1)
            out[k.strip().lower()] = v.strip()
    return out

def _tel__clean_digits(x: object) -> str:
    """Normaliza cualquier valor a dígitos.
    - Soporta int/float (incl. notación científica) sin perder dígitos ni meter .0
    - Si detecta patrón de fijo con extensión, conserva solo la base.
    """
    if x is None or (isinstance(x, float) and pd.isna(x)):
        return ""

    # Numéricos: evitar notación científica y decimales
    try:
        if isinstance(x, (int, np.integer)):
            return str(int(x))
        if isinstance(x, (float, np.floating)) and pd.notna(x):
            s_num = f"{float(x):.0f}".strip()
            if s_num.isdigit():
                return s_num
    except Exception:
        pass

    s = str(x).strip()
    if not s:
        return ""

    m = _TEL_EXT_PATTERN.match(s)
    if m:
        s = m.group(1)

    return re.sub(r"\D+", "", s)


def _tel__extract_candidates(x: object, minlen: int, maxlen: int) -> list[str]:
    """Extrae candidatos telefónicos desde una celda.
    - Si es numérico: normaliza directo (evita notación científica).
    - Si es texto: busca tokens de 7..15 dígitos y luego aplica filtro minlen/maxlen.
    - Fallback: limpia todo a dígitos.
    """
    if x is None or (isinstance(x, float) and pd.isna(x)):
        return []

    # Ruta numérica (int/float): normaliza directo
    if isinstance(x, (int, float, np.integer, np.floating)) and pd.notna(x):
        d = _tel__clean_digits(x)
        return [d] if (d and minlen <= len(d) <= maxlen) else []

    raw = str(x)
    if not raw.strip():
        return []

    tokens = re.findall(r"\d{7,15}", raw)
    cands = []
    for t in tokens:
        if minlen <= len(t) <= maxlen:
            cands.append(t)

    if not cands:
        d = _tel__clean_digits(raw)
        if minlen <= len(d) <= maxlen:
            cands.append(d)

    seen = set()
    out = []
    for p in cands:
        if p and p not in seen:
            seen.add(p)
            out.append(p)
    return out


def sinergia_apply_regla_telefonos__deprecated_0550(
    df_in: pd.DataFrame,
    df_src: pd.DataFrame,
    df_modelo: pd.DataFrame,
    use_all_phones: bool,
    log: str | None = None,
) -> tuple[pd.DataFrame, str | None]:
    """
    Llena Telefono 1..4 según ModeloRelacion:
    - Filtra TipoRegla=REGLA_TELEFONOS
    - Lee ParametrosRegla: cols=...;minlen=...;maxlen=...
    - Si use_all_phones=False: solo llena Telefono 1..2, deja 3..4 en blanco
    """
    if df_modelo is None or df_modelo.empty:
        return df_in, log

    tel_rows = df_modelo[df_modelo["TipoRegla"].astype(str).str.upper() == "REGLA_TELEFONOS"].copy()
    if tel_rows.empty:
        return df_in, log

    tel_rows = tel_rows.sort_values("OrdenDestino")
    tel_targets = tel_rows["ColumnaDestino"].tolist()

    params = _tel__parse_kv_params(tel_rows.iloc[0].get("ParametrosRegla"))
    cols_raw = params.get("cols", "")
    src_cols = [c.strip() for c in cols_raw.split(",") if c.strip()]

    minlen = int(params.get("minlen", 10))
    maxlen = int(params.get("maxlen", 11))

    # asegurar columnas destino
    for c in tel_targets:
        if c not in df_in.columns:
            df_in[c] = ""

    # match robusto columnas origen
    matched = []
    for sc in src_cols:
        col = _tel__find_col(df_src, sc)
        if col:
            matched.append(col)

    if not matched:
        for c in tel_targets:
            df_in[c] = ""
        if log is not None:
            log = _log_append(log, f"WARN: REGLA_TELEFONOS: no se encontraron columnas origen {src_cols}.")
        return df_in, log

    max_fill = 4 if use_all_phones else 2

    out_vals = {c: [] for c in tel_targets}
    n = len(df_in)

    for i in range(n):
        candidates = []
        for col in matched:
            candidates.extend(_tel__extract_candidates(df_src.iloc[i][col], minlen, maxlen))

        # de-dup final conservando orden
        seen = set()
        uniq = []
        for p in candidates:
            if p and p not in seen:
                seen.add(p)
                uniq.append(p)

        for j, dest_col in enumerate(tel_targets):
            if j < max_fill and j < len(uniq):
                out_vals[dest_col].append(uniq[j])
            else:
                out_vals[dest_col].append("")

    for c in tel_targets:
        df_in[c] = out_vals[c]

    # ENFORCE ABSOLUTO: SOLO CELULARES (CO) -> deben iniciar por "3"
    # (descarta fijos y cualquier otro formato que no cumpla)
    removed_total = 0
    for c in tel_targets:
        s = df_in[c].astype("string")
        s = s.str.replace(r"\D", "", regex=True).str.strip()
        s = s.replace("", pd.NA)

        before = int(s.notna().sum())
        s = s.where(s.str.len().between(minlen, maxlen), pd.NA)
        s = s.where(s.str.startswith("3"), pd.NA)  # <-- regla dura
        removed_total += before - int(s.notna().sum())

        df_in[c] = s.fillna("")

    if log is not None:
        log = _log_append(
            log,
            level="INFO",
            message=f"REGLA_TELEFONOS aplicada · usar_todos={use_all_phones} · origen={matched} · minlen={minlen} maxlen={maxlen} · mobile_only_removed={removed_total}."
        )
    return df_in, log

# SinergIA3200 - REGLA_FRANJAS (FRANJAMORA desde Config_SinergIA/Parameters)
# ============================

import re
import unicodedata
import pandas as pd

def sinergia_apply_regla_franjas(
    df_in: pd.DataFrame,
    log: str | None = None,
    enabled: bool = True,
    parametro: str = "FRANJAMORA",
) -> tuple[pd.DataFrame, str]:
    if log is None:
        log = ""
    if not enabled:
        return df_in, log
    if df_in is None or df_in.empty:
        return df_in, _log_append(log, "REGLA_FRANJAS omitida: DF IN vacío.")

    def _norm_key(s: str) -> str:
        if s is None:
            return ""
        s = str(s).strip().lower()
        s = "".join(c for c in unicodedata.normalize("NFKD", s) if not unicodedata.combining(c))
        # quitar puntuación / símbolos, dejar letras/números/espacios
        s = re.sub(r"[^a-z0-9\s]", " ", s)
        s = re.sub(r"\s+", " ", s).strip()
        return s

    # 1) Cargar Parameters desde Config (si existe helper canónico)
    df_params = None
    try:
        if "_get_cfg_params" in globals():
            df_params = _get_cfg_params(log)
        elif "read_gsheet" in globals() and "CONFIG_SPREADSHEET_ID" in globals():
            df_params = read_gsheet(CONFIG_SPREADSHEET_ID, "Parameters")
    except Exception as e:
        df_params = None
        log = _log_append(log, f"REGLA_FRANJAS: no se pudo leer Parameters: {e}")

    if df_params is None or (isinstance(df_params, pd.DataFrame) and df_params.empty):
        if "Franja" not in df_in.columns:
            df_in["Franja"] = pd.Series(pd.NA, index=df_in.index, dtype="string")
        return df_in, _log_append(log, f"REGLA_FRANJAS omitida: Parameters vacío/no disponible. parametro={parametro}.")

    df_p = df_params.copy()
    df_p.columns = [str(c).strip().lower() for c in df_p.columns]

    need = {"parametro", "desde", "hasta"}
    if not need.issubset(set(df_p.columns)):
        if "Franja" not in df_in.columns:
            df_in["Franja"] = pd.Series(pd.NA, index=df_in.index, dtype="string")
        return df_in, _log_append(log, f"REGLA_FRANJAS omitida: faltan columnas en Parameters. found={list(df_p.columns)}.")

    c_etq = "etiqueta" if "etiqueta" in df_p.columns else None

    df_f = df_p.loc[df_p["parametro"].astype(str).str.strip().str.upper().eq(str(parametro).strip().upper())].copy()
    if df_f.empty:
        if "Franja" not in df_in.columns:
            df_in["Franja"] = pd.Series(pd.NA, index=df_in.index, dtype="string")
        return df_in, _log_append(log, f"REGLA_FRANJAS omitida: sin filas para parametro={parametro} en Parameters.")

    df_f["desde"] = pd.to_numeric(df_f["desde"], errors="coerce")
    df_f["hasta"] = pd.to_numeric(df_f["hasta"], errors="coerce")

    # 2) Detectar columna de días en mora (robusto)
    dias_col = None
    for c in df_in.columns:
        nk = _norm_key(c)
        # Queremos "dias" + "mora" (evita agarrar "valor mora")
        if ("mora" in nk) and (("dia" in nk) or ("dias" in nk)) and ("valor" not in nk):
            dias_col = c
            break

    if dias_col is None:
        # fallback: match exacto normalizado
        for c in df_in.columns:
            nk = _norm_key(c)
            if nk in {"dias en mora", "dias mora", "diasmora"}:
                dias_col = c
                break

    if dias_col is None:
        if "Franja" not in df_in.columns:
            df_in["Franja"] = pd.Series(pd.NA, index=df_in.index, dtype="string")
        return df_in, _log_append(log, "REGLA_FRANJAS omitida: no se encontró columna de Días en Mora en IN.")

    dias = pd.to_numeric(df_in[dias_col], errors="coerce")
    if int(dias.notna().sum()) == 0:
        if "Franja" not in df_in.columns:
            df_in["Franja"] = pd.Series(pd.NA, index=df_in.index, dtype="string")
        return df_in, _log_append(log, f"REGLA_FRANJAS omitida: columna '{dias_col}' no parseable a numérico (todo NaN).")

    fr = pd.Series(pd.NA, index=df_in.index, dtype="string")

    # 3) Asignación por rangos [desde, hasta]
    for _, row in df_f.iterrows():
        d = row.get("desde")
        h = row.get("hasta")
        if pd.isna(d) or pd.isna(h):
            continue
        etiqueta = ""
        if c_etq:
            etiqueta = str(row.get(c_etq) or "").strip()
        if not etiqueta:
            etiqueta = f"{int(d)}-{int(h)}"
        mask = (dias >= d) & (dias <= h)
        fr = fr.mask(mask, etiqueta)

    df_in["Franja"] = fr
    nonempty = int(fr.astype(str).str.strip().ne("").sum())
    log = _log_append(log, f"REGLA_FRANJAS aplicada: nonempty={nonempty}/{len(df_in)}. parametro={parametro}. dias_col={dias_col}.")
    return df_in, log

# SinergIA3300 - limpieza de prefijos numéricos y encabezados según Estructuras
import pandas as pd

def sinergia_apply_leading_noise_cleanup(
    df: pd.DataFrame,
    df_modelo: pd.DataFrame,
    log: str,
    apply_all_text_cols: bool,
    marker_col: str = "LimpiarColumna",
    exclude_cols: set | None = None,
) -> tuple[pd.DataFrame, str]:
    """
    Quita prefijos tipo '0', '00', '001', '0001', números y signos antes del texto.
    Regla: si el texto termina quedando sin letras, se vuelve vacío.
    Modo:
    - apply_all_text_cols=True  -> aplica a casi todas las columnas texto (excepto exclude_cols)
    - apply_all_text_cols=False -> aplica solo a ColumnaDestino donde ModeloRelacion[LimpiarColumna] sea TRUE
    """
    if df is None or df.empty:
        return df, log

    if exclude_cols is None:
        exclude_cols = {
            "Crédito", "Credito", "Status",
            "Documento de identidad", "Identificacion", "Identificación",
        }

    candidates = []
    if apply_all_text_cols:
        for c in df.columns:
            if c in exclude_cols:
                continue
            if pd.api.types.is_string_dtype(df[c]) or pd.api.types.is_object_dtype(df[c]):
                candidates.append(c)
    else:
        if df_modelo is None or df_modelo.empty or marker_col not in df_modelo.columns:
            return df, _log_append(log, "Limpieza prefijos: marker LimpiarColumna no disponible.  Sin cambios.")
        mm = df_modelo.copy()
        mm["ColumnaDestino"] = mm["ColumnaDestino"].astype(str).str.strip()
        mm["_mk"] = mm[marker_col].map(_as_bool)
        candidates = [c for c in mm.loc[mm["_mk"], "ColumnaDestino"].tolist() if c and c in df.columns and c not in exclude_cols]

    if not candidates:
        return df, _log_append(log, "Limpieza prefijos: no hay columnas candidatas.  Sin cambios.")

    # Regex de ruido al inicio y al final
    rx_edge = r"^[\s0-9\-\.,;:/\\#\(\)\[\]\{\}]+|[\s0-9\-\.,;:/\\#\(\)\[\]\{\}]+$"

    changed = 0
    for c in candidates:
        s = df[c].fillna("").astype("string").astype(str).str.strip()

        # Si no hay letras, vacío
        has_alpha = s.str.contains(r"[A-Za-z]", regex=True)
        s = s.where(has_alpha, "")

        # Quita ruido en bordes y re-trim
        s2 = s.str.replace(rx_edge, "", regex=True).str.strip()

        # Si quedó sin letras, vacío
        has_alpha2 = s2.str.contains(r"[A-Za-z]", regex=True)
        s2 = s2.where(has_alpha2, "")

        if (s2 != df[c].fillna("").astype("string").astype(str)).any():
            changed += 1
        df[c] = s2

    log = _log_append(log, f"Limpieza prefijos aplicada.  Columnas_afectadas={changed}/{len(candidates)}.  Modo_all={apply_all_text_cols}.")
    return df, log

def sinergia_enforce_headers_from_estructuras(
    df: pd.DataFrame,
    df_estructuras: pd.DataFrame,
    log: str,
    sistema: str,
    archivo_logico: str,
) -> tuple[pd.DataFrame, str]:
    """
    Fuerza encabezados EXACTOS (con tildes) y orden según hoja Estructuras.
    Úsalo justo antes de exportar CSV.
    """
    if df is None or df.empty or df_estructuras is None or df_estructuras.empty:
        return df, log

    e = df_estructuras.copy()
    e.columns = [str(c).strip() for c in e.columns]

    req = ["Sistema", "ArchivoLogico", "ColumnaOrden", "NombreColumna", "AliasCanonico"]
    miss = [c for c in req if c not in e.columns]
    if miss:
        return df, _log_append(log, f"Estructuras inválida: faltan columnas {miss}.")

    e["Sistema"] = e["Sistema"].astype(str).str.strip()
    e["ArchivoLogico"] = e["ArchivoLogico"].astype(str).str.strip()

    e = e[(e["Sistema"] == str(sistema).strip()) & (e["ArchivoLogico"] == str(archivo_logico).strip())].copy()
    if e.empty:
        return df, _log_append(log, f"Estructuras sin filas para Sistema='{sistema}' ArchivoLogico='{archivo_logico}'.")

    e["ColumnaOrden"] = pd.to_numeric(e["ColumnaOrden"], errors="coerce")
    e = e.sort_values(["ColumnaOrden", "NombreColumna"], kind="stable")

    desired_names = e["NombreColumna"].astype(str).str.strip().tolist()
    alias_map = dict(zip(e["AliasCanonico"].astype(str).str.strip(), desired_names))

    # índice por clave normalizada de columnas actuales
    cur_cols = list(df.columns)
    cur_by_key = {_sinergia_norm_key(c): c for c in cur_cols}

    rename = {}
    for cur in cur_cols:
        kcur = _sinergia_norm_key(cur)
        # Si ya coincide con algún NombreColumna, no tocar
        if kcur in {_sinergia_norm_key(x) for x in desired_names}:
            continue
        # Si coincide con alias, renombra a NombreColumna con tilde
        if cur in alias_map:
            rename[cur] = alias_map[cur]
            continue
        # Si coincide por clave con alias, renombra
        for a, dn in alias_map.items():
            if _sinergia_norm_key(a) == kcur:
                rename[cur] = dn
                break

    if rename:
        df = df.rename(columns=rename)

    # Reorden: si falta alguna, la crea vacía para no romper layout
    for c in desired_names:
        if c not in df.columns:
            df[c] = ""

    df = df[desired_names]
    log = _log_append(log, f"Encabezados y orden forzados desde Estructuras.  Archivo='{archivo_logico}'.  cols={len(desired_names)}.")
    return df, log

# SinergIA3400 - Generación del archivo Entrada_AWS (CSV/XLSX) usando archivo temporal
import tempfile
import time
import os

def _generar_archivo_gestion(df_in: pd.DataFrame, formato: str):
    """
    Toma DF_IN_CACHE ya normalizado y genera un archivo descargable
    con el nombre Entrada_AWS_YYYY_MM_DD_HHMM.* en un archivo temporal.
    Devuelve SOLO la ruta (str), que es lo que gr.File espera.
    """

    if df_in is None or df_in.empty:
        return None

    timestamp = time.strftime("%Y_%m_%d_%H%M")
    base_name = f"Entrada_AWS_{timestamp}"

    # XLSX
    if formato == "XLSX":
        # crear archivo temporal con sufijo .xlsx
        with tempfile.NamedTemporaryFile(delete=False, suffix=".xlsx") as tmp:
            tmp_path = tmp.name

        # escribir el dataframe en esa ruta
        df_in.to_excel(tmp_path, index=False)

        # renombrar para que tenga el nombre final (opcional)
        final_path = os.path.join(os.path.dirname(tmp_path), base_name + ".xlsx")
        os.replace(tmp_path, final_path)

        # gr.File OUTPUT espera un str con la ruta
        return final_path

    # CSV (coma)
    if formato == "CSV (coma)":
        with tempfile.NamedTemporaryFile(delete=False, suffix=".csv") as tmp:
            tmp_path = tmp.name

        df_in.to_csv(tmp_path, index=False, sep=",")

        final_path = os.path.join(os.path.dirname(tmp_path), base_name + ".csv")
        os.replace(tmp_path, final_path)
        return final_path

    # CSV (punto y coma)
    if formato == "CSV (punto y coma)":
        with tempfile.NamedTemporaryFile(delete=False, suffix=".csv") as tmp:
            tmp_path = tmp.name

        df_in.to_csv(tmp_path, index=False, sep=";")

        final_path = os.path.join(os.path.dirname(tmp_path), base_name + ".csv")
        os.replace(tmp_path, final_path)
        return final_path

    # formato desconocido
    return None

# SinergIA3500 - OUT_GESTION layout builder (CANÓNICO: ModeloRelacion)
import pandas as pd
import unicodedata

# Fallback solo por estabilidad si ModeloRelacion no carga (no debería ocurrir)
_GESTION_OUT_COLUMNS_FALLBACK = [
    "Documento de identidad","Nombre Completo","Dirección Del Cliente","Fecha Nacimiento",
    "Fecha Expedición","Reportado a Centrales","Crédito","Fecha Creación del crédito","Valor",
    "Número de cuotas vencidas","Fecha de vencimiento","Días en Mora","Valor Mora","Cargos Jurídico",
    "Saldo Total","Telefono 1","Telefono 2","Telefono 3","Telefono 4","Almacen","Municipio Almacen",
    "Direccion Almacen","Teléfono Almacén","Status","Servicio","Franja","IN_PRIORIDAD",
    "Tipo de Documento","In_Serviceid"
]

_GESTION_SPEC_CACHE = {"cols": None, "date_cols": None}

def _gestion__norm(s: str) -> str:
    s = "" if s is None else str(s)
    s = unicodedata.normalize("NFKD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    return s.strip().lower()

def _gestion_out_spec_from_modelorelacion() -> tuple[list[str], list[str]]:
    """
    Canoniza OUT_GESTION desde Config_SinergIA / ModeloRelacion.
    - Filtro: Sistema='SinergIA' y ArchivoDestino='IN_SISTECREDITO'
    - Orden: OrdenDestino
    - Columnas: ColumnaDestino (únicas en orden)
    - Fechas: TipoDatoDestino inicia con 'Fecha'
    """
    # 1) Cargar ModeloRelacion
    dfm = None
    if "_load_modelorelacion_df" in globals():
        try:
            dfm = _load_modelorelacion_df()
        except Exception:
            dfm = None
    if dfm is None:
        dfm = read_gsheet(CONFIG_SPREADSHEET_ID, "ModeloRelacion")

    dfm = dfm.copy()
    dfm.columns = [str(c).strip() for c in dfm.columns]

    # 2) Filtrar canónico
    if "Sistema" in dfm.columns:
        dfm = dfm[dfm["Sistema"].astype(str).str.strip().str.upper() == "SINERGIA"]
    if "ArchivoDestino" in dfm.columns:
        dfm = dfm[dfm["ArchivoDestino"].astype(str).str.strip().str.upper() == "IN_SISTECREDITO"]

    # 3) Orden
    if "OrdenDestino" in dfm.columns:
        dfm["OrdenDestino"] = pd.to_numeric(dfm["OrdenDestino"], errors="coerce")
        dfm = dfm.sort_values("OrdenDestino", kind="stable")

    # 4) Columnas destino (únicas)
    raw_cols = [str(x).strip() for x in dfm.get("ColumnaDestino", pd.Series([], dtype=object)) if str(x).strip()]
    seen, out_cols = set(), []
    for c in raw_cols:
        if c not in seen:
            seen.add(c)
            out_cols.append(c)

    # 5) Columnas fecha
    date_cols = []
    if "TipoDatoDestino" in dfm.columns and "ColumnaDestino" in dfm.columns:
        for _, r in dfm.iterrows():
            t = str(r.get("TipoDatoDestino", "")).strip().lower()
            dest = str(r.get("ColumnaDestino", "")).strip()
            if dest and t.startswith("fecha"):
                date_cols.append(dest)
    dseen, out_dates = set(), []
    for c in date_cols:
        if c not in dseen:
            dseen.add(c)
            out_dates.append(c)

    return out_cols, out_dates

def _gestion_get_spec(log: str) -> tuple[list[str], list[str], str]:
    if _GESTION_SPEC_CACHE["cols"] is not None:
        return _GESTION_SPEC_CACHE["cols"], _GESTION_SPEC_CACHE["date_cols"], log

    try:
        cols, dcols = _gestion_out_spec_from_modelorelacion()
        if not cols or len(cols) < 10:
            raise ValueError(f"ModeloRelacion devolvió spec insuficiente. cols={len(cols)}")
        _GESTION_SPEC_CACHE["cols"] = cols
        _GESTION_SPEC_CACHE["date_cols"] = dcols
        log = _log_append(log, f"OUT_GESTION spec OK (ModeloRelacion). cols={len(cols)} fechas={len(dcols)}")
        return cols, dcols, log
    except Exception as e:
        cols = _GESTION_OUT_COLUMNS_FALLBACK
        dcols = ["Fecha Nacimiento","Fecha Expedición","Fecha Creación del crédito","Fecha de vencimiento"]
        _GESTION_SPEC_CACHE["cols"] = cols
        _GESTION_SPEC_CACHE["date_cols"] = dcols
        log = _log_append(log, f"OUT_GESTION spec FAIL -> fallback. {type(e).__name__}: {e}")
        return cols, dcols, log

def _to_out_gestion_layout(df_in: pd.DataFrame, log: str) -> tuple[pd.DataFrame, str]:
    """
    Asegura OUT_GESTION (canónico por ModeloRelacion):
    - Columnas y orden desde ModeloRelacion (ColumnaDestino por OrdenDestino).
    - Alinea headers por match sin tildes/variantes (no pierde datos).
    - Formato de fechas DD/MM/YYYY cuando sea posible.
    """
    if df_in is None or df_in.empty:
        return pd.DataFrame(), _log_append(log, "OUT_GESTION: DF_IN vacío. No se puede construir layout.")

    df = df_in.copy()
    gestion_cols, gestion_date_cols, log = _gestion_get_spec(log)

    # 0) Alinear headers a canónico (match sin tildes)
    cols_before = list(df.columns)
    norm_to_actual = {_gestion__norm(c): c for c in cols_before}
    rename_map = {}
    for expected in gestion_cols:
        ne = _gestion__norm(expected)
        if ne in norm_to_actual:
            actual = norm_to_actual[ne]
            if actual != expected:
                rename_map[actual] = expected
    if rename_map:
        df.rename(columns=rename_map, inplace=True)
        log = _log_append(log, f"OUT_GESTION headers align OK. renamed={len(rename_map)}")

    # 1) Crear faltantes
    for c in gestion_cols:
        if c not in df.columns:
            df[c] = ""

    # 2) Formatear fechas (según ModeloRelacion)
    for c in gestion_date_cols:
        if c in df.columns:
            dt = pd.to_datetime(df[c], errors="coerce", dayfirst=True)
            df[c] = dt.dt.strftime("%d/%m/%Y").fillna("")

    # 3) Normalizar boolean/int esperable
    if "Reportado a Centrales" in df.columns:
        df["Reportado a Centrales"] = pd.to_numeric(df["Reportado a Centrales"], errors="coerce").fillna(0).astype(int)

    # 4) Recortar a layout estricto
    df = df[gestion_cols].copy()

    log = _log_append(log, f"OUT_GESTION layout OK. Columnas={len(df.columns)} Filas={len(df)}")
    return df, log

# SinergIA3510 - GESTION_PREWRITE: build OUT_GESTION + ExportGate (no escribe archivo)
def sinergia_pr04_build_out_gestion_and_gate(
    df_in,
    *,
    log: str = "",
    rc=None,
) -> tuple[object, dict, str]:
    """
    Construye df_out_gestion usando el layout canónico (SinergIA3500)
    y evalúa ExportGate Gestion (SinergIA4400) sin escribir archivo.
    Devuelve: (df_out_gestion, gates, log)
    """
    # Guardrails
    need = ["_to_out_gestion_layout", "sinergia_export_gate_gestion"]
    miss = [n for n in need if n not in globals() or not callable(globals().get(n))]
    if miss:
        raise RuntimeError(f"ABORT · faltan definiciones: {miss}")

    # 1) Layout OUT_GESTION
    df_out, log2 = _to_out_gestion_layout(df_in, log)

    # 2) ExportGate Gestion
    ok_gestion, _ = sinergia_export_gate_gestion(df_out, log="")
    gates = {"PR_EXPORT_GESTION": {"ok": bool(ok_gestion)}}

    # 3) Evidencia (manifest + audit) si hay rc
    if rc:
        try:
            rc.set_manifest("gates.PR_EXPORT_GESTION", gates["PR_EXPORT_GESTION"])
            rc.add_event(
                "PR_EXPORT_GESTION_OK" if ok_gestion else "PR_EXPORT_GESTION_FAIL",
                level="INFO" if ok_gestion else "ERROR",
                message="ExportGate Gestion OK." if ok_gestion else "ExportGate Gestion FAIL.",
                data={"rows": int(len(df_out)) if hasattr(df_out, "__len__") else None, "cols": int(len(getattr(df_out, "columns", [])))},
                etapa="PR_04",
            )
            rc.set_manifest("metrics.PR_EXPORT_GESTION", {"rows": int(len(df_out)), "cols": int(len(getattr(df_out, "columns", [])))})
        except Exception:
            pass

    return df_out, gates, log2

# SinergIA3600 - Diagnóstico de folder_id y listado de archivos para dropdowns (Bases operativas)
def _safe_call_folder_id(fn_name: str):
    fn = globals().get(fn_name)
    if not callable(fn):
        return None, f"{fn_name} no existe"
    try:
        return fn(), None
    except Exception as e:
        return None, f"{fn_name} error: {e}"

def _drive_list_names_best_effort(folder_id: str, max_items: int = 50):
    """
    Intenta listar nombres usando la función que exista en tu notebook.
    Retorna (names, err).  names es lista[str].
    """
    if not folder_id:
        return [], "folder_id vacío"

    # 1) Si existe drive_list_files(folder_id) y devuelve dicts con name
    for cand in ["drive_list_files", "drive_list_files_in_folder", "drive_list_folder_files"]:
        fn = globals().get(cand)
        if callable(fn):
            try:
                items = fn(folder_id)
                names = []
                # soporta lista de dict o tuplas
                for it in items or []:
                    if isinstance(it, dict):
                        n = it.get("name") or it.get("title")
                        if n: names.append(str(n))
                    elif isinstance(it, (list, tuple)) and len(it) >= 2:
                        # (id, name) o (name, id)
                        if isinstance(it[1], str):
                            names.append(it[1])
                        elif isinstance(it[0], str):
                            names.append(it[0])
                return names[:max_items], None
            except Exception as e:
                return [], f"{cand} error: {e}"

    # 2) Si no hay función de listado, devolvemos err explícito
    return [], "No existe función de listado Drive (drive_list_files / drive_list_files_in_folder / drive_list_folder_files)"

def sinergia_debug_operational_dropdown_sources(log: str = "") -> str:
    log = _log_append(log, "DEBUG · Dropdown sources (Bases operativas)")

    targets = [
        ("RUTINA", "get_rutinas_folder_id"),
        ("GESTION", "get_gestion_folder_id"),
        ("PROMESAS", "get_promesas_folder_id"),
        ("PAGOS", "get_pagos_folder_id"),
    ]

    for label, fn_name in targets:
        folder_id, err = _safe_call_folder_id(fn_name)
        if err:
            log = _log_append(log, f"DEBUG · {label} · {err}")
            continue

        log = _log_append(log, f"DEBUG · {label} · folder_id={folder_id}")

        names, lerr = _drive_list_names_best_effort(folder_id, max_items=30)
        if lerr:
            log = _log_append(log, f"DEBUG · {label} · list_err={lerr}")
        else:
            log = _log_append(log, f"DEBUG · {label} · files_count={len(names)}")
            if names:
                log = _log_append(log, f"DEBUG · {label} · sample={names[:10]}")

    return log

# SinergIA3700 Carga FULL de Rutina (Drive → bytes; sin filesystem)
from typing import Optional, Tuple
import io, os
import pandas as pd

def _load_rutina_full_for_export(
    dd_archivo_rutina: Optional[str],
    file_rutina_local,
    log: str,
) -> Tuple[pd.DataFrame, str]:
    """
    Lee TODAS las filas de la Rutina para exportar a Entrada_AWS.
    - Local: lee de archivo subido (bytes)
    - Drive: usa drive_download_file(fid) → (name, bytes), sin tocar filesystem
    Devuelve (df, log)
    """

    # 1) Local tiene prioridad
    if file_rutina_local is not None:
        try:
            # Compat robusta: filepath / dict / file-like
            name, data = _local_file_to_name_and_bytes(file_rutina_local)
            df = _read_any_bytes_to_df_full(name, data)

            log = _log_append(log, f"Rutina FULL desde archivo local '{name}'. Shape={df.shape}")
            return df, log

        except Exception as e:
            log = _log_append(log, f"Error leyendo Rutina FULL desde archivo local: {e}")
            return pd.DataFrame(), log

    # 2) Drive (bytes, no path)
    nombre_archivo = (dd_archivo_rutina or "").strip()
    if not nombre_archivo:
        log = _log_append(log, "No se seleccionó archivo de Rutina en el dropdown (export FULL).")
        return pd.DataFrame(), log

    try:
        folder_id = get_rutinas_folder_id()
        if not folder_id:
            log = _log_append(log, "No se encontró ID de carpeta 'Rutinas' en SettingID.")
            return pd.DataFrame(), log

        fid, name_drive = drive_find_by_name(folder_id, nombre_archivo)
        if not fid:
            log = _log_append(log, f"Archivo de Rutina '{nombre_archivo}' no encontrado en Drive.")
            return pd.DataFrame(), log

        # ⬇️ Aquí está el cambio clave: bytes, no path
        name, data = drive_download_file(fid)   # → (nombre_real, bytes)
        bio = io.BytesIO(data)
        ext = os.path.splitext(name or name_drive)[1].lower()

        if ext in (".xlsx", ".xls"):
            df = pd.read_excel(bio, engine="openpyxl")
        else:
            df = pd.read_csv(bio, sep=None, engine="python")

        log = _log_append(log, f"Rutina FULL desde Drive '{name_drive}' (vía bytes). Shape={df.shape}")
        return df, log

    except Exception as e:
        log = _log_append(log, f"Error leyendo Rutina FULL desde Drive: {e}")
        return pd.DataFrame(), log

# SinergIA3800 - Pipeline FULL Rutina→IN (independiente de la GUI)
import pandas as pd

def run_pipeline_rutina_to_in_full(
    df_rutina: pd.DataFrame | None = None,
    log: str = "",
    use_ints: bool = False,
    use_all_phones: bool = False,
    use_upper: bool = True,
    order_keys: list | None = None,
    order_desc_flag: bool = False,
    # compat llamadas antiguas
    df: pd.DataFrame | None = None,
    **_,
) -> tuple[pd.DataFrame, str]:
    """
    FULL debe ir por el mismo camino que el PREVIEW siempre que estén disponibles los builders DIRECTO/DEFAULT.
    Si el ModeloRelacion/camino no está disponible, cae a fallback CFG sin romper.
    Retorno SIEMPRE: (df, log).
    """
    import inspect

    def _unpack2(res, a0=None, b0=None):
        # acepta (a,b), (a,b,...) o valores sueltos
        if isinstance(res, (tuple, list)):
            a = res[0] if len(res) > 0 else a0
            b = res[1] if len(res) > 1 else b0
            return a, b
        return (res if res is not None else a0), b0

    # cache cfg para reglas IN (cargado on-demand)
    df_cfg = None
    df_params = None

    def _apply_rules_compat(df_in, df_src, log_local, use_all, use_up, use_ints_local, order_keys_local):
        """
        Wrapper para llamar _apply_in_siste_business_rules sin romper por firmas distintas.
        - Pasa SIEMPRE df_estructuras (requerido).
        - Pasa df_params si existe.
        Retorna SIEMPRE (df, log).  Si falla, NO tumba el FULL.
        """
        if "_apply_in_siste_business_rules" not in globals():
            return df_in, log_local

        nonlocal df_cfg, df_params

        # Cargar cfg on-demand (requerido por _apply_in_siste_business_rules)
        if (df_cfg is None) or (hasattr(df_cfg, "empty") and df_cfg.empty):
            if "_get_cfg_estructuras" in globals():
                df_cfg, log_local = _unpack2(_get_cfg_estructuras(log_local), pd.DataFrame(), log_local)

        if df_cfg is None or (hasattr(df_cfg, "empty") and df_cfg.empty):
            return df_in, _log_append(log_local, "Pipeline FULL Rutina→IN: WARN apply_rules skipped: df_estructuras vacío.")

        # df_params es opcional
        if df_params is None:
            if "_get_cfg_params" in globals():
                try:
                    df_params = _get_cfg_params(log_local)
                except Exception:
                    df_params = None

        fn = globals()["_apply_in_siste_business_rules"]
        try:
            sig = inspect.signature(fn)
            p = sig.parameters
            accepts_varkw = any(v.kind == inspect.Parameter.VAR_KEYWORD for v in p.values())

            mapping = {
                # df principal
                "df_in": df_in,
                "df": df_in,
                "df_clean": df_in,

                # fuente (opcional)
                "df_rutina": df_src,
                "df_src": df_src,
                "df_norm": df_src,

                # cfg
                "df_estructuras": df_cfg,
                "df_cfg": df_cfg,
                "estructuras_df": df_cfg,
                "df_params": df_params,

                # flags
                "use_ints": bool(use_ints_local),
                "use_all_phones": bool(use_all),
                "use_upper": bool(use_up),
                "order_keys": (order_keys_local or []),

                # log
                "log": log_local,
            }

            kwargs = mapping if accepts_varkw else {k: v for k, v in mapping.items() if k in p}
            res = fn(**kwargs)
            return _unpack2(res, df_in, log_local)

        except Exception as e:
            return df_in, _log_append(log_local, f"Pipeline FULL Rutina→IN: WARN apply_rules skipped: {e}")

    def _post_fix_compat(df_in, df_src, log_local, use_all):
        """
        Wrapper para llamar _post_fix_in_siste_business_rules sin romper por firmas distintas.
        Retorna SIEMPRE (df, log).  Si falla, NO tumba el FULL.
        """
        if "_post_fix_in_siste_business_rules" not in globals():
            return df_in, log_local

        fn = globals()["_post_fix_in_siste_business_rules"]
        try:
            sig = inspect.signature(fn)
            p = sig.parameters
            accepts_varkw = any(v.kind == inspect.Parameter.VAR_KEYWORD for v in p.values())

            mapping = {
                "df_clean": df_in,
                "df_in": df_in,
                "df": df_in,

                "df_ter_raw": df_src,
                "df_rutina": df_src,
                "df_src": df_src,

                "log": log_local,
                "use_all_phones": bool(use_all),
                "use_all": bool(use_all),
            }

            kwargs = mapping if accepts_varkw else {k: v for k, v in mapping.items() if k in p}
            res = fn(**kwargs)
            return _unpack2(res, df_in, log_local)

        except Exception as e:
            return df_in, _log_append(log_local, f"Pipeline FULL Rutina→IN: WARN post_fix skipped: {e}")

    def _dynamic_sort_compat(df_in_local, log_local, order_keys_local, order_desc_local):
        """
        Wrapper para llamar _apply_dynamic_sorting sin romper por firmas distintas.
        Retorna SIEMPRE (df, log).  Si falla, hace skip del sorting (no tumba FULL).
        """
        if "_apply_dynamic_sorting" not in globals():
            return df_in_local, log_local

        fn = globals()["_apply_dynamic_sorting"]
        try:
            sig = inspect.signature(fn)
            p = sig.parameters
            accepts_varkw = any(v.kind == inspect.Parameter.VAR_KEYWORD for v in p.values())

            mapping = {
                # df
                "df": df_in_local,
                "df_in": df_in_local,
                "df_clean": df_in_local,

                # log
                "log": log_local,

                # orden
                "order_keys": (order_keys_local or []),
                "order_desc_flag": bool(order_desc_local),
                "order_desc": bool(order_desc_local),
                "descending": bool(order_desc_local),
                "reverse": bool(order_desc_local),
            }

            kwargs = mapping if accepts_varkw else {k: v for k, v in mapping.items() if k in p}

            # si la firma no acepta ninguno de los nombres df*, pasamos el DF posicional
            has_df_kw = any(k in kwargs for k in ("df", "df_in", "df_clean"))
            if not has_df_kw:
                res = fn(df_in_local, log_local, (order_keys_local or []), bool(order_desc_local))
                return _unpack2(res, df_in_local, log_local)

            res = fn(**kwargs)
            return _unpack2(res, df_in_local, log_local)

        except Exception as e:
            return df_in_local, _log_append(log_local, f"Pipeline FULL Rutina→IN: WARN sorting skipped: {e}")

    try:
        if df_rutina is None and df is not None:
            df_rutina = df

        if df_rutina is None or (hasattr(df_rutina, "empty") and df_rutina.empty):
            return pd.DataFrame(), _log_append(log, "DF de Rutina FULL vacío al iniciar pipeline.")

        log = _log_append(log, f"Pipeline FULL Rutina→IN: inicio (filas={len(df_rutina)})")

        # normalizar order_keys
        if order_keys is None:
            order_keys = []
        elif isinstance(order_keys, str):
            order_keys = [order_keys] if order_keys.strip() else []

        df_src = df_rutina.copy()
        df_in = None
        used_path = "FALLBACK"

        # A) Camino PREVIEW (DIRECTO/DEFAULT)
        if (
            "sinergia_filter_modelorelacion_for_in" in globals()
            and "sinergia_validate_modelorelacion_min" in globals()
            and "sinergia_build_in_direct_default" in globals()
        ):
            df_modelo_all = None
            if "_load_modelorelacion_df" in globals():
                df_modelo_all = _load_modelorelacion_df()
            elif "read_gsheet" in globals() and "CONFIG_SPREADSHEET_ID" in globals():
                df_modelo_all = read_gsheet(CONFIG_SPREADSHEET_ID, "ModeloRelacion")

            if df_modelo_all is not None and hasattr(df_modelo_all, "empty") and (not df_modelo_all.empty):
                df_modelo_in, log = _unpack2(
                    sinergia_filter_modelorelacion_for_in(
                        df_modelo=df_modelo_all,
                        log=log,
                        sistema="SinergIA",
                        archivo_destino="IN_SISTECREDITO",
                    ),
                    pd.DataFrame(),
                    log,
                )

                ok_modelo, log = _unpack2(
                    sinergia_validate_modelorelacion_min(df_modelo_in, log),
                    False,
                    log,
                )

                if bool(ok_modelo) and (df_modelo_in is not None) and (not df_modelo_in.empty):
                    used_path = "DIRECTO_DEFAULT"

                    df_in, log = _unpack2(
                        sinergia_build_in_direct_default(
                            df_src=df_src,
                            df_modelo=df_modelo_in,
                            log=log,
                            use_ints=bool(use_ints),
                            use_upper=bool(use_upper),
                            use_all_phones=bool(use_all_phones),
                        ),
                        pd.DataFrame(),
                        log,
                    )

                    # Reglas canónicas (compat firma)
                    df_in, log = _apply_rules_compat(
                        df_in=df_in,
                        df_src=df_src,
                        log_local=log,
                        use_all=use_all_phones,
                        use_up=use_upper,
                        use_ints_local=bool(use_ints),
                        order_keys_local=order_keys,
                    )

                    # Post-fix (compat)
                    df_in, log = _post_fix_compat(
                        df_in=df_in,
                        df_src=df_src,
                        log_local=log,
                        use_all=use_all_phones,
                    )

        # B) Fallback CFG (si no hubo DIRECTO/DEFAULT)
        if df_in is None or (hasattr(df_in, "empty") and df_in.empty):
            df_norm = df_src.copy()

            if "_normalizar_rutina" in globals():
                df_norm, log = _unpack2(
                    _normalizar_rutina(
                        df=df_src,
                        log=log,
                        use_ints=bool(use_ints),
                        use_all_phones=bool(use_all_phones),
                        use_upper=bool(use_upper),
                    ),
                    df_src,
                    log,
                )
            else:
                df_norm = df_src

            # Construcción IN por cfg si existe
            if "_get_cfg_estructuras" in globals() and "_get_cfg_params" in globals() and "_build_in_from_cfg" in globals():
                df_cfg, log = _unpack2(_get_cfg_estructuras(log), pd.DataFrame(), log)
                df_params, log = _unpack2(_get_cfg_params(log), pd.DataFrame(), log)

                df_in, log = _unpack2(
                    _build_in_from_cfg(
                        df_norm=df_norm,
                        df_cfg=df_cfg,
                        df_params=df_params,
                        log=log,
                        archivo_destino="IN_SISTECREDITO",
                        sistema="SinergIA",
                        fuente="TER_UNISONO",
                    ),
                    pd.DataFrame(),
                    log,
                )
            else:
                df_in = df_norm.copy()

            # Reglas canónicas (compat firma)
            df_in, log = _apply_rules_compat(
                df_in=df_in,
                df_src=df_norm,
                log_local=log,
                use_all=use_all_phones,
                use_up=use_upper,
                use_ints_local=bool(use_ints),
                order_keys_local=order_keys,
            )

            # Post-fix (compat)
            df_in, log = _post_fix_compat(
                df_in=df_in,
                df_src=df_norm,
                log_local=log,
                use_all=use_all_phones,
            )

        # Ordenamiento dinámico final
        if "_apply_dynamic_sorting" in globals() and order_keys:
            df_in, log = _dynamic_sort_compat(
                df_in_local=df_in,
                log_local=log,
                order_keys_local=order_keys,
                order_desc_local=bool(order_desc_flag),
            )

        # Gate (si existe)
        if "sinergia_quality_gate_in" in globals():
            ok_gate, log = _unpack2(sinergia_quality_gate_in(df_in, log), True, log)
            if not bool(ok_gate):
                log = _log_append(log, "GATE · QUALITY_IN FAIL (se retorna DF igual para diagnóstico).")

        log = _log_append(log, f"Pipeline FULL Rutina→IN: fin (filas={len(df_in)}) · path={used_path}")
        return df_in, log

    except Exception as e:
        log = _log_append(log, f"Pipeline FULL Rutina→IN: ERROR {e}")
        return pd.DataFrame(), log

# SinergIA3900 - Aplicación del Ordenamiento Dinámico Operativo (CON MAPEO DE COLUMNAS)

def _apply_dynamic_sorting(
    df_in: pd.DataFrame,
    log: str,
    order_keys: list[str] | str | None,
    order_desc_flag: bool = False,  # TRUE = Descendente (Z-A / Mayor a menor)
) -> tuple[pd.DataFrame, str]:
    """
    Ordena el DataFrame IN_SISTECREDITO, mapeando los nombres amigables de la GUI
    a los nombres técnicos del DataFrame.

    Mapeos pedidos:
      - Nombre         -> Nombre Completo
      - Identificación -> Documento de identidad
      - Fecha nacimiento -> Fecha Nacimiento
      - Fecha expedición -> Fecha Expedición
      - Días mora      -> Días en Mora
      - Ciudad         -> Municipio Almacén
      - Vencidas       -> Número de cuotas vencidas

    Parche:
      - Ordenamiento por FECHAS se hace como datetime (no como string).
      - Ordenamiento por NUMÉRICOS se hace con llave numérica sin alterar el valor original.
      - Se usan columnas temporales de sort y se eliminan al final.
      - Se manda todo NA/NaT al final (na_position='last').
    """
    if df_in is None or df_in.empty:
        return df_in, _log_append(log, "Ordenamiento omitido: DF IN vacío.")

    # log = _log_append(log, f"SONDA003 SORT_INPUT order_keys={order_keys} desc={order_desc_flag}")

    # 0. Diccionario GUI -> columnas reales del IN
    MAPPING_SORT_GUI_TO_DF = {
        "Nombre": "Nombre Completo",
        "Identificación": "Documento de identidad",
        "Fecha nacimiento": "Fecha Nacimiento",
        "Fecha expedición": "Fecha Expedición",
        "Días mora": "Días en Mora",
        "Ciudad": "Municipio Almacén",
        "Vencidas": "Número de cuotas vencidas",
    }

    # 1. Normalizar y mapear claves desde la GUI
    if not order_keys:
        friendly_sort_cols: list[str] = []
    elif isinstance(order_keys, str):
        friendly_sort_cols = [k.strip() for k in order_keys.split(",") if k.strip()]
    else:
        friendly_sort_cols = [str(k).strip() for k in order_keys if str(k).strip()]

    mapped_cols = [MAPPING_SORT_GUI_TO_DF.get(key, key) for key in friendly_sort_cols]
    sort_cols = [col for col in mapped_cols if col in df_in.columns]

    # 2. Definir dirección de ordenamiento
    if not sort_cols:
        log = _log_append(
            log,
            "No hay selección válida de orden en GUI. Aplicando ordenamiento canónico (Mora, Saldo, Vencidas, Documento)...",
        )

        sort_cols = []
        sort_ascending: list[bool] = []

        if "Días en Mora" in df_in.columns:
            sort_cols.append("Días en Mora")
            sort_ascending.append(False)
        if "Saldo Total" in df_in.columns:
            sort_cols.append("Saldo Total")
            sort_ascending.append(False)
        if "Número de cuotas vencidas" in df_in.columns:
            sort_cols.append("Número de cuotas vencidas")
            sort_ascending.append(False)
        if "Documento de identidad" in df_in.columns:
            sort_cols.append("Documento de identidad")
            sort_ascending.append(True)

    else:
        log = _log_append(log, f"Aplicando ordenamiento dinámico: Por {', '.join(sort_cols)}...")
        is_ascending = not order_desc_flag
        sort_ascending = [is_ascending] * len(sort_cols)

    if not sort_cols:
        log = _log_append(
            log,
            "Advertencia: Ordenamiento omitido. No se encontraron columnas válidas para ordenar.",
        )
        return df_in, log

    # 3. Sort robusto (NUM y FECHA con llaves temporales)
    try:
        df_work = df_in.copy()

        NUMERIC_SORT_COLS = {
            "Días en Mora",
            "Saldo Total",
            "Número de cuotas vencidas",
            "IN_PRIORIDAD",
            "Documento de identidad",
            "Valor",
            "Valor Mora",
            "Reportado a Centrales",
        }

        DATE_SORT_COLS = {
            "Fecha Nacimiento",
            "Fecha Expedición",
            "Fecha de vencimiento",
            "Fecha Creación del crédito",
            "Fecha creación del crédito",
        }

        def _coerce_date_series(sr: pd.Series) -> pd.Series:
            """
            Convierte a datetime de forma robusta:
              - Soporta strings dd/mm/yyyy y variantes (dayfirst=True)
              - Soporta numéricos tipo serial Excel (rango típico)
              - Neutraliza outliers (años muy viejos/futuros) y placeholders comunes
            """
            if sr is None:
                return pd.to_datetime(pd.Series([], dtype="object"), errors="coerce")

            # Caso 1: si ya es datetime
            try:
                if pd.api.types.is_datetime64_any_dtype(sr):
                    sdt = sr
                else:
                    # Detectar si es mayormente numérico
                    s_num = pd.to_numeric(sr, errors="coerce")
                    non_na = s_num.dropna()
                    ratio_num = (len(non_na) / max(len(sr), 1))

                    if ratio_num >= 0.80:
                        # Heurística: serial Excel típico entre 20000 y 60000 (aprox 1954-2064)
                        if not non_na.empty and non_na.between(20000, 60000).mean() >= 0.80:
                            sdt = pd.to_datetime(s_num, unit="D", origin="1899-12-30", errors="coerce")
                        else:
                            # Intento yyyymmdd cuando parezca 8 dígitos
                            s_as_int = s_num.dropna().astype("int64")
                            if not s_as_int.empty and s_as_int.between(19000101, 20991231).mean() >= 0.80:
                                sdt = pd.to_datetime(s_as_int.astype(str), format="%Y%m%d", errors="coerce")
                            else:
                                # Fallback: parse genérico
                                sdt = pd.to_datetime(sr.astype(str).str.strip(), errors="coerce", dayfirst=True)
                    else:
                        sdt = pd.to_datetime(sr.astype(str).str.strip(), errors="coerce", dayfirst=True)
            except Exception:
                sdt = pd.to_datetime(sr.astype(str).str.strip(), errors="coerce", dayfirst=True)

            # Regla de calidad: outliers y placeholders
            # - 1900-01-01 suele ser placeholder en Excel/datos de negocio
            # - años muy antiguos suelen ser parse erróneo (ej 1771)
            try:
                bad_mask = (sdt.dt.year < 1900) | (sdt.dt.year > 2100) | (sdt.dt.date == pd.Timestamp("1900-01-01").date())
                sdt = sdt.mask(bad_mask)
            except Exception:
                pass

            return sdt

        sort_by_cols: list[str] = []
        tmp_cols: list[str] = []

        for i, col in enumerate(sort_cols):
            if col in NUMERIC_SORT_COLS:
                sk = f"__SK_NUM_{i:02d}"
                df_work[sk] = pd.to_numeric(df_work[col], errors="coerce")
                sort_by_cols.append(sk)
                tmp_cols.append(sk)

            elif col in DATE_SORT_COLS:
                sk = f"__SK_DT_{i:02d}"
                df_work[sk] = _coerce_date_series(df_work[col])
                sort_by_cols.append(sk)
                tmp_cols.append(sk)

            else:
                sort_by_cols.append(col)

        df_out = df_work.sort_values(
            by=sort_by_cols,
            ascending=sort_ascending,
            ignore_index=True,
            na_position="last",
        )

        if tmp_cols:
            df_out = df_out.drop(columns=tmp_cols, errors="ignore")

        log = _log_append(
            log,
            f"Ordenamiento de priorización aplicado exitosamente: Por {', '.join(sort_cols)}.",
        )
        return df_out, log

    except Exception as e:
        log = _log_append(
            log,
            f"ERROR CRÍTICO al aplicar ordenamiento: {e}. Se devuelve DF sin ordenar.",
        )
        return df_in, log

# SinergIA4000 - NORMALIZACIÓN NUMÉRICA A ENTEROS (GUIADA POR ESTRUCTURAS)
# ============================

import re
import numpy as np
import pandas as pd

def _sinergia_force_numeric_integers(
    df_in: pd.DataFrame,
    estructuras_df: pd.DataFrame | None,
    archivo_logico: str,
    log: str,
    enabled: bool,
    min_int_digits: int = 5,   # regla: >4 dígitos en parte entera
) -> tuple[pd.DataFrame, str]:
    if not enabled:
        return df_in, log

    if df_in is None or df_in.empty:
        return df_in, _log_append(log, "Normalización enteros omitida: DF vacío.")

    # 1) Determinar columnas numéricas desde Estructuras (por ArchivoLogico y TipoDato=Numero)
    num_cols: list[str] = []
    if estructuras_df is not None and not estructuras_df.empty:
        cols_norm = {str(c).strip().lower(): c for c in estructuras_df.columns}
        c_arch = cols_norm.get("archivologico") or cols_norm.get("archivo_logico") or cols_norm.get("archivo")
        c_name = cols_norm.get("nombrecolumna") or cols_norm.get("nombre_columna") or cols_norm.get("columna") or cols_norm.get("nombre")
        c_tipo = cols_norm.get("tipodato") or cols_norm.get("tipo_dato") or cols_norm.get("tipo")

        if c_arch and c_name and c_tipo:
            mask = (
                estructuras_df[c_arch].astype(str).str.strip().eq(str(archivo_logico).strip())
                & estructuras_df[c_tipo].astype(str).str.strip().str.lower().eq("numero")
            )
            num_cols = [
                c for c in estructuras_df.loc[mask, c_name].astype(str).str.strip().tolist()
                if c
            ]

    # Fallback si no hay Estructuras: sólo columnas ya numéricas
    if not num_cols:
        num_cols = df_in.select_dtypes(include=["number"]).columns.tolist()

    # 2) Parser numérico robusto (maneja miles/decimales con coma/punto)
    def _parse_num(x):
        if x is None:
            return np.nan
        if isinstance(x, (int, np.integer)):
            return float(x)
        if isinstance(x, (float, np.floating)):
            return float(x)

        s = str(x).strip()
        if s == "" or s.lower() in {"nan", "none", "null"}:
            return np.nan

        s = re.sub(r"\s+", "", s)
        s = s.replace("$", "").replace("%", "")

        # Ambos separadores: decide decimal por el último separador
        if "," in s and "." in s:
            if s.rfind(",") > s.rfind("."):
                # 1.234.567,89 -> 1234567.89
                s = s.replace(".", "")
                s = s.replace(",", ".")
            else:
                # 1,234,567.89 -> 1234567.89
                s = s.replace(",", "")

        # Sólo coma: decimal si tail 1-2 dígitos, si no miles
        elif "," in s:
            tail = s.split(",")[-1]
            if len(tail) in (1, 2):
                s = s.replace(".", "")
                s = s.replace(",", ".")
            else:
                s = s.replace(",", "")

        # Limpiar caracteres no numéricos (deja - y .)
        s = re.sub(r"[^0-9\.\-]", "", s)

        try:
            return float(s)
        except Exception:
            return np.nan

    forced_cols: list[str] = []
    cast_int_cols: list[str] = []

    for col in num_cols:
        if col not in df_in.columns:
            continue

        # Convertimos con parser robusto (sirve si venía como texto)
        s_num = df_in[col].map(_parse_num)
        non_na = s_num.dropna().abs()

        if non_na.empty:
            continue

        # Máximo de dígitos en parte entera (abs)
        max_digits = int(non_na.map(lambda v: len(str(int(abs(v))))).max())

        # ¿Tiene fracción?
        has_frac = bool(((non_na % 1) != 0).any())

        # Regla: forzar a entero (redondeo) sólo si parte entera >= min_int_digits
        if max_digits >= int(min_int_digits):
            s_int = s_num.round(0)
            df_in[col] = s_int.astype("Int64")
            forced_cols.append(col)

        # Si NO aplica la regla, pero la columna ya es entera pura, castear para quitar .0
        else:
            if not has_frac:
                df_in[col] = s_num.astype("Int64")
                cast_int_cols.append(col)

    if forced_cols or cast_int_cols:
        parts = []
        if forced_cols:
            parts.append(f"forzadas={len(forced_cols)}")
        if cast_int_cols:
            parts.append(f"enteras_puras={len(cast_int_cols)}")

        log = _log_append(
            log,
            "Normalización enteros aplicada: " + ", ".join(parts)
            + f". Archivo={archivo_logico}. min_int_digits={min_int_digits}.",
        )
    else:
        log = _log_append(
            log,
            f"Normalización enteros: sin cambios. Archivo={archivo_logico}. min_int_digits={min_int_digits}.",
        )

    return df_in, log

# SinergIA4100 - Export Gestion FULL con progreso y log
import re
import pandas as pd
from datetime import datetime, timedelta
import gradio as gr

def _export_gestion_full(
    formato: str,
    dd_archivo_rutina,
    file_rutina_local,
    chk_valores_enteros_local,
    chk_todos_cel_local,
    chk_mayus_local,
    chk_order_local,
    chk_order_desc_local,
    log_text,
    progress: gr.Progress = gr.Progress(track_tqdm=True),
):



    # PATCH_CTX001 · crear ctx SIEMPRE antes de cualquier uso (set_manifest / add_event / finalize)
    log_local = log_text or ""
    try:
        ctx = sinergia_new_run_context(
            action="PR_08_export_gestion_full",
            meta={
                "ui_action": "btn_export_gestion",
                "formato": str(formato),
                "rutina_drive": str(dd_archivo_rutina or ""),
                "rutina_local": sinergia_guess_file_name(file_rutina_local),
            },
        )
        ctx.add_event("PR_08_START", message="Inicio exportación Gestion FULL.")
    except Exception as e:
        log_local = _log_append(log_local, f"PR_08_INIT_FAIL · {type(e).__name__}: {e}")
        return None, "RUNCTX_FAIL", log_local



    # SONDA002 · export_gestion_full entry (sin depender de df_in no definido)
    df_probe = (
        locals().get("df_in")
        or locals().get("df_in_base")
        or locals().get("df_in_full")
        or globals().get("DF_IN_CACHE", None)
    )
    log_local = _log_append(log_local, f"SONDA002 · export_gestion_full entry · in_shape={getattr(df_probe,'shape',None)}")
    #FINAL SONDA002



    try:
        progress(0.05, desc="Cargando rutina FULL...")

        df_rut_full, log_local = _load_rutina_full_for_export(
            dd_archivo_rutina=dd_archivo_rutina,
            file_rutina_local=file_rutina_local,
            log=log_local,
        )

        ctx.set_manifest("inputs.rutina.rows", int(len(df_rut_full)) if hasattr(df_rut_full, "__len__") else 0)

        if df_rut_full is None or df_rut_full.empty:
            log_local = _log_append(log_local, "DF de Rutina FULL vacío o no encontrado. No se genera archivo Export_AWS.")
            ctx.add_event("PR_08_FAIL", level="ERROR", message="Rutina FULL vacía.")
            ctx.finalize("FAIL")
            return None, ctx.run_id, log_local

        # Compat mínima para que la normalización FULL (via Estructuras) no deje campos críticos en blanco
        created = []
        # Nombre completo
        if "NombreCompleto" not in df_rut_full.columns and "Upper" in df_rut_full.columns:
            df_rut_full["NombreCompleto"] = df_rut_full["Upper"]
            created.append("NombreCompleto<=Upper")
        if "Upper" not in df_rut_full.columns and "NombreCompleto" in df_rut_full.columns:
            df_rut_full["Upper"] = df_rut_full["NombreCompleto"].fillna("").astype(str).str.upper()
            created.append("Upper<=NombreCompleto.upper")

        # Fecha vencimiento
        if "FechaVencimiento" not in df_rut_full.columns:
            if "FechaMasVencida" in df_rut_full.columns:
                df_rut_full["FechaVencimiento"] = df_rut_full["FechaMasVencida"]
                created.append("FechaVencimiento<=FechaMasVencida")

        # Almacén y datos almacén (cuando vienen con nombres alternos)
        if "Almacen" not in df_rut_full.columns and "ConsecutivoAlmacen" in df_rut_full.columns:
            df_rut_full["Almacen"] = df_rut_full["ConsecutivoAlmacen"]
            created.append("Almacen<=ConsecutivoAlmacen")
        if "DireccionAlmacen" not in df_rut_full.columns and "Direccion" in df_rut_full.columns:
            df_rut_full["DireccionAlmacen"] = df_rut_full["Direccion"]
            created.append("DireccionAlmacen<=Direccion")
        if "TelefonoAlmacen" not in df_rut_full.columns and "PrimerTelefono" in df_rut_full.columns:
            df_rut_full["TelefonoAlmacen"] = df_rut_full["PrimerTelefono"]
            created.append("TelefonoAlmacen<=PrimerTelefono")
        if "MunicipioAlmacen" not in df_rut_full.columns:
            if "Municipio" in df_rut_full.columns:
                df_rut_full["MunicipioAlmacen"] = df_rut_full["Municipio"]
                created.append("MunicipioAlmacen<=Municipio")

        # Status / Servicio (si vienen como EstadoCentrales o ReglaCarteraCodigo)
        if "Status" not in df_rut_full.columns and "EstadoCentrales" in df_rut_full.columns:
            df_rut_full["Status"] = df_rut_full["EstadoCentrales"]
            created.append("Status<=EstadoCentrales")
        if "Servicio" not in df_rut_full.columns and "ReglaCarteraCodigo" in df_rut_full.columns:
            df_rut_full["Servicio"] = df_rut_full["ReglaCarteraCodigo"]
            created.append("Servicio<=ReglaCarteraCodigo")

        # SONDA mínima y útil (1 línea) para dejar de “adivinar”
        keys_check = [
            "Upper","NombreCompleto","FechaMasVencida","FechaVencimiento",
            "ConsecutivoAlmacen","Almacen","Direccion","DireccionAlmacen",
            "PrimerTelefono","TelefonoAlmacen","Municipio","MunicipioAlmacen",
            "EstadoCentrales","Status","ReglaCarteraCodigo","Servicio",
            "CreditNumber","Crédito","Credito"
        ]
        present = [k for k in keys_check if k in df_rut_full.columns]
        log_local = _log_append(log_local, f"SONDA_RUT_COMPAT created={created} present={present}")

        progress(0.35, desc="Ejecutando pipeline Rutina→IN (FULL)...")

        df_in_full, log_local = run_pipeline_rutina_to_in_full(
            df_rutina=df_rut_full,
            log=log_local,
            use_ints=bool(chk_valores_enteros_local),
            use_all_phones=bool(chk_todos_cel_local),
            use_upper=bool(chk_mayus_local),
            order_keys=chk_order_local or [],
            order_desc_flag=bool(chk_order_desc_local),
        )

        # SONDA F1 (1 línea) sobre el resultado IN antes del layout
        __cols_out = ["Nombre Completo","Fecha de vencimiento","Almacén","Municipio Almacén","Dirección Almacén","Teléfono Almacén","Crédito","Status"]
        __fill = lambda df, c: float((df[c].fillna("").astype(str).str.strip() != "").mean()) if (df is not None and c in df.columns) else -1.0
        __uuid = lambda df, c: float(df[c].fillna("").astype(str).str.contains(r"^[0-9A-Fa-f]{8}-", regex=True, na=False).mean()) if (df is not None and c in df.columns) else -1.0
        miss_out = [c for c in __cols_out if df_in_full is None or c not in df_in_full.columns]
        log_local = _log_append(
            log_local,
            "SONDA_F1 miss_out=" + str(miss_out) +
            " | " + ",".join([f"{c}={__fill(df_in_full, c):.2f}" for c in __cols_out]) +
            f" | uuid(Crédito)={__uuid(df_in_full,'Crédito'):.2f} uuid(Status)={__uuid(df_in_full,'Status'):.2f}"
        )

        ctx.set_manifest("outputs.in.rows", int(len(df_in_full)) if hasattr(df_in_full, "__len__") else 0)

        if df_in_full is None or df_in_full.empty:
            log_local = _log_append(log_local, "Resultado IN_SISTECREDITO vacío. No se genera archivo Gestion.")
            ctx.add_event("PR_08_FAIL", level="ERROR", message="IN_FULL vacío.")
            ctx.finalize("FAIL")
            return None, ctx.run_id, log_local

        progress(0.75, desc="Construyendo DF a exportar...")

        df_to_export = df_in_full

        if "_to_out_gestion_layout" in globals():
            try:
                df_to_export, log_local = _to_out_gestion_layout(df_in_full, log_local)
            except Exception as e:
                log_local = _log_append(log_local, f"OUT_GESTION layout falló, se exporta IN_FULL. Error: {e}")
                df_to_export = df_in_full

        if df_to_export is None or df_to_export.empty:
            log_local = _log_append(log_local, "DF_TO_EXPORT vacío. No se genera archivo.")
            ctx.add_event("PR_08_FAIL", level="ERROR", message="DF_TO_EXPORT vacío.")
            ctx.finalize("FAIL")
            return None, ctx.run_id, log_local

        ok_gate, log_local = sinergia_export_gate_gestion(df_to_export, log_local, ctx=ctx)
        if not ok_gate:
            ctx.add_event("PR_08_FAIL", level="ERROR", message="ExportGate Gestion falló.")
            ctx.finalize("FAIL")
            return None, ctx.run_id, log_local

        progress(0.85, desc=f"Generando archivo ({formato})...")

        ruta = _generar_archivo_gestion(df_to_export, formato)

        ctx.set_manifest("outputs.file.path", str(ruta or ""))
        ctx.set_manifest("outputs.file.formato", str(formato))
        ctx.set_manifest("outputs.rows", int(len(df_to_export)) if hasattr(df_to_export, "__len__") else 0)

        if not ruta:
            log_local = _log_append(log_local, "No se pudo generar el archivo Gestion (ruta vacía).")
            ctx.add_event("PR_08_FAIL", level="ERROR", message="Ruta vacía al generar archivo.")
            ctx.finalize("FAIL")
            return None, ctx.run_id, log_local

        progress(1.0, desc="Listo")

        log_local = _log_append(log_local, f"Archivo Gestion OK ({formato}). Filas_export={len(df_to_export)}.")
        ctx.add_event("PR_08_OK", message="Exportación Gestion OK.")
        ctx.finalize("OK")
        return ruta, ctx.run_id, log_local

    except Exception as e:
        log_local = _log_append(log_local, f"Error inesperado en exportación Gestion FULL: {e}")
        ctx.add_event("PR_08_FAIL", level="ERROR", message="Excepción inesperada.", data={"error": str(e)})
        ctx.finalize("FAIL")
        return None, ctx.run_id, log_local




# SONDA003 · hard-guard export callback: nunca dejar UI en "Error" sin traza mínima
_export_gestion_full__orig = _export_gestion_full

def _export_gestion_full(*args, **kwargs):
    try:
        return _export_gestion_full__orig(*args, **kwargs)
    except Exception as e:
        import traceback

        # log_text posicional (según firma actual) o por kwargs
        log_text = args[8] if len(args) >= 9 else kwargs.get("log_text", "")
        log_local = (log_text or "")

        tb = traceback.extract_tb(e.__traceback__)
        last = tb[-1] if tb else None
        if last:
            code = (last.line or "").strip()
            if len(code) > 140:
                code = code[:140] + "…"
            log_local = _log_append(log_local, f"SONDA004 · TRACE · {last.name}:{last.lineno} · {code}")

        log_local = _log_append(log_local, f"SONDA003 · EXPORT_FAIL · {type(e).__name__}: {e}")
        return None, "EXPORT_FAIL", log_local




def _first_nonempty_series(df, candidates:str):
    """
    candidates: 'ColA;ColB;ColC' (como en ModeloRelacion/ColumnaOrigen)
    retorna la primera serie existente y no-toda-vacía; None si ninguna.
    """
    for raw in [c.strip() for c in str(candidates).split(';') if str(c).strip()]:
        if raw in df.columns:
            s = df[raw]
            if not (s.isna().all() or (s.astype(str).str.strip()=='').all()):
                return s
    return None

