def _coerce_date_series(s: pd.Series) -> pd.Series:
    """
    Convierte fechas mixtas (str, excel serial, NaN) → YYYY-MM-DD (string).
    - Excel serial: origin=1899-12-30
    - str: intenta dayfirst
    """
    s2 = s.copy()
    # serial excel (numérico "grande"):  10^3–10^5 aprox.
    mask_num = pd.to_numeric(s2, errors='coerce').notna()
    s2_num = pd.to_numeric(s2[mask_num], errors='coerce')
    # Si parecen seriales (> 59 evita bug del 29/02/1900)
    serial_mask = (s2_num > 59) & (s2_num < 60000)
    s2.loc[mask_num & serial_mask] = (
        pd.to_datetime('1899-12-30') + pd.to_timedelta(s2_num[serial_mask].astype(int), unit='D')
    ).dt.strftime('%Y-%m-%d').values

    # El resto: parse str
    mask_rest = ~ (mask_num & serial_mask)
    parsed = pd.to_datetime(s2[mask_rest], errors='coerce', dayfirst=True)
    s2.loc[mask_rest] = parsed.dt.strftime('%Y-%m-%d').where(parsed.notna(), None)
    return s2

def _digits_only(x: str) -> str:
    return re.sub(r'\D+', '', str(x) if x is not None else '')

def _normalize_phones_row(values, must_start3=True, minlen=10, maxlen=11):
    """Retorna (mobiles[], landlines[]) limpios, únicos, con 57->10 dígitos normal."""
    seen = set()
    mobiles, lands = [], []
    for v in values:
        d = _digits_only(v)
        if not d:
            continue
        # normaliza 57xxxxxxxxxx → xxxxxxxxxx
        if len(d) == 12 and d.startswith('57'):
            d = d[2:]
        if len(d) == 11 and d.startswith('0'):
            d = d[1:]
        if len(d) < minlen or len(d) > maxlen:
            continue
        if d in seen:
            continue
        seen.add(d)
        if d[0] == '3' and (not must_start3 or d[0] == '3'):
            mobiles.append(d)
        else:
            lands.append(d)
    return mobiles, lands

# SinergIA4200 - Parche de compatibilidad y orquestación FULL → GESTION
import pandas as pd

# --- 0) Aliases/mapeos de nombres heredados vs. actuales ---------------------
