# SinergIA4300
def _audit_gestion_out(df_out: pd.DataFrame, log=""):
    checks = []

    # Nombre completo vacío
    if "Nombre Completo" in df_out.columns:
        s = df_out["Nombre Completo"].fillna("").astype(str).str.strip()
        checks.append(("Nombre Completo vacío", float((s == "").mean())))

    # Vencimiento inválido (robusto: DD/MM/YYYY, YYYY-MM-DD, YYYYMMDD, serial Excel)
    if "Fecha de vencimiento" in df_out.columns:
        raw = df_out["Fecha de vencimiento"]
        s = raw.fillna("").astype(str).str.strip()
        s = s.replace({"NaT": "", "nan": "", "None": ""})

        __sample = s[s != ""].head(3).tolist()
        __p = {
            "slash": float(s.str.contains(r"/", na=False).mean()),
            "dash": float(s.str.contains(r"-", na=False).mean()),
            "sci": float(s.str.contains(r"[eE]\+?\d+", na=False).mean()),
            "comma": float(s.str.contains(r",", na=False).mean()),
        }
        log = _log_append(log, f"SONDA_VENC sample={__sample} pat={__p}")


        dt = pd.Series(pd.NaT, index=df_out.index)

        mask_8 = s.str.fullmatch(r"\d{8}", na=False)  # YYYYMMDD
        if bool(mask_8.any()):
            dt.loc[mask_8] = pd.to_datetime(s.loc[mask_8], errors="coerce", format="%Y%m%d")

        mask_serial = s.str.fullmatch(r"\d{5}(\.\d+)?", na=False)  # Excel serial ~ 45000
        if bool(mask_serial.any()):
            num = pd.to_numeric(s.loc[mask_serial], errors="coerce")
            dt.loc[mask_serial] = pd.to_datetime(num, errors="coerce", unit="D", origin="1899-12-30")

        mask_rest = ~(mask_8 | mask_serial)
        if bool(mask_rest.any()):
            dt.loc[mask_rest] = pd.to_datetime(s.loc[mask_rest], errors="coerce", dayfirst=True)

        checks.append(("Vencimiento inválido", float(dt.isna().mean())))

    # Teléfonos (al menos uno válido)
    tel_cols = [c for c in ["Telefono 1", "Telefono 2", "Telefono 3", "Telefono 4"] if c in df_out.columns]
    if tel_cols:
        def ok_tel(x):
            d = _digits_only(x)
            return (len(d) in (10, 11)) and (d.startswith("3") or d.startswith("57"))

        bad = 1.0 - pd.concat([df_out[c].map(ok_tel) for c in tel_cols], axis=1).any(axis=1).mean()
        checks.append(("Filas sin ningún teléfono válido", float(bad)))

    for name, rate in checks:
        log = _log_append(log, f"AUDIT · {name}: {rate:.1%}")
    return log

# SinergIA4400 Gates mínimos (QualityGate IN + ExportGate Gestion)

import pandas as pd

def sinergia_quality_gate_in(df_in: pd.DataFrame, log: str, ctx: "SinergIA_RunContext|None" = None) -> tuple[bool, str]:
    if df_in is None or df_in.empty:
        if ctx: ctx.set_manifest("gates.quality_in.status", "FAIL")
        return False, _log_append(log, "GATE · QUALITY_IN FAIL: IN vacío.")

    must_cols = ["Documento de identidad", "Telefono 1"]
    missing = [c for c in must_cols if c not in df_in.columns]
    if missing:
        if ctx:
            ctx.set_manifest("gates.quality_in.status", "WARN")
            ctx.set_manifest("gates.quality_in.missing_cols", missing)
        log = _log_append(log, f"GATE · QUALITY_IN WARN: faltan columnas {missing}.")
        return True, log

    if ctx:
        ctx.set_manifest("gates.quality_in.status", "OK")
    log = _log_append(log, "GATE · QUALITY_IN OK.")
    return True, log


def sinergia_export_gate_gestion(df_out: pd.DataFrame, log: str, ctx: "SinergIA_RunContext|None" = None) -> tuple[bool, str]:
    if df_out is None or df_out.empty:
        if ctx: ctx.set_manifest("gates.export_gestion.status", "FAIL")
        return False, _log_append(log, "GATE · EXPORT_AWS FAIL: DF_OUT vacío.")

    # Normalizador (sin tildes)  -  no depende del builder
    def _gate_norm(s: str) -> str:
        try:
            fn = globals().get("_gestion__norm", None)
            if callable(fn):
                return fn(s)
        except Exception:
            pass
        import unicodedata
        s = "" if s is None else str(s)
        s = unicodedata.normalize("NFKD", s)
        s = "".join(ch for ch in s if not unicodedata.combining(ch))
        return s.strip().lower()

    # Expected canónico: ModeloRelacion (si está disponible).  Fallback: GESTION_OUT_COLUMNS.
    expected = None
    try:
        cache = globals().get("_GESTION_SPEC_CACHE", None)
        if isinstance(cache, dict):
            expected = cache.get("cols", None)
    except Exception:
        expected = None

    if not expected:
        fn = globals().get("_gestion_out_spec_from_modelorelacion", None)
        if callable(fn):
            try:
                expected, _ = fn()
            except Exception:
                expected = None

    if not expected:
        expected = globals().get("GESTION_OUT_COLUMNS", None)

    # Validación robusta por normalización (Almacen == Almacén, etc.)
    if isinstance(expected, list) and expected:
        actual_norm = {_gate_norm(c) for c in df_out.columns}
        missing = [c for c in expected if _gate_norm(c) not in actual_norm]
        if missing:
            if ctx:
                ctx.set_manifest("gates.export_gestion.status", "FAIL")
                ctx.set_manifest("gates.export_gestion.missing_cols", missing)
            return False, _log_append(log, f"GATE · EXPORT_AWS FAIL: faltan columnas {missing}.")

        if ctx:
            ctx.set_manifest("gates.export_gestion.expected_cols", len(expected))
            ctx.set_manifest("gates.export_gestion.actual_cols", len(df_out.columns))
    else:
        if ctx:
            ctx.set_manifest("gates.export_gestion.expected_cols", 29)
            ctx.set_manifest("gates.export_gestion.actual_cols", len(df_out.columns))
        if len(df_out.columns) < 10:
            if ctx: ctx.set_manifest("gates.export_gestion.status", "FAIL")
            return False, _log_append(log, f"GATE · EXPORT_GESTION FAIL: muy pocas columnas ({len(df_out.columns)}).")

    # Auditoría de contenido (usa tu función existente)
    try:
        log = _audit_gestion_out(df_out, log=log)
    except Exception as e:
        log = _log_append(log, f"AUDIT · _audit_gestion_out falló: {e}")

    if ctx:
        ctx.set_manifest("gates.export_gestion.status", "OK")
    log = _log_append(log, "GATE · EXPORT_GESTION OK.")
    return True, log

# SinergIA4410 - PIPE_GATES_WIRING: QUALITY_IN + EXPORT_AWS (manifest + audit)
# Inserción: debajo de SinergIA4400 y arriba de SinergIA4500.

def sinergia_pr04_quality_and_export_gates(
    df_in,
    df_out_gestion=None,
    *,
    log: str = "",
    rc=None,
) -> tuple[dict, str]:
    """
    Ejecuta gates oficiales:
    - QUALITY_IN sobre df_in (SinergIA4400)
    - EXPORT_AWS sobre df_out_gestion (SinergIA4400) si se provee
    Escribe a manifest y audit_events si rc existe.  No imprime DF.
    """
    gates = {}

    # Guardrails
    need = ["sinergia_quality_gate_in", "sinergia_export_gate_gestion"]
    miss = [n for n in need if n not in globals() or not callable(globals().get(n))]
    if miss:
        raise RuntimeError(f"ABORT · faltan definiciones: {miss}")

    ok_in, _ = sinergia_quality_gate_in(df_in, log="")
    gates["PR_QUALITY_IN"] = {"ok": bool(ok_in)}

    if rc:
        try:
            rc.set_manifest("gates.PR_QUALITY_IN", gates["PR_QUALITY_IN"])
            rc.add_event(
                "PR_QUALITY_IN_OK" if ok_in else "PR_QUALITY_IN_FAIL",
                level="INFO" if ok_in else "ERROR",
                message="QualityGate IN OK." if ok_in else "QualityGate IN FAIL.",
                data={"rows": int(len(df_in)) if hasattr(df_in, "__len__") else None},
                etapa="PR_04",
            )
        except Exception:
            pass

    # ExportGate Gestion solo si hay df_out_gestion
    if df_out_gestion is not None:
        ok_gestion, _ = sinergia_export_gate_gestion(df_out_gestion, log="")
        gates["PR_EXPORT_GESTION"] = {"ok": bool(ok_gestion)}
        if rc:
            try:
                rc.set_manifest("gates.PR_EXPORT_GESTION", gates["PR_EXPORT_GESTION"])
                rc.add_event(
                    "PR_EXPORT_GESTION_OK" if ok_gestion else "PR_EXPORT_GESTION_FAIL",
                    level="INFO" if ok_gestion else "ERROR",
                    message="ExportGate Gestion OK." if ok_gestion else "ExportGate Gestion FAIL.",
                    data={"rows": int(len(df_out_gestion)) if hasattr(df_out_gestion, "__len__") else None},
                    etapa="PR_04",
                )
            except Exception:
                pass

    return gates, log

# SinergIA4500 - Bootstrap global + guard de idempotencia para Launcher/Callbacks

SINERGIA_APP = None
SINERGIA_COMPONENTS = None
SINERGIA_CALLBACKS_REGISTERED = False


def sinergia_assert_prereqs() -> None:
    missing = []
    for fn in ["sinergia_gui_shell", "register_callbacks"]:
        if fn not in globals() or not callable(globals().get(fn)):
            missing.append(fn)
    if missing:
        raise RuntimeError(
            f"Faltan prerequisitos: {missing}.  Ejecuta primero SinergIA0480 (GUI) y SinergIA0360 (Callbacks)."
        )


def _sinergia_validate_components_for_callbacks(components: dict) -> None:
    """
    Valida que existan los componentes que los callbacks de Listas suelen requerir.
    Si aún no has aplicado el parche GUI/Callbacks, esto evita NameError dentro de register_callbacks.
    """
    if not isinstance(components, dict):
        raise RuntimeError("GUI devolvió 'components' inválido.  Se esperaba dict.")

    # Mínimos existentes históricamente
    base_required = ["btn_listas", "df_listas_show"]

    # Nuevos (para fuentes + previews por canal).  Si aún no están, fallamos con mensaje claro.
    listas_required = [
        "df_listas_sources",
        "df_prev_wa", "out_lista_wa",
        "df_prev_wise", "out_lista_wise",
        "df_prev_sms", "out_lista_sms",
        "df_prev_voz", "out_lista_voz",
    ]

    missing = [k for k in (base_required + listas_required) if k not in components]
    if missing:
        raise RuntimeError(
            "GUI/Callbacks desalineados.  Faltan componentes requeridos por 'Derivar listas': "
            f"{missing}.  Agrega estos componentes en sinergia_gui_shell() y referéncialos en "
            "register_callbacks(components) vía components['...']."
        )


def sinergia_build_app(force_rebuild: bool = False):
    global SINERGIA_APP, SINERGIA_COMPONENTS, SINERGIA_CALLBACKS_REGISTERED

    import gradio as gr

    sinergia_assert_prereqs()

    # Reusar app existente si aplica
    if (SINERGIA_APP is not None) and (not force_rebuild):
        # Si por algún motivo no quedaron callbacks registrados, los registramos (idempotente por flag)
        if (not SINERGIA_CALLBACKS_REGISTERED) and isinstance(SINERGIA_COMPONENTS, dict):
            try:
                _sinergia_validate_components_for_callbacks(SINERGIA_COMPONENTS)
                with SINERGIA_APP:
                    register_callbacks(SINERGIA_COMPONENTS)
                SINERGIA_CALLBACKS_REGISTERED = True
            except Exception as e:
                raise RuntimeError(f"Reuso APP falló al registrar callbacks.  {e}")
        return SINERGIA_APP, SINERGIA_COMPONENTS

    # Reset limpio por rebuild
    try:
        gr.close_all()
    except Exception:
        pass

    app, components = sinergia_gui_shell()

    # Validación temprana (evita NameError dentro de register_callbacks)
    _sinergia_validate_components_for_callbacks(components)

    # Registrar callbacks SOLO una vez por build
    try:
        with app:
            register_callbacks(components)
    except NameError as e:
        # Error típico: variables no definidas en register_callbacks por no usar components['...']
        raise RuntimeError(
            "register_callbacks falló por NameError.  Causa probable: se referencian variables "
            "como 'df_listas_sources' sin haberlas definido desde components['df_listas_sources'].  "
            f"Detalle: {e}"
        )
    except KeyError as e:
        raise RuntimeError(
            "register_callbacks falló por KeyError.  Causa probable: falta una key en components.  "
            f"Detalle: {e}"
        )
    except Exception as e:
        raise RuntimeError(f"register_callbacks falló.  {e}")

    SINERGIA_APP = app
    SINERGIA_COMPONENTS = components
    SINERGIA_CALLBACKS_REGISTERED = True

    return app, components

# SinergIA4700 - Diagnóstico seguro de claves de components
comps = None
if "SINERGIA_COMPONENTS" in globals() and SINERGIA_COMPONENTS:
    comps = SINERGIA_COMPONENTS
elif "components" in globals():
    comps = components

if not comps:
    print("components no está listo.  Ejecuta SinergIA0940 (build) y SinergIA0980 (launch).")
else:
    print("===== LISTA DE CLAVES EN components =====")
    for k in comps.keys():
        print(k)

# SinergIA4800 - Helpers ModeloRelacion (tokens, alias, fechas, teléfonos)
import re, unicodedata
import pandas as pd

def _normkey(s: str) -> str:
    s = str(s or "")
    s = unicodedata.normalize("NFKD", s).encode("ascii", "ignore").decode("ascii")
    return re.sub(r"[^A-Za-z0-9]", "", s).lower()

def _build_aliases_for_df(df: pd.DataFrame) -> dict:
    """
    Permite que 'Nombre Completo' == 'NombreCompleto' == 'NOMBRE_COMPLETO', etc.
    Mapea clave normalizada -> nombre real de columna.
    """
    aliases = {}
    for c in df.columns:
        aliases[_normkey(c)] = c
    return aliases

def _resolve_col(df: pd.DataFrame, token: str, aliases: dict) -> str | None:
    # 1) literal exacto
    if token in df.columns:
        return token
    # 2) alias normalizado
    k = _normkey(token)
    return aliases.get(k)

def _parse_params(spec: str) -> dict:
    d = {}
    for tok in str(spec or "").split(";"):
        if "=" in tok:
            k, v = tok.split("=", 1)
            d[k.strip()] = v.strip()
    return d

def _is_mobile(num: str) -> bool:
    return len(num) in (10, 11) and str(num).startswith("3")

def _coerce_fecha(series: pd.Series) -> pd.Series:
    """
    Maneja strings y ordinales de Excel (1899-12-30).
    Devuelve YYYY-MM-DD (string) o '' si NaT.
    """
    s = series.copy()

    # Intento 1: to_datetime directo
    dt1 = pd.to_datetime(s, errors="coerce", dayfirst=False)

    # Intento 2: ordinal Excel si hay números con magnitud típica
    as_num = pd.to_numeric(s, errors="coerce")
    mask_excel = as_num.notna() & (as_num.between(20000, 600000))
    dt2 = pd.to_datetime(as_num[mask_excel], unit="D", origin="1899-12-30")

    dt = dt1.astype("datetime64[ns]")
    dt.loc[mask_excel] = dt2

    out = dt.dt.strftime("%Y-%m-%d")
    out = out.where(dt.notna(), "")
    return out

def _coerce_num(series: pd.Series, force_int: bool = True) -> pd.Series:
    s = pd.to_numeric(series, errors="coerce")
    if force_int:
        return s.fillna(0).round(0).astype("Int64")
    return s

def pick_from_tokens(df: pd.DataFrame, spec: str, aliases_norm: dict) -> pd.Series:
    """
    Interpreta expresiones como:
      'Upper;NombreCompleto'  'strip;DireccionResidencia'  'lower;Campo'
    - Aplica la 1ª transformación (upper/lower/title/strip) encontrada
      a la 1ª columna válida encontrada después.
    - Si no hay transformaciones, devuelve la 1ª columna válida.
    """
    tokens = [t.strip() for t in str(spec or "").split(";") if t.strip()]
    if not tokens:
        return pd.Series([None] * len(df), index=df.index)

    # 1) si alguna columna literal existe, úsala tal cual
    for t in tokens:
        col = _resolve_col(df, t, aliases_norm)
        if col:
            return df[col]

    # 2) detectar transformación y luego base
    tr = None
    base = None
    for t in tokens:
        tl = t.lower()
        if tl in ("upper","lower","title","strip"):
            tr = tl
            continue
        col = _resolve_col(df, t, aliases_norm)
        if col:
            base = df[col].astype(str)
            break

    if base is None:
        return pd.Series([None] * len(df), index=df.index)

    if tr == "upper": base = base.str.upper()
    elif tr == "lower": base = base.str.lower()
    elif tr == "title": base = base.str.title()
    elif tr == "strip": base = base.str.strip()

    return base

def build_telefonos(df_src: pd.DataFrame, params: str, aliases_norm: dict, use_all_phones: bool) -> pd.DataFrame:
    """
    Consolida teléfonos y devuelve columnas: Telefono 1..4
    Reglas:
      - limpiar a dígitos
      - descartar 'SINCONTACTODIRECTO'
      - priorizar celulares (prefijo 3), luego fijos
      - deduplicar por fila
      - si use_all_phones=False, limita la toma a 2 mejores números
    ParametrosRegla:
      cols=Celular,Celular2,Fijo,Fijo2;minlen=10;maxlen=11
    """
    p = _parse_params(params)
    cols = [c.strip() for c in str(p.get("cols","")).split(",") if c.strip()]
    minlen = int(p.get("minlen", 10))
    maxlen = int(p.get("maxlen", 11))

    real_cols = []
    for c in cols:
        col = _resolve_col(df_src, c, aliases_norm)
        if col:
            real_cols.append(col)

    out = pd.DataFrame(index=df_src.index)
    if not real_cols:
        for k in range(1,5): out[f"Telefono {k}"] = ""
        return out

    stack = pd.concat(
        [df_src[c].astype(str).map(_only_digits) for c in real_cols],
        axis=1
    )

    def pick_row(row):
        nums = [n for n in row if n and n != "0"]
        # filtrar longitudes y 'SINCONTACTODIRECTO'
        nums = [n for n in nums if (minlen <= len(n) <= maxlen)]
        nums = [n for n in nums if "SINCONTACTODIRECTO" not in n.upper()]
        mobiles = []
        land = []
        seen = set()
        for n in nums:
            if n in seen:
                continue
            seen.add(n)
            (mobiles if _is_mobile(n) else land).append(n)
        ordered = mobiles + land
        if not use_all_phones:
            ordered = ordered[:2]
        while len(ordered) < 4:
            ordered.append("")
        return pd.Series(ordered[:4], index=[f"Telefono {k}" for k in range(1,5)])

    return stack.apply(pick_row, axis=1)

# SinergIA4900 - Post-fix IN_SISTECREDITO (fechas + franja + SOLO celulares en salida)
def _post_fix_in_siste_business_rules(
    df_clean: pd.DataFrame,
    df_ter_raw: pd.DataFrame,
    log: str,
    use_all_phones: bool,
) -> tuple[pd.DataFrame, str]:
    """
    Post-fix NO destructivo.
    Objetivos:
    1) Enforce de columnas tipo Fecha según ModeloRelacion (dtype datetime64[ns]).
    2) Garantizar columna 'Franja' (Parameters.FranjaMora si existe; si no, 'SIN_FRANJA').
    3) Enforce SOLO celulares en salida (Telefono 1..4 y Teléfono Almacén) usando helper enforce_only_mobile_phones_on_output.
    """
    if df_clean is None or df_clean.empty:
        return df_clean, _log_append(log, "Post-fix: DF vacío. Saltando.")

    df = df_clean.copy()

    # ---------- 1) ENFORCE FECHAS (ModeloRelacion.TipoDatoDestino=Fecha) ----------
    date_cols = []
    coerced_total = 0
    converted_cols = 0

    try:
        df_modelo = _load_modelorelacion_df()
        if isinstance(df_modelo, pd.DataFrame) and not df_modelo.empty:
            dm = df_modelo.copy()
            if "Sistema" in dm.columns:
                dm["Sistema"] = dm["Sistema"].astype(str).str.replace("SinergIA", "SinergIA", regex=False)

            mask = (
                (dm.get("Sistema").astype(str) == "SinergIA") &
                (dm.get("ArchivoDestino").astype(str) == "IN_SISTECREDITO") &
                (dm.get("TipoDatoDestino").astype(str).str.strip().str.lower() == "fecha")
            )
            if "ColumnaDestino" in dm.columns:
                date_cols = [c for c in dm.loc[mask, "ColumnaDestino"].astype(str).tolist() if c]
    except Exception:
        date_cols = []

    def _best_parse_date(series: pd.Series) -> tuple[pd.Series, int]:
        """
        Devuelve (parsed, coerced_to_nat_count).
        Elige entre dayfirst True/False por mayor parseo.
        Trata 1900-01-01 como sentinela => NaT.
        """
        s = series

        if pd.api.types.is_datetime64_any_dtype(s):
            return s, 0

        s_str = s.astype("string").str.strip()
        s_str = s_str.replace({"": pd.NA, "nan": pd.NA, "None": pd.NA, "NaT": pd.NA})

        p1 = pd.to_datetime(s_str, errors="coerce", dayfirst=True)
        p2 = pd.to_datetime(s_str, errors="coerce", dayfirst=False)

        best = p1 if int(p1.notna().sum()) >= int(p2.notna().sum()) else p2

        num = pd.to_numeric(s, errors="coerce")
        if int(num.notna().sum()) > 0:
            med = float(num.dropna().median())
            if 1000 < med < 100000:
                p_excel = pd.to_datetime(num, unit="d", origin="1899-12-30", errors="coerce")
                if int(p_excel.notna().sum()) > int(best.notna().sum()):
                    best = p_excel

        before = int(best.isna().sum())
        best = best.mask(best <= pd.Timestamp("1900-01-02"), pd.NaT)
        after = int(best.isna().sum())

        coerced = max(0, after - before)
        return best, coerced

    if date_cols:
        for col in date_cols:
            if col in df.columns:
                parsed, coerced = _best_parse_date(df[col])
                df[col] = parsed
                coerced_total += int(coerced)
                converted_cols += 1

        log = _log_append(
            log,
            f"Post-fix: FECHAS enforced cols={converted_cols}/{len(date_cols)} coerced_to_NaT={coerced_total}"
        )
    else:
        log = _log_append(log, "Post-fix: FECHAS skip (ModeloRelacion sin columnas Fecha detectables).")

    # ---------- cargar Parameters (opcional) ----------
    df_params = None
    try:
        tmp = _get_cfg_params(log)
        df_params = tmp[0] if isinstance(tmp, tuple) else tmp
    except Exception:
        df_params = None

    # ---------- 2) FRANJA ----------
    col_dias = None
    for c in ("Días en Mora", "Dias en Mora", "DiasMora", "Dias_mora", "dias_mora"):
        if c in df.columns:
            col_dias = c
            break

    if "Franja" not in df.columns:
        df["Franja"] = pd.NA

    filled = 0
    if col_dias is not None:
        dias = pd.to_numeric(df[col_dias], errors="coerce")

        franjas_ok = False
        if isinstance(df_params, pd.DataFrame) and not df_params.empty:
            cols_needed = {"Parametro", "Desde", "Hasta", "Etiqueta"}
            if cols_needed.issubset(set(df_params.columns)):
                mask = (df_params["Parametro"].astype(str).str.strip().str.lower() == "franjamora")
                df_franjas = df_params.loc[mask, ["Desde", "Hasta", "Etiqueta"]].copy()

                if not df_franjas.empty:
                    franjas_ok = True
                    df_franjas["Desde"] = pd.to_numeric(df_franjas["Desde"], errors="coerce")
                    df_franjas["Hasta"] = pd.to_numeric(df_franjas["Hasta"], errors="coerce")
                    df_franjas = df_franjas.sort_values(["Desde", "Hasta"], na_position="last")

                    base_null = df["Franja"].isna()
                    for _, r in df_franjas.iterrows():
                        lo = r["Desde"]
                        hi = r["Hasta"]
                        label = str(r["Etiqueta"])

                        if pd.isna(lo) and pd.isna(hi):
                            continue
                        if pd.isna(lo):
                            m = dias.le(hi)
                        elif pd.isna(hi):
                            m = dias.ge(lo)
                        else:
                            m = dias.ge(lo) & dias.le(hi)

                        target = base_null & m
                        if target.any():
                            df.loc[target, "Franja"] = label
                            base_null = df["Franja"].isna()

        still_null = df["Franja"].isna()
        if still_null.any():
            df.loc[still_null, "Franja"] = "SIN_FRANJA"

        filled = int((~df["Franja"].isna()).sum())
        log = _log_append(
            log,
            f"Post-fix: FRANJA {'OK' if franjas_ok else 'FALLBACK'} (col_dias='{col_dias}', filled={filled}/{len(df)})",
        )
    else:
        df["Franja"] = df["Franja"].fillna("SIN_FRANJA")
        log = _log_append(log, "Post-fix: FRANJA FALLBACK (sin columna de mora).")

    # ---------- 3) SOLO CELULARES EN SALIDA (Telefono 1..4 / Teléfono Almacén) ----------
    try:
        df, log = enforce_only_mobile_phones_on_output(df, use_all_phones=use_all_phones, log=log)
    except NameError:
        log = _log_append(log, "Post-fix: SOLO_MOBILE_OUTPUT skip (función enforce_only_mobile_phones_on_output no definida).")
    except Exception as e:
        log = _log_append(log, f"Post-fix: SOLO_MOBILE_OUTPUT error: {e}")

    return df, log

# SinergIA5000 - Reglas DIRECTO/DEFAULT/TELEFONOS + utilitarios
import pandas as pd

def expected_in_columns(df_modelo: pd.DataFrame) -> list[str]:
    dfm = df_modelo.copy()
    dfm["OrdenDestino"] = pd.to_numeric(dfm["OrdenDestino"], errors="coerce")
    dfm = dfm.sort_values("OrdenDestino", kind="stable")
    cols = [c for c in dfm["ColumnaDestino"].astype(str) if c.strip()]
    # mantener único respetando el orden
    seen, out = set(), []
    for c in cols:
        if c not in seen:
            seen.add(c); out.append(c)
    return out

def _ensure_upper_column(df: pd.DataFrame) -> pd.DataFrame:
    # Si alguna parte del flujo espera 'Upper' como token literal, no molesta tenerla
    if "Upper" not in df.columns:
        df = df.copy()
        df["Upper"] = ""
    return df



def _apply_regla_default(n_rows: int, valor_predeterminado, tipo_dato_destino: str) -> pd.Series:
    t = (tipo_dato_destino or "").strip().lower()
    base = pd.Series([valor_predeterminado] * n_rows)
    if t.startswith("fecha"):
        return _coerce_fecha(base)
    elif t.startswith("numero"):
        return _coerce_num(base, force_int=True)
    else:
        return base.astype(str).str.strip()

# SinergIA5100 - Construcción IN_SISTECREDITO desde ModeloRelacion
import pandas as pd
_MODELO_RELACION_CACHE: pd.DataFrame | None = None

def _load_modelorelacion_df() -> pd.DataFrame:
    global _MODELO_RELACION_CACHE
    if _MODELO_RELACION_CACHE is not None:
        return _MODELO_RELACION_CACHE
    df = read_gsheet(CONFIG_SPREADSHEET_ID, "ModeloRelacion")
    df.columns = [str(c).strip() for c in df.columns]
    _MODELO_RELACION_CACHE = df
    return df

def build_in_from_modelorelacion(
    df_rutina: pd.DataFrame | None = None,
    df_modelo: pd.DataFrame | None = None,
    use_all_phones: bool = False,
    log: str = "",
    # --- compatibilidad con llamadas antiguas:
    df_ter: pd.DataFrame | None = None
):
    """Compat: si me llaman con df_ter=, úsalo como df_rutina."""
    if df_rutina is None and df_ter is not None:
        df_rutina = df_ter
    assert df_rutina is not None, "df_rutina no puede ser None"

    log = _log_append(log, "Construyendo IN desde ModeloRelacion...")
    df = _ensure_upper_column(df_rutina.copy())
    if df_modelo is None:
        df_modelo = _load_modelorelacion_df()

    out = {}
    orden_cols = expected_in_columns(df_modelo)

    for _, r in df_modelo.sort_values('OrdenDestino', kind='stable').iterrows():
        dest   = str(r.get('ColumnaDestino','')).strip()
        if not dest:
            continue
        tipo   = str(r.get('TipoRegla','DIRECTO')).strip().upper()
        tdata  = str(r.get('TipoDatoDestino','')).strip()
        origen = str(r.get('ColumnaOrigen','')).strip()
        vdef   = r.get('ValorPredeterminado', '')

        if tipo == 'DIRECTO':
            out[dest] = _apply_regla_directo(df, origen, tdata)

        elif tipo == 'DEFAULT':
            out[dest] = _apply_regla_default(len(df), vdef, tdata)

        elif tipo == 'REGLA_TELEFONOS':
            tel_df = _apply_regla_telefonos(
                df, params=str(r.get('ParametrosRegla','')),
                use_all_phones=bool(use_all_phones)
            )
            for c in ['Telefono 1','Telefono 2','Telefono 3','Telefono 4']:
                out.setdefault(c, tel_df[c])

        else:
            out[dest] = pd.Series(['']*len(df))
            log = _log_append(log, f"TipoRegla '{tipo}' para '{dest}' no implementado; columna vacía.")

    df_out = pd.DataFrame(out).reindex(columns=orden_cols, fill_value='')

    # Fallback de vencimiento si la fuente vino mal:
    if 'Fecha de vencimiento' in df_out.columns:
        venc = df_out['Fecha de vencimiento']
        if (pd.to_datetime(venc, errors='coerce').isna().mean() > 0.5) and ('Días en Mora' in df_out.columns):
            hoy = pd.Timestamp.today().normalize()
            dias = pd.to_numeric(df_out['Días en Mora'], errors='coerce').fillna(0).astype(int)
            df_out['Fecha de vencimiento'] = (hoy - pd.to_timedelta(dias, unit='D')).dt.strftime('%Y-%m-%d')
            log = _log_append(log, "Fallback vencimiento: hoy - Días en Mora.")

    return df_out, log

# SinergIA5200 - T5 Hard-Wire Patch (Nombre Completo + Telefonos)  [ANTI-DESCONEXIÓN]
import pandas as pd
import numpy as np
import re

# -----------------------------
# Helpers robustos
# -----------------------------

_SINERGIA_TRANSFORMS = {"upper"}

def sinergia__split_tokens(s: str):
    s = "" if s is None else str(s)
    # separador principal = ';'  (config actual)
    toks = [t.strip() for t in s.split(";") if t is not None and str(t).strip()]
    return toks

def sinergia__pick_existing_col(df: pd.DataFrame, candidates):
    if df is None or df.empty:
        return None
    cmap = {str(c).strip().lower(): c for c in df.columns}
    for cand in candidates or []:
        key = str(cand).strip().lower()
        if key in cmap:
            return cmap[key]
    return None

def sinergia__resolve_direct_source(df_src: pd.DataFrame, col_origen_spec: str):
    """
    Soporta estos casos:
    - "NombreCompleto"  (directo)
    - "Upper;NombreCompleto"  (fallback: si no existe NombreCompleto, usa Upper como columna real)
    - "upper;NombreCompleto"  (transform + fallback a 'upper' si existe como columna real)
    """
    toks = sinergia__split_tokens(col_origen_spec)
    if not toks:
        return None, None

    transform = None
    # Si el primer token es transform y hay más tokens, lo tratamos como transform.
    if toks[0].strip().lower() in _SINERGIA_TRANSFORMS and len(toks) >= 2:
        transform = toks[0].strip().lower()
        candidates = toks[1:]
        # fallback importante: si el token de transform también existe como columna real (caso "Upper"),
        # lo agregamos al final como candidato.
        candidates_fb = candidates + [toks[0]]
    else:
        candidates = toks
        candidates_fb = toks

    src_col = sinergia__pick_existing_col(df_src, candidates_fb)
    return src_col, transform

# -----------------------------
# Phones (usa tu lógica, pero reforzada)
# -----------------------------

def sinergia__clean_phone_series(s: pd.Series) -> pd.Series:
    s = s.fillna("").astype(str)
    s = s.str.replace(r"\D+", "", regex=True)
    s = s.replace({"nan": "", "None": ""})
    return s

def sinergia__normalize_phone_series(d: pd.Series, minlen=10, maxlen=11) -> pd.Series:
    d = d.copy()
    d = d.mask(d.str.startswith("57") & (d.str.len() > maxlen), d.str[2:])
    d = d.mask(d.str.len() > maxlen, d.str[-maxlen:])
    d = d.where(d.str.len().between(minlen, maxlen), "")
    return d

def sinergia_build_phones_df(df_src: pd.DataFrame, cols, minlen=10, maxlen=11, max_out=4, use_all=False) -> pd.DataFrame:
    n = 0 if df_src is None else len(df_src)
    out = {f"Telefono {i}": [""] * n for i in range(1, max_out + 1)}
    if df_src is None or n == 0:
        return pd.DataFrame(out)

    cols_present = []
    for c in cols or []:
        real = sinergia__pick_existing_col(df_src, [c])
        if real:
            cols_present.append(real)

    if not cols_present:
        return pd.DataFrame(out)

    arr = []
    for c in cols_present:
        d = sinergia__normalize_phone_series(sinergia__clean_phone_series(df_src[c]), minlen=minlen, maxlen=maxlen)
        arr.append(d.to_numpy(dtype=object))

    mat = np.vstack(arr).T
    limit = max_out if use_all else min(2, max_out)

    for i in range(n):
        seen = set()
        phones = []
        for j in range(mat.shape[1]):
            v = mat[i, j]
            if not v or v in seen:
                continue
            seen.add(v)
            phones.append(v)
            if len(phones) >= limit:
                break

        for k in range(1, max_out + 1):
            out[f"Telefono {k}"][i] = phones[k-1] if (k <= limit and k-1 < len(phones)) else ""

    return pd.DataFrame(out)

# -----------------------------
# Postfill T5 (se ejecuta SIEMPRE al final del builder)
# -----------------------------

def sinergia_postfill_T5(df_src: pd.DataFrame, df_out: pd.DataFrame, df_modelo: pd.DataFrame, ui_state=None, log: str = ""):
    if df_src is None or df_out is None or df_modelo is None or df_modelo.empty:
        return df_out, log

    ui_state = ui_state or {}
    use_all = bool(ui_state.get("usar_todos_celulares_disponibles", False))
    texto_mayus = bool(ui_state.get("texto_mayusculas", True))  # default True para tu caso actual

    # 1) Nombre Completo
    if "Nombre Completo" in df_out.columns and "ColumnaDestino" in df_modelo.columns:
        mr = df_modelo[df_modelo["ColumnaDestino"].astype(str).str.strip().str.lower() == "nombre completo"]
        if not mr.empty:
            col_origen = mr.iloc[0].get("ColumnaOrigen", "")
            src_col, transform = sinergia__resolve_direct_source(df_src, col_origen)
            if src_col:
                s = df_src[src_col].fillna("").astype(str)
                if (transform == "upper") or texto_mayus:
                    s = s.str.upper()
                df_out["Nombre Completo"] = s

    # 2) Telefonos 1..4 (REGLA_TELEFONOS)
    if "TipoRegla" in df_modelo.columns:
        tel_rows = df_modelo[df_modelo["TipoRegla"].astype(str).str.upper() == "REGLA_TELEFONOS"]
        if not tel_rows.empty:
            params = str(tel_rows.iloc[0].get("ParametrosRegla", "") or "")
            p = {}
            for part in params.split(";"):
                if "=" in part:
                    k, v = part.split("=", 1)
                    p[k.strip().lower()] = v.strip()

            cols = [c.strip() for c in p.get("cols", "").split(",") if c.strip()]
            minlen = int(float(p.get("minlen", "10") or 10))
            maxlen = int(float(p.get("maxlen", "11") or 11))

            phones_df = sinergia_build_phones_df(df_src, cols, minlen=minlen, maxlen=maxlen, max_out=4, use_all=use_all)
            for c in ["Telefono 1", "Telefono 2", "Telefono 3", "Telefono 4"]:
                if c in df_out.columns and c in phones_df.columns:
                    df_out[c] = phones_df[c]

    # Log mínimo trazable
    try:
        filled_name = int((df_out.get("Nombre Completo", pd.Series([""]*len(df_out))).astype(str).str.len() > 0).sum())
        filled_tel1 = int((df_out.get("Telefono 1", pd.Series([""]*len(df_out))).astype(str).str.len() > 0).sum())
        msg = f"T5 POSTFILL OK.  NombreCompleto_filled={filled_name}.  Tel1_filled={filled_tel1}.  use_all={use_all}."
        if "_log_append" in globals() and isinstance(log, str):
            log = _log_append(log, msg)
        else:
            log = (log + "\n" + msg) if isinstance(log, str) else msg
    except Exception:
        pass

    return df_out, log

# -----------------------------
# Wrap FINAL (al builder que usa on_clean_rutina)
# -----------------------------

def sinergia_patch_builder_T5():
    if "build_in_from_modelorelacion" not in globals():
        print("T5 patch: build_in_from_modelorelacion no existe en globals().")
        return False

    old = globals()["build_in_from_modelorelacion"]
    if getattr(old, "_sinergia_wrapped_T5_final", False):
        print("T5 patch: ya estaba aplicado.")
        return True

    def wrapped(*args, **kwargs):
        res = old(*args, **kwargs)

        # En este pipeline: args[0]=df_src, args[1]=df_modelo
        df_src = args[0] if (len(args) >= 1 and isinstance(args[0], pd.DataFrame)) else None
        df_modelo = args[1] if (len(args) >= 2 and isinstance(args[1], pd.DataFrame)) else None

        # UI state opcional: si tú lo defines global, lo respetamos.
        ui_state = globals().get("SINERGIA_UI_STATE", {"texto_mayusculas": True, "usar_todos_celulares_disponibles": False})

        if isinstance(res, tuple) and len(res) >= 2 and isinstance(res[0], pd.DataFrame) and isinstance(res[1], str):
            df_out, log = res[0], res[1]
            df_out, log = sinergia_postfill_T5(df_src, df_out, df_modelo, ui_state=ui_state, log=log)
            return (df_out, log) + res[2:]

        if isinstance(res, pd.DataFrame):
            df_out, _log = sinergia_postfill_T5(df_src, res, df_modelo, ui_state=ui_state, log="")
            return df_out

        return res

    wrapped._sinergia_wrapped_T5_final = True
    globals()["build_in_from_modelorelacion"] = wrapped
    print("T5 patch aplicado sobre build_in_from_modelorelacion.  (Hard-Wire)")
    return True

sinergia_patch_builder_T5()

# SinergIA5300 - Helpers teléfonos + limpieza direcciones + matching de columnas con tildes
from __future__ import annotations

import re
import unicodedata
import pandas as pd


def _norm_colkey(name: str) -> str:
    """Normaliza nombres de columnas para matching (ignora tildes/espacios/case)."""
    s = str(name or "")
    s = "".join(c for c in unicodedata.normalize("NFKD", s) if not unicodedata.combining(c))
    s = s.strip().lower()
    s = re.sub(r"\s+", " ", s)
    return s


def _find_col(df: pd.DataFrame, target: str) -> str | None:
    """Devuelve el nombre real de la columna en df que matchee target ignorando tildes."""
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return None
    t = _norm_colkey(target)
    for c in df.columns:
        if _norm_colkey(c) == t:
            return c
    return None


def _parse_parametros_regla__deprecated_2200(raw: str) -> dict:
    """
    Parse simple: 'a=b;c=d' y soporta comas.
    Ej: 'cols=Celular,Celular2,Fijo,Fijo2;minlen=10;maxlen=11'
    """
    out = {}
    s = (raw or "").strip()
    if not s:
        return out
    parts = [p.strip() for p in s.split(";") if p and p.strip()]
    for p in parts:
        if "=" in p:
            k, v = p.split("=", 1)
            out[k.strip().lower()] = v.strip()
        else:
            out[p.strip().lower()] = True
    return out


def _normalize_digits_series(ser: pd.Series) -> pd.Series:
    """Deja solo dígitos.  NaN -> ''."""
    s = ser.fillna("").astype("string")
    s = s.str.replace(r"\D+", "", regex=True)
    return s.fillna("").astype("string")


def _valid_len_mask(digits: pd.Series, minlen: int, maxlen: int) -> pd.Series:
    ln = digits.str.len()
    return ln.ge(int(minlen)) & ln.le(int(maxlen))


def _normalize_phone_series(ser: pd.Series, minlen: int = 10, maxlen: int = 11) -> pd.Series:
    d = _normalize_digits_series(ser)
    m = _valid_len_mask(d, minlen, maxlen)
    return d.where(m, "")


def _extract_col_mobiles_from_text(ser_text: pd.Series) -> pd.Series:
    """
    Extrae celular colombiano (10 dígitos iniciando por 3) desde un texto.
    Soporta separadores comunes.  Retorna solo el primer match por fila (o '').
    """
    s = ser_text.fillna("").astype("string")

    # Captura un móvil 3XXXXXXXXX permitiendo separadores dentro
    # Ej: '313 441 2145', '(313)441-2145', '57 3134412145'
    pat = re.compile(r"(?:\+?57[\s\-\.\(\)]*)?(3(?:[\s\-\.\(\)]*\d){9})")
    found = s.str.findall(pat)

    def _first_clean(lst):
        if not lst:
            return ""
        x = str(lst[0])
        x = re.sub(r"\D+", "", x)
        return x if len(x) == 10 and x.startswith("3") else ""

    return found.map(_first_clean).astype("string").fillna("")


def _dedup_compact_candidates(cands: list[pd.Series], limit: int = 4) -> list[pd.Series]:
    """
    Dedup + compact por fila preservando orden.  Implementación eficiente (loop por fila, pocos candidatos).
    Retorna lista de Series (len=limit).
    """
    if not cands:
        return [pd.Series([], dtype="string") for _ in range(limit)]

    n = len(cands[0])
    mats = [c.fillna("").astype("string").to_numpy() for c in cands]
    out = [[""] * n for _ in range(limit)]

    for i in range(n):
        seen = set()
        picks = []
        for arr in mats:
            v = arr[i]
            if not v:
                continue
            if v in seen:
                continue
            seen.add(v)
            picks.append(v)
            if len(picks) >= limit:
                break
        while len(picks) < limit:
            picks.append("")
        for j in range(limit):
            out[j][i] = picks[j]

    return [pd.Series(out[j], index=cands[0].index, dtype="string") for j in range(limit)]


def _clean_address_series(ser: pd.Series) -> pd.Series:
    """
    Limpieza específica para Direcciones:
    - Trim + colapsa espacios.
    - Quita signos al inicio/fin.
    - Quita números al inicio (incluye 0,00,000...).
    - Si al final queda sin letras (solo números/signos/espacios) -> ''.
    """
    out = ser.fillna("").astype("string").astype(str)

    # Normaliza acentos (consistente con tu pipeline de texto)
    out = out.map(lambda s: "".join(c for c in unicodedata.normalize("NFKD", s) if not unicodedata.combining(c)))

    # Colapsa espacios
    out = out.str.replace(r"\s+", " ", regex=True).str.strip()

    # Quita signos al inicio/fin (cualquier no-alfanumérico)
    out = out.str.replace(r"^[^A-Za-z0-9]+", "", regex=True)
    out = out.str.replace(r"[^A-Za-z0-9]+$", "", regex=True)

    # Quita números al inicio (incluye ceros)
    out = out.str.replace(r"^[0-9]+", "", regex=True).str.strip()
    out = out.str.replace(r"^[^A-Za-z]+", "", regex=True).str.strip()  # por si quedaron signos tras quitar números

    # Si no hay letras -> vacío
    has_letter = out.str.contains(r"[A-Za-z]", regex=True, na=False)
    out = out.where(has_letter, "")

    # Re-trim final
    out = out.str.replace(r"\s+", " ", regex=True).str.strip()
    return out.astype("string").fillna("")


def sinergia_apply_regla_telefonos_from_modelo(
    df_out: pd.DataFrame,
    df_src: pd.DataFrame,
    df_modelo: pd.DataFrame,
    log: str,
    usar_todos: bool = True,
    fallback_phone_sources: list[str] | None = None,
) -> tuple[pd.DataFrame, str]:
    """
    Aplica REGLA_TELEFONOS en df_out usando ParametrosRegla del ModeloRelacion.
    - Dedup consistente.
    - Recupera móviles desde Dirección Del Cliente (origen) cuando existan.
    - Completa Teléfono Almacén si existe en df_out (desde el origen del MR si se puede).
    """

    if df_out is None or not isinstance(df_out, pd.DataFrame) or df_out.empty:
        return df_out, log

    if df_src is None or not isinstance(df_src, pd.DataFrame):
        return df_out, log

    if df_modelo is None or not isinstance(df_modelo, pd.DataFrame) or df_modelo.empty:
        return df_out, log

    # Localiza filas de regla en MR
    df_mr = df_modelo.copy()
    df_mr.columns = [str(c).strip() for c in df_mr.columns]
    if "TipoRegla" not in df_mr.columns:
        return df_out, log

    df_tel = df_mr[df_mr["TipoRegla"].astype(str).str.strip().str.upper() == "REGLA_TELEFONOS"].copy()
    if df_tel.empty:
        return df_out, log

    # Toma parámetros (la primera fila)
    params_raw = str(df_tel.iloc[0].get("ParametrosRegla", "") or "")
    params = _parse_parametros_regla(params_raw)

    cols_raw = params.get("cols") or ""
    phone_src_cols = [c.strip() for c in str(cols_raw).split(",") if c and c.strip()]
    if not phone_src_cols and fallback_phone_sources:
        phone_src_cols = list(fallback_phone_sources)

    minlen = int(params.get("minlen") or 10)
    maxlen = int(params.get("maxlen") or 11)

    # Dest cols: intenta por nombres canónicos del config (con y sin tildes)
    cand_dest = ["Telefono 1", "Telefono 2", "Telefono 3", "Telefono 4",
                 "Teléfono 1", "Teléfono 2", "Teléfono 3", "Teléfono 4"]
    phone_dest_cols = []
    for name in cand_dest:
        c = _find_col(df_out, name)
        if c and c not in phone_dest_cols:
            phone_dest_cols.append(c)

    # Si vienen como Telefono1/Telefono2 (alias) también
    for name in ["Telefono1", "Telefono2", "Telefono3", "Telefono4"]:
        c = _find_col(df_out, name)
        if c and c not in phone_dest_cols:
            phone_dest_cols.append(c)

    # Solo necesitamos 4 destinos (si existen)
    phone_dest_cols = phone_dest_cols[:4]

    # Recuperación desde Dirección Del Cliente: busca el ORIGEN real en MR para ese destino
    addr_dest = _find_col(df_out, "Dirección Del Cliente") or _find_col(df_out, "Direccion Del Cliente")
    addr_src_ser = None
    if "ColumnaDestino" in df_mr.columns and "ColumnaOrigen" in df_mr.columns:
        if addr_dest:
            # ubica fila DIRECTO de Dirección Del Cliente para obtener spec origen real
            mr_addr = df_mr[
                (df_mr["ColumnaDestino"].astype(str).str.strip().map(_norm_colkey) == _norm_colkey(addr_dest))
            ]
            if not mr_addr.empty:
                spec = str(mr_addr.iloc[0].get("ColumnaOrigen", "") or "")
                # usa _pick_from_spec si existe, si no intenta columna directa
                if spec and "_pick_from_spec" in globals():
                    try:
                        addr_src_ser = _pick_from_spec(df_src, spec)
                    except Exception:
                        addr_src_ser = None
                else:
                    c0 = spec.split(";")[0].strip()
                    if c0 and c0 in df_src.columns:
                        addr_src_ser = df_src[c0]

    # Construye candidatos desde columnas fuente
    cand_series = []
    for c in phone_src_cols:
        if c in df_src.columns:
            cand_series.append(_normalize_phone_series(df_src[c], minlen=minlen, maxlen=maxlen))

    # + móviles desde dirección (si hay)
    if addr_src_ser is not None:
        mob_from_addr = _extract_col_mobiles_from_text(addr_src_ser)
        # filtra longitudes válidas (móvil 10)
        mob_from_addr = mob_from_addr.where(mob_from_addr.str.len().eq(10), "")
        cand_series.append(mob_from_addr)

    # Si no hay nada, no hacemos nada
    if not cand_series or not phone_dest_cols:
        log = _log_append(log, f"INFO · REGLA_TELEFONOS (builder) omitida: sin fuentes o sin destinos. origen={phone_src_cols}.")
        return df_out, log

    # Dedup+compact
    limit = 4 if usar_todos else 1
    picks = _dedup_compact_candidates(cand_series, limit=limit)

    # Asignación a destinos
    for i, dcol in enumerate(phone_dest_cols[:limit]):
        df_out[dcol] = picks[i]

    # Si el DF tiene más columnas de teléfono, las dejamos limpias cuando usar_todos=False
    if not usar_todos and len(phone_dest_cols) > 1:
        for dcol in phone_dest_cols[1:]:
            df_out[dcol] = ""

    # Teléfono Almacén: intenta normalizar desde su origen en MR (DIRECTO).  Si no, deja tal cual.
    tel_alm_dest = _find_col(df_out, "Teléfono Almacén") or _find_col(df_out, "Telefono Almacen") or _find_col(df_out, "TelefonoAlmacen")
    if tel_alm_dest and "ColumnaDestino" in df_mr.columns and "ColumnaOrigen" in df_mr.columns:
        mr_ta = df_mr[df_mr["ColumnaDestino"].astype(str).str.strip().map(_norm_colkey) == _norm_colkey(tel_alm_dest)]
        if not mr_ta.empty:
            spec_ta = str(mr_ta.iloc[0].get("ColumnaOrigen", "") or "").strip()
            if spec_ta:
                src_ser = None
                if "_pick_from_spec" in globals():
                    try:
                        src_ser = _pick_from_spec(df_src, spec_ta)
                    except Exception:
                        src_ser = None
                if src_ser is None:
                    c0 = spec_ta.split(";")[0].strip()
                    if c0 and c0 in df_src.columns:
                        src_ser = df_src[c0]

                if src_ser is not None:
                    df_out[tel_alm_dest] = _normalize_phone_series(src_ser, minlen=minlen, maxlen=maxlen)

    log = _log_append(
        log,
        f"INFO · REGLA_TELEFONOS aplicada (builder) · usar_todos={usar_todos} · origen={phone_src_cols} · minlen={minlen} maxlen={maxlen}."
    )
    return df_out, log


def sinergia_clean_direcciones_inplace(df_out: pd.DataFrame, log: str) -> tuple[pd.DataFrame, str]:
    """Limpia Dirección Del Cliente y Dirección Almacén con la regla nueva (incluye ceros)."""
    if df_out is None or not isinstance(df_out, pd.DataFrame) or df_out.empty:
        return df_out, log

    for tgt in ["Dirección Del Cliente", "Direccion Del Cliente"]:
        c = _find_col(df_out, tgt)
        if c:
            df_out[c] = _clean_address_series(df_out[c])

    for tgt in ["Dirección Almacén", "Direccion Almacen", "Direccion Almacén"]:
        c = _find_col(df_out, tgt)
        if c:
            df_out[c] = _clean_address_series(df_out[c])

    log = _log_append(log, "INFO · Limpieza direcciones aplicada (cliente/almacén): signos+num/ceros al inicio/fin, trim, solo-num->vacío.")
    return df_out, log

# SinergIA5400 - Builder IN + filtro MR + OUT_GESTION layout por Estructuras (tildes)
import pandas as pd


_REQUIRED_MR_COLS = [
    "Sistema",
    "ArchivoDestino",
    "OrdenDestino",
    "ColumnaDestino",
    "TipoDatoDestino",
    "TipoRegla",
    "ColumnaOrigen",
    "ValorPredeterminado",
    "ParametrosRegla",
]


def sinergia_filter_modelorelacion_for_in__deprecated_2300(
    df_modelo: pd.DataFrame,
    log: str,
    sistema: str = "SinergIA",
    archivo_destino: str = "IN_SISTECREDITO",
    fallback_sistemas: list[str] | None = None,
) -> tuple[pd.DataFrame, str]:
    """Filtra ModeloRelacion a las filas canónicas de IN_SISTECREDITO."""
    if df_modelo is None or not isinstance(df_modelo, pd.DataFrame) or df_modelo.empty:
        return pd.DataFrame(), _log_append(log, "ModeloRelacion vacío o inválido.")

    df = df_modelo.copy()
    df.columns = [str(c).strip() for c in df.columns]

    miss = [c for c in _REQUIRED_MR_COLS if c not in df.columns]
    if miss:
        log = _log_append(log, f"ModeloRelacion: faltan columnas {miss}.")
        return pd.DataFrame(), log

    df["Sistema"] = df["Sistema"].astype(str).str.strip()
    df["ArchivoDestino"] = df["ArchivoDestino"].astype(str).str.strip()

    sistemas_ok = [str(sistema).strip()]
    if fallback_sistemas:
        sistemas_ok += [str(x).strip() for x in fallback_sistemas if str(x).strip()]
    # compat vieja por si aparece en algún archivo legado
    if "SinergIA_Cobros" not in sistemas_ok:
        sistemas_ok.append("SinergIA_Cobros")

    df = df[df["Sistema"].isin(sistemas_ok)]
    df = df[df["ArchivoDestino"] == str(archivo_destino).strip()]

    df["OrdenDestino"] = pd.to_numeric(df["OrdenDestino"], errors="coerce")
    df["ColumnaDestino"] = df["ColumnaDestino"].astype(str).str.strip()

    df = df[df["ColumnaDestino"] != ""]
    df = df.sort_values(["OrdenDestino", "ColumnaDestino"], kind="stable")

    log = _log_append(log, f"ModeloRelacion filtrado: Sistema={sistemas_ok}, ArchivoDestino='{archivo_destino}'. Filas={len(df)}.")
    return df.reset_index(drop=True), log


def _sinergia_cast_by_tipo__deprecated_2300(
    series: pd.Series,
    tipo: str,
    use_ints: bool = False,
    use_upper: bool = False,
    dest_col: str | None = None,
    *args,
    **kwargs,
) -> pd.Series:
    """
    Cast + limpieza por tipo destino.
    - Compat: tolera llamadas antiguas con args/kwargs.
    - Texto: aplica normalización y MAYÚSCULAS si use_upper.
    - Direcciones: limpieza adicional por dest_col.
    """
    import unicodedata
    import re

    # compat: si venían en args
    if isinstance(use_ints, bool) is False and len(args) > 0 and isinstance(args[0], bool):
        use_ints = bool(args[0])
    if isinstance(use_upper, bool) is False and len(args) > 1 and isinstance(args[1], bool):
        use_upper = bool(args[1])

    tipo_norm = (tipo or "").strip().lower()

    if tipo_norm == "numero":
        return pd.to_numeric(series, errors="coerce")

    if tipo_norm == "fecha":
        return series.astype("string").fillna("").str.strip()

    # Texto
    out = series.fillna("").astype("string").astype(str)

    # Normalizar (quitar acentos)
    out = out.map(lambda s: "".join(c for c in unicodedata.normalize("NFKD", s) if not unicodedata.combining(c)))

    # Colapsar espacios y trim
    out = out.str.replace(r"\s+", " ", regex=True).str.strip()

    # Filtrar a alfanum + espacio + whitelist (si está cacheada)
    allowed = globals().get("_SINERGIA_ALLOWED_SPECIALS_CACHE") or set()
    injected = kwargs.get("allowed_specials") or kwargs.get("allowed_chars")
    if injected:
        try:
            for ch in list(injected):
                if (not str(ch).isalnum()) and (not str(ch).isspace()):
                    allowed.add(str(ch))
        except Exception:
            pass

    allowed_class = "".join(re.escape(ch) for ch in sorted(allowed))
    pattern = rf"[^A-Za-z0-9 {allowed_class}]+" if allowed_class else r"[^A-Za-z0-9 ]+"
    out = out.str.replace(pattern, "", regex=True)

    # Re-colapsar espacios
    out = out.str.replace(r"\s+", " ", regex=True).str.strip()

    if use_upper:
        out = out.str.upper()

    # Limpieza especial para direcciones (incluye ceros al inicio)
    if dest_col:
        dc = _norm_colkey(dest_col)
        if dc in (_norm_colkey("Dirección Del Cliente"), _norm_colkey("Direccion Del Cliente"),
                  _norm_colkey("Dirección Almacén"), _norm_colkey("Direccion Almacen"), _norm_colkey("Direccion Almacén")):
            out = _clean_address_series(out)

    return out.astype("string").fillna("")

