########### AQUI EL CÓDIGO sinergia_build_in_direct_default que se reemplazó por el que está más abajo

def sinergia_to_out_gestion_layout_by_estructuras(
    df_in: pd.DataFrame,
    df_estructuras: pd.DataFrame,
    log: str,
    sistema: str = "SinergIA",
    archivo_logico_out: str = "ENTRADA_AWS",
) -> tuple[pd.DataFrame, str]:
    """
    Layout OUT_GESTION obedeciendo Config_SinergIA / Estructuras (NombreColumna, con tildes).
    Elimina hardcode tipo 'Almacen/Municipio Almacen/...'.
    """
    if df_in is None or not isinstance(df_in, pd.DataFrame):
        return pd.DataFrame(), _log_append(log, "OUT_GESTION FAIL: df_in inválido.")

    if df_estructuras is None or not isinstance(df_estructuras, pd.DataFrame) or df_estructuras.empty:
        return df_in.copy(), _log_append(log, "OUT_GESTION WARN: Estructuras vacío; se deja df_in sin re-layout.")

    df_e = df_estructuras.copy()
    df_e.columns = [str(c).strip() for c in df_e.columns]

    need_cols = ["Sistema", "ArchivoLogico", "ColumnaOrden", "NombreColumna"]
    miss = [c for c in need_cols if c not in df_e.columns]
    if miss:
        return df_in.copy(), _log_append(log, f"OUT_GESTION WARN: Estructuras sin columnas {miss}; se deja df_in sin re-layout.")

    df_e["Sistema"] = df_e["Sistema"].astype(str).str.strip()
    df_e["ArchivoLogico"] = df_e["ArchivoLogico"].astype(str).str.strip()

    df_e = df_e[(df_e["Sistema"] == str(sistema).strip()) & (df_e["ArchivoLogico"] == str(archivo_logico_out).strip())].copy()
    if df_e.empty:
        return df_in.copy(), _log_append(log, f"OUT_GESTION WARN: no hay Estructuras para Sistema='{sistema}', ArchivoLogico='{archivo_logico_out}'.")

    df_e["ColumnaOrden"] = pd.to_numeric(df_e["ColumnaOrden"], errors="coerce")
    df_e["NombreColumna"] = df_e["NombreColumna"].astype(str).str.strip()
    df_e = df_e[df_e["NombreColumna"] != ""].sort_values(["ColumnaOrden", "NombreColumna"], kind="stable")

    out_cols = df_e["NombreColumna"].tolist()

    df_out = df_in.copy()
    for c in out_cols:
        if c not in df_out.columns:
            df_out[c] = ""

    df_out = df_out[out_cols]

    miss_in = [c for c in out_cols if c not in df_in.columns]
    log = _log_append(log, f"OUT_GESTION layout OK (por Estructuras). Columnas={len(out_cols)} Filas={len(df_out)} miss_in={miss_in[:5]}{'...' if len(miss_in)>5 else ''}.")
    return df_out, log

#SinergIA5500 - Builder canónico IN_SISTECREDITO (DIRECTO/DEFAULT) + filtro ModeloRelacion

import pandas as pd

_REQUIRED_MR_COLS = [
    "Sistema",
    "ArchivoDestino",
    "OrdenDestino",
    "ColumnaDestino",
    "TipoDatoDestino",
    "TipoRegla",
    "ColumnaOrigen",
    "ValorPredeterminado",
    "ParametrosRegla",
]

def sinergia_filter_modelorelacion_for_in(
    df_modelo: pd.DataFrame,
    log: str,
    sistema: str = "SinergIA",
    archivo_destino: str = "IN_SISTECREDITO",
) -> tuple[pd.DataFrame, str]:
    """
    Filtra ModeloRelacion a las filas canónicas de IN_SISTECREDITO.
    Anti-desconexión: si llega vacío/invalidado (p.ej. tras 'Limpar rutina'),
    intenta recargar desde fuente canónica antes de filtrar.
    """
    # 0) Normaliza entradas
    sistema = str(sistema or "").strip()
    archivo_destino = str(archivo_destino or "").strip()

    # 1) Recarga defensiva si viene vacío/inválido
    needs_reload = (df_modelo is None) or (not isinstance(df_modelo, pd.DataFrame)) or df_modelo.empty
    if needs_reload:
        df_reload = pd.DataFrame()

        # 1A) Fuente 1: loader interno (si existe)
        if "_load_modelorelacion_df" in globals():
            try:
                df_reload = _load_modelorelacion_df()
            except Exception as e:
                log = _log_append(log, f"SONDA_MR reload(_load_modelorelacion_df) fail: {e}")
                df_reload = pd.DataFrame()

        # 1B) Fuente 2: Google Sheet (fallback)
        if (df_reload is None) or (not isinstance(df_reload, pd.DataFrame)) or df_reload.empty:
            if (
                "read_gsheet" in globals()
                and "CONFIG_SPREADSHEET_ID" in globals()
                and str(CONFIG_SPREADSHEET_ID or "").strip()
            ):
                try:
                    df_reload = read_gsheet(CONFIG_SPREADSHEET_ID, "ModeloRelacion")
                except Exception as e:
                    log = _log_append(log, f"SONDA_MR reload(read_gsheet) fail: {e}")
                    df_reload = pd.DataFrame()

        df_modelo = df_reload if isinstance(df_reload, pd.DataFrame) else pd.DataFrame()
        log = _log_append(log, f"SONDA_MR reload rows_total={len(df_modelo) if isinstance(df_modelo, pd.DataFrame) else -1}")

    # 2) Guardrails mínimos
    if df_modelo is None or not isinstance(df_modelo, pd.DataFrame) or df_modelo.empty:
        return pd.DataFrame(), _log_append(log, "ModeloRelacion vacío o inválido.")

    df = df_modelo.copy()
    df.columns = [str(c).strip() for c in df.columns]

    miss = [c for c in _REQUIRED_MR_COLS if c not in df.columns]
    if miss:
        log = _log_append(log, f"ModeloRelacion: faltan columnas {miss}.")
        return pd.DataFrame(), log

    # 3) Filtro robusto (trim + case-insensitive)
    df["Sistema"] = df["Sistema"].astype(str).str.strip()
    df["ArchivoDestino"] = df["ArchivoDestino"].astype(str).str.strip()

    df = df[df["Sistema"].str.upper() == sistema.upper()]
    df = df[df["ArchivoDestino"].str.upper() == archivo_destino.upper()]

    # 4) Orden + limpieza básica
    df["OrdenDestino"] = pd.to_numeric(df["OrdenDestino"], errors="coerce")
    df["ColumnaDestino"] = df["ColumnaDestino"].astype(str).str.strip()

    df = df[df["ColumnaDestino"] != ""]
    df = df.sort_values(["OrdenDestino", "ColumnaDestino"], kind="stable")

    log = _log_append(
        log,
        f"ModeloRelacion filtrado: Sistema='{sistema}', ArchivoDestino='{archivo_destino}'. Filas={len(df)}.",
    )
    return df.reset_index(drop=True), log



def sinergia_validate_modelorelacion_min(df_modelo: pd.DataFrame, log: str) -> tuple[bool, str]:
    """Valida mínimos de ModeloRelacion para construir IN.  Sin levantar excepciones."""
    if df_modelo is None or not isinstance(df_modelo, pd.DataFrame) or df_modelo.empty:
        return False, _log_append(log, "ModeloRelacion validación FAIL: df vacío.")

    miss = [c for c in _REQUIRED_MR_COLS if c not in df_modelo.columns]
    if miss:
        return False, _log_append(log, f"ModeloRelacion validación FAIL: faltan columnas {miss}.")

    # OrdenDestino debe existir al menos parcialmente
    if df_modelo["OrdenDestino"].isna().all():
        log = _log_append(log, "ModeloRelacion WARN: OrdenDestino viene todo NaN; se usará orden de aparición.")
        df_modelo["OrdenDestino"] = range(1, len(df_modelo) + 1)

    # ColumnaDestino no vacía
    if (df_modelo["ColumnaDestino"].astype(str).str.strip() == "").all():
        return False, _log_append(log, "ModeloRelacion validación FAIL: ColumnaDestino vacío en todas las filas.")

    # Duplicados en ColumnaDestino
    dups = df_modelo["ColumnaDestino"].astype(str).str.strip().duplicated(keep="first")
    if dups.any():
        n = int(dups.sum())
        log = _log_append(log, f"ModeloRelacion WARN: {n} ColumnaDestino duplicadas; se conserva la primera por orden.")
        df_modelo = df_modelo.loc[~dups].copy()

    return True, log


def sinergia_make_empty_in(df_modelo: pd.DataFrame) -> pd.DataFrame:
    """Crea DF vacío con las columnas destino (orden canónico)."""
    if df_modelo is None or not isinstance(df_modelo, pd.DataFrame) or df_modelo.empty:
        return pd.DataFrame()
    cols = df_modelo["ColumnaDestino"].astype(str).str.strip().tolist()
    cols = [c for c in cols if c]
    # quita duplicados preservando orden
    seen = set()
    cols2 = []
    for c in cols:
        if c in seen:
            continue
        seen.add(c)
        cols2.append(c)
    return pd.DataFrame(columns=cols2)


def _sinergia_coerce_fecha_ddmmyyyy(ser: pd.Series) -> pd.Series:
    """Normaliza fechas mixtas (str/serial excel) → DD/MM/YYYY (string)."""
    s = ser.copy()

    num = pd.to_numeric(s, errors="coerce")
    serial_mask = num.notna() & (num > 59) & (num < 60000)
    if serial_mask.any():
        dt = pd.to_datetime("1899-12-30") + pd.to_timedelta(num[serial_mask].astype(int), unit="D")
        s.loc[serial_mask] = dt.dt.strftime("%d/%m/%Y").values

    rest_mask = ~serial_mask
    parsed = pd.to_datetime(s[rest_mask], errors="coerce", dayfirst=True)
    s.loc[rest_mask] = parsed.dt.strftime("%d/%m/%Y").where(parsed.notna(), "")

    # limpia NaT/None
    s = s.astype("string").fillna("")
    s = s.replace({"NaT": "", "None": ""})
    return s


def _sinergia_cast_by_tipo__deprecated_2400(series: pd.Series, tipo: str, use_upper: bool = False, *args, **kwargs) -> pd.Series:
    """
    Cast + limpieza por tipo destino.
    Compat: acepta args/kwargs extra sin romper llamadas existentes.
    Texto: limpieza estricta (a-z/A-Z/0-9/espacio) + whitelist desde hoja UNICODE.
    """
    import re
    import unicodedata

    # Compat: algunos callers pasan use_upper como 3er arg posicional
    if not isinstance(use_upper, bool) and len(args) > 0 and isinstance(args[0], bool):
        use_upper = args[0]

    tipo_norm = (tipo or "").strip().lower()

    # Cache whitelist UNICODE (y permite inyección por kwargs si existiera)
    global _SINERGIA_ALLOWED_SPECIALS_CACHE
    if "_SINERGIA_ALLOWED_SPECIALS_CACHE" not in globals():
        _SINERGIA_ALLOWED_SPECIALS_CACHE = set()
        try:
            df_u = read_gsheet(CONFIG_SPREADSHEET_ID, "UNICODE")
            if isinstance(df_u, pd.DataFrame) and not df_u.empty:
                cols = list(df_u.columns)
                cand = [c for c in cols if any(k in str(c).lower() for k in ["char", "caracter", "símb", "simbol", "unicode", "permit", "allow"])]
                col = cand[0] if cand else cols[0]
                for v in df_u[col].dropna().astype(str).tolist():
                    s = v.strip()
                    if not s:
                        continue
                    for ch in s:
                        if (not ch.isalnum()) and (not ch.isspace()):
                            _SINERGIA_ALLOWED_SPECIALS_CACHE.add(ch)
        except Exception:
            _SINERGIA_ALLOWED_SPECIALS_CACHE = set()

    injected = kwargs.get("allowed_specials") or kwargs.get("allowed_chars")
    if injected:
        try:
            for ch in list(injected):
                if (not str(ch).isalnum()) and (not str(ch).isspace()):
                    _SINERGIA_ALLOWED_SPECIALS_CACHE.add(str(ch))
        except Exception:
            pass

    if tipo_norm == "numero":
        return pd.to_numeric(series, errors="coerce")

    if tipo_norm == "fecha":
        # No abrimos otra causa aquí: mantenemos salida simple (ajustaremos formato fecha en iteración aparte)
        return series.astype("string").str.strip()

    # Texto (default)
    out = series.fillna("").astype("string").astype(str)

    # 1) Normalizar (quitar acentos)
    out = out.map(lambda s: "".join(c for c in unicodedata.normalize("NFKD", s) if not unicodedata.combining(c)))

    # 2) Colapsar espacios y trim
    out = out.str.replace(r"\s+", " ", regex=True).str.strip()

    # 3) Filtrar caracteres: alfanum + espacio + whitelist UNICODE
    allowed = _SINERGIA_ALLOWED_SPECIALS_CACHE or set()
    allowed_class = "".join(re.escape(ch) for ch in sorted(allowed))
    pattern = rf"[^A-Za-z0-9 {allowed_class}]+" if allowed_class else r"[^A-Za-z0-9 ]+"
    out = out.str.replace(pattern, "", regex=True)

    # 4) Re-colapsar espacios por si la remoción dejó dobles
    out = out.str.replace(r"\s+", " ", regex=True).str.strip()

    if use_upper:
        out = out.str.upper()

    return out

# SinergIA5600 - Limpieza de textos (prefijos 0/00/000 + números + signos) + control por LimpiarColumna
import pandas as pd

def _as_bool(v) -> bool:
    if isinstance(v, bool):
        return v
    s = str(v).strip().lower()
    return s in ("1", "true", "t", "yes", "y", "si", "sí", "x")

def _sinergia_norm_key(s: str) -> str:
    # clave comparable sin tildes, para mapear encabezados
    import unicodedata, re
    s = "" if s is None else str(s)
    s = s.strip().lower()
    s = "".join(c for c in unicodedata.normalize("NFKD", s) if not unicodedata.combining(c))
    s = re.sub(r"\s+", " ", s).strip()
    return s

def _sinergia_cast_by_tipo(series: pd.Series, tipo: str, *args, **kwargs) -> pd.Series:
    """
    Cast + limpieza por tipo destino.  Compat con llamadas existentes:
    - Viejo: _sinergia_cast_by_tipo(ser, tipo, use_upper_bool)
    - Nuevo: _sinergia_cast_by_tipo(ser, tipo, use_ints_bool, use_upper_bool, dest_col)
    """
    import re
    import unicodedata

    # Parse args compat
    use_ints = False
    use_upper = False
    dest_col = None

    if len(args) >= 1 and isinstance(args[0], bool):
        if len(args) >= 2 and isinstance(args[1], bool):
            use_ints = bool(args[0])
            use_upper = bool(args[1])
            if len(args) >= 3 and isinstance(args[2], str):
                dest_col = args[2]
        else:
            use_upper = bool(args[0])

    if kwargs.get("use_ints") is not None:
        use_ints = bool(kwargs["use_ints"])
    if kwargs.get("use_upper") is not None:
        use_upper = bool(kwargs["use_upper"])
    if kwargs.get("dest_col") is not None:
        dest_col = str(kwargs["dest_col"])

    tipo_norm = (tipo or "").strip().lower()

    if tipo_norm == "numero":
        return pd.to_numeric(series, errors="coerce")

    if tipo_norm == "fecha":
        return series.astype("string").fillna("").str.strip()

    # TEXTO
    out = series.fillna("").astype("string").astype(str)

    # Cache whitelist UNICODE
    global _SINERGIA_ALLOWED_SPECIALS_CACHE
    if "_SINERGIA_ALLOWED_SPECIALS_CACHE" not in globals():
        _SINERGIA_ALLOWED_SPECIALS_CACHE = set()
        try:
            df_u = read_gsheet(CONFIG_SPREADSHEET_ID, "UNICODE")
            if isinstance(df_u, pd.DataFrame) and not df_u.empty:
                cols = list(df_u.columns)
                cand = [c for c in cols if any(k in str(c).lower() for k in ["char", "caracter", "símb", "simbol", "unicode", "permit", "allow"])]
                col = cand[0] if cand else cols[0]
                for v in df_u[col].dropna().astype(str).tolist():
                    s = v.strip()
                    if not s:
                        continue
                    for ch in s:
                        if (not ch.isalnum()) and (not ch.isspace()):
                            _SINERGIA_ALLOWED_SPECIALS_CACHE.add(ch)
        except Exception:
            _SINERGIA_ALLOWED_SPECIALS_CACHE = set()

    # Inyección opcional
    injected = kwargs.get("allowed_specials") or kwargs.get("allowed_chars")
    if injected:
        try:
            for ch in list(injected):
                ch = str(ch)
                if (not ch.isalnum()) and (not ch.isspace()):
                    _SINERGIA_ALLOWED_SPECIALS_CACHE.add(ch)
        except Exception:
            pass

    # Regla mínima para no romper UUIDs
    _SINERGIA_ALLOWED_SPECIALS_CACHE.add("-")

    # 1) Normalizar tildes en VALORES (no encabezados)
    out = out.map(lambda s: "".join(c for c in unicodedata.normalize("NFKD", s) if not unicodedata.combining(c)))

    # 2) Colapsar espacios
    out = out.str.replace(r"\s+", " ", regex=True).str.strip()

    # 3) Filtrar caracteres
    allowed = _SINERGIA_ALLOWED_SPECIALS_CACHE or set()
    allowed_class = "".join(re.escape(ch) for ch in sorted(allowed))
    pattern = rf"[^A-Za-z0-9 {allowed_class}]+" if allowed_class else r"[^A-Za-z0-9 ]+"
    out = out.str.replace(pattern, "", regex=True)

    # 4) Re-colapsar espacios
    out = out.str.replace(r"\s+", " ", regex=True).str.strip()

    if use_upper:
        out = out.str.upper()

    return out

# SinergIA5700
def sinergia_build_in_direct_default(
    df_src: pd.DataFrame,
    df_modelo: pd.DataFrame,
    log: str,
    use_ints: bool,
    use_upper: bool,
    use_all_phones: bool,
) -> tuple[pd.DataFrame, str]:
    """
    Construye IN respetando columnas + orden.  Rellena DIRECTO/DEFAULT.
    Actualización:
    - Aplica REGLA_TELEFONOS aquí (con df_src) para que FULL/EXPORT no quede sin teléfonos.
    - Recupera móviles desde 'Dirección Del Cliente' (si aparecen) sin duplicar.
    - Limpia bordes de 'Dirección Del Cliente' y 'Dirección Almacén':
      quita signos al inicio/fin (incluyendo permitidos por UNICODE), trim y vacía si queda solo números/signos.
    """

    # =========================
    # PARTE 1/2  (helpers)
    # =========================
    import re
    import numpy as np

    def _kv_params(s: str) -> dict:
        out = {}
        s = (s or "").strip()
        if not s:
            return out
        parts = re.split(r"[;|]\s*", s)
        for p in parts:
            if not p or "=" not in p:
                continue
            k, v = p.split("=", 1)
            k = k.strip()
            v = v.strip()
            if k:
                out[k] = v
        return out

    def _digits(ser: pd.Series) -> pd.Series:
        s = ser.fillna("").astype("string").astype(str)
        s = s.str.replace(r"\D+", "", regex=True)
        # quita prefijo 57 si viene pegado a un móvil
        s = s.str.replace(r"^57(\d{10})$", r"\1", regex=True)
        return s

    def _valid_phone(digits: pd.Series, minlen: int, maxlen: int, mobile_only: bool) -> pd.Series:
        d = digits.fillna("").astype("string")
        ok_len = d.str.len().between(int(minlen), int(maxlen))
        if mobile_only:
            ok_mobile = d.str.match(r"^3\d{9}$", na=False)  # Colombia móvil
            ok = ok_len & ok_mobile
        else:
            ok = ok_len
        return d.where(ok, "")

    def _extract_mobile_from_text(text_ser: pd.Series) -> pd.Series:
        raw = text_ser.fillna("").astype("string").astype(str)
        dig = raw.str.replace(r"\D+", "", regex=True)
        m = dig.str.extract(r"(3\d{9})", expand=False)
        return m.fillna("").astype("string")

    def _clean_address_edges(addr: pd.Series) -> pd.Series:
        s = addr.fillna("").astype("string").astype(str)
        s = s.str.replace(r"\s+", " ", regex=True).str.strip()

        # quita signos al inicio/fin (incluye permitidos por UNICODE)
        s = s.str.replace(r"^[^A-Za-z0-9]+", "", regex=True)
        s = s.str.replace(r"[^A-Za-z0-9]+$", "", regex=True)

        # re-trim
        s = s.str.replace(r"\s+", " ", regex=True).str.strip()

        # si inicia con teléfono pegado (10-11 dígitos), lo retira
        s = s.str.replace(r"^\d{10,11}\s*", "", regex=True).str.strip()

        # si queda sin letras (solo números/signos), dejar vacío
        has_letter = s.str.contains(r"[A-Za-z]", regex=True, na=False)
        s = s.where(has_letter, "")
        return s

    def _first_nonempty(arr: np.ndarray) -> np.ndarray:
        n, k = arr.shape
        out = np.full(n, "", dtype=object)
        for j in range(k):
            take = (out == "") & (arr[:, j] != "")
            if take.any():
                out[take] = arr[take, j]
        return out

    def _dedup_pick_4(arr: np.ndarray) -> tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray]:
        o1 = _first_nonempty(arr)
        a2 = np.where(arr != o1[:, None], arr, "")
        o2 = _first_nonempty(a2)
        a3 = np.where((arr != o1[:, None]) & (arr != o2[:, None]), arr, "")
        o3 = _first_nonempty(a3)
        a4 = np.where((arr != o1[:, None]) & (arr != o2[:, None]) & (arr != o3[:, None]), arr, "")
        o4 = _first_nonempty(a4)
        return o1, o2, o3, o4

    # =========================
    # PARTE 2/2  (builder)
    # =========================
    if df_src is None or not isinstance(df_src, pd.DataFrame):
        return pd.DataFrame(), _log_append(log, "IN builder FAIL: df_src inválido.")

    if df_modelo is None or not isinstance(df_modelo, pd.DataFrame) or df_modelo.empty:
        return pd.DataFrame(), _log_append(log, "IN builder FAIL: ModeloRelacion vacío.")

    # columnas destino en orden (sin duplicados)
    dest_cols = df_modelo["ColumnaDestino"].astype(str).str.strip().tolist()
    dest_cols = [c for c in dest_cols if c]
    seen = set()
    dest_cols2 = []
    for c in dest_cols:
        if c in seen:
            continue
        seen.add(c)
        dest_cols2.append(c)

    df_out = pd.DataFrame(index=df_src.index)
    pending_counts: dict[str, int] = {}

    # Captura REGLA_TELEFONOS desde ModeloRelacion
    phone_rows = df_modelo[df_modelo["TipoRegla"].astype(str).str.upper().str.strip() == "REGLA_TELEFONOS"].copy()
    phone_dest_cols = phone_rows["ColumnaDestino"].astype(str).str.strip().tolist() if not phone_rows.empty else []
    phone_dest_cols = [c for c in phone_dest_cols if c]

    phone_params_raw = ""
    if not phone_rows.empty and "ParametrosRegla" in phone_rows.columns:
        ser_p = phone_rows["ParametrosRegla"].fillna("").astype(str).str.strip()
        phone_params_raw = next((x for x in ser_p.tolist() if x), "")

    p = _kv_params(phone_params_raw)
    cols_raw = p.get("cols", "Celular,Celular2,Fijo,Fijo2")
    src_phone_cols = [c.strip() for c in cols_raw.split(",") if c and c.strip()]
    minlen = int(p.get("minlen", 10) or 10)
    maxlen = int(p.get("maxlen", 11) or 11)

    # Construcción base DIRECTO/DEFAULT
    for _, r in df_modelo.iterrows():
        dest = str(r.get("ColumnaDestino", "")).strip()
        if not dest:
            continue

        regla = str(r.get("TipoRegla", "")).strip().upper()
        tipo_dato = str(r.get("TipoDatoDestino", "")).strip()
        origen = r.get("ColumnaOrigen", "")
        vdef = r.get("ValorPredeterminado", "")

        if regla == "DIRECTO":
            try:
                ser = _pick_from_spec(df_src, str(origen))
            except Exception:
                ser = pd.Series([None] * len(df_src), index=df_src.index)
            df_out[dest] = _sinergia_cast_by_tipo(ser, tipo_dato, use_upper=use_upper)

        elif regla == "DEFAULT":
            ser = pd.Series([vdef] * len(df_src), index=df_src.index)
            df_out[dest] = _sinergia_cast_by_tipo(ser, tipo_dato, use_upper=use_upper)

        elif regla == "REGLA_TELEFONOS":
            pending_counts[regla] = pending_counts.get(regla, 0) + 1
            df_out[dest] = ""  # se rellena al final

        else:
            pending_counts[regla] = pending_counts.get(regla, 0) + 1
            ser = pd.Series([""] * len(df_src), index=df_src.index)
            df_out[dest] = _sinergia_cast_by_tipo(ser, tipo_dato, use_upper=use_upper)

    # asegura columnas
    for c in dest_cols2:
        if c not in df_out.columns:
            df_out[c] = ""

    # Aplica REGLA_TELEFONOS en bloque (con df_src)
    if phone_dest_cols:
        n = len(df_out)
        cand = []

        # candidatos desde columnas configuradas
        for col in src_phone_cols:
            if col in df_src.columns:
                d = _digits(df_src[col])
                cand.append(_valid_phone(d, minlen, maxlen, mobile_only=(not bool(use_all_phones))))

        # extraer móvil desde Dirección Del Cliente (ya mapeada en IN si existe)
        if "Dirección Del Cliente" in df_out.columns:
            mob = _extract_mobile_from_text(df_out["Dirección Del Cliente"])
            cand.append(_valid_phone(mob, minlen, maxlen, mobile_only=True))

        if cand:
            arr = np.stack([s.fillna("").astype(str).to_numpy(dtype=object) for s in cand], axis=1)
            t1, t2, t3, t4 = _dedup_pick_4(arr)
        else:
            t1 = t2 = t3 = t4 = np.full(n, "", dtype=object)

        picks = [t1, t2, t3, t4]
        for i, dcol in enumerate(phone_dest_cols[:4]):
            df_out[dcol] = picks[i]

        # Teléfono Almacén: si existe, normaliza (toma de origen si lo hay; si no, deja lo que haya)
        if "Teléfono Almacén" in df_out.columns:
            src_ser = None
            for cand_col in ["TelefonoAlmacen", "PrimerTelefono", "Teléfono Almacén", "Telefono Almacén"]:
                if cand_col in df_src.columns:
                    src_ser = df_src[cand_col]
                    break
            if src_ser is None:
                src_ser = df_out["Teléfono Almacén"]
            df_out["Teléfono Almacén"] = _valid_phone(_digits(src_ser), minlen, maxlen, mobile_only=False)

        log = _log_append(
            log,
            f"INFO · REGLA_TELEFONOS aplicada (builder) · usar_todos={bool(use_all_phones)} · origen={src_phone_cols} · minlen={minlen} maxlen={maxlen}."
        )

    # Limpieza bordes Dirección (Cliente/Almacén)
    for col in ["Dirección Del Cliente", "Dirección Almacén"]:
        if col in df_out.columns:
            df_out[col] = _clean_address_edges(df_out[col])

    # reordena canon
    df_out = df_out[dest_cols2]

    if pending_counts:
        resumen = ", ".join([f"{k}:{v}" for k, v in pending_counts.items() if k])
        log = _log_append(log, f"IN builder: reglas pendientes (en blanco, T5+): {resumen}.")

    log = _log_append(log, f"IN builder OK (DIRECTO/DEFAULT). Shape={df_out.shape}.")
    return df_out, log

# SinergIA5800 - REGLA_TELEFONOS completa
import pandas as pd

def _parse_parametros_regla(param_str: str) -> dict:
    out = {}
    s = (param_str or "").strip()
    if not s:
        return out
    parts = [p.strip() for p in s.split(";") if p.strip()]
    for p in parts:
        if "=" in p:
            k, v = p.split("=", 1)
            out[k.strip()] = v.strip()
        else:
            out[p.strip()] = True
    return out

def _clean_phone_digits(s: pd.Series) -> pd.Series:
    x = s.fillna("").astype("string").astype(str)
    x = x.str.replace(r"\D+", "", regex=True)
    x = x.str.strip()
    return x

def _normalize_phone_len(s: pd.Series, minlen: int, maxlen: int) -> pd.Series:
    x = _clean_phone_digits(s)

    # Normaliza prefijos comunes si vienen pegados
    # 57XXXXXXXXXX  -> XXXXXXXXXX
    x = x.where(~x.str.startswith("57"), x.str[2:])

    # 0XXXXXXXXXX -> XXXXXXXXXX (si queda en rango)
    x = x.where(~((x.str.len() == (maxlen)) & x.str.startswith("0")), x.str[1:])

    ok = x.str.len().between(minlen, maxlen)
    return x.where(ok, "")

def _is_mobile_co(s: pd.Series) -> pd.Series:
    x = s.fillna("").astype("string")
    return (x.str.len() == 10) & (x.str.startswith("3"))

def _extract_mobile_from_address(addr: pd.Series) -> pd.Series:
    """
    Extrae celular colombiano desde texto evitando confundir con numeraciones de dirección.
    Captura patrón 3xx xxx xxxx con separadores.
    """
    a = addr.fillna("").astype("string").astype(str)

    # Captura: 3dd ddd dddd con separadores libres, opcional +57
    m = a.str.extract(r"(?<!\d)(?:\+?57\s*)?(3\d{2})\s*[- ]?\s*(\d{3})\s*[- ]?\s*(\d{4})(?!\d)", expand=True)
    if m is None or m.empty:
        return pd.Series([""] * len(a), index=a.index, dtype="string")

    x = (m[0].fillna("") + m[1].fillna("") + m[2].fillna("")).astype("string")
    x = x.where(x.str.len() == 10, "")
    return x

def sinergia_apply_regla_telefonos(
    df_out: pd.DataFrame,
    df_src: pd.DataFrame,
    df_modelo: pd.DataFrame,
    log: str,
    use_all_phones: bool,
) -> tuple[pd.DataFrame, str]:
    """
    Aplica REGLA_TELEFONOS a df_out basado en parámetros de ModeloRelacion.
    - Pool base: cols=Celular,Celular2,Fijo,Fijo2 (configurable)
    - Extra: recupera celulares desde 'Dirección Del Cliente' (si existe) sin duplicar
    - Completa 'Teléfono Almacén' con origen preferido (PrimerTelefono / TelefonoAlmacen) y fallback
    """
    if df_out is None or df_out.empty or df_modelo is None or df_modelo.empty:
        return df_out, log

    mr_tel = df_modelo.copy()
    mr_tel["TipoRegla"] = mr_tel["TipoRegla"].astype(str).str.strip().str.upper()
    mr_tel = mr_tel[mr_tel["TipoRegla"] == "REGLA_TELEFONOS"]
    if mr_tel.empty:
        return df_out, log

    # Parámetros de la primera fila de la regla (canon)
    p = _parse_parametros_regla(str(mr_tel.iloc[0].get("ParametrosRegla", "")))
    cols = [c.strip() for c in str(p.get("cols", "Celular,Celular2,Fijo,Fijo2")).split(",") if c.strip()]
    minlen = int(str(p.get("minlen", "10")).strip() or 10)
    maxlen = int(str(p.get("maxlen", "11")).strip() or 11)

    addr_col = str(p.get("addr_col", "Dirección Del Cliente")).strip()
    almacen_phone_col = str(p.get("almacen_col", "PrimerTelefono")).strip()
    almacen_addr_col = str(p.get("almacen_addr_col", "Dirección Almacén")).strip()

    # Candidatos desde df_src
    cand = []
    origen_real = []
    for c in cols:
        if c in df_src.columns:
            cand.append(_normalize_phone_len(df_src[c], minlen, maxlen))
            origen_real.append(c)

    # Extra desde dirección del cliente (solo móvil)
    addr_mobile = None
    if addr_col in df_out.columns:
        addr_mobile = _extract_mobile_from_address(df_out[addr_col])
    elif addr_col in df_src.columns:
        addr_mobile = _extract_mobile_from_address(df_src[addr_col])
    else:
        addr_mobile = pd.Series([""] * len(df_out), index=df_out.index, dtype="string")

    # Construye matriz de candidatos (hasta 5) y dedup simple por bfill
    df_cand = pd.DataFrame(index=df_out.index)
    for i, s in enumerate(cand[:4]):
        df_cand[f"c{i+1}"] = s
    df_cand["c5_addr"] = addr_mobile

    # Dedup básico por columna secuencial
    cols_c = list(df_cand.columns)
    for j in range(1, len(cols_c)):
        prev = cols_c[:j]
        cur = cols_c[j]
        mask_dup = False
        for pr in prev:
            mask_dup = mask_dup | ((df_cand[cur] != "") & (df_cand[cur] == df_cand[pr]))
        df_cand[cur] = df_cand[cur].where(~mask_dup, "")

    # Compacta a la izquierda
    df_comp = df_cand.replace("", pd.NA).bfill(axis=1).fillna("")

    # Si no usar todos, filtra a móviles y re-compacta
    if not use_all_phones:
        for c in df_comp.columns:
            df_comp[c] = df_comp[c].where(_is_mobile_co(df_comp[c]), "")
        df_comp = df_comp.replace("", pd.NA).bfill(axis=1).fillna("")

    # Asigna a las 4 columnas destino (por orden del MR)
    tel_dest_cols = mr_tel["ColumnaDestino"].astype(str).str.strip().tolist()
    tel_dest_cols = [c for c in tel_dest_cols if c]
    tel_dest_cols = tel_dest_cols[:4]

    for k in range(4):
        if k < len(tel_dest_cols) and tel_dest_cols[k] in df_out.columns:
            df_out[tel_dest_cols[k]] = df_comp.iloc[:, k].astype("string")
        else:
            # Fallback por nombres típicos si el MR trae algo raro
            name_map = [("Telefono 1", 0), ("Telefono 2", 1), ("Telefono 3", 2), ("Telefono 4", 3),
                        ("Teléfono 1", 0), ("Teléfono 2", 1), ("Teléfono 3", 2), ("Teléfono 4", 3)]
            for nm, idx in name_map:
                if nm in df_out.columns:
                    df_out[nm] = df_comp.iloc[:, idx].astype("string")

    # Teléfono Almacén: origen preferido y fallback
    if "Teléfono Almacén" in df_out.columns or "Telefono Almacen" in df_out.columns:
        tel_alm_col_out = "Teléfono Almacén" if "Teléfono Almacén" in df_out.columns else "Telefono Almacen"

        src_ser = None
        if almacen_phone_col in df_src.columns:
            src_ser = df_src[almacen_phone_col]
        elif "TelefonoAlmacen" in df_src.columns:
            src_ser = df_src["TelefonoAlmacen"]
        elif "Teléfono Almacén" in df_src.columns:
            src_ser = df_src["Teléfono Almacén"]

        if src_ser is not None:
            tel_alm = _normalize_phone_len(src_ser, minlen, maxlen)
        else:
            tel_alm = pd.Series([""] * len(df_out), index=df_out.index, dtype="string")

        # Fallback: extrae móvil desde Dirección Almacén (si existe)
        if (tel_alm == "").any():
            if almacen_addr_col in df_out.columns:
                fb = _extract_mobile_from_address(df_out[almacen_addr_col])
            elif almacen_addr_col in df_src.columns:
                fb = _extract_mobile_from_address(df_src[almacen_addr_col])
            else:
                fb = pd.Series([""] * len(df_out), index=df_out.index, dtype="string")
            tel_alm = tel_alm.where(tel_alm != "", fb)

        df_out[tel_alm_col_out] = tel_alm.astype("string")

    log = _log_append(
        log,
        f"INFO · REGLA_TELEFONOS aplicada · usar_todos={use_all_phones} · origen={origen_real} · minlen={minlen} maxlen={maxlen} · addr_mobile={'ok' if addr_mobile is not None else 'no'}."
    )
    return df_out, log

# SinergIA5900 - Parser de especificaciones y DIRECTO token-aware
import re

_TRANSFORMS = {'upper','lower','title','strip'}

def _pick_from_spec(df: pd.DataFrame, spec: str) -> pd.Series:
    """
    Modo dual:
    1) Transform mode: si el spec contiene un transform (upper/lower/title/strip) y DESPUÉS hay una columna válida,
       aplica el transform a esa columna (ej: "upper;NombreCompleto" cuando existe "NombreCompleto").
    2) Fallback mode: si NO hay columna válida para el transform, interpreta todos los tokens como alternativas de columna
       (ej: "Upper;NombreCompleto" en TER_UNISONO donde existe columna "Upper" pero NO existe "NombreCompleto").
    """
    tokens = [t.strip() for t in str(spec).split(';') if t and str(t).strip()]
    if not tokens:
        return pd.Series([None] * len(df), index=df.index)

    # Normalizar tokens a "base" (ignora sufijos "Nombre,1")
    bases = []
    for t in tokens:
        base = t.split(',')[0].strip()
        if base:
            bases.append(base)

    # Mapa case-insensitive para columnas reales
    colmap = {str(c).lower(): c for c in df.columns}

    def _actual_col(name: str):
        return colmap.get(str(name).lower())

    # Detectar transform (si existe)
    transform = next((b.lower() for b in bases if b.lower() in _TRANSFORMS), None)

    # Columnas existentes (incluye tokens que coinciden con transform si realmente existen como columna)
    existing_all = []
    existing_non_transform = []
    for b in bases:
        ac = _actual_col(b)
        if ac is None:
            continue
        existing_all.append(ac)
        if str(b).lower() not in _TRANSFORMS:
            existing_non_transform.append(ac)

    # Decidir modo
    if transform and existing_non_transform:
        # Transform mode: aplica transform a la primera columna válida no-transform
        candidates = existing_non_transform
        transform_to_apply = transform
    else:
        # Fallback mode: trata todo como alternativas de columna (incluye "Upper" como columna si existe)
        candidates = existing_all
        transform_to_apply = None

    if not candidates:
        return pd.Series([None] * len(df), index=df.index)

    ser = df[candidates[0]].astype('string')

    if transform_to_apply == 'upper':
        ser = ser.str.upper()
    elif transform_to_apply == 'lower':
        ser = ser.str.lower()
    elif transform_to_apply == 'title':
        ser = ser.str.title()
    elif transform_to_apply == 'strip':
        ser = ser.str.strip()

    return ser


def _apply_regla_directo(df_src: pd.DataFrame, origen_spec: str, tipo_dato_dest: str) -> pd.Series:
    ser = _pick_from_spec(df_src, origen_spec)

    td = (tipo_dato_dest or '').strip().lower()
    if td == 'fecha':
        ser = pd.to_datetime(ser, errors='coerce').dt.strftime('%Y-%m-%d')
    elif td == 'numero':
        ser = pd.to_numeric(ser, errors='coerce')
    else:
        ser = ser.astype('string').fillna('')
    return ser

# SinergIA6000 - Resolver robusto de columnas origen (aliases/variantes)
import re
import unicodedata
import pandas as pd

def _norm_colname(x: str) -> str:
    s = "" if x is None else str(x)
    s = "".join(c for c in unicodedata.normalize("NFKD", s) if not unicodedata.combining(c))
    s = s.lower().strip()
    s = re.sub(r"[^a-z0-9]+", "", s)
    return s

def _resolve_src_col(df: pd.DataFrame, alias: str, extra_candidates=None) -> str:
    if df is None or df.empty:
        return ""
    if alias in df.columns:
        return alias

    cols = list(df.columns)
    norm_map = {_norm_colname(c): c for c in cols}

    # match normalizado
    a = _norm_colname(alias)
    if a in norm_map:
        return norm_map[a]

    # candidatos extra (por destino)
    cand_list = []
    if extra_candidates:
        cand_list.extend([c for c in extra_candidates if c])

    for cand in cand_list:
        if cand in df.columns:
            return cand
        nc = _norm_colname(cand)
        if nc in norm_map:
            return norm_map[nc]

    # fallback por "contains" (último recurso)
    for c in cols:
        if a and a in _norm_colname(c):
            return c

    return ""

# SinergIA6100
# OBJETIVO: Asegurar que la exportación Gestion use el MISMO DF limpio del pipeline Rutina→IN
#           y que Teléfono 1..4 sean SIEMPRE celulares CO válidos (10 dígitos, empiezan por '3').
#           Además, agregar SONDA006 para validar en 1 salida si el export cumple reglas de panel.

import pandas as pd

# ==============================
# 1) Normalizador celular CO
# ==============================

def _only_digits(x) -> str:
    s = '' if x is None else str(x)
    return ''.join(ch for ch in s if ch.isdigit())


def _normalize_co_mobile(x):
    """Devuelve un celular CO (10 dígitos, inicia por 3) o None.

    Maneja prefijo país 57 cuando viene pegado: 57XXXXXXXXXX -> XXXXXXXXXX.
    """
    d = _only_digits(x)
    if not d:
        return None

    # prefijo país
    if d.startswith('57') and len(d) == 12:
        d = d[2:]

    # ceros a la izquierda (casos típicos)
    if d.startswith('0') and len(d) == 11:
        d = d[1:]

    # regla dura: CO mobile
    if len(d) == 10 and d.startswith('3'):
        return d
    return None


# =============================================
# 2) REGLA_TELEFONOS (solo móviles, sin fijos)
# =============================================

def _parse_params(params: str) -> dict:
    out = {}
    for p in str(params).split(';'):
        if '=' in p:
            k, v = p.split('=', 1)
            out[k.strip().lower()] = v.strip()
    return out


def _apply_regla_telefonos(df: pd.DataFrame, params: str, use_all_phones: bool) -> pd.DataFrame:
    """Construye Telefono 1..4.

    REGLA CANÓNICA (CO): SOLO celulares. Nunca fijos.
    use_all_phones SOLO controla si llenamos Tel 3 y Tel 4 (True) o los dejamos vacíos (False).
    """
    P = _parse_params(params)

    # 2.1 Lista de columnas candidatas
    # Si Config trae Fijo/Fijo2, se ignoran de forma forzada.
    raw_cols = [c.strip() for c in P.get('cols', 'Celular,Celular2,Fijo,Fijo2').split(',') if c.strip()]
    cols = [c for c in raw_cols if 'fijo' not in c.strip().lower()]  # ignora fijos siempre

    # Si al filtrar quedaron 0, caemos al default móvil
    if not cols:
        cols = ['Celular', 'Celular2']

    # 2.2 Construye candidatos normalizados
    cands = []
    for c in cols:
        s = df[c] if c in df.columns else pd.Series([None] * len(df))
        s = s.map(_normalize_co_mobile)
        cands.append(s)

    def chain_pick(series_list):
        out = pd.Series([None] * len(df))
        for s in series_list:
            out = out.where(out.notna(), s)
        return out

    def remove_used(series_list, used):
        return [s.where(s != used, None) for s in series_list]

    tel1 = chain_pick(cands)
    tel2 = chain_pick(remove_used(cands, tel1))
    tel3 = chain_pick(remove_used(remove_used(cands, tel1), tel2))
    tel4 = chain_pick(remove_used(remove_used(remove_used(cands, tel1), tel2), tel3))

    if not use_all_phones:
        tel3 = pd.Series([None] * len(df))
        tel4 = pd.Series([None] * len(df))

    return pd.DataFrame({
        'Telefono 1': tel1.fillna(''),
        'Telefono 2': tel2.fillna(''),
        'Telefono 3': tel3.fillna(''),
        'Telefono 4': tel4.fillna(''),
    })


# =====================================================
# 3) SONDA006: auditoría de reglas aplicadas en export
# =====================================================

def SONDA006_export_audit(df_in: pd.DataFrame, panel_flags: dict) -> str:
    """Devuelve un string de auditoría PASS/FAIL.

    Espera que df_in ya sea el DF final (post-fix + orden) que se va a exportar.
    """
    cols_tel = [c for c in ['Telefono 1', 'Telefono 2', 'Telefono 3', 'Telefono 4'] if c in df_in.columns]

    def invalid_mobile_rate(series: pd.Series) -> float:
        s = series.fillna('').astype(str)
        s = s.map(_normalize_co_mobile)
        # si normalize devuelve None y el original no estaba vacío => inválido
        orig = series.fillna('').astype(str).map(_only_digits)
        invalid = (orig != '') & (s.isna())
        return float(invalid.mean())

    report = []
    missing = []

    # Teléfonos
    if cols_tel:
        inv_rates = {c: invalid_mobile_rate(df_in[c]) for c in cols_tel}
        worst = max(inv_rates.values()) if inv_rates else 0.0
        report.append(f"SONDA006 PHONES invalid_rate_max={worst:.6f} by_col={inv_rates}")
        if worst > 0:
            missing.append('REGLA_TELEFONOS mobile_only (hay no-celulares)')
    else:
        report.append('SONDA006 PHONES cols_missing=Telefono 1..4')
        missing.append('REGLA_TELEFONOS (cols ausentes)')

    # Upper
    if panel_flags.get('use_upper'):
        if 'Nombre Completo' in df_in.columns:
            s = df_in['Nombre Completo'].fillna('').astype(str)
            nonempty = s != ''
            if nonempty.any():
                upper_ok = (s[nonempty] == s[nonempty].str.upper()).mean()
                report.append(f"SONDA006 UPPER upper_ratio={float(upper_ok):.6f}")
                if upper_ok < 0.99:
                    missing.append('Texto en MAYÚSCULAS (no aplicado 100%)')
            else:
                report.append('SONDA006 UPPER Nombre Completo vacío')
                missing.append('Nombre Completo (vacío)')

    # Orden (verifica monotonicidad simple del primer key si existe)
    order_keys = panel_flags.get('order_keys') or []
    if order_keys:
        k0 = order_keys[0]
        if k0 in df_in.columns:
            s = pd.to_numeric(df_in[k0], errors='coerce')
            desc = bool(panel_flags.get('order_desc_flag'))
            mono = s.is_monotonic_decreasing if desc else s.is_monotonic_increasing
            report.append(f"SONDA006 ORDER key0={k0} desc={desc} monotonic={mono}")
            if not mono:
                missing.append('Ordenamiento (panel)')
        else:
            report.append(f"SONDA006 ORDER key0_missing={k0}")
            missing.append('Ordenamiento (col no existe)')

    status = 'PASS' if not missing else 'FAIL'
    report.append(f"SONDA006 RESULT={status} MISSING={missing}")
    return '\n'.join(report)


# =========================================================
