# SinergIA0870 - LATEST_RUN_DIR_POLICY: AUTO_PICK_LATEST_VALID (elige run más reciente con manifest.json válido)
import os
import json
import re
from datetime import datetime
from typing import Optional, Tuple, Any

# Patrón run_id: YYYYMMDD_HHMMSS_hex(8..16)
_RUNID_RE_LOCAL = re.compile(r"^\d{8}_\d{6}_[0-9a-f]{8,16}$", re.IGNORECASE)

def _sinergia__parse_iso_ts(ts: Any) -> Optional[float]:
    """Parsea ISO8601 a epoch.  Soporta sufijo 'Z'.  Retorna None si no parsea."""
    if not isinstance(ts, str) or not ts.strip():
        return None
    s = ts.strip().replace("Z", "+00:00")
    try:
        return datetime.fromisoformat(s).timestamp()
    except Exception:
        return None

def _sinergia__manifest_ok(run_dir: str) -> Tuple[bool, Optional[dict], Optional[float]]:
    """
    Validación mínima defendible:
    - existe manifest.json
    - parsea JSON
    - tiene run_id string no vacío
    Retorna (ok, manifest_dict, manifest_ts_epoch|None)
    """
    mf = os.path.join(run_dir, "manifest.json")
    if not os.path.isfile(mf):
        return False, None, None
    try:
        with open(mf, "r", encoding="utf-8") as f:
            man = json.load(f)
    except Exception:
        return False, None, None

    rid = man.get("run_id")
    if not isinstance(rid, str) or not rid.strip():
        return False, None, None

    ts = man.get("created_at") or man.get("started_at") or man.get("ts")
    ts_epoch = _sinergia__parse_iso_ts(ts)
    return True, man, ts_epoch

def sinergia_latest_run_dir(base: str = "/content/sinergia_runs") -> Optional[str]:
    """
    AUTO_PICK_LATEST_VALID:
    - ignora carpetas internas (_baselines/_indexes/etc)
    - filtra por patrón de run_id
    - requiere manifest.json válido
    - ordena por timestamp de manifest (si existe) y fallback por mtime
    """
    if not os.path.isdir(base):
        return None

    candidates = []
    for name in os.listdir(base):
        if not name or name.startswith("_"):
            continue
        if not _RUNID_RE_LOCAL.match(name):
            continue
        p = os.path.join(base, name)
        if not os.path.isdir(p):
            continue

        ok, man, ts_epoch = _sinergia__manifest_ok(p)
        if not ok:
            continue

        try:
            mtime = os.path.getmtime(p)
        except Exception:
            mtime = 0.0

        # Orden: primero ts_epoch si existe, luego mtime
        order_ts = ts_epoch if isinstance(ts_epoch, (int, float)) else 0.0
        candidates.append((order_ts, mtime, p))

    if not candidates:
        return None

    candidates.sort(key=lambda t: (t[0], t[1]))
    return candidates[-1][2]

# SinergIA0876 - Compat: mantener helper "clean" pero sin override global (anti-deriva)
def sinergia_latest_run_dir_clean(base: str = "/content/sinergia_runs") -> Optional[str]:
    """
    Compatibilidad: antes esta función reemplazaba globalmente sinergia_latest_run_dir.
    Ahora solo delega a la política canónica AUTO_PICK_LATEST_VALID.
    """
    return sinergia_latest_run_dir(base=base)

"""##Tools"""

# CODE_INDEXER: Inventario determinístico de bloques # SinergIAxxxx desde .py

import os, re, json, hashlib
from datetime import datetime

def _sha256_short(path: str, n: int = 12) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()[:n]

def sinergia_index_tags(
    py_path: str,
    *,
    out_dir: str = "/content/sinergia_runs/_indexes",
    max_desc_lines: int = 6,
) -> dict:
    """
    Extrae bloques cuyo header_line (línea 1 del bloque) contiene: '# SinergIA####' o '#SinergIA####'.
    Regresa meta + filas.  Escribe CSV y MD para pegar en el chat.
    """
    if not os.path.exists(py_path):
        raise FileNotFoundError(f"PY_NOT_FOUND: {py_path}")

    os.makedirs(out_dir, exist_ok=True)

    with open(py_path, "r", encoding="utf-8", errors="replace") as f:
        lines = f.readlines()

    total_lines = len(lines)
    bytes_sz = os.path.getsize(py_path)
    sha_short = _sha256_short(py_path)

    tag_pat = re.compile(r"^\s*#\s*SinergIA(\d{3,6})\b")
    blocks = []
    for i, line in enumerate(lines, start=1):
        m = tag_pat.match(line)
        if m:
            tag_num = m.group(1).zfill(4)  # normaliza a 4+ si venía corto
            tag = f"SinergIA{tag_num}"
            header = line.strip()
            blocks.append({"tag": tag, "header_line": i, "header": header})

    # calcular límites de bloque (start/end)
    for idx, b in enumerate(blocks):
        start = b["header_line"]
        end = (blocks[idx + 1]["header_line"] - 1) if idx + 1 < len(blocks) else total_lines
        b["end_line"] = end

        # descripción: primeras N líneas no vacías después del header
        desc = []
        funcs = []
        for j in range(start + 1, min(end + 1, start + 1 + 200)):
            t = lines[j - 1].rstrip("\n")
            if not t.strip():
                continue
            # capturar definiciones
            if re.match(r"^\s*(def|class)\s+", t):
                funcs.append(t.strip())
            # descripción tentativa: comentarios/docstring simples
            if t.strip().startswith("#") and len(desc) < max_desc_lines:
                desc.append(t.strip().lstrip("#").strip())
        b["desc"] = "  ".join(desc).strip()
        b["funcs"] = ", ".join(funcs[:8])  # sin ruido

    # duplicados
    counts = {}
    for b in blocks:
        counts[b["tag"]] = counts.get(b["tag"], 0) + 1

    dup_total = sum(1 for k, v in counts.items() if v > 1)

    # construir filas “cell”
    rows = []
    seen_idx = {}
    for n, b in enumerate(blocks, start=1):
        tag = b["tag"]
        seen_idx[tag] = seen_idx.get(tag, 0) + 1
        tag_disp = tag
        if counts.get(tag, 0) > 1:
            tag_disp = f"{tag} {seen_idx[tag]}/{counts[tag]}"

        rows.append({
            "cell": n,
            "etiqueta": tag_disp,
            "header_line": b["header_line"],
            "descripcion": b.get("desc", ""),
            "funciones_y_definiciones": b.get("funcs", ""),
        })

    first_tag = rows[0]["etiqueta"] if rows else None
    last_tag = rows[-1]["etiqueta"] if rows else None

    meta = {
        "source_file": os.path.basename(py_path),
        "sha256_corto": sha_short,
        "bytes": bytes_sz,
        "lineas": total_lines,
        "etiquetas_sinergia": len(rows),
        "duplicadas": int(dup_total),
        "primera": first_tag,
        "ultima": last_tag,
        "ts": datetime.now().isoformat(),
    }

    # escribir CSV
    csv_path = os.path.join(out_dir, "index_sinergia.csv")
    with open(csv_path, "w", encoding="utf-8") as f:
        f.write("cell,etiqueta,header_line,descripcion,funciones_y_definiciones\n")
        for r in rows:
            def esc(x):
                s = str(x).replace('"', '""')
                return f'"{s}"'
            f.write(",".join([esc(r["cell"]), esc(r["etiqueta"]), esc(r["header_line"]), esc(r["descripcion"]), esc(r["funciones_y_definiciones"])]) + "\n")

    # escribir MD (tabla lista para pegar)
    md_path = os.path.join(out_dir, "index_sinergia.md")
    with open(md_path, "w", encoding="utf-8") as f:
        f.write(f"Fuente única analizada: `{meta['source_file']}`.  \n")
        f.write(f"Ancla: sha256_corto={meta['sha256_corto']}.  bytes={meta['bytes']}.  líneas={meta['lineas']}.  etiquetas SinergIA={meta['etiquetas_sinergia']}.  duplicadas={meta['duplicadas']}.  \n\n")
        f.write("| cell | etiqueta | header_line | descripción | funciones y definiciones |\n")
        f.write("|---:|---|---:|---|---|\n")
        for r in rows:
            f.write(f"| {r['cell']} | {r['etiqueta']} | {r['header_line']} | {r['descripcion']} | {r['funciones_y_definiciones']} |\n")

    # escribir meta JSON
    meta_path = os.path.join(out_dir, "index_meta.json")
    with open(meta_path, "w", encoding="utf-8") as f:
        json.dump(meta, f, ensure_ascii=False, indent=2)

    print(f"INDEX_OK · file={meta['source_file']} · sha={meta['sha256_corto']} · tags={meta['etiquetas_sinergia']} · dup={meta['duplicadas']} · first={meta['primera']} · last={meta['ultima']}")
    print(f"INDEX_OUT · {md_path}")
    return {"meta": meta, "rows": rows, "out_dir": out_dir, "md_path": md_path, "csv_path": csv_path, "meta_path": meta_path}

# USO:
# sinergia_index_tags("/content/sinergia_cobranzas_20260102_02_starting.py")

import os

# 1) Encuentra candidatos .py en /content (y en tu carpeta de runs)
def _find_py_candidates(base="/content", limit=20):
    hits = []
    for root, _, files in os.walk(base):
        for fn in files:
            if fn.lower().endswith(".py") and "sinergia" in fn.lower():
                hits.append(os.path.join(root, fn))
    hits = sorted(hits, key=lambda p: os.path.getmtime(p))
    return hits[-limit:]

cands = _find_py_candidates("/content", limit=20)
print("PY candidates (últimos):")
for p in cands[-10:]:
    print(" -", p)

# 2) Elige el más reciente (o cambia py_path manualmente si quieres)
py_path = cands[-1] if cands else None
print("\nSELECTED =", py_path)

# 3) Ejecuta el indexador (esto sí imprime INDEX_OK)
if py_path:
    res = sinergia_index_tags(py_path)
    print("\nMD_PATH =", res["md_path"])
else:
    print("NO_PY_FOUND.  Sube/exporta el .py y vuelve a correr.")

