import os

def sinergia_latest_run_dir_clean(base="/content/sinergia_runs"):
    if not os.path.isdir(base):
        return None
    ds = []
    for d in os.listdir(base):
        p = os.path.join(base, d)
        if not os.path.isdir(p):
            continue
        if d.startswith("_"):   # ignora _baselines, _indexes, etc
            continue
        ds.append(p)
    return sorted(ds)[-1] if ds else None

