import os, sys, json, csv, hashlib
from datetime import datetime
import pandas as pd

BASELINES_DIR = "/content/sinergia_runs/_baselines"

def _safe_json(x):
    try:
        json.dumps(x, ensure_ascii=False)
        return x
    except Exception:
        return str(x)

def _rc_get_manifest(rc):
    m = getattr(rc, "manifest", None)
    return m if isinstance(m, dict) else {}

def _rc_get_events(rc):
    ev = getattr(rc, "events", None)
    if isinstance(ev, list):
        return ev
    ev2 = getattr(rc, "audit_events", None)
    return ev2 if isinstance(ev2, list) else []

def _pick_col(df: pd.DataFrame, candidates: list[str]) -> str:
    for c in candidates:
        if c in df.columns:
            return c
    return ""

def _hash_cols(cols_sorted: list[str]) -> str:
    s = "\n".join([str(c) for c in cols_sorted])
    return hashlib.sha256(s.encode("utf-8")).hexdigest()[:12]

def _baseline_path(key: str) -> str:
    safe = "".join(ch if ch.isalnum() or ch in ("_", "-", ".") else "_" for ch in str(key))
    return os.path.join(BASELINES_DIR, f"{safe}.json")

def _contract_gate_schema(rc, *, dataset_key: str, df, etapa: str, strict: bool = True) -> tuple[bool, dict]:
    os.makedirs(BASELINES_DIR, exist_ok=True)

    if df is None or not isinstance(df, pd.DataFrame):
        rep = {"ok": False, "reason": "DF_MISSING_OR_NOT_DF", "dataset_key": dataset_key}
        try:
            rc.set_manifest(f"gates.{etapa}_CONTRACT_{dataset_key}", rep)
            rc.add_event(f"{etapa}_CONTRACT_FAIL", level="ERROR", message=f"Contrato {dataset_key}: df no disponible.", data=rep, etapa=etapa)
        except Exception:
            pass
        return False, rep

    cols_sorted = sorted([str(c) for c in df.columns])
    cur_hash = _hash_cols(cols_sorted)
    p = _baseline_path(dataset_key)

    if not os.path.exists(p):
        baseline = {
            "dataset_key": dataset_key,
            "created_at": datetime.now().isoformat(),
            "cols_sorted": cols_sorted,
            "ncols": int(len(cols_sorted)),
            "schema_hash": cur_hash,
        }
        try:
            with open(p, "w", encoding="utf-8") as f:
                json.dump(baseline, f, ensure_ascii=False, indent=2)
        except Exception:
            pass

        rep = {"ok": True, "baseline_created": True, "schema_hash": cur_hash, "ncols": int(len(cols_sorted))}
        try:
            rc.set_manifest(f"contracts.{etapa}.{dataset_key}", {"schema_hash": cur_hash, "ncols": int(len(cols_sorted)), "cols_sorted": cols_sorted})
            rc.set_manifest(f"gates.{etapa}_CONTRACT_{dataset_key}", rep)
            rc.add_event(f"{etapa}_CONTRACT_BASELINE", level="INFO", message=f"Baseline creado para {dataset_key}.", data=rep, etapa=etapa)
        except Exception:
            pass
        return True, rep

    try:
        with open(p, "r", encoding="utf-8") as f:
            baseline = json.load(f)
    except Exception:
        baseline = {}

    base_cols = baseline.get("cols_sorted") or []
    base_hash = baseline.get("schema_hash") or _hash_cols(sorted([str(c) for c in base_cols]))

    ok = (cols_sorted == list(base_cols))
    rep = {
        "ok": bool(ok),
        "baseline_created": False,
        "schema_hash": cur_hash,
        "baseline_hash": base_hash,
        "ncols": int(len(cols_sorted)),
        "baseline_ncols": int(len(base_cols)),
        "diff_missing": sorted(list(set(base_cols) - set(cols_sorted)))[:50],
        "diff_extra": sorted(list(set(cols_sorted) - set(base_cols)))[:50],
    }

    try:
        rc.set_manifest(f"contracts.{etapa}.{dataset_key}", {
            "schema_hash": cur_hash,
            "baseline_hash": base_hash,
            "ncols": int(len(cols_sorted)),
            "baseline_ncols": int(len(base_cols)),
            "diff_missing": rep["diff_missing"],
            "diff_extra": rep["diff_extra"],
        })
        rc.set_manifest(f"gates.{etapa}_CONTRACT_{dataset_key}", rep)
        rc.add_event(
            f"{etapa}_CONTRACT_OK" if ok else f"{etapa}_CONTRACT_FAIL",
            level="INFO" if ok else "ERROR",
            message=f"Contrato {dataset_key} {'OK' if ok else 'FAIL'} (schema drift).",
            data=rep,
            etapa=etapa,
        )
    except Exception:
        pass

    if strict and not ok:
        return False, rep
    return True, rep

