# SinergIA1000 - DEV Runner PREVIEW PR_04+PR_06 (evidence-safe)
# Reemplazo completo del runner sinergia_dev_run_preview_pr04_pr06.
# Garantiza: run_dir + manifest.json + audit_events.jsonl/csv siempre.
# FIX: evita UnboundLocalError por nombres locales (_load_rutina_any_source / run_pipeline_rutina_to_in_full)

import os, json, csv
from datetime import datetime

def _rc_get_dir(rc):
    return getattr(rc, "dir", None) or getattr(rc, "run_dir", None) or ""

def _rc_get_manifest(rc):
    m = getattr(rc, "manifest", None)
    return m if isinstance(m, dict) else {}

def _rc_get_events(rc):
    ev = getattr(rc, "events", None)
    if isinstance(ev, list):
        return ev
    ev2 = getattr(rc, "audit_events", None)
    return ev2 if isinstance(ev2, list) else []

def _safe_json(obj):
    try:
        json.dumps(obj, ensure_ascii=False)
        return obj
    except Exception:
        return str(obj)

def _write_manifest_and_audit_fallback(rc, status="OK"):
    run_dir = _rc_get_dir(rc)
    if not run_dir:
        return {"ok": False, "reason": "NO_RUN_DIR"}

    os.makedirs(run_dir, exist_ok=True)

    manifest_path = os.path.join(run_dir, "manifest.json")
    jsonl_path = os.path.join(run_dir, "audit_events.jsonl")
    csv_path = os.path.join(run_dir, "audit_events.csv")

    manifest = _rc_get_manifest(rc)
    events = _rc_get_events(rc)

    # Completar mínimos si faltan
    manifest.setdefault("run_id", getattr(rc, "run_id", ""))
    manifest.setdefault("action", getattr(rc, "action", "DEV_RUNNER"))
    manifest.setdefault("started_at", manifest.get("started_at") or datetime.now().isoformat())
    manifest["ended_at"] = datetime.now().isoformat()
    manifest["status"] = manifest.get("status") or status

    wrote_manifest = False
    wrote_audit = False

    # Manifest (no destructivo: si existe, no sobrescribe)
    try:
        if not os.path.exists(manifest_path):
            with open(manifest_path, "w", encoding="utf-8") as f:
                json.dump(_safe_json(manifest), f, ensure_ascii=False, indent=2)
        wrote_manifest = os.path.exists(manifest_path)
    except Exception:
        wrote_manifest = False

    # Audit JSONL + CSV (header estable; si existe, no sobrescribe)
    try:
        if not os.path.exists(jsonl_path):
            with open(jsonl_path, "w", encoding="utf-8") as f:
                for e in events:
                    f.write(json.dumps(_safe_json(e), ensure_ascii=False) + "\n")
        if not os.path.exists(csv_path):
            with open(csv_path, "w", newline="", encoding="utf-8") as f:
                w = csv.writer(f)
                w.writerow(["ts", "run_id", "etapa", "code", "level", "message"])
                for e in events:
                    w.writerow([
                        e.get("ts", ""),
                        e.get("run_id", manifest.get("run_id","")),
                        e.get("etapa", e.get("stage","")),
                        e.get("code", ""),
                        e.get("level", ""),
                        e.get("message", ""),
                    ])
        wrote_audit = os.path.exists(jsonl_path) or os.path.exists(csv_path)
    except Exception:
        wrote_audit = False

    return {
        "ok": bool(wrote_manifest and wrote_audit),
        "run_dir": run_dir,
        "has_manifest": os.path.exists(manifest_path),
        "has_audit_jsonl": os.path.exists(jsonl_path),
        "has_audit_csv": os.path.exists(csv_path),
    }

def sinergia_dev_run_preview_pr04_pr06(
    rutina_name: str,
    *,
    max_rows: int = 5000,
    sample_rows: int = 0,
    corte_ano: int = 2026,
    corte_mes: str = "Ene",
):
    # Guardrails (order-safe)
    # Si el notebook ejecuta esta celda antes que las definiciones posteriores, definimos fallbacks mínimos.
    # IMPORTANTE: los fallbacks NO deben crear nombres locales con los mismos nombres “reales”.
    if "_load_rutina_any_source" not in globals() or not callable(globals().get("_load_rutina_any_source")):
        import pandas as pd
        from typing import Tuple, Optional

        def _fallback_load_rutina_any_source(
            dd_archivo_rutina: Optional[str],
            file_rutina_local,
            log: str,
            max_rows: int,
        ) -> Tuple[pd.DataFrame, str]:
            log = _log_append(log, "Inicio carga de Rutina (TER_UNISONO)...")

            # 1) Archivo local (prioridad)
            if file_rutina_local is not None:
                try:
                    name = getattr(file_rutina_local, "name", "archivo_local_rutina")
                    data = file_rutina_local.read()
                    log = _log_append(log, f"Usando archivo local Rutina: {name}")
                    df = _read_any_bytes_to_df(name, data, nrows=max_rows)
                    log = _log_append(log, f"Archivo local Rutina leído. Shape preview={df.shape}")
                    return df, log
                except Exception as e:
                    log = _log_append(log, f"Error leyendo archivo local Rutina: {e}")
                    return pd.DataFrame(), log

            # 2) Archivo en Drive
            if not dd_archivo_rutina:
                log = _log_append(log, "No se seleccionó Rutina en Drive ni archivo local.")
                return pd.DataFrame(), log

            folder_id = ""
            if "get_rutinas_folder_id" in globals() and callable(globals().get("get_rutinas_folder_id")):
                folder_id = get_rutinas_folder_id()

            if not folder_id:
                log = _log_append(log, "No se encontró ID de carpeta 'rutinas' en SettingID.")
                return pd.DataFrame(), log

            try:
                log = _log_append(log, f"Buscando archivo de Rutina en Drive: {dd_archivo_rutina}")
                df_drive, log = _leer_df_desde_drive(
                    tipo="RUTINA",
                    folder_id=folder_id,
                    archivo=dd_archivo_rutina,
                    log=log,
                    nrows=max_rows,
                )
                if df_drive is None:
                    return pd.DataFrame(), log
                log = _log_append(log, f"Rutina desde Drive leída. Shape preview={df_drive.shape}")
                return df_drive, log
            except Exception as e:
                log = _log_append(log, f"Error leyendo Rutina desde Drive: {e}")
                return pd.DataFrame(), log

        globals()["_load_rutina_any_source"] = _fallback_load_rutina_any_source

    if "run_pipeline_rutina_to_in_full" not in globals() or not callable(globals().get("run_pipeline_rutina_to_in_full")):
        import pandas as pd
        import unicodedata as _ud

        def _nk(x: str) -> str:
            s = str(x or "").strip().lower()
            s = "".join(ch for ch in _ud.normalize("NFKD", s) if not _ud.combining(ch))
            s = s.replace(" ", "").replace("_", "").replace("-", "")
            return s

        def _pick_best(df: pd.DataFrame, keys: list[str]) -> str | None:
            cols = list(df.columns)
            nk_cols = {c: _nk(c) for c in cols}
            for k in keys:
                kk = _nk(k)
                for c, nc in nk_cols.items():
                    if kk == nc or kk in nc:
                        return c
            return None

        def _fallback_run_pipeline_rutina_to_in_full(
            df_rutina: pd.DataFrame | None = None,
            log: str = "",
            use_ints: bool = False,
            use_all_phones: bool = False,
            use_upper: bool = True,
            order_keys: list | None = None,
            order_desc_flag: bool = False,
            df: pd.DataFrame | None = None,
            **_,
        ) -> tuple[pd.DataFrame, str]:
            # soporte compat
            if df_rutina is None and df is not None:
                df_rutina = df
            if df_rutina is None or df_rutina is ...:
                return pd.DataFrame(), _log_append(log, "Pipeline Rutina→IN: df_rutina vacío.")

            # Intento 1: si existe normalize_rutina_to_in, úsalo.
            if "normalize_rutina_to_in" in globals() and callable(globals().get("normalize_rutina_to_in")):
                try:
                    return normalize_rutina_to_in(df_rutina, None, log)
                except Exception:
                    pass

            # Fallback mínimo: construir esquema IN_SISTECREDITO desde Estructuras (gsheet) + mapeos heurísticos.
            if "read_gsheet" not in globals() or "CONFIG_SPREADSHEET_ID" not in globals():
                raise RuntimeError("ABORT · No hay read_gsheet/CONFIG_SPREADSHEET_ID para construir IN_SISTECREDITO (fallback).")

            df_es = read_gsheet(CONFIG_SPREADSHEET_ID, "Estructuras")
            df_in = df_es[df_es["ArchivoLogico"].astype(str) == "IN_SISTECREDITO"].copy()
            df_in = df_in.sort_values("ColumnaOrden", kind="mergesort")

            expected_cols = df_in["NombreColumna"].astype(str).tolist()
            expected_types = dict(zip(df_in["NombreColumna"].astype(str), df_in["TipoDato"].astype(str)))

            out = pd.DataFrame(index=df_rutina.index)
            for col in expected_cols:
                # 1) exacto
                if col in df_rutina.columns:
                    out[col] = df_rutina[col]
                    continue

                # 2) heurísticas mínimas por campos críticos
                if col == "Documento de identidad":
                    src = _pick_best(df_rutina, ["Identificacion", "Identificación", "Documento", "DocumentoIdentidad", "Cedula", "Cédula", "CC", "ID"])
                    out[col] = df_rutina[src] if src else pd.NA
                    continue

                if col == "Nombre Completo":
                    src = _pick_best(df_rutina, ["Upper", "Nombre Completo", "Nombre", "Nombres", "Cliente", "NombreCliente"])
                    out[col] = df_rutina[src] if src else pd.NA
                    continue

                if col == "Dirección Del Cliente":
                    src = _pick_best(df_rutina, ["DireccionResidencia", "Dirección", "Direccion", "DireccionDelCliente", "DireccionCliente"])
                    out[col] = df_rutina[src] if src else pd.NA
                    continue

                out[col] = pd.NA

            # Telefonos 1..4: toma columnas candidatas en orden
            phone_candidates = [c for c in df_rutina.columns if "tel" in _nk(c) or "cel" in _nk(c)]
            for i in range(1, 5):
                tgt = f"Telefono {i}"
                if tgt in expected_cols:
                    src = phone_candidates[i - 1] if len(phone_candidates) >= i else None
                    out[tgt] = df_rutina[src] if src else pd.NA

            # Tipado mínimo
            for c in out.columns:
                t = str(expected_types.get(c, "")).strip().lower()
                if "fecha" in t:
                    out[c] = pd.to_datetime(out[c], errors="coerce", dayfirst=True)
                elif "numero" in t:
                    out[c] = pd.to_numeric(out[c], errors="coerce")

            # Orden determinístico si aplica
            if order_keys:
                keys = [k for k in order_keys if k in out.columns]
                if keys:
                    out = out.sort_values(keys, ascending=not bool(order_desc_flag), kind="mergesort")

            return out[expected_cols], _log_append(log, f"Pipeline Rutina→IN: fallback mínimo OK. Shape={out.shape}")

        globals()["run_pipeline_rutina_to_in_full"] = _fallback_run_pipeline_rutina_to_in_full

    _required = [
        "_load_rutina_any_source",
        "run_pipeline_rutina_to_in_full",
        "sinergia_pr06_build_teleton_y_bolsas_min",
        "sinergia_new_run_context",
        "_write_manifest_and_audit_fallback",
        "_rc_get_dir",
    ]
    _missing = [n for n in _required if n not in globals() or not callable(globals().get(n))]
    if _missing:
        raise RuntimeError(f"ABORT · faltan definiciones: {_missing}")

    log = globals().get("log", "")

    # Alias (siempre por globals; nunca por nombre directo)
    _load_rut = globals().get("_load_rutina_any_source")
    if not callable(_load_rut):
        raise RuntimeError("ABORT · _load_rutina_any_source no está disponible (callable=False)")

    _run_pipe = globals().get("run_pipeline_rutina_to_in_full")
    if not callable(_run_pipe):
        raise RuntimeError("ABORT · run_pipeline_rutina_to_in_full no está disponible (callable=False)")

    # 1) PREVIEW rutina por nombre (no depende de GUI)
    df_rut_prev, log = _load_rut(rutina_name, None, log, max_rows=max_rows)

    # 2) BASE (canon: Rutina -> IN)  (FIX: usar alias _run_pipe)
    df_in_prev, log = _run_pipe(
        df_rutina=df_rut_prev,
        log=log,
        use_ints=True,
        use_all_phones=True,
        use_upper=True,
        order_keys=["Documento de identidad"],
        order_desc_flag=False,
    )
    df_base_cobranza = df_in_prev

    # 3) RunContext (único)
    rc = sinergia_new_run_context(
        "DEV_PREVIEW_PR04_PR06",
        meta={
            "rutina_name": rutina_name,
            "max_rows": int(max_rows),
            "corte_ano": int(corte_ano),
            "corte_mes": str(corte_mes),
        },
    )

    # Registrar base en manifest (si existe setter)
    try:
        if hasattr(rc, "set_manifest") and callable(getattr(rc, "set_manifest")):
            rc.set_manifest("inputs.df_base_cobranza_shape", getattr(df_base_cobranza, "shape", None))
            rc.set_manifest("gates.PR_04_BASE", {"ok": True})
        elif hasattr(rc, "manifest") and isinstance(rc.manifest, dict):
            rc.manifest.setdefault("inputs", {})
            rc.manifest["inputs"]["df_base_cobranza_shape"] = getattr(df_base_cobranza, "shape", None)
            rc.manifest.setdefault("gates", {})
            rc.manifest["gates"]["PR_04_BASE"] = {"ok": True}
    except Exception:
        pass


    # 3.5) QUALITY_IN Gate (si está disponible)  [NO toca export AWS]
    ok_quality_in = None
    try:
        _qgin = globals().get("sinergia_quality_gate_in")
        if callable(_qgin):
            ok_quality_in, _ = _qgin(df_base_cobranza, log="")
            # manifest
            if hasattr(rc, "set_manifest") and callable(getattr(rc, "set_manifest")):
                rc.set_manifest("gates.PR_QUALITY_IN", {"ok": bool(ok_quality_in)})
            elif hasattr(rc, "manifest") and isinstance(rc.manifest, dict):
                rc.manifest.setdefault("gates", {})
                rc.manifest["gates"]["PR_QUALITY_IN"] = {"ok": bool(ok_quality_in)}
            # audit
            if hasattr(rc, "add_event") and callable(getattr(rc, "add_event")):
                rc.add_event(
                    "PR_QUALITY_IN_OK" if ok_quality_in else "PR_QUALITY_IN_FAIL",
                    level="INFO" if ok_quality_in else "ERROR",
                    message="QualityGate IN OK." if ok_quality_in else "QualityGate IN FAIL.",
                    data={"rows": int(len(df_base_cobranza)) if hasattr(df_base_cobranza, "__len__") else None},
                    etapa="PR_04",
                )
        else:
            # degradable: no existe la función aún
            if hasattr(rc, "set_manifest") and callable(getattr(rc, "set_manifest")):
                rc.set_manifest("gates.PR_QUALITY_IN", {"ok": None, "reason": "MISSING_FN"})
                rc.set_manifest("modo_degradado", True)
                rc.set_manifest("degradado_reasons", ["QUALITY_IN_MISSING_FN"])
    except Exception:
        pass

    # Reemplaza la línea de print existente por esta (misma línea, más info, sin ruido extra)
    print(f"DEV base_shape={getattr(df_base_cobranza,'shape',None)} · PR_04_BASE.ok=True · QUALITY_IN={ok_quality_in}")

    # print(f"DEV base_shape={getattr(df_base_cobranza,'shape',None)} · PR_04_BASE.ok=True")

    # 4) PR_06 (usa el mismo rc para que todo quede en un run_dir)
    status = "OK"
    try:
        df_tele, df_bolsas, log, rc2 = sinergia_pr06_build_teleton_y_bolsas_min(
            df_base_cobranza,
            log=log,
            rc=rc,
            meta={"corte_ano": int(corte_ano), "corte_mes": str(corte_mes)},
            sample_rows=int(sample_rows),
        )
        rc = rc2 or rc
        status = "OK"
    except Exception as e:
        status = "FAIL"
        try:
            if hasattr(rc, "add_event") and callable(getattr(rc, "add_event")):
                rc.add_event("DEV_RUNNER_FAIL", level="ERROR", message=str(e), etapa="DEV_RUNNER")
        except Exception:
            pass
        df_tele, df_bolsas = None, None

    # 5) Forzar persistencia de evidencia (aunque PR_06 ya haya finalizado)
    try:
        if hasattr(rc, "finalize") and callable(getattr(rc, "finalize")):
            rc.finalize(status)
    except Exception:
        pass

    rep = _write_manifest_and_audit_fallback(rc, status=status)

    print(f"DEV run_id={getattr(rc,'run_id',None)}")
    print(f"DEV run_dir={_rc_get_dir(rc)}")
    print(f"DEV evidence_written={rep.get('ok',False)} manifest={rep.get('has_manifest',False)} audit_jsonl={rep.get('has_audit_jsonl',False)} audit_csv={rep.get('has_audit_csv',False)}")

    return df_base_cobranza, df_tele, df_bolsas, log, rc

# SinergIA1100 - DEV_RUNNER_PR04_PR07 (sin GUI, evidencia mínima, no toca export AWS)
# Inserción: debajo de SinergIA0129 y arriba de SinergIA0130.

from datetime import datetime
import os, json

def sinergia_dev_run_preview_pr04_pr07(
    *,
    rutina_name: str,
    aws_log_filename: str | None = None,
    max_rows: int = 5000,
    corte_ano: int = 2026,
    corte_mes: str = "Ene",
    strict_no_history: bool = True,
    evidence_rows: int = 0,   # 0 = no escribe samples extra
) -> dict:
    """
    Runner DEV único:
    - PR_04_BASE (usa canon Rutina→IN existente vía sinergia_dev_run_preview_pr04_pr06)
    - PR_06 (Teletón+Bolsas)
    - (opcional) PR_03.5 Enrich con historial AWS (si aws_log_filename)
    - PR_07 ComplianceGate mínimo
    Devuelve dict con dfs y run_dir.  No usa GUI.  No toca export AWS.
    """

    t0 = datetime.now()

    # Guardrails
    need = ["sinergia_dev_run_preview_pr04_pr06", "sinergia_pr07_compliance_gate_min"]
    miss = [n for n in need if n not in globals() or not callable(globals().get(n))]
    if miss:
        raise RuntimeError(f"ABORT · faltan definiciones: {miss}")

    # 1) PR_04 + PR_06 (runner ya existente)
    df_base, df_tele, df_bolsas, log, rc = sinergia_dev_run_preview_pr04_pr06(
        rutina_name=rutina_name,
        max_rows=max_rows,
        sample_rows=0,  # samples de Teletón se controlan en PR_06, aquí lo dejamos quieto
        corte_ano=corte_ano,
        corte_mes=corte_mes,
    )

    # 2) (opcional) cargar AWS_Log por nombre (sin GUI) y enriquecer base con PR_03.5
    has_hist = False
    non_null_last = 0
    if aws_log_filename:
        if "_load_aws_any_source" not in globals() or not callable(globals().get("_load_aws_any_source")):
            raise RuntimeError("ABORT · _load_aws_any_source no está definido.  Ejecuta el bloque de carga AWS_Log.")
        df_aws, log = _load_aws_any_source(dd_archivo_aws=aws_log_filename, file_aws_local=None, log=log, max_rows=max_rows)
        globals()["DF_AWS_CACHE"] = df_aws.copy()

        if "sinergia_pr035_enrich_base_with_contact_history" in globals() and callable(globals().get("sinergia_pr035_enrich_base_with_contact_history")):
            df_base, log, rc = sinergia_pr035_enrich_base_with_contact_history(
                df_base,
                log=log,
                rc=rc,
                max_rows_aws=max_rows,
                out_col_last_contact="Fecha Ult Contacto",
            )
            has_hist = ("Fecha Ult Contacto" in df_base.columns)
            non_null_last = int(df_base["Fecha Ult Contacto"].notna().sum()) if has_hist else 0
        else:
            # degradable: hay AWS, pero no existe PR_03.5 implementado
            rc.set_manifest("modo_degradado", True)
            rc.set_manifest("degradado_reasons", (rc.manifest.get("degradado_reasons", []) if isinstance(getattr(rc, "manifest", {}), dict) else []) + ["PR_03_5_MISSING"])

    # 3) PR_07 ComplianceGate
    df_el, df_ex, log, rc = sinergia_pr07_compliance_gate_min(
        df_base,
        log=log,
        rc=rc,
        strict_no_history=bool(strict_no_history),
        dev_override_allow_pass=False,
        sample_rows=0,
    )

    # 4) Evidencia mínima adicional (opcional)
    if int(evidence_rows) > 0:
        n = int(min(int(evidence_rows), len(df_base)))
        try:
            p1 = os.path.join(rc.dir, f"base_sample_{n}.csv")
            df_base.head(n).to_csv(p1, index=False, encoding="utf-8")
            rc.set_manifest("outputs.base_sample", os.path.basename(p1))
        except Exception as e:
            rc.add_event("DEV_WARN", level="WARN", message=f"No se pudo escribir base_sample: {e}", etapa="DEV")

        try:
            n2 = int(min(int(evidence_rows), len(df_el)))
            p2 = os.path.join(rc.dir, f"eligible_sample_{n2}.csv")
            df_el.head(n2).to_csv(p2, index=False, encoding="utf-8")
            rc.set_manifest("outputs.eligible_sample", os.path.basename(p2))
        except Exception as e:
            rc.add_event("DEV_WARN", level="WARN", message=f"No se pudo escribir eligible_sample: {e}", etapa="DEV")

        try:
            p3 = os.path.join(rc.dir, "dev_summary.json")
            summary = {
                "rutina_name": rutina_name,
                "aws_log_filename": aws_log_filename,
                "base_shape": list(getattr(df_base, "shape", (None, None))),
                "teleton_shape": list(getattr(df_tele, "shape", (None, None))),
                "bolsas_shape": list(getattr(df_bolsas, "shape", (None, None))),
                "has_last_contact": bool(has_hist),
                "non_null_last_contact": int(non_null_last),
                "eligible_rows": int(len(df_el)),
                "excluded_rows": int(len(df_ex)),
                "run_id": rc.run_id,
                "run_dir": rc.dir,
                "ts_start": t0.isoformat(),
                "ts_end": datetime.now().isoformat(),
            }
            with open(p3, "w", encoding="utf-8") as f:
                json.dump(summary, f, ensure_ascii=False, indent=2)
            rc.set_manifest("outputs.dev_summary", os.path.basename(p3))
        except Exception:
            pass

    # retorno unificado (evita “too many values to unpack”)
    return {
        "df_base_cobranza": df_base,
        "df_teleton_general": df_tele,
        "df_bolsas": df_bolsas,
        "df_eligible": df_el,
        "df_excluded": df_ex,
        "run_id": rc.run_id,
        "run_dir": rc.dir,
        "has_last_contact": bool(has_hist),
        "non_null_last_contact": int(non_null_last),
        "rc": rc,
        "log": log,
    }

# SinergIA1600 - QA_CALL: DEV_RUNNER → cargar AWS_Log por nombre → PR_03.5 → PR_07 (sin GUI)
import os, sys, json, csv
from datetime import datetime

AWS_LOG_FILENAME = "10_00_MejorGest_Log_Noviembre_2025.xlsx"  # <-- cámbialo al que esté en tu Drive/carpeta


# Guard order-safe: si aún no existe _load_aws_any_source (definida más abajo), la definimos aquí.
if "_load_aws_any_source" not in globals() or not callable(globals().get("_load_aws_any_source")):
    import pandas as pd
    from typing import Tuple, Optional

    _PREVIEW_ROWS_AWS_FALLBACK = 5000

    def _load_aws_any_source(
        dd_archivo_aws: Optional[str],
        file_aws_local,
        log: str,
        max_rows: int = _PREVIEW_ROWS_AWS_FALLBACK,
    ) -> Tuple[pd.DataFrame, str]:
        log = _log_append(log, "Inicio carga de AWS_Log...")

        # 1) Archivo local (prioridad)
        if file_aws_local is not None:
            try:
                name = getattr(file_aws_local, "name", "archivo_local_aws")
                data = file_aws_local.read()
                log = _log_append(log, f"Usando archivo local AWS: {name}")

                df = _read_any_bytes_to_df(name, data, nrows=max_rows)
                log = _log_append(log, f"Archivo local AWS leído. Shape preview={df.shape}")
                return df, log
            except Exception as e:
                log = _log_append(log, f"Error leyendo archivo local AWS: {e}")
                return pd.DataFrame(), log

        # 2) Archivo en Drive
        if not dd_archivo_aws:
            log = _log_append(log, "No se seleccionó archivo AWS en Drive ni archivo local.")
            return pd.DataFrame(), log

        folder_id = ""
        if "get_aws_folder_id" in globals() and callable(globals().get("get_aws_folder_id")):
            folder_id = get_aws_folder_id()

        if not folder_id:
            log = _log_append(log, "No se encontró ID de carpeta 'AWS_Log' en SettingID.")
            return pd.DataFrame(), log

        try:
            log = _log_append(log, f"Buscando archivo AWS en Drive: {dd_archivo_aws}")
            df_drive, log = _leer_df_desde_drive(
                tipo="AWS",
                folder_id=folder_id,
                archivo=dd_archivo_aws,
                log=log,
                nrows=max_rows,
            )
            if df_drive is None:
                return pd.DataFrame(), log
            log = _log_append(log, f"AWS desde Drive leído. Shape preview={df_drive.shape}")
            return df_drive, log
        except Exception as e:
            log = _log_append(log, f"Error leyendo AWS desde Drive: {e}")
            return pd.DataFrame(), log

