# SinergIA1740 - DEV_RUNNER_E2E: PR_04 -> PR_06 -> PR_03.5 -> PR_07 -> PR_08_MULTI (una sola llamada)

from datetime import datetime

def sinergia_dev_run_e2e_pr04_to_pr08(
    *,
    rutina_name: str,
    aws_log_filename: str | None = None,
    max_rows: int = 5000,
    corte_ano: int = 2026,
    corte_mes: str = "Ene",
    strict_no_history: bool = True,
    publish_aliases: list[str] | None = None,
) -> dict:
    """
    Runner DEV único (sin GUI):
    - PR_04_BASE + QUALITY_IN (canon Rutina->IN)  [no toca Export AWS]
    - PR_06 Teletón + Bolsas (wiring mínimo)
    - PR_03 Contract (df_base_cobranza)
    - PR_03.5 Enrich con historial AWS (si aws_log_filename)
    - PR_07 ComplianceGate
    - PR_08_MULTI Listas (WhatsApp/Wise/SMS) + publicación a Drive (Listas_Trabajo_Genesys)
    Retorna dict con dfs + run_id/run_dir + results PR_08.
    """
    t0 = datetime.now()

    # Guardrails mínimos
    need = [
        "sinergia_dev_run_preview_pr04_pr06",
        "sinergia_pr07_compliance_gate_min",
        "sinergia_pr08_publish_multi",
    ]
    miss = [n for n in need if n not in globals() or not callable(globals().get(n))]
    if miss:
        raise RuntimeError(f"ABORT · faltan definiciones: {miss}")

    # 1) PR_04 + PR_06 (canon)
    df_base, df_tele, df_bolsas, log, rc = sinergia_dev_run_preview_pr04_pr06(
        rutina_name=rutina_name,
        max_rows=max_rows,
        sample_rows=0,
        corte_ano=corte_ano,
        corte_mes=corte_mes,
    )

    # 2) PR_03 Contract (si existe validador)
    if "sinergia_pr03_contract_gate" in globals() and callable(globals().get("sinergia_pr03_contract_gate")):
        df_base, log, rc = sinergia_pr03_contract_gate(
            df_base,
            log=log,
            rc=rc,
            archivo_logico="IN_SISTECREDITO",
            sistema="SinergIA",
        )

    # 3) PR_03.5 historial (opcional)
    if aws_log_filename:
        if "_load_aws_any_source" not in globals() or not callable(globals().get("_load_aws_any_source")):
            raise RuntimeError("ABORT · _load_aws_any_source no está definido (bloque AWS_Log no ejecutado).")

        df_aws, log = _load_aws_any_source(dd_archivo_aws=aws_log_filename, file_aws_local=None, log=log, max_rows=max_rows)
        if df_aws is not None and getattr(df_aws, "shape", (0, 0))[0] > 0:
            globals()["DF_AWS_CACHE"] = df_aws.copy()
            if "sinergia_pr035_enrich_base_with_contact_history" in globals() and callable(globals().get("sinergia_pr035_enrich_base_with_contact_history")):
                df_base, log, rc = sinergia_pr035_enrich_base_with_contact_history(
                    df_base,
                    log=log,
                    rc=rc,
                    max_rows_aws=max_rows,
                    out_col_last_contact="Fecha Ult Contacto",
                )
            else:
                if hasattr(rc, "set_manifest") and callable(getattr(rc, "set_manifest")):
                    rc.set_manifest("modo_degradado", True)
                    rc.set_manifest("degradado_reasons", ["PR_03_5_MISSING"])

    # 4) PR_07
    df_el, df_ex, log, rc = sinergia_pr07_compliance_gate_min(
        df_base,
        log=log,
        rc=rc,
        strict_no_history=bool(strict_no_history),
        dev_override_allow_pass=False,
        sample_rows=0,
    )

    # 5) PR_08 MULTI
    publish_aliases = publish_aliases or ["DIGITAL_WHATSAPP", "DIGITAL_WISE", "DIGITAL_SMS"]
    pr08_results, log = sinergia_pr08_publish_multi(
        df_eligible=df_el,
        rc=rc,
        log=log,
        sistema="SinergIA",
        aliases=publish_aliases,
        require_pr07_ok=True,
    )

    # 6) Resumen limpio (3 líneas)
    print("DEV_E2E · run_id =", getattr(rc, "run_id", None))
    print("DEV_E2E · run_dir =", getattr(rc, "dir", None))
    print("DEV_E2E · PR_08 published =", {k: v.get("published") for k, v in (pr08_results or {}).items()})

    return {
        "df_base_cobranza": df_base,
        "df_teleton_general": df_tele,
        "df_bolsas": df_bolsas,
        "df_eligible": df_el,
        "df_excluded": df_ex,
        "pr08_results": pr08_results,
        "run_id": getattr(rc, "run_id", None),
        "run_dir": getattr(rc, "dir", None),
        "rc": rc,
        "log": log,
        "ts_start": t0.isoformat(),
        "ts_end": datetime.now().isoformat(),
    }

