# SinergIA0860 - SONDA_PACK (dump compacto de evidencia por run_dir)

import os, json, csv
from datetime import datetime

def sinergia_sonda_pack(run_dir: str, *, max_events: int = 5) -> dict:
    """
    Retorna un resumen compacto para pegar en el chat.
    No imprime DataFrames.  Lee manifest.json y audit_events.csv/jsonl si existen.
    """
    out = {
        "ts": datetime.now().isoformat(),
        "run_dir": run_dir,
        "files": [],
        "manifest": {},
        "events_head": [],
    }

    if not run_dir or not os.path.isdir(run_dir):
        out["error"] = "RUN_DIR_NOT_FOUND"
        return out

    files = sorted(os.listdir(run_dir))
    out["files"] = [f for f in files if f.endswith((".json", ".jsonl", ".csv", ".xlsx"))]

    manifest_path = os.path.join(run_dir, "manifest.json")
    if os.path.exists(manifest_path):
        try:
            with open(manifest_path, "r", encoding="utf-8") as f:
                m = json.load(f)
            # Solo claves relevantes
            out["manifest"] = {
                "run_id": m.get("run_id"),
                "status": m.get("status"),
                "started_at": m.get("started_at"),
                "ended_at": m.get("ended_at"),
                "gates": m.get("gates", {}),
                "metrics": m.get("metrics", {}),
                "modo_degradado": m.get("modo_degradado", False),
                "degradado_reasons": m.get("degradado_reasons", []),
                "summary": m.get("summary", {}),
            }
        except Exception as e:
            out["manifest_error"] = str(e)

    # Prefer CSV (más fácil de leer)
    csv_path = os.path.join(run_dir, "audit_events.csv")
    if os.path.exists(csv_path):
        try:
            with open(csv_path, "r", encoding="utf-8") as f:
                r = csv.DictReader(f)
                head = []
                for i, row in enumerate(r):
                    if i >= int(max_events):
                        break
                    head.append({
                        "ts": row.get("ts",""),
                        "run_id": row.get("run_id",""),
                        "etapa": row.get("etapa",""),
                        "code": row.get("code",""),
                        "level": row.get("level",""),
                        "message": row.get("message",""),
                    })
            out["events_head"] = head
        except Exception as e:
            out["events_error"] = str(e)
    else:
        jsonl_path = os.path.join(run_dir, "audit_events.jsonl")
        if os.path.exists(jsonl_path):
            try:
                head = []
                with open(jsonl_path, "r", encoding="utf-8") as f:
                    for i, line in enumerate(f):
                        if i >= int(max_events):
                            break
                        head.append(json.loads(line))
                out["events_head"] = head
            except Exception as e:
                out["events_error"] = str(e)

    return out

def sinergia_print_sonda_pack(run_dir: str) -> None:
    d = sinergia_sonda_pack(run_dir)
    print("SONDA_PACK · run_dir =", d.get("run_dir"))
    m = d.get("manifest", {}) or {}
    print("SONDA_PACK · run_id  =", m.get("run_id"))
    g = m.get("gates", {}) or {}
    # imprime solo gates más comunes (si existen)
    for k in ["PR_03_5", "PR_04_BASE", "PR_06", "PR_07", "PR_08"]:
        if k in g:
            print(f"SONDA_PACK · gates.{k} =", g.get(k))
    # archivos
    print("SONDA_PACK · files  =", d.get("files", []))
    # 3 eventos
    ev = d.get("events_head", [])[:3]
    if ev:
        print("SONDA_PACK · events_head =", ev)

# SinergIA0880 - GOLDEN_BASELINE: freeze + check (antideriva) desde run_dir (NO toca Export AWS)

import os, json, shutil
from datetime import datetime

def sinergia_freeze_baseline(*, run_dir: str, baseline_name: str = "GOLDEN_PR04_PR08_V1") -> str:
    if not run_dir or not os.path.isdir(run_dir):
        raise FileNotFoundError(f"RUN_DIR_NOT_FOUND: {run_dir}")

    base_root = "/content/sinergia_runs/_baselines"
    out_dir = os.path.join(base_root, baseline_name)
    os.makedirs(out_dir, exist_ok=True)

    manifest_path = os.path.join(run_dir, "manifest.json")
    if not os.path.isfile(manifest_path):
        raise FileNotFoundError(f"MANIFEST_NOT_FOUND: {manifest_path}")

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # artefactos a copiar (mínimo)
    to_copy = ["manifest.json", "audit_events.csv", "audit_events.jsonl"]
    for fn in to_copy:
        src = os.path.join(run_dir, fn)
        if os.path.isfile(src):
            shutil.copy2(src, os.path.join(out_dir, fn))

    # copia también XLSX de listas (evidencia funcional PR_08)
    xlsx = sorted([f for f in os.listdir(run_dir) if f.lower().endswith(".xlsx")])
    for fn in xlsx:
        shutil.copy2(os.path.join(run_dir, fn), os.path.join(out_dir, fn))

    gates = (manifest.get("gates", {}) or {})
    g03 = gates.get("PR_03_CONTRACT", {}) if isinstance(gates.get("PR_03_CONTRACT", {}), dict) else {}
    schema_hash = g03.get("schema_hash")
    contract_id = g03.get("contract_id")

    # baseline meta (reglas mínimas)
    meta = {
        "baseline_name": baseline_name,
        "frozen_at": datetime.now().isoformat(),
        "run_id": manifest.get("run_id"),
        "source_run_dir": run_dir,
        "schema_hash": schema_hash,
        "contract_id": contract_id,
        "expected_gates_ok": {
            "PR_QUALITY_IN": True,
            "PR_EXPORT_AWS": True,
            "PR_07": True,
        },
        "expected_pr08_published": {
            "DIGITAL_WHATSAPP": True,
            "DIGITAL_WISE": True,
            "DIGITAL_SMS": True,
        },
        "files": {
            "copied_core": [fn for fn in to_copy if os.path.isfile(os.path.join(out_dir, fn))],
            "copied_xlsx": xlsx,
        },
    }

    with open(os.path.join(out_dir, "baseline_meta.json"), "w", encoding="utf-8") as f:
        json.dump(meta, f, ensure_ascii=False, indent=2)

    print("BASELINE_FREEZE · ok=True")
    print("BASELINE_FREEZE · dir =", out_dir)
    print("BASELINE_FREEZE · xlsx =", xlsx)
    return out_dir

def sinergia_check_baseline(*, run_dir: str, baseline_name: str = "GOLDEN_PR04_PR08_V1") -> dict:
    base_dir = os.path.join("/content/sinergia_runs/_baselines", baseline_name)
    meta_path = os.path.join(base_dir, "baseline_meta.json")
    man_path = os.path.join(run_dir, "manifest.json")

    if not os.path.isfile(meta_path):
        raise FileNotFoundError(f"BASELINE_META_NOT_FOUND: {meta_path}")
    if not os.path.isfile(man_path):
        raise FileNotFoundError(f"MANIFEST_NOT_FOUND: {man_path}")

    with open(meta_path, "r", encoding="utf-8") as f:
        meta = json.load(f)
    with open(man_path, "r", encoding="utf-8") as f:
        man = json.load(f)

    gates = (man.get("gates", {}) or {})
    probs = []

    # gates ok mínimos
    for k, v in (meta.get("expected_gates_ok") or {}).items():
        ok = (gates.get(k, {}) or {}).get("ok") if isinstance(gates.get(k, {}), dict) else None
        if ok != v:
            probs.append(f"GATE_MISMATCH {k}: got={ok} exp={v}")

    # schema hash mínimo
    g03 = gates.get("PR_03_CONTRACT", {}) if isinstance(gates.get("PR_03_CONTRACT", {}), dict) else {}
    if meta.get("schema_hash") and g03.get("schema_hash") != meta.get("schema_hash"):
        probs.append(f"SCHEMA_HASH_MISMATCH got={g03.get('schema_hash')} exp={meta.get('schema_hash')}")

    # PR_08 published (por canal) - usa manifest gates.PR_08_* si existen
    exp08 = meta.get("expected_pr08_published") or {}
    for al, exp in exp08.items():
        g = gates.get(f"PR_08_{al}", None)
        pub = (g or {}).get("published") if isinstance(g, dict) else None
        if pub != exp:
            probs.append(f"PR08_PUBLISHED_MISMATCH {al}: got={pub} exp={exp}")

    out = {"ok": (len(probs) == 0), "problems": probs, "baseline": base_dir, "run_dir": run_dir}
    print("BASELINE_CHECK · ok =", out["ok"])
    if probs:
        print("BASELINE_CHECK · problems =", probs[:5])
    return out

# USO (con tu run actual ya listo)
RUN_DIR = globals().get("LATEST_RUN_DIR", None)
if not RUN_DIR:
    raise RuntimeError("ABORT · LATEST_RUN_DIR no está definido.")

BASE = sinergia_freeze_baseline(run_dir=RUN_DIR, baseline_name="GOLDEN_PR04_PR08_V1")
_ = sinergia_check_baseline(run_dir=RUN_DIR, baseline_name="GOLDEN_PR04_PR08_V1")

# SinergIA0881 - Baseline
_ = sinergia_check_baseline(
    run_dir=globals().get("LATEST_RUN_DIR"),
    baseline_name="GOLDEN_PR04_PR08_V1",
)

# SinergIA0890 - FINALIZE_EVIDENCE: re-persist manifest/audit al final (y arregla corrida actual / baseline copy)

import os, json, csv, shutil
from datetime import datetime

def _safe_json(x):
    try:
        json.dumps(x, ensure_ascii=False)
        return x
    except Exception:
        return str(x)

def _rc_get_manifest(rc):
    m = getattr(rc, "manifest", None)
    return m if isinstance(m, dict) else {}

def _rc_get_events(rc):
    ev = getattr(rc, "events", None)
    if isinstance(ev, list):
        return ev
    ev2 = getattr(rc, "audit_events", None)
    return ev2 if isinstance(ev2, list) else []

def _backfill_pr08_channel_gates(manifest: dict, run_dir: str):
    gates = manifest.get("gates", {})
    if not isinstance(gates, dict):
        gates = {}
        manifest["gates"] = gates

    try:
        files = [f for f in os.listdir(run_dir) if f.lower().endswith(".xlsx")]
    except Exception:
        files = []

    mapping = {
        "DIGITAL_WHATSAPP": "BD_Envios_WhatsApp_",
        "DIGITAL_WISE": "BD_Envios_Validador_Wise_",
        "DIGITAL_SMS": "BD_Envios_SMS_",
    }

    for al, prefix in mapping.items():
        k = f"PR_08_{al}"
        if k in gates and isinstance(gates.get(k), dict) and ("published" in gates[k]):
            continue
        has_file = any(str(fn).startswith(prefix) for fn in files)
        if has_file:
            gates[k] = {"ok": True, "published": True, "reason": "BACKFILL_FROM_FILES", "drive_file_id": gates.get(k, {}).get("drive_file_id") if isinstance(gates.get(k), dict) else None}

def sinergia_persist_rc_evidence(*, rc, run_dir: str | None = None) -> str:
    run_dir = run_dir or getattr(rc, "dir", None)
    if not run_dir or not os.path.isdir(run_dir):
        raise FileNotFoundError(f"RUN_DIR_NOT_FOUND: {run_dir}")

    manifest = _rc_get_manifest(rc)
    events = _rc_get_events(rc)

    # asegura campos básicos
    if "run_id" not in manifest:
        manifest["run_id"] = getattr(rc, "run_id", None)
    manifest["ended_at"] = datetime.now().isoformat()

    # backfill PR_08 por canal si faltan
    _backfill_pr08_channel_gates(manifest, run_dir)

    # paths
    manifest_path = os.path.join(run_dir, "manifest.json")
    jsonl_path = os.path.join(run_dir, "audit_events.jsonl")
    csv_path = os.path.join(run_dir, "audit_events.csv")

    # write manifest
    with open(manifest_path, "w", encoding="utf-8") as f:
        json.dump(_safe_json(manifest), f, ensure_ascii=False, indent=2)

    # write jsonl
    with open(jsonl_path, "w", encoding="utf-8") as f:
        for e in (events or []):
            f.write(json.dumps(_safe_json(e), ensure_ascii=False) + "\n")

    # write csv
    with open(csv_path, "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f)
        w.writerow(["ts", "run_id", "etapa", "code", "level", "message"])
        for e in (events or []):
            w.writerow([
                e.get("ts", ""),
                e.get("run_id", getattr(rc, "run_id", "")),
                e.get("etapa", e.get("stage","")),
                e.get("code", ""),
                e.get("level", ""),
                e.get("message", ""),
            ])

    return run_dir

def sinergia_finalize_current_run(*, baseline_name: str = "GOLDEN_PR04_PR08_V1"):
    rc = globals().get("rc", None)
    run_dir = globals().get("LATEST_RUN_DIR", None) or getattr(rc, "dir", None)

    if rc is None or run_dir is None:
        raise RuntimeError("ABORT · Se requiere rc y LATEST_RUN_DIR (o rc.dir).")

    # persist evidencia completa al final
    run_dir = sinergia_persist_rc_evidence(rc=rc, run_dir=run_dir)

    # sincroniza copia del baseline (para que el baseline tenga manifest/audit correctos también)
    base_dir = os.path.join("/content/sinergia_runs/_baselines", baseline_name)
    if os.path.isdir(base_dir):
        for fn in ["manifest.json", "audit_events.csv", "audit_events.jsonl"]:
            src = os.path.join(run_dir, fn)
            dst = os.path.join(base_dir, fn)
            if os.path.isfile(src):
                shutil.copy2(src, dst)

    gk = list((_rc_get_manifest(rc).get("gates", {}) or {}).keys())
    print("FINALIZE · run_dir =", run_dir)
    print("FINALIZE · gates_keys_sample =", gk[:8])
    print("FINALIZE · ok=True")

# Ejecuta esto UNA VEZ para arreglar el manifest/audit del run actual y del baseline
sinergia_finalize_current_run(baseline_name="GOLDEN_PR04_PR08_V1")

# SinergIA8510 - QA_DIAG_PR03_5 (por qué no hay match de historia)
import os, json, re
import pandas as pd

def _norm_docid(x) -> str:
    if x is None:
        return ""
    s = str(x).strip()
    if not s or s.lower() in ("nan", "none"):
        return ""
    m = re.match(r"^\s*(\d+(?:\.\d+)?)\s*[eE]\s*([+-]?\d+)\s*$", s)
    if m:
        try:
            base = float(m.group(1)); exp = int(m.group(2))
            s = str(int(round(base * (10 ** exp))))
        except Exception:
            pass
    if re.match(r"^\d+\.0$", s):
        s = s[:-2]
    return re.sub(r"\D+", "", s)

def _pick_col_any(df: pd.DataFrame, candidates):
    for c in candidates:
        if c in df.columns:
            return c
    return ""

# 1) Manifest del run actual
run_dir = getattr(globals().get("rc", None), "dir", "") or ""
print("DIAG0137 · run_dir =", run_dir)

manifest_path = os.path.join(run_dir, "manifest.json") if run_dir else ""
if not manifest_path or not os.path.exists(manifest_path):
    print("DIAG0137 · manifest NOT FOUND")
else:
    m = json.load(open(manifest_path, "r", encoding="utf-8"))
    g35 = (m.get("gates", {}) or {}).get("PR_03_5", None)
    met35 = (m.get("metrics", {}) or {}).get("PR_03_5", {})
    print("DIAG0137 · gates.PR_03_5 =", g35)
    print("DIAG0137 · aws_source =", met35.get("aws_source"))
    print("DIAG0137 · aws_rows =", met35.get("aws_rows"))
    print("DIAG0137 · aws_doc_col =", met35.get("aws_doc_col"))
    print("DIAG0137 · aws_dt_col =", met35.get("aws_dt_col"))
    print("DIAG0137 · aws_unique_norm =", met35.get("aws_unique_docs_norm"))
    print("DIAG0137 · matched_docs =", met35.get("matched_docs"))
    print("DIAG0137 · matched_ratio =", met35.get("matched_ratio"))

# 2) Estado en memoria: DF_AWS_CACHE, dd_archivo_aws
df_aws = globals().get("DF_AWS_CACHE", None)
print("DIAG0137 · DF_AWS_CACHE exists =", isinstance(df_aws, pd.DataFrame), "shape =", getattr(df_aws, "shape", None))

dd_aws = globals().get("dd_archivo_aws", None)
try:
    ddv = dd_aws.value if hasattr(dd_aws, "value") else dd_aws
except Exception:
    ddv = dd_aws
print("DIAG0137 · dd_archivo_aws value =", str(ddv)[:120])

# 3) Match real por documento (si hay AWS en memoria)
df_base = globals().get("df_base_cobranza", None)
if not isinstance(df_base, pd.DataFrame):
    print("DIAG0137 · df_base_cobranza NOT FOUND en memoria")
elif not isinstance(df_aws, pd.DataFrame) or df_aws.empty:
    print("DIAG0137 · AWS vacío en memoria, no se puede calcular intersección")
else:
    c_doc_base = _pick_col_any(df_base, ["Documento de identidad","DocumentoDeIdentidad","Identificacion","Identificación","IN_DOCUMENTO_DE_IDENTIDAD"])
    c_doc_aws  = _pick_col_any(df_aws,  ["IN_DOCUMENTO_DE_IDENTIDAD","Documento de identidad","Documento","Documento Clte","Identificacion","Identificación"])
    c_dt_aws   = _pick_col_any(df_aws,  ["Fecha Ult Gestion","Fecha Últ Gestión","Fecha Mejor Gest","Fecha Ult Contacto","Fecha Último Contacto","Fecha Gestion","Fecha Gestión","Fecha Contacto","Fecha"])

    print("DIAG0137 · base_doc_col =", c_doc_base)
    print("DIAG0137 · aws_doc_col  =", c_doc_aws)
    print("DIAG0137 · aws_dt_col   =", c_dt_aws)

    base_norm = df_base[c_doc_base].map(_norm_docid) if c_doc_base else pd.Series([], dtype="object")
    aws_norm  = df_aws[c_doc_aws].map(_norm_docid) if c_doc_aws else pd.Series([], dtype="object")

    base_set = set([x for x in base_norm.unique().tolist() if x])
    aws_set  = set([x for x in aws_norm.unique().tolist() if x])

    inter = base_set.intersection(aws_set)
    print("DIAG0137 · base_unique_norm =", len(base_set))
    print("DIAG0137 · aws_unique_norm  =", len(aws_set))
    print("DIAG0137 · intersection_norm =", len(inter))

    # parseabilidad de fechas (muestra ratio)
    if c_dt_aws:
        dt = pd.to_datetime(df_aws[c_dt_aws], errors="coerce", dayfirst=True, utc=False)
        ratio = float(dt.notna().mean()) if len(dt) else 0.0
        print("DIAG0137 · aws_dt_parse_ratio =", round(ratio, 4))
    else:
        print("DIAG0137 · aws_dt_parse_ratio = NA (sin columna fecha)")

    # 5 ejemplos de base que no están en aws (para ver formato)
    if len(inter) == 0 and len(base_set) > 0:
        miss = [x for x in list(base_set)[:50] if x not in aws_set][:5]
        print("DIAG0137 · sample_base_norm_not_in_aws =", miss)